import * as _ from "lodash";
// utility functions for react components
import React = require("react");
import { IconButton, Button as MUIButton } from "../imports/material-ui-imports";
import { Tooltip } from "./Tooltip";
import { isNode } from "../services/platform";
import {
	Plus, PlusCircleOutline, Minus, MinusCircleOutline,
	PlaylistPlus, InformationOutline, Tune,
	CodeTags, FileCheck, VideoInputComponent,
	DeveloperBoard, Memory, History, FileOutline,
} from "../imports/mdi-material-ui-imports";
import { IButtonInfo, TreeButtonIcons } from "../services/instanceContainers/button";
import { OutputViewMgr } from "../services/ui/outputView";
import { assertUnreachable } from "../services/utils";
import { commonStyles } from "./styles/common";

export function mapInOrder<T>(
	toMap: { [key: string]: T },
	order: string[],
	action: (item: T) => JSX.Element) {

	return _.map(order, (key) => {
		const item = toMap[key];
		return action(item);
	});
}

export function getWindowHeight() {
	if (isNode()) {
		const gui = require("nw.gui");
		const win = gui.Window.get().window;

		return win.innerHeight;
	} else {
		return window.innerHeight || document.documentElement.clientHeight || document.body.clientHeight;
	}
}

export function getHeight() {
	const body = document.documentElement.getElementsByTagName("body")[0];
	const height = window.innerHeight || document.documentElement.clientHeight || body.clientHeight;
	return height;
}

export interface DropDownOption {
	name: string;						// value associated with the entry (should be unique)
	displayName?: string;				// name to be displayed
	level?: number;						// add one for each sub option relationship
	isDisabled?: boolean;				// determines if this entry is clickable or just for grouping
	description?: string;				// tooltip for this option (unformatted)
}

export interface FormattedDropDownOption extends Omit<DropDownOption, "description"> {
	description?: React.ReactNode;		// tooltip for this option (formatted)
	icon?: JSX.Element;					// icon for action option
}

export const enum ButtonType {
	Icon,
	Button,
}

export function createButton(
	buttonInfo: IButtonInfo,
	onClick: (event: React.MouseEvent<HTMLElement>) => void,
	type: ButtonType = ButtonType.Icon,
) {
	const icon = (
		translateIcon(buttonInfo.getIcon())
	);

	// pick the right kind of button to display based on the type

	const button = type === ButtonType.Icon ? (
		<IconButton
			id={`${buttonInfo.getID()}`}
			onClick={onClick}
			disabled={buttonInfo.isDisabled()}
			style={commonStyles.smallIcon}
		>
			{icon}
		</IconButton>
	) : (
		<MUIButton
			onClick={onClick}
			variant="contained"
			size="small"
			color="primary"
			disabled={buttonInfo.isDisabled()}
		>
			{icon}
			{buttonInfo.getText()}
		</MUIButton>
	);

	return (
		<Tooltip
			key={buttonInfo.getID()}
			title={buttonInfo.getTooltip()}
			placement="right"
			noWrap>
			{button}
		</Tooltip>
	);
}

function translateIcon(icon: TreeButtonIcons) {
	if (icon === TreeButtonIcons.ADD_WITH_CHOICE) {
		return <PlaylistPlus style={commonStyles.smallIcon} />;
	} else if (icon === TreeButtonIcons.ADD_SUB) {
		return <Plus style={{ ...commonStyles.smallIcon }} />;
	} else if (icon === TreeButtonIcons.ADD) {
		return <PlusCircleOutline style={{ ...commonStyles.smallIcon }} />;
	} else if (icon === TreeButtonIcons.REMOVE_SUB) {
		return <Minus style={commonStyles.smallIcon} />;
	} else if (icon === TreeButtonIcons.REMOVE) {
		return <MinusCircleOutline style={commonStyles.smallIcon} />;
	}
	return null;
}

export function mayBeScrollIntoView(selected: boolean, ref: HTMLElement) {
	if (selected && ref) {
		ref.scrollIntoView({ block: "center", inline: "start" });
	}
}

export function getViewIcon(mgr: OutputViewMgr) {
	if (mgr.type === "history") {
		return <History style={commonStyles.mediumIcon} />;
	} else if (mgr.type === "meta") {
		return <FileOutline style={commonStyles.mediumIcon} />;
	} else if (mgr.type === "preference") {
		return <Tune style={commonStyles.mediumIcon} />;
	} else if (mgr.type === "code") {
		return <CodeTags style={commonStyles.mediumIcon} />;
	} else if (mgr.type === "refs") {
		return <FileCheck style={commonStyles.mediumIcon} />;
	} else if (mgr.type === "ioSets") {
		return <VideoInputComponent style={commonStyles.mediumIcon} />;
	} else if (mgr.type === "board") {
		return <DeveloperBoard style={commonStyles.mediumIcon} />;
	} else if (mgr.type === "device") {
		return <Memory style={commonStyles.mediumIcon} />;
	} else if (mgr.type === "problems") {
		return <InformationOutline style={commonStyles.mediumIcon} />;
	} else {
		assertUnreachable(mgr);
	}
}
