import React = require("react");
import { IProps as IToolTipProps, Tooltip } from "../Tooltip";

// eslint-disable-next-line @typescript-eslint/ban-types
export function withTooltip<T extends object>(BaseComponent: React.ComponentType<T>) {
	class WithTooltip extends React.Component<T & { tooltipProps: IToolTipProps } & { component: React.ElementType }> {
		public override render() {
			// Typescript says "Rest types may only be created from object types", but 
			// this.props IS an object type, so whatever - I'm ignoring
			// @ts-ignore
			const { tooltipProps, ...rest } = this.props;
			return (
				<Tooltip {...tooltipProps} >
					<BaseComponent
						{...rest as T}
					/>
				</Tooltip>
			);
		}
	}
	return WithTooltip;
}
