import React = require("react");
import { IStorageFile } from "../../services/storage";
import { ErrorStore } from "../../services/errorStore";
import { ModalService } from "../../services/ui/modals";
import { AsyncComponent } from "../AsyncComponent";
import { ProgressBar } from "../ProgressBar";
import { FileNode } from "./FileNode";
import { ICommonProps } from "./common";
import { FileModuleMgr } from "../../services/instanceContainers/fileModuleMgr";
import { ConfigStoreActions } from "../../services/configStore";
import { IFileWatcher, FileWatcher } from "../../services/fileWatcher";

interface IState {
	root?: IStorageFile;
	watcher?: IFileWatcher;
}

interface IFileExplorerProps extends Omit<ICommonProps, "fnameFilter" | "selectedPath"> {
	errorStore: ErrorStore;
	modalService: ModalService;
	moduleMgr: FileModuleMgr;
	actions: ConfigStoreActions;
}

// Replaces the requirement list when the module uses the fileTree view
export class FileExplorer extends AsyncComponent<IFileExplorerProps, IState> {

	public override state: IState = {};

	public override render(): JSX.Element {
		if (!this.state.root) {
			return <ProgressBar title="Reading..." />;
		}

		const moduleMgr = this.props.moduleMgr;
		return <FileNode
			selectedPath={moduleMgr.getAbsolutePath(moduleMgr.getSelectedFileRelativePath())}
			onFileSelect={(file) => this.props.actions.requestFile(moduleMgr, file)}
			onFolderSelect={(folder) => this.props.actions.requestFile(moduleMgr, folder)}
			style={"fileExplorer"}
			onFolderExpand={(folder, open) => this.props.actions.toggleFolderExpansion(folder, open)}
			level={1}
			disabled={false}
			pickDir={false}
			getSize={(file) => moduleMgr.getFileSize(file)}
			fileTree={this.state.root}
			fnameFilter={".*"}
			fileHasStatus={(file) => moduleMgr.getFileInstanceStatus(file)}
		/>;
	}

	public override componentWillUnmount() {
		super.componentWillUnmount();
		if (this.state.watcher) {
			this.state.watcher.close();
		}
	}

	protected propsChanged() {
		return this.props.moduleMgr.shouldUpdate();
	}

	protected clearAsyncData() {
		this.setState({ root: null });
	}

	protected async fetchAsyncData() {
		await this.props.actions.refreshFileTree(this.props.moduleMgr);
		const newFileTree = this.props.moduleMgr.getFileTree();
		if (this.state.watcher && (this.state.watcher.getWatchedPath() === newFileTree.path)) {
			// watched path did not change
			return { root: newFileTree };
		} else {
			return { root: newFileTree, watcher: this.createWatcher(newFileTree.path) };
		}
	}

	private createWatcher(path: string) {
		if (this.state.watcher) {
			this.state.watcher.close();
		}
		return new FileWatcher(path, () => this.reFetchAsyncData(), this.props.errorStore);
	}
}
