import * as _ from "lodash";
import { ValidationSummary } from "../../../services/objectManagers/validations";
import { assertUnreachable, getDisplayName } from "../../../services/utils";
import { ExtendedElkNode } from "../layout/customTypes";
import { applyDisabled, applyError, applyFiltered, applySelected, applyUnused, applyWarning } from "../styling/applyStyles";
import { ClassesType } from "../styling/clockTreeStyles";
import { INodeProps } from "./NodeFactory";

export function applyNodeStyles({
	node,
	treeNode,
	displayScriptName,
	searchText,
	disabledInstances,
	usedInstances,
	classes,
	validations,
	selected,
}: INodeProps
) {
	// Error trumps warnings trumps disabled trumps unused
	// Filtered and selected are applied additively

	const styledClasses = applyAdditiveStyles(selected, searchText, node, displayScriptName, classes);
	const mgr = treeNode.getIpInstanceMgr(node.data.ipInstance.name);
	const summary = validations?.getSummary(mgr) ?? ValidationSummary.None;
	switch (summary) {
		case ValidationSummary.Error:
			return applyError(styledClasses);
		case ValidationSummary.Warning:
			return applyWarning(styledClasses);
		case ValidationSummary.None:
			if (_.includes(disabledInstances, node.id)) {
				return applyDisabled(styledClasses);
			} else if (!_.includes(usedInstances, node.id)) {
				return applyUnused(styledClasses);
			}
			return styledClasses;
		default:
			assertUnreachable(summary);
	}
}

function applyAdditiveStyles(
	selected: boolean, searchText: string, node: ExtendedElkNode, displayScriptName: boolean, classes: ClassesType["classes"]) {
	if (!_.isEmpty(searchText) &&
		!getDisplayName(node.data.ipInstance, displayScriptName).toLowerCase().includes(searchText.toLowerCase())) {
		classes = applyFiltered(classes);
	}
	if (selected) {
		classes = applySelected(classes);
	}
	return classes;
}
