
import React = require("react");
import * as _ from "lodash";
import { Menu, MenuItem, Typography, Grid } from "../imports/material-ui-imports";
import { NavButton } from "./buttons/NavButton";
import { FileBrowse } from "./FileBrowse";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { isNode, isCloud } from "../services/platform";
import { assertUnreachable } from "../services/utils";

interface IProps extends IGlobalServiceProps {
	onFileNew: () => void;
	onFileOpen: (fPath: string) => void;
	onFileSave?: () => void;
	onFileSaveAs: (fPath: string) => void;
	currentScript: string;
}

interface IStates {
	anchorEl: HTMLElement;
}

const enum MenuText {
	NEW = "New",
	OPEN = "Open",
	SAVE = "Save",
	SAVEAS = "Save As",
}

class MenuEntry {
	constructor(public readonly menuText: MenuText, public readonly shortcut: string) { }

	public getShortcutDisplayText() {
		const asUpper = _.toUpper(this.shortcut);
		return `CTRL + ${asUpper === this.shortcut ? "SHIFT +" : ""} ${asUpper}`;
	}

	public getInputId() {
		return _.camelCase(`fileMenu${this.menuText}Input`);
	}

	public getMenuItemKey() {
		return `${_.camelCase(this.menuText)}MenuItem`;
	}
}

const menuEntries: { [key in MenuText]: MenuEntry } = {
	[MenuText.NEW]: new MenuEntry(MenuText.NEW, "n"),
	[MenuText.OPEN]: new MenuEntry(MenuText.OPEN, "o"),
	[MenuText.SAVE]: new MenuEntry(MenuText.SAVE, "s"),
	[MenuText.SAVEAS]: new MenuEntry(MenuText.SAVEAS, "S"), // capital since it's ctrl + shift + s
};

// don't support "Save" in cloud

if (isCloud()) {
	delete menuEntries[MenuText.SAVE];
}

export class FileMenu extends React.Component<IProps, IStates> {
	constructor(props: IProps) {
		super(props);
		this.state = { anchorEl: null };
	}
	public override render() {

		return (
			<React.Fragment>
				{
					// Render two hidden file-browse's for open and save.  
					// We need them always visible so the shortcut key can always trigger them
				}
				<FileBrowse
					modalService={this.props.modalService}
					errorStore={this.props.errorStore}
					id={menuEntries[MenuText.OPEN].getInputId()}
					accept={".syscfg,.pinmux"}
					onChange={(fPath) => {
						this.handleClose();
						this.props.onFileOpen(fPath);
					}}
				/>

				<FileBrowse
					modalService={this.props.modalService}
					errorStore={this.props.errorStore}
					id={menuEntries[MenuText.SAVEAS].getInputId()}
					saveAs={this.props.currentScript}
					accept={".syscfg,.pinmux"}
					onChange={(fPath) => {
						this.handleClose();
						this.props.onFileSaveAs(fPath);
					}}
				/>

				{
					// Now render the menu and drop down
				}
				<NavButton
					id="fileBtn"
					onClick={(e) => this.setState({ anchorEl: e.currentTarget })}
				>
					File
				</NavButton>
				<Menu
					id="menu-"
					anchorEl={this.state.anchorEl}
					open={!!this.state.anchorEl}
					onClose={this.handleClose}
					anchorOrigin={{
						vertical: "bottom",
						horizontal: "left",
					}}
					getContentAnchorEl={null}
					PaperProps={{ style: { width: "300px" } }}
				>
					{_.map(menuEntries, (entry) => {
						return <MenuItem
							key={entry.getMenuItemKey()}
							onClick={() => this.handleSelection(entry)}>
							<Grid container alignItems="baseline" justify="space-between">
								<Grid item ><Typography role="option">{entry.menuText}</Typography></Grid>
								<Grid item >
									<Typography variant="caption" color="textSecondary">{entry.getShortcutDisplayText()}</Typography>
								</Grid>
							</Grid>
						</MenuItem>;
					})}
				</Menu>
			</React.Fragment >
		);
	}

	public override componentDidMount() {
		if (isNode() || isCloud()) {
			document.addEventListener("keydown", this.handleKeydown, false);
		}
	}

	public override componentWillUnmount() {
		if (isNode() || isCloud()) {
			document.removeEventListener("keydown", this.handleKeydown);
		}
	}

	private handleClose = () => {
		this.setState({ anchorEl: null });
	}

	private handleKeydown = (event: KeyboardEvent) => {
		if (event.ctrlKey) {
			const entry = _.find(menuEntries, (e) => e.shortcut === event.key);
			if (entry) {
				this.handleSelection(entry);
				event.preventDefault();
			}
		}
	}

	private handleSelection(menuEntry: MenuEntry) {
		switch (menuEntry.menuText) {
			case MenuText.NEW:
				this.handleClose();
				this.props.onFileNew();
				break;

			case MenuText.SAVE:
				if (this.props.currentScript) {
					this.handleClose();
					this.props.onFileSave();
				} else {
					this.handleSelection(menuEntries[MenuText.SAVEAS]);
				}
				break;

			case MenuText.OPEN:
			case MenuText.SAVEAS:
				const chooser = document.querySelector(`#${menuEntry.getInputId()}`) as HTMLInputElement;
				chooser.click();
				break;

			default:
				assertUnreachable(menuEntry.menuText);
		}
		this.handleClose();
	}
}
