import * as _ from "lodash";
import { IFormatter } from "./formatting/formattingTypes";
import * as Konva from "konva";
import { tiStatusColor, pinColors } from "../components/styles/colors";
import { isFormattedLink } from "./formatting/link";
import { ILinkActions } from "../components/actions/ILinkActions";
import { defaultFontSize, ATheme, ColorIndex } from "../components/styles/themes";
import { getWindowHeight } from "../components/ComponentUtils";
import { DevicePinSolutionMap, Pin as PinReq } from "./solver/requirements";
import * as data from "dataInterfaces";
import { PinInfo } from "./pinInfo";
import { assertUnreachable } from "./utils";

let pkg: QFPPkg;
let stage: Konva.Stage;
let pinLayer: Konva.Layer;

// Width and height of the pin view
let width: number;
let height: number;
// extend the width when it is not wide enough to accommodate the pin info at the center
let extraXOffset: number;

let pkgLayer: Konva.Layer;

const PIN_UNASSIGNED = "Pin Available" as const;
const PIN_ASSIGNED = "Pin Assigned" as const;
const PIN_NOT_AVAILABLE = "Pin Not Available" as const;
const PIN_WARNING = "Warning" as const;
const PIN_RESERVED = "Pin Reserved" as const;
const PIN_POWER = "Power" as const;
const PIN_GROUND = "Ground" as const;
export const PIN_FIXED = "Fixed (N/A)" as const;
export type PinType = typeof PIN_UNASSIGNED |
	typeof PIN_ASSIGNED |
	typeof PIN_NOT_AVAILABLE |
	typeof PIN_WARNING |
	typeof PIN_RESERVED |
	typeof PIN_POWER |
	typeof PIN_GROUND |
	typeof PIN_FIXED;

const MINIMUM_WIDTH = 180;

let PIN_TYPES: PinType[];

export const DEVICE_PIN_TO_PIN_TYPE: { [key: string]: PinType } = {
	Default: PIN_UNASSIGNED,
	Power: PIN_POWER,
	Ground: PIN_GROUND,
	Fixed: PIN_FIXED,
	Reserved: PIN_RESERVED,
};

const PIN_SIZE = defaultFontSize;
const EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT = PIN_SIZE * 3;

export function init(
	pinInfo: PinInfo,
	deviceData: data.AdaptedDeviceInfo,
	devicePinSolutionMap: DevicePinSolutionMap,
	selectedPins: Set<string>,
	formatter: IFormatter,
	shouldShowModeTable: boolean,
	actions: ILinkActions,
	theme: ATheme) {
	pkg = createPkg(pinInfo, deviceData, devicePinSolutionMap, selectedPins, formatter, actions, theme);

	stage = null;
	pinLayer = null;

	// Width and height of the pin view
	width = PIN_SIZE * (pkg.numColumns) + (2 * EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT);
	extraXOffset = (width > MINIMUM_WIDTH) ? 0 : MINIMUM_WIDTH - width;
	width = (width > MINIMUM_WIDTH) ? width : MINIMUM_WIDTH;
	height = PIN_SIZE * (pkg.numRows) + (2 * EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT);

	stage = new Konva.Stage({
		container: "deviceView",
		width,
		height: height + pkg.extraSpaceBelow,
	});

	pkgLayer = new Konva.Layer();
	pkg.addBorder(pkgLayer);
	stage.add(pkgLayer);

	pinLayer = new Konva.Layer();
	pkg.addPins(pinLayer, shouldShowModeTable);
	stage.add(pinLayer);

	stage.draw();
}

export function redraw(
	pinInfo: PinInfo,
	formatter: IFormatter,
	selectedPins: Set<string>,
	devicePinSolutionMap: DevicePinSolutionMap,
	strokeColor: string,
) {
	if (stage) {
		pkg.pinInfo = pinInfo;
		pkg.selectedPins = selectedPins;
		pkg.devicePinSolutionMap = devicePinSolutionMap;
		pkg.formatter = formatter;
		pkg.redraw(strokeColor);
	}
}

export function destroy() {

	// destroy is not recursive
	// we have to first destroy the stage, then its children
	// and then children of the children.

	pkgLayer.destroyChildren();
	pkgLayer.destroy();
	pinLayer.destroyChildren();
	pinLayer.destroy();
	stage.destroyChildren();
	stage.destroy();

	// Clear Konva impl cache to avoid memory leaks.
	(Konva as any).shapes = {};
}

function createPkg(
	pinInfo: PinInfo,
	deviceData: data.AdaptedDeviceInfo,
	devicePinSolutionMap: DevicePinSolutionMap,
	selectedPins: Set<string>,
	formatter: IFormatter,
	actions: ILinkActions,
	theme: ATheme): QFPPkg {

	setUpPinTypes(deviceData.showExtendedPinTypes);

	if (deviceData.packageDescription.type === "QFP") {

		const qfpPkg = new QFPPkg(
			pinInfo, deviceData, devicePinSolutionMap, selectedPins, formatter, actions, theme);

		return qfpPkg;

	} else if (deviceData.packageDescription.type === "BGA") {

		const bgaPkg = new BGAPkg(
			pinInfo, deviceData, devicePinSolutionMap, selectedPins, formatter, actions, theme);

		return bgaPkg;

	}

	throw new Error("Unsupported Package Type");
}

function setUpPinTypes(showExtendedPinTypes: boolean) {
	PIN_TYPES = [PIN_UNASSIGNED, PIN_ASSIGNED, PIN_WARNING];

	if (showExtendedPinTypes) {
		PIN_TYPES = PIN_TYPES.concat([PIN_POWER, PIN_GROUND]);
	}

	PIN_TYPES = PIN_TYPES.concat([PIN_FIXED]);
}

type PinShape = Konva.Shape & { pin?: Pin };

interface Pin {
	shape: PinShape;
	pinName?: string;
	pinType: PinType;
	currentlySelected?: boolean;
}

class QFPPkg {

	public extraSpaceBelow = 0; // Additional space at the bottom of the pin view
	public numColumns: number;
	public numRows: number;

	protected deviceData: data.AdaptedDeviceInfo;
	protected rowColumnInverted: boolean;

	protected pkgInfo: DeviceInfo.PackageDescription;

	protected pins: Pin[] = [];
	protected extraTopLeft = (PIN_SIZE / 4) + EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT;
	protected extraBottomRight = 2 * EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT;

	constructor(
		public pinInfo: PinInfo,
		deviceData: data.AdaptedDeviceInfo,
		public devicePinSolutionMap: DevicePinSolutionMap,
		public selectedPins: Set<string>,
		public formatter: IFormatter,
		private readonly actions: ILinkActions,
		public theme: ATheme) {

		this.deviceData = deviceData;
		this.pkgInfo = deviceData.packageDescription;
		this.rowColumnInverted = deviceData.rowColumnInverted;

		// extra row and column needed , because the corner elements don"t exist
		this.numColumns = this.pkgInfo.numColumns + 2;
		this.numRows = this.pkgInfo.numRows + 2;
	}

	public pinLegendYFactor() {
		return 0.25;
	}

	public dimpleRadius() {
		return PIN_SIZE / 2;
	}

	public dimpleX() {
		return PIN_SIZE * 3;
	}

	public dimpleY() {
		return height - (PIN_SIZE * 3);
	}

	public legendShape(): PinShape {
		return new Konva.Rect({
			x: 0,
			y: 0,
			width: PIN_SIZE,
			height: PIN_SIZE / 2,
			fill: "grey",
		});
	}

	public legendLblOffsetY() {
		return -(PIN_SIZE / 4);
	}

	public addBorder(layer: Konva.Layer) {

		// Add border on the inside of pins
		const borderStrokeWidth = 1;
		const borderX = PIN_SIZE + borderStrokeWidth;
		const borderY = PIN_SIZE + borderStrokeWidth;
		const borderWidth = this.borderWidth() - (2 * borderStrokeWidth);
		const borderHeight = this.borderHeight() - (2 * borderStrokeWidth);

		const border = new Konva.Rect({
			x: borderX,
			y: borderY,
			width: borderWidth,
			height: borderHeight,
			stroke: "black",
			strokeWidth: borderStrokeWidth,
			cornerRadius: 5,
		});

		layer.add(border);

		// add the dimple
		const dimple = new Konva.Circle({
			radius: this.dimpleRadius(),
			stroke: "black",
			strokeWidth: 2,
			x: this.dimpleX(),
			y: this.dimpleY(),
		});

		layer.add(dimple);

		// Add the legend
		const legendY = borderY + (borderHeight * this.pinLegendYFactor());

		let maxLblWidth = 0;
		const lbls: Konva.Text[] = [];
		const shapes: Konva.Shape[] = [];
		_.each(PIN_TYPES, (pinType, i) => {
			const pinShapeY = legendY + (PIN_SIZE * i);

			const shape = this.legendShape();
			shape.y(pinShapeY);

			const pin: Pin = {
				pinType,
				shape,
			};
			this.applyPinDecorationsToShape(pin);

			const lbl = new Konva.Text({
				x: 0,
				y: pinShapeY + this.legendLblOffsetY(),
				text: pinType,
				fontSize: PIN_SIZE,
				fill: this.theme.theme.palette.text.primary,
			});

			if (lbl.width() > maxLblWidth) {
				maxLblWidth = lbl.width();
			}

			shapes.push(shape);
			lbls.push(lbl);
		});

		const padding = (PIN_SIZE / 4);
		const legendSize = maxLblWidth + PIN_SIZE + padding;
		const legendX = ((borderWidth - legendSize) / 2) + borderX;
		const lblX = legendX + PIN_SIZE + padding;

		for (let k = 0; k < lbls.length; k++) {
			shapes[k].x(legendX);
			layer.add(shapes[k]);
			lbls[k].x(lblX);
			layer.add(lbls[k]);
		}
	}

	public addPins(layer: Konva.Layer, shouldShowModeTable: boolean) {

		for (let i = 0; i < this.numColumns; i++) {
			for (let k = 0; k < this.numRows; k++) {
				const pinX = (i * PIN_SIZE);
				const pinY = (k * PIN_SIZE);

				this.addCellContent(layer, pinX, pinY, k, i);
			}
		}

		layer.on("mouseover", (obj) => {
			const shape = obj.target as PinShape;
			if (shape?.pin?.pinType) { // target is maybe a pin label on the edge?
				switch (shape.pin.pinType) {
					case PIN_WARNING:
					case PIN_ASSIGNED:
						document.body.style.cursor = "pointer";
						break;
					case PIN_UNASSIGNED:
					case PIN_RESERVED:
					case PIN_POWER:
					case PIN_GROUND:
					case PIN_FIXED:
					case PIN_NOT_AVAILABLE:
						break;
					default:
						assertUnreachable(shape.pin.pinType);
				}
				this.showPopUp(obj.target as PinShape, obj.evt.clientX, obj.evt.clientY, shouldShowModeTable);
			}
		});

		layer.on("mouseout", () => {
			document.body.style.cursor = "default";
			this.hidePopUp();
		});

		layer.on("click", (obj) => {
			const assignments = this.devicePinSolutionMap[(obj.target as PinShape).pin.pinName];
			if (!_.isEmpty(assignments)) {
				const link = _.first(this.formatter(_.first(assignments)).toParts());
				if (isFormattedLink(link)) {
					link.linkAction(this.actions);
				}
			}
		});
	}

	public getXPinOffSet(row: number, column: number) {
		if (row === 0 || row === (this.numRows - 1)) {
			return this.extraTopLeft;
		} else if (column === this.numColumns - 1) {
			return this.extraBottomRight + extraXOffset;
		}
		return 0;
	}

	public getYPinOffSet(row: number, column: number) {
		if (column === 0 || column === this.numColumns - 1) {
			return this.extraTopLeft;
		} else if (row === this.numRows - 1) {
			return this.extraBottomRight;
		}
		return 0;
	}

	public applyPinDecorations(pin: Pin) {
		this.setPinType(pin);
		this.applyPinDecorationsToShape(pin);
	}

	public createLbl(x: number, y: number, row: number, column: number) {
		// base the calculation on the actual package information note the grid
		// package used for display
		const numPinsInColumn = this.pkgInfo.numColumns;
		const numPinsInRow = this.pkgInfo.numRows;

		const pinWidthOffSet = (PIN_SIZE + (PIN_SIZE / 4));
		const pinHeightOffSet = (PIN_SIZE / 2);

		const lbl = new Konva.Text({
			x,
			y,
			text: "",
			fontSize: PIN_SIZE,
			fill: "black",
			rotation: 0,
		});

		let pinNumber: number;

		if (row === this.numRows - 1) { // bottom 
			pinNumber = column;
			lbl.text(this.lblText(pinNumber));
			lbl.x(lbl.x() - pinHeightOffSet);
			lbl.y(lbl.y() - pinHeightOffSet);
			lbl.rotation(-90);
		} else if (column === this.numColumns - 1) { // right
			pinNumber = numPinsInColumn + (this.numRows - row - 1);
			lbl.text(this.lblText(pinNumber));
			lbl.y(lbl.y() - pinHeightOffSet);
			const offSetPadding = isNaN(parseInt(this.lblText(pinNumber), 10)) ? 14 : 4; // arbitrary based on eyeballing
			lbl.x(lbl.x() - pinWidthOffSet - offSetPadding);
		} else if (row === 0) { // top
			pinNumber = numPinsInColumn + numPinsInRow + (this.numColumns - column - 1);
			lbl.text(this.lblText(pinNumber));
			lbl.x(lbl.x() - pinHeightOffSet);
			lbl.y(lbl.y() + pinWidthOffSet + lbl.width());
			lbl.rotation(-90);
		} else if (column === 0) { // left
			pinNumber = numPinsInRow + (2 * numPinsInColumn) + (row);
			lbl.text(this.lblText(pinNumber));
			lbl.y(lbl.y() - pinHeightOffSet);
			lbl.x(lbl.x() + pinWidthOffSet);

		} else {
			throw new Error("Unable to map pin name");
		}

		return lbl;
	}

	public lblText(pinNumber: number) {
		return pinNumber.toString();
	}

	public addCellContent(layer: Konva.Layer, pinX: number, pinY: number, row: number, column: number) {

		if (this.isValidRowCol(row, column)) {

			let pinWidth = PIN_SIZE;
			let pinHeight = PIN_SIZE / 2;

			// rotate the top and bottom pins
			if (row === 0 || row === this.numRows - 1) {
				const temp = pinWidth;
				pinWidth = pinHeight;
				pinHeight = temp;
			}

			pinX += this.getXPinOffSet(row, column);
			pinY += this.getYPinOffSet(row, column);

			const lbl = this.createLbl(pinX, pinY, row, column);

			const shape: PinShape = new Konva.Rect({
				x: pinX,
				y: pinY,
				width: pinWidth,
				height: pinHeight,
				fill: "grey",
			});

			const pin: Pin = {
				shape,
				pinName: lbl.text(),
				pinType: null,
			};

			shape.pin = pin;

			this.applyPinDecorations(pin);

			layer.add(pin.shape);
			layer.add(lbl);
			this.pins.push(pin);
		}
	}

	public redraw(strokeColor: string) {
		_.each(this.pins, (pin) => {
			// if it is not just a label pin
			if (pin.shape) {
				if (this.setPinType(pin)) {
					// smooth out edges in light/dark mode
					pin.shape.stroke(strokeColor);
					pin.shape.draw();
					this.applyPinDecorationsToShape(pin);
					pin.shape.draw();
				}
			}
		});
	}

	private isValidRowCol(row: number, column: number) {
		return ((row === 0 || row === this.numRows - 1) && column > 0 && column < this.numColumns - 1) ||
			((column === 0 || column === this.numColumns - 1) && row > 0 && row < this.numRows - 1);
	}

	private createPopUpDetails(pin: Pin, shouldShowModeTable: boolean) {

		const pinName = pin.pinName;
		const devicePin = this.deviceData.devicePins[pinName];
		if (!devicePin) {
			return null;
		}
		const tooltipInfo = this.pinInfo.getTooltip(shouldShowModeTable, devicePin);

		const rows = _.map(tooltipInfo, (rowInfo) => {
			let style = "white-space:nowrap;vertical-align:top";
			if (rowInfo.success) {
				style += ";color:#49b653";
			} else if (rowInfo.title) {
				style += ";text-decoration:underline";
			}

			const col2 = _.map(rowInfo.col2, (curCol2Content) => {
				if (rowInfo.col2.length > 1) {
					return `<span>${curCol2Content}<br/></span>`;
				} else {
					return curCol2Content;
				}
			}).join("");

			return `<tr style='${style}'> <td> ${rowInfo.col1} </td> <td> ${col2} </td> <tr>`;
		});

		return `<table> ${rows.join(" ")} </table>`;
	}

	private showPopUp(shape: PinShape, x: number, y: number, shouldShowModeTable: boolean) {

		const popUp = document.getElementById("pinDetails");

		if (shape.pin) {
			// get the document height
			const currentDocHeight = getWindowHeight();
			const html = this.createPopUpDetails(shape.pin, shouldShowModeTable);
			if (html) {
				popUp.innerHTML = html;
				popUp.style.display = "block";
				popUp.style.position = "fixed";

				// give it 30 px extra padding, so it"s not quite hugging the bottom
				const yOverFlow = (y + popUp.clientHeight + 30) - currentDocHeight;
				y = (yOverFlow > 0) ? (y - yOverFlow) : y;

				popUp.style.top = y + "px";
				// move the tooltip a bit away from the pin itself to prevent it blocks the pin
				popUp.style.left = (x - popUp.clientWidth - 10) + "px";
			}
		}
	}

	private setPinType(pin: Pin) {

		const pinName = pin.pinName;
		const devicePin = this.deviceData.devicePins[pinName];
		const assignments = this.devicePinSolutionMap[pinName];

		let changed = false;
		let pinType: PinType = PIN_NOT_AVAILABLE;
		let currentlySelected = false;

		if (devicePin) {
			pinType = DEVICE_PIN_TO_PIN_TYPE[devicePin.devicePinType];

			if (assignments) {
				if (this.isCurrentlySelected(assignments)) {
					currentlySelected = true;
				}
				pinType = PIN_ASSIGNED;
				if (_.some(assignments, (assignment) => assignment.solution.warningDetailsText.length > 0)) {
					pinType = PIN_WARNING;
				} else if (_.every(assignments, (assignment) => assignment.reserved)) {
					pinType = PIN_RESERVED;
				}
			}
		}

		changed = (pin.currentlySelected !== currentlySelected) ||
			pin.pinType !== pinType;
		pin.currentlySelected = currentlySelected;
		pin.pinType = pinType;

		return changed;
	}

	private isCurrentlySelected(assignments: PinReq[]) {
		return _.some(assignments, (assignment) =>
			this.selectedPins.has(assignment.solution.assignedToName));
	}

	private borderWidth() {
		return width - (2 * PIN_SIZE);
	}

	private borderHeight() {
		return height - (2 * PIN_SIZE);
	}

	private applyPinDecorationsToShape(pin: Pin) {
		if (pin.shape) {
			let fill;
			let stroke;
			const strokeWidth = 2;

			switch (pin.pinType) {
				case PIN_UNASSIGNED:
					fill = stroke = pinColors.available;
					break;
				case PIN_ASSIGNED:
					fill = stroke = pinColors.used;
					break;
				case PIN_WARNING:
					fill = stroke = tiStatusColor.warning;
					break;
				case PIN_POWER:
					fill = stroke = pinColors.power;
					break;
				case PIN_GROUND:
					fill = stroke = pinColors.ground;
					break;
				case PIN_RESERVED:
				// A legacy bug always showed reserved pins the same as fixed pins, so keep it the same for now
				// fill = stroke = pinColors.reserved;
				// break;
				case PIN_FIXED:
					fill = stroke = pinColors.fixed;
					break;
				case PIN_NOT_AVAILABLE:
					// when showing extended pin types, set to white so they are not visible
					fill = this.deviceData.showExtendedPinTypes ? "white" : "#D8D8D8";
					stroke = this.deviceData.showExtendedPinTypes ? "white" : "#D8D8D8";
					break;
				default:
					assertUnreachable(pin.pinType);
			}

			if (pin.currentlySelected) {
				stroke = this.theme.colors[ColorIndex.SELECTEDPINSTROKECOLOR];
				fill = (pin.pinType === PIN_WARNING) ?
					pinColors.highlightedShared : pinColors.highlightedUsed;
			}

			pin.shape.fill(fill);
			pin.shape.stroke(stroke);
			pin.shape.strokeWidth(strokeWidth);
		}
	}

	private hidePopUp() {
		const popUp = document.getElementById("pinDetails");
		popUp.style.display = "none";
	}

}

class BGAPkg extends QFPPkg {

	private rowNames: string[];
	private columnNames: string[];

	constructor(
		pinInfo: PinInfo,
		deviceData: data.AdaptedDeviceInfo,
		devicePinSolutionMap: DevicePinSolutionMap,
		selectedPins: Set<string>,
		formatter: IFormatter,
		actions: ILinkActions,
		theme: ATheme) {
		super(pinInfo, deviceData, devicePinSolutionMap, selectedPins, formatter, actions, theme);

		this.numColumns = this.pkgInfo.numColumns;
		this.numRows = this.pkgInfo.numRows;
		// Additional space at the bottom of the pin view for the legend to be displayed
		this.extraSpaceBelow = PIN_SIZE * (1 + PIN_TYPES.length);
		this.columnNames = this.getColumnNames(this.pkgInfo.numColumns);
		this.rowNames = this.getRowNames(this.pkgInfo.numRows);

		if (this.rowColumnInverted) {
			const temp = this.rowNames;
			this.rowNames = this.columnNames;
			this.columnNames = temp;

			this.rowNames.reverse();
			this.columnNames.reverse();
		}

		this.extraTopLeft = EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT;
		this.extraBottomRight = EXTRA_PADDING_BEFORE_FIRST_VISIBLE_ELEMENT;
	}

	public override pinLegendYFactor() {
		return 1.05;
	}

	public override dimpleRadius() {
		return (PIN_SIZE / 3);
	}

	public override dimpleX() {
		return PIN_SIZE * 2;
	}

	public override dimpleY() {
		return height - (PIN_SIZE * 2);
	}

	public override getXPinOffSet() {
		return this.extraTopLeft;
	}

	public override getYPinOffSet() {
		return this.extraBottomRight;
	}

	public override addCellContent(layer: Konva.Layer, pinX: number, pinY: number, row: number, column: number) {
		pinX += PIN_SIZE / 2;
		pinY += PIN_SIZE / 2;

		const radius = PIN_SIZE / 2.5;

		pinX += this.getXPinOffSet();
		pinY += this.getYPinOffSet();

		const pinName = this.pinName(row, column);
		let lbl = this.createLbl(pinX, pinY, row, column);

		const pin: Pin = {
			shape: null,
			pinName,
			pinType: null,
		};

		pin.shape = new Konva.Circle({
			x: pinX,
			y: pinY,
			radius,
			fill: "grey",
		});

		pin.shape.pin = pin;
		this.applyPinDecorations(pin);

		if (pin.shape) {
			layer.add(pin.shape);
		}
		if (lbl) {
			layer.add(lbl);
		}

		if (row === 0 && column === 0) {
			// extra lbl for the left upper column
			lbl = this.createLbl(pinX, pinY, -1, column);
			layer.add(lbl);
		}

		this.pins.push(pin);
	}

	public override legendShape() {
		return new Konva.Circle({
			x: 0,
			y: 0,
			radius: PIN_SIZE / 2.5,
			fill: "grey",
		});
	}

	public override legendLblOffsetY() {
		return -(PIN_SIZE / 2.5);
	}

	public override createLbl(x: number, y: number, row: number, column: number) {
		let lbl = new Konva.Text({
			x,
			y,
			text: "",
			fontSize: PIN_SIZE,
			fill: this.theme.theme.palette.text.primary,
			rotation: 0,
		});

		const offSet = PIN_SIZE / 2;
		const padding = 4;

		if (row === 0) { // top
			lbl.text(this.columnNames[column]);
			lbl.y(lbl.y() - offSet - padding);
			lbl.x(lbl.x() - offSet);
			lbl.rotation(-90);
		} else if (column === 0) { // left

			// this is the special case for the upper left hand corner with 2 labels
			// generate 1 with row = 0 and another when row == -1 is passed in.
			row = (row === -1) ? 0 : row;

			lbl.text(this.rowNames[row]);
			lbl.x(lbl.x() - offSet - lbl.width() - padding);
			lbl.y(lbl.y() - offSet);

		} else if (row === -1 && column === -1) {

		} else {
			lbl = null;
		}

		return lbl;
	}

	private pinName(row: number, column: number) {
		if (this.rowColumnInverted) {
			return this.rowNames[row] + this.columnNames[column];
		}

		return this.columnNames[column] + this.rowNames[row];
	}

	private getColumnNames(numColumns: number) {

		const columns: string[] = [];
		let index = 0;
		while (columns.length !== numColumns) {
			if (index < 26) {
				const char = String.fromCharCode("A".charCodeAt(0) + index);
				if (char !== "I" && char !== "O" && char !== "Q" && char !== "S" && char !== "X" && char !== "Z") {
					columns.push(char);
				}
			} else {
				const numElements = index + 1;
				const appendToIndex = Math.floor((numElements / 26)) - 1;
				columns.push(columns[appendToIndex].concat(columns[(numElements % 26) - 1]));
			}

			index++;
		}

		return columns;
	}

	private getRowNames(numRows: number) {

		const rows: string[] = [];
		for (let index = numRows; index > 0; index--) {
			rows.push(index.toString());
		}

		return rows;
	}
}
