import React = require("react");
import { AppBar, IconButton, Typography, Toolbar } from "../imports/material-ui-imports";
import { ArrowLeft, ArrowRight, MenuRight } from "../imports/mdi-material-ui-imports";
import { OutputMenu } from "./OutputViews/OutputMenu";
import { ConfigStoreActions } from "../services/configStore";
import { ITreeNode } from "./TreeNode";
import { Tab } from "../services/tabs";
import { Tooltip } from "./Tooltip";
import { ATheme } from "./styles/themes";
import { NavigationHistory } from "../services/navigationHistory";
import { commonStyles } from "./styles/common";
import { OutputViewMgr } from "../services/ui/outputView";
import { IGlobalServiceProps } from "./IGlobalServicesProps";

interface IProps extends IGlobalServiceProps {
	actions: ConfigStoreActions;
	selectedTreeNode: ITreeNode;
	selectedTab: Tab;
	theme: ATheme;
	navHistory: NavigationHistory;
	viewMgrs: OutputViewMgr[];
	showingOutput: boolean;
}

export class Breadcrumb extends React.Component<IProps> {
	public override render() {
		const { navHistory } = this.props;
		return (
			<AppBar color="inherit" id="breadcrumb" style={{
				backgroundColor: this.props.theme.theme.palette.background.default,
				boxShadow: "0 1px 1px #bbb",
				position: "relative",
				paddingTop: this.props.theme.theme.spacing(1),
				paddingBottom: this.props.theme.theme.spacing(1),
				zIndex: 1,
			}}>
				<Toolbar disableGutters style={{ ...commonStyles.toolbarStyle }}>
					<div style={{
						marginLeft: this.props.theme.theme.spacing(2),
						marginRight: this.props.theme.theme.spacing(2),
					}}>
						<NavigatorButton type="backward"
							theme={this.props.theme}
							navAction={() => navHistory.back()}
							disabled={!navHistory.canMoveBack()}
						/>
						<NavigatorButton type="forward"
							theme={this.props.theme}
							navAction={() => navHistory.forward()}
							disabled={!navHistory.canMoveForward()}
						/>
					</div>
					<Typography variant="body2" id="breadcrumbTabName">
						{this.props.selectedTab.getTitle()}
					</Typography>
					{!!this.props.selectedTreeNode &&
						<React.Fragment>
							<MenuRight color="primary" style={{ ...commonStyles.smallIcon, color: "#aaa" }} />
							<Typography variant="body2">
								{this.props.selectedTreeNode.getDisplayName(false)}
							</Typography>
						</React.Fragment>
					}
					<div style={{ flexGrow: 1 }} />
					{this.props.showingOutput &&
						<OutputMenu
							{...this.props}
							theme={this.props.theme}
							actions={this.props.actions}
							viewMgrs={this.props.viewMgrs}
						/>
					}
				</Toolbar>
			</AppBar >
		);
	}
}

interface INavigatorButtonProps {
	type: "forward" | "backward";
	navAction: () => void;
	disabled: boolean;
	theme: ATheme;
}

class NavigatorButton extends React.Component<INavigatorButtonProps> {
	public override render() {
		const iconUsed = this.props.type === "forward" ?
			<ArrowRight color="primary" style={{ ...commonStyles.smallIcon }} />
			: <ArrowLeft color="primary" style={{ ...commonStyles.smallIcon }} />;
		return (
			<Tooltip placement="top" title={`Go ${this.props.type}`} noWrap>
				<IconButton
					id={`navigate_${this.props.type}_btn`}
					onClick={() => this.props.navAction()}
					disabled={this.props.disabled}
				>
					{iconUsed}
				</IconButton>
			</Tooltip>
		);
	}
}
