
import * as React from "react";
import { getDisplayName } from "../../../services/utils";
import { ExtendedElkNode } from "../layout/customTypes";
import { PositionedDiv } from "./PositionedDiv";

// Adapts a PositionedDiv for a specific elk node layout

interface IProps {
	node: ExtendedElkNode;
	onSelect: (selection: string) => void;
	suppressTooltip?: boolean;
	className: string;
}

// There is no sense making this a PureComponent.  All clients are already PureComponents or memos

export class PositionedNode extends React.Component<IProps> {
	public override render() {
		const { node, className, children } = this.props;

		return (
			<PositionedDiv
				x={node.x}
				y={node.y}
				height={node.height}
				width={node.width}
				onSelect={this.onSelect}
				tooltip={this.getToolTip()}
				className={className}
			>
				{children}
			</PositionedDiv>
		);
	}

	private onSelect = () => this.props.onSelect(this.props.node.data.ipInstance.name);

	private getToolTip() {
		if (this.props.suppressTooltip) {
			return undefined;
		}
		const { ipInstance } = this.props.node.data;
		if (ipInstance.description) {
			return `${getDisplayName(ipInstance, false)}: ${ipInstance.description}`;
		}
		return getDisplayName(ipInstance, false);
	}
}
