import React = require("react");
import * as _ from "lodash";
import ReactDOM = require("react-dom");
import { Notification } from "../../components/Notification";
import { INotification } from "../INotification";
import { ThemeProvider } from "../../imports/material-ui-imports";
import { ATheme, ColorIndex } from "../../components/styles/themes";

export class NotificationService implements INotification {
	constructor(public theme: ATheme) { }
	public closeNotification() {
		ReactDOM.unmountComponentAtNode(document.getElementById("notificationRoot"));
	}
	public pushNotification(msg: string) {
		ReactDOM.render(<ThemeProvider theme={this.theme.theme}>
			<Notification
				msg={msg}
				iconColor={this.theme.colors[ColorIndex.BACKGROUNDCOLOR]}
				onClose={this.closeNotification} />
		</ThemeProvider>, document.getElementById("notificationRoot"));
	}
}
