import * as _ from "lodash";
import React = require("react");
import {
	List, ListItem, Typography, ListItemSecondaryAction, IconButton, ListItemText, Divider,
} from "../imports/material-ui-imports";
import { Minus } from "../imports/mdi-material-ui-imports";
import { InstanceStatusDecorator } from "./Decorators";
import { CommonClasses, commonStyles, withCommonStyles } from "./styles/common";
import { HardwareComponentMgr } from "../services/instanceContainers/hardwareComponent";
import { ModuleInstanceMgr } from "../services/objectManagers/moduleInstance";
import { ConfigStoreActions } from "../services/configStore";
import { IFormatter } from "../services/formatting/formattingTypes";
import { AttachDetachSoftwareButton } from "./AttachDetachSoftwareButton";
import { ButtonType } from "./ComponentUtils";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { DisplayLongDescButton, LongDescription } from "./LongDescription";
import { defaultTheme } from "./styles/themes";
import { ResourceLoader, ResourceType } from "../services/resources/metaContentLoaders/resourceLoader";
import { CModuleInstance } from "../services/objectManagers/ui/moduleInstance";
import { InlineErrorBoundary } from "./InlineErrorBoundry";
import { IMyListItem } from "../services/IMyListItem";
import { shouldShowLongDescription } from "../services/utils";
import { OutputViewMgr } from "../services/ui/outputView";
import { Validations } from "../services/objectManagers/validations";
import { PinDisplayType } from "../services/userPreferences";

interface IProps {
	actions: ConfigStoreActions;
	hwComponentMgr: HardwareComponentMgr;
	arePowerDomainSettingsEnabled: boolean;
	formatter: IFormatter;
	validations: Validations;
	displayScriptName: boolean;
	devicePinDisplayType: PinDisplayType[];
	headerPinDisplayType: PinDisplayType[];
	resourceLoader: ResourceLoader;
	focusedSubItemPath: string[];
	showUsed: boolean;
	showPinTable: boolean;
	viewMgrs: OutputViewMgr[];
}

interface IState {
	anchorEl: HTMLElement;	// stores where the menu should be opened
	menuOpened: boolean;	// show/hide menu
}

// View for configuring the selected Hardware component
// shows button to add compatible software modules, the associated list items and a configurables card for the software
class StyledHardwareRequirements extends React.Component<IProps & IGlobalServiceProps & CommonClasses, IState> {

	public override state: IState = {
		anchorEl: null,
		menuOpened: false,
	};

	public override render() {

		const { hwComponentMgr, actions } = this.props;
		const selectedMyListItem = hwComponentMgr.getSelectedMyListItem();
		const listItems = hwComponentMgr.getInstances();
		const attachButtonText = hwComponentMgr.getAttachButtonInfo().getText();
		const showingOutput = _.some(this.props.viewMgrs, (v) => v.isDisplayed());
		const showLongDescription = shouldShowLongDescription(hwComponentMgr);
		return (
			<List
				style={{
					marginLeft: defaultTheme.theme.spacing(1),
					marginRight: defaultTheme.theme.spacing(1),
					paddingTop: 0,
				}}
			>
				<ListItem style={{ paddingLeft: 0, paddingRight: 0 }}>
					<div style={{ flex: 1 }}>
						<Typography variant="subtitle2" style={{ display: "inline-block" }}>
							{hwComponentMgr.getDisplayName(this.props.displayScriptName)}
						</Typography>
						<DisplayLongDescButton
							onClick={() => actions.setShowUserLongDescPref(hwComponentMgr, !showLongDescription)}
							name={hwComponentMgr.getDisplayName(this.props.displayScriptName)}
							hidden={!hwComponentMgr.getLongDescription() || hwComponentMgr.isDetached()}
						/>
					</div>
					<AttachDetachSoftwareButton
						treeNode={hwComponentMgr}
						actions={actions}
						type={ButtonType.Button}
						displayScriptName={this.props.displayScriptName}
					/>
				</ListItem>
				{showLongDescription &&
					<LongDescription
						closeDescription={() => actions.setShowUserLongDescPref(hwComponentMgr, false)}
						longDescription={hwComponentMgr.getLongDescription()}
						canonicalName={hwComponentMgr.getParentSource().definition}
						resourceType={ResourceType.DATA}
						disableClose={hwComponentMgr.isDetached()}
						resourceLoader={this.props.resourceLoader}
						formatter={this.props.formatter}
						actions={this.props.actions}
					/>}
				<Divider key="headerDiv" />
				{!_.isEmpty(listItems) ?
					_.map(listItems, (listItem) => {
						return (
							<ListItem
								button
								key={listItem.getID()}
								className={(listItem === selectedMyListItem)
									? this.props.classes.selectedList : this.props.classes.unSelectedList}
								onClick={() => this.props.actions.setSelectedMyListItem(hwComponentMgr, listItem)}
							>
								<InstanceStatusDecorator
									id={listItem.getID() + "Icon"}
									instanceMgr={listItem}
									validations={this.props.validations}
								/>
								<ListItemText key="text"
									primary={<Typography variant="subtitle2">
										{listItem.getNameMgr().getValue()}
									</Typography>} />
								{listItem.isRemovable() &&
									<ListItemSecondaryAction>
										<IconButton
											onClick={() => this.props.actions.removeInstance(listItem)}
											style={{ padding: defaultTheme.theme.spacing(1) }}
										>
											<Minus style={{ ...commonStyles.smallIcon }} />
										</IconButton>
									</ListItemSecondaryAction>
								}
							</ListItem>
						);
					})
					:
					<ListItem>
						<Typography variant="body2" style={{ textAlign: "center", width: "100%" }}>
							Click the <b>{attachButtonText}</b> button to select software to use
						</Typography>
					</ListItem>
				}
				<Divider key="listOrInstDiv" />
				{
					!_.isEmpty(listItems) &&
					<HardwareRequirementsListItem
						{...this.props}
						myListItem={selectedMyListItem}
						showingOutput={showingOutput}
						isPreview={hwComponentMgr.isDetached()}
					/>
				}
			</List>
		);
	}
}

export const HardwareRequirements = withCommonStyles(StyledHardwareRequirements);

// Allows configuration of the selected list item
// reuses the implementation in the Requirements component
class HardwareRequirementsListItem extends React.Component<{
	myListItem: IMyListItem;
	actions: ConfigStoreActions;
	showingOutput: boolean;
	formatter: IFormatter;
	validations: Validations;
	displayScriptName: boolean;
	devicePinDisplayType: PinDisplayType[];
	headerPinDisplayType: PinDisplayType[];
	resourceLoader: ResourceLoader;
	isPreview: boolean;
	focusedSubItemPath: string[];
	showUsed: boolean;
	showPinTable: boolean;
	arePowerDomainSettingsEnabled: boolean;
} & IGlobalServiceProps, {}> {
	public override render() {
		const instMgr = this.props.myListItem;
		if (instMgr instanceof ModuleInstanceMgr) {
			return (
				<List>
					<InlineErrorBoundary theme={this.props.theme} key={instMgr.getID()}>
						<CModuleInstance
							{...this.props}
							instMgr={instMgr}
							productLookupName={instMgr.getModuleName()}
						/>
					</InlineErrorBoundary>
				</List>
			);
		} else {
			throw new Error("Not a module instance");
		}
	}
}
