import * as _ from "lodash";
import { Peripheral as PeripheralReq, Pin } from "./requirements";
import { Const } from "../utils";
import * as data from "dataInterfaces";

export const solutionChanged = "Solution has changed";
export const solutionMaybeChanged = "Solution may have changed";

export class SuggestedSolution {
	private readonly missingEntries: (PeripheralReq | Pin)[] = [];

	// Requirement to assignment map
	// Const.ANY means any assignment is valid
	// null means an error was suggested

	private readonly entries = new Map<PeripheralReq | Pin, string>();

	// Does this assignment exist in the set of suggestions?

	public contains(peripheral: data.Peripheral, peripheralReq: PeripheralReq): boolean;
	public contains(devicePin: data.DevicePin, pinReq: Pin): boolean;
	public contains(
		pinOrPeripheral: data.DevicePin | data.Peripheral, req: PeripheralReq | Pin) {
		return this.containsAssignment(pinOrPeripheral.name, req);
	}

	// Is this requirement marked as an error in the set of suggestions?

	public containsError(req: PeripheralReq | Pin) {
		return null === this.getEntry(req);
	}

	public applyWarnings() {

		// If any of the entries don't match what the solver eventually solved for, then likely the
		// solution was invalid (invalid option, two options had the same value etc).  We can find
		// those differences and mark them with a warning.

		this.entries.forEach((_assignedToName, req) => {
			const isError = !_.isEmpty(req.solution.errorText);
			if ((isError && !this.containsError(req)) ||
				(!isError && !this.containsAssignment(req.solution.assignedToName, req))) {
				req.solution.warningText = solutionChanged;
				req.solution.warningDetailsText.push(
					"The suggested solution was invalid.  As such, this specific entry differs from what was suggested");
			}
		});

		// For any missing entries in the solution, maybe the value differs and maybe it doesn't.
		// Either way, mark them with a warning

		_.each(this.missingEntries, (req) => {
			req.solution.warningText = solutionMaybeChanged;
			req.solution.warningDetailsText.push(
				"No suggested solution was provided, so this value may differ from the last time this tool was run");
		});
	}

	private containsAssignment(assignment: string, req: PeripheralReq | Pin) {
		const entry = this.getEntry(req);
		return assignment === entry || Const.ANY === entry;
	}

	private getEntry(req: PeripheralReq | Pin) {

		if (!this.entries.has(req)) {
			if (req.solution.errorText) {
				this.entries.set(req, null);						// Marked as an error
			} else if (req.solution.assignedToName) {
				this.entries.set(req, req.solution.assignedToName);	// Marked a as suggestion
			} else if (req.userOverride) {
				this.entries.set(req, req.userOverride);			// Override: treat as a normal suggestion
			} else {
				this.entries.set(req, Const.ANY);					// Missing entry: treat as "Any" and solve
				this.missingEntries.push(req);						// ... but warn the user of this
			}
		}
		return this.entries.get(req);
	}
}
