import React = require("react");
import { Button } from "../../imports/material-ui-imports";
import { IButtonProps } from "./IButtonProps";
import { ColorIndex } from "../styles/themes";
import { commonStyles } from "../styles/common";

export function SecondaryButton(props: React.PropsWithChildren<Omit<IButtonProps, "style">>) {
	return (
		<Button
			component="span"
			color="primary"
			variant="outlined"
			className={props.disabled ? " disabled-button" : ""}
			disabled={props.disabled}
			onClick={props.onClick}
			id={props.id}
			style={{
				backgroundColor: props.theme.colors[ColorIndex.BUTTONBACKGROUNDCOLOR],
				whiteSpace: "nowrap",
				...commonStyles.button,
				marginBottom: props.theme.theme.spacing(2),
			}}
			size="small"
		>
			{props.children}
		</Button>
	);
}
