import * as React from "react";
import * as _ from "lodash";
import {
	Typography, List, ListItem, ListItemIcon, ListItemText,
} from "../../imports/material-ui-imports";
import { CircleSmall } from "../../imports/mdi-material-ui-imports";

export function UnsupportedInstances(props: { instances: string[] }) {
	const isOrAre = _.size(props.instances) > 1 ? "are" : "is";
	return (
		<React.Fragment>
			<Typography>
				{`The following ${isOrAre} not supported by the new target.  Associated settings were not migrated:`}
			</Typography>
			<List component="nav">
				{_.map(props.instances, (m) => (
					<ListItem >
						<ListItemIcon>
							<CircleSmall />
						</ListItemIcon>
						<ListItemText primary={m} />
					</ListItem>
				))}
			</List>
		</React.Fragment>
	);
}
