import * as React from "react";
import * as _ from "lodash";
import { ExtendedElkNode } from "../layout/customTypes";
import { ClassesType } from "../styling/clockTreeStyles";
import { Validations, ValidationSummary } from "../../../services/objectManagers/validations";
import { INodeProps, NodeComponent } from "./NodeFactory";

// Renders all the nodes with errors/warnings, but ignores selection.  The assumption is that all nodes are rendered
// underneath this component, but with errors/warnings ignored, and thus can be rendered less often.  
// Effectively, this component filters just the nodes with errors/warnings, and then renders just those. 

export interface INodeValidationProps extends Omit<INodeProps, "node" | "selected"> {
	nodes: ExtendedElkNode[];
	validations: Validations; 		// No longer optional
}

export function NodeStatusIndicator(props: INodeValidationProps & ClassesType) {
	const { nodes, treeNode, validations } = props;
	return <>
		{
			_.chain(nodes)
				.filter((node) => _.isEmpty(node.children))
				.filter((node) => {
					const mgr = treeNode.getIpInstanceMgr(node.data.ipInstance.name);
					return validations.getSummary(mgr) !== ValidationSummary.None;
				})
				.map((node) => <NodeComponent {...props} node={node} key={node.id} />)
				.value()
		}
	</>;
}
