	public beginTabCreation() {
		this.clockTreeNodeMap.clear();
	}

	public registerClockTreeNode(treeNode: ITreeNode, views: string[], defaultFor: string[]) {
		_.each(views, (i) => {
			const entry = this.clockTreeNodeMap.get(i) ?? { views: [], defaultViews: [] };
			entry.views.push(treeNode);
			this.clockTreeNodeMap.set(i, entry);
		});
		_.each(defaultFor, (i) => {
			const entry = this.clockTreeNodeMap.get(i) ?? { views: [], defaultViews: [] };
			entry.defaultViews.push(treeNode);
			this.clockTreeNodeMap.set(i, entry);
		});
	}

	public lookupNodes(ipInstance: IPInstance) {
		return this.clockTreeNodeMap.get(ipInstance.name);
	}

	public getValidations() {
		return this.validations;
	}

	public validate() {

		// Note that validation is currently isolated to the context.  This makes implementing validation a bit easier,
		// with the limitation that you can't tag errors on another context.  Since you can still read the state of 
		// another context, that allows you to validate against yourself, so this seems like a reasonable limitation.

		// The algorithm is to reset validation, validate names separately (so we can do one grouping of them all), and
		// finally validate each object

		this.validations.reset();
		const mgrs = [...this.getInterfaceMgrs(), ...this.getModuleMgrs()];
		validateNames(mgrs, this.isCorePinmux(), this.validations);
		_.each(mgrs, (m) => {
			m.validate(this.validations);
		});
	}

	public finalValidate() {

		// Unlike validate, we don't reset the validation as it's expected this happens after solving and extends the 
		// initial validation.  Additionally, only modules support final validation

		_.each(this.getModuleMgrs(), (mod) => mod.finalValidate());
		this.validations.clearUnusedSuppression();
	}

