	// Resets the runtime to have zero configuration, but does not alter the device/board 
	// configuration as that might require meta-content to be re-run

	public reset() {

		// For all added modules/peripherals, remove the $instances/$static data visible to the runtime meta code

		_.each(this.modules, (mod) => {
			clear(mod.$instances);
			mod.$static = null;
		});
		_.each(this.peripherals, (perf) => clear(perf.$instances));

		// Next, clear internal references that module/interface managers maintain

		_.each(this.moduleMgrs, (modMgr) => {
			clear(modMgr.instances);
			modMgr.static = null;
		});
		_.each(this.interfaceMgrs, (intMgr) => {
			clear(intMgr.instances);
		});

		// Clear out our references to created modules/peripherals

		clear(this.modules);
		clear(this.clockTreeInstances);
		this.managersMap.clear();
		this.interfaceMap.clear();
		this.getValidations().reset();

		// Clear out the exclusion information in the code generator

		this.codeGenerator.clearExclusion();

		// Now, do whatever we normally do in the constructor to pre-setup existing content

		configurationChanged();
		this.initClockTreeModules();
	}

	public invalidateProxies() {

		// Ideally this would be part of reset(), but the issue was common enough that we couldn't
		// turn this on without breaking a lot of stuff.  As such, this happens only in testing.

		// This works because the proxy handler throws if memberMgrs is not present

		_.each(this.moduleMgrs, (modMgr) => {
			_.each(modMgr.instances, (i) => {
				delete i.memberMgrs;
			});
			if (modMgr.static) {
				delete modMgr.static.memberMgrs;
			}
		});
	}

