	public getModuleMgr(modulePath: string): ModuleMgr {

		modulePath = this.resolveModulePath(modulePath);
		if (!this.moduleMgrs[modulePath]) {
			const { name, module } = this.loadModule(modulePath);
			if (name !== modulePath) {

				// This module is a proxy.  We don't want to expose it on moduleMgrs as that will 
				// make it appear in places it shouldn't.

				return this.getModuleMgr(name);
			}

			// Non-proxy module - create a manager for it

			this.moduleMgrs[modulePath] =
				(module.uiView === "fileTree")
					? new FileModuleMgr(this, module)
					: new ModuleMgr(this, module);
		}

		return this.moduleMgrs[modulePath];
	}

