	// TODO: Eventually we should make this work across contexts, but for now we are explicitly 
	// disabling this feature in a multi-context setup
	// See https://jira.itg.ti.com/browse/PMUX-2888

	public getAllPinMgrSetToDevicePin(devicePinName: string) {
		if (this.isMultiContext()) {
			return [];
		}
		return _.filter(this.getAllMembersWithSolverReqs(), (i): i is APinMgr<any> => {
			return (i instanceof APinMgr) && i.memberMgrs.$assign.getValue() === devicePinName;
		});
	}

	public getAllInterfaceInstanceSetToPeripheral(peripheralName: string) {
		if (this.isMultiContext()) {
			return [];
		}
		return _.filter(this.getAllMembersWithSolverReqs(), (i): i is InterfaceInstanceMgr => {
			return (i instanceof InterfaceInstanceMgr) && i.memberMgrs.$assign.getValue() === peripheralName;
		});
	}

