	public serialize(partialOptions: Partial<SerializationOptions> = {}, scriptPath: string = null) {
		const options = {
			...defaultSerializationOptions,
			...partialOptions,
		};

		setSerializeProjectPath(scriptPath);

		// Boosterpacks must be at the top, as board layout must be known prior to importing modules

		const statements = [
			...this.serializeFileOwnership(),
			...this.serializeBoosterPacks(options),
			...this.serializeModules(options),
			...this.serializeInterfaces(options),
		];

		// Move all $suggestedSolution assignments to the bottom

		const [bottom, top] = _.partition(statements,
			(statement) => (statement instanceof SuggestedSolutionAssignment));

		if (_.isEmpty(bottom)) {
			return top;
		}

		return [
			...top,
			new BlockComment("Pinmux solution for unlocked pins/peripherals. " +
				"This ensures that minor changes to the automatic solver in a future version of the tool will not impact the " +
				"pinmux you originally saw.  These lines can be completely deleted in order to re-solve from scratch."),
			...bottom,
		];
	}

