import * as React from "react";
import * as _ from "lodash";
import { LineComponent } from "./LineComponent";
import { ExtendedElkLine } from "../layout/customTypes";
import { ClassesType } from "../styling/clockTreeStyles";
import { Port } from "clockTree";

// This component renders a collection of lines

interface ILineProps {
	lines: ExtendedElkLine[];
	onMouseEnter: (line: ExtendedElkLine) => void;
	onMouseLeave: () => void;
	onClick: (line: ExtendedElkLine) => void;
	selectedSignalPath: Port[];
	highlightSignalPath: Port[];
}

export class Lines extends React.Component<ILineProps & ClassesType> {
	public override render() {
		const { lines, classes, onMouseEnter, onMouseLeave, onClick, selectedSignalPath, highlightSignalPath } = this.props;
		return <>
			{_.map(lines, (line) => {
				return <LineComponent
					key={`${line.start.x}_${line.start.y}_${line.end.x}_${line.end.y}_line`}
					edge={line}
					classes={classes}
					onMouseEnter={onMouseEnter}
					onMouseLeave={onMouseLeave}
					onClick={onClick}
					selected={isInSignalPath(line, selectedSignalPath)}
					highlight={isInSignalPath(line, highlightSignalPath)}
				/>;
			})}
		</>;
	}

	public override shouldComponentUpdate(nextProps: Readonly<ILineProps & ClassesType>) {
		// We are taking a shortcut here because we know how the parent works.  It will never send us new callbacks as 
		// those are assigned on component construction.  It won't change classes as that is fixed to the theme which 
		// is fixed to cli args.  And it won't send us new lines without doing a new layout, which will unmount us.  As
		// such, we can just look at the signal path.  

		// However, the signal path is calculated in render (as it could change when configurables change) so it will 
		// be a new array each time, even if the contents are the same.  As such, we compare contents

		return !_.isEqual(this.props.selectedSignalPath, nextProps.selectedSignalPath) ||
			!_.isEqual(this.props.highlightSignalPath, nextProps.highlightSignalPath);
	}
}

function isInSignalPath(line: ExtendedElkLine, signalPath: Port[]) {
	return _.some(signalPath, (dest) =>
		_.some(line.data.edges, (e) => {
			if (_.startsWith(e.target.instName, "$broken")) {
				return _.some(e.signal.targets, (t) => t.instName === dest.instName && t.pinName === dest.pinName);
			}
			return e.target.instName === dest.instName && e.target.pinName === dest.pinName;
		})
	);
}
