import React = require("react");
import * as _ from "lodash";
import ReactDOM = require("react-dom");
import { ErrorModal } from "../../components/modals/ErrorModal";
import { ConfirmModal } from "../../components/modals/ConfirmModal";
import { IModalService } from "../IModalService";
import { InvalidMinToolVersion } from "../product/versionCheck";
import { UpdateModal } from "../../components/modals/UpdateModal";
import { ATheme } from "../../components/styles/themes";
import { UseCustomBoard } from "../../components/modals/UseCustomBoard";
import { ITarget, SwitchBoardOrDevice } from "../../components/modals/SwitchBoardOrDevice";
import { ProgressBar } from "../../components/ProgressBar";
import { ThemeProvider, Typography } from "../../imports/material-ui-imports";
import { UnsupportedInstances } from "../../components/modals/UnsupportedInstances";
import { ITargetID } from "../migration/migrate";
import { MigrationOptions } from "../migration/migrationOptions";

export class ModalService implements IModalService {

	// the base mount-point is modalRoot
	private mountPoints: HTMLElement[] = [document.getElementById("modalRoot")];

	constructor(public theme: ATheme) { }

	public showModal(
		title: string,
		content: JSX.Element | string,
		onClose = () => { },
		hideTitleIcon?: boolean,
	) {
		this.showConfirmModal(title, content, null, onClose, null, "OK", hideTitleIcon);
	}

	public showUseCustomBoardModal(currentBoard: string, confirmAction: (lockSolutionFirst: boolean) => void) {
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<UseCustomBoard
					currentBoard={currentBoard}
					confirmAction={
						(lockSolutionFirst) => {
							this.closeModal();
							confirmAction(lockSolutionFirst);
						}
					}
					cancelAction={this.closeModal}
					registerSubModalMountPoint={this.handleMountPointRef}
					theme={this.theme}
				/>
			</ThemeProvider>,
			_.last(this.mountPoints),
		);
	}

	public showIncompatibleInstances(instances: string[]) {
		return new Promise<void>((resolve) => {
			this.showModal(
				"Incompatible Software and/or Peripherals",
				<UnsupportedInstances instances={instances} />,
				resolve,
			);
		});
	}

	public showSwitchBoardOrDeviceModal(
		currentTarget: ITarget,
		migrationOptions: MigrationOptions,
		confirmAction: (newTarget: ITargetID, lockSolutionFirst: boolean) => void,
	) {
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<SwitchBoardOrDevice
					currentTarget={currentTarget}
					migrationOptions={migrationOptions}
					confirmAction={
						(newTarget, lockSolutionFirst) => {
							this.closeModal();
							confirmAction(newTarget, lockSolutionFirst);
						}
					}
					cancelAction={this.closeModal}
					registerSubModalMountPoint={this.handleMountPointRef}
					theme={this.theme}
				/>
			</ThemeProvider>,
			_.last(this.mountPoints),
		);
	}

	public async showProgressDuring<T>(title: string, operation: () => Promise<T>) {
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<ProgressBar id="progressModal" title={title} />;
			</ThemeProvider>,
			_.last(this.mountPoints),
		);
		try {
			return await operation();
		} finally {
			this.closeModal();
		}
	}

	public showUpdateModal(error: InvalidMinToolVersion, confirmAction: () => void) {
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<UpdateModal
					error={error}
					theme={this.theme}
					registerSubModalMountPoint={this.handleMountPointRef}
					confirmAction={
						() => {
							this.closeModal();
							confirmAction();
						}
					} />
			</ThemeProvider>,
			_.last(this.mountPoints),
		);
	}

	public showOhSnapErrorModal(error: Error, onClose: () => void = () => { }) {
		this.showErrorModal(
			"Oh Snap! The last change caused an exception...",
			error,
			onClose,
		);
	}

	public showErrorModal(title: string, error: Error, onClose: () => void = () => { }, onConfirm?: () => void,
		confirmText?: string, cancelText?: string, content?: string) {
		const confirmAction = onConfirm ? () => { this.closeModal(); onConfirm(); } : null;
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<ErrorModal
					theme={this.theme}
					id={"errorModal"}
					title={title}
					error={error}
					onClose={() => {
						this.closeModal();
						onClose();
					}}
					onConfirm={confirmAction}
					confirmText={confirmText}
					cancelText={cancelText}
					registerSubModalMountPoint={this.handleMountPointRef}
					content={content}
				/>
			</ThemeProvider>,
			_.last(this.mountPoints),
		);
	}

	public showConfirmModal(
		title: string,
		content: JSX.Element | string,
		confirmCallback?: () => void,
		cancelCallback?: () => void,
		confirmText?: string,
		cancelText?: string,
		hideTitleIcon?: boolean,
	) {
		const confirmAction = !confirmCallback ? null :
			() => {
				this.closeModal();
				confirmCallback();
			};
		ReactDOM.render(
			<ThemeProvider theme={this.theme.theme}>
				<ConfirmModal
					hideTitleIcon={hideTitleIcon}
					id={"confirmationModal"}
					title={title}
					confirmAction={confirmAction}
					cancelAction={
						() => {
							this.closeModal();
							if (cancelCallback) {
								cancelCallback();
							}
						}
					}
					confirmText={confirmText}
					cancelText={cancelText}
					registerSubModalMountPoint={this.handleMountPointRef}
					theme={this.theme}
				>
					{(typeof content === "string") ?
						(<Typography variant="body2" style={{ whiteSpace: "pre" }}>
							{content}
						</Typography>) : (content)}
				</ConfirmModal>
			</ThemeProvider>,
			_.last(this.mountPoints),
		);
	}

	public reset() {
		while (_.size(this.mountPoints) > 1) {
			this.closeModal();
		}
	}

	private closeModal = () => {
		// remove the next mount point that hasn't been used yet
		if (_.size(this.mountPoints) > 1) {
			this.mountPoints = _.dropRight(this.mountPoints);
		}

		// un-mount the top-most modal so that another can be mounted if needed
		ReactDOM.unmountComponentAtNode(_.last(this.mountPoints));
	}

	// callback to obtain the reference to the next mount point
	private handleMountPointRef = (el: HTMLElement) => {
		if (el) {
			this.mountPoints.push(el);
		}
	}
}
