/* eslint-disable no-bitwise */
import * as _ from "lodash";
// ------------------------------------------------------------------------------------------------
// Choices
// This file represents a singleton that is a collection of choices that must be made in order to 
// solve for the current set of requirements.  It's basically an array with some extra utility 
// functions.
//
// Note that a "choice" here is unknown boolean value (true/false) which if true means the real-
// world choice it maps to is "taken", but if false means that some other choice is "taken".  
// Later, clauses (boolean algebra expressions) will relate the choices to each other.
//
// As such, a "choice" is the same as a "literal" in glucose (our 3rd party SAT solver).  Glucose 
// requires it's literals to be identified by an index starting at 1 and increasing, without 
// skipping any numbers.  This is because 1) the literal values (true/false/unknown) are stored in 
// an array and referred to by index and 2) because then a false literal can be represented by a 
// negative value (negative it's index), meaning 0 cannot be a valid literal id.
// ------------------------------------------------------------------------------------------------

import { glucoseModule, addAssumptions, changeAssumption, solve as gfSolve } from "./glucoseFunctions";
import { debug, log, textBasedClauses } from "./debug";
import { Peripheral, Pin } from "./requirements";

export interface SolutionMap {
	peripherals: { [peripheralName: string]: Peripheral[] };
	peripheralPins: { [interfacePinName: string]: Pin[] };
	devicePins: { [devicePinName: string]: Pin[] };
}

export interface ApplyableChoice {

	// Called once we've decided the choice has been taken.  
	// There is no callback for un-taken choices

	apply(solutionMap: SolutionMap): void;
}

interface SolveableChoice extends ApplyableChoice {

	// The way to refer to this specific choice in glucose (literal value)

	readonly id: number;

	// For debug purposes only - always undefined in production
	readonly name?: string;
}

interface ErrorChoice extends SolveableChoice {

	// True if choosing this error frees up a GPIO pin

	readonly restrictsGPIO: boolean;
}

// A GPIO choice for the optimized GPIO method
// Instead of giving something to the solver, we create a choice for either "pick a GPIO" or "this 
// is an error".  We don't hand it to the solver, but keep track of free GPIO pins, and then apply
// the pin choice or the error based on the error resolution code

class GPIOChoice {
	public readonly pinChoice: ApplyableChoice;
	public readonly errorChoice: ApplyableChoice;
	public chosenChoice: ApplyableChoice;
	public readonly restrictsGPIO = true;
	constructor(pinChoice: ApplyableChoice, errorChoice: ApplyableChoice) {
		this.pinChoice = pinChoice;
		this.errorChoice = errorChoice;
		this.chosenChoice = pinChoice;
	}
}

// How many GPIO pins are free to pick from, considering other choices

let availableGPIOPins: number;

// True if we can optimize GPIO choices outside of the solver

let isGPIOOptimizable: boolean;

// Array of all choices that are passed to the solver
// Index 0 is a dummy index, as that's never a valid literal (see summary above)

let choices: SolveableChoice[];

// Error choices are also stored here.  If "taken" they are stored in "error".

let errors: {
	error: {
		[key: string]: ErrorChoice | GPIOChoice,
	},
	valid: {
		[key: string]: ErrorChoice | GPIOChoice,
	},
};

// An assumption is a glucose literal that has a assumed value before solving, and can be changed
// in order to re-solve with the different assumptions.  As such, it represents errors/warnings or
// pin minimization.  It must also be a choice and thus in "choices" above

let assumptions: { [key: string]: SolveableChoice };

// Errors are always created after all system choices are made.  All the choice factory files 
// create choices, then add errors when generating clauses.  As such, instead of storing them 
// separately, we just keep track of the index to the first error.  Assumptions (warnings, pin
// minimizations) are generated next, so the first assumption is just a later index.
// This isn't really ideal, but it works and changing it would be somewhat non-trivial.

let firstError: number;
let firstAssumption: number;

// The GPIO choices that are outside of the solver

let requiredGPIOPins: GPIOChoice[];

// Errors that initially we assume to be true

let initiallyAssumedErrors: string[];

export function reset(_availableGPIOPins: number, _isGPIOOptimizable: boolean) {

	availableGPIOPins = _availableGPIOPins;
	isGPIOOptimizable = _isGPIOOptimizable;

	choices = [{ id: 0, apply() { } }]; // Index 0 must be empty
	errors = {
		error: {},
		valid: {},
	};
	assumptions = {};
	firstError = 0;
	firstAssumption = 0;
	requiredGPIOPins = [];
	initiallyAssumedErrors = [];
}

export function push(choice: SolveableChoice) {
	choices.push(choice);
	return choices.length - 1;
}

export function pushGPIO(pinChoice: ApplyableChoice, errorChoice: ApplyableChoice, name: string) {
	const gpioChoice = new GPIOChoice(pinChoice, errorChoice);
	requiredGPIOPins.push(gpioChoice);
	errors.valid[name] = gpioChoice;
}

export function pushError(choice: ErrorChoice, name: string, assumeError2 = false) {
	const id = push(choice);
	errors.valid[name] = choice;
	if (assumeError2) {
		initiallyAssumedErrors.push(name);
	}
	if (0 === firstError) {
		firstError = id;
	}
	if (choice.restrictsGPIO) {
		--availableGPIOPins;
	}
	return id;
}

export function pushAssumption(choice: SolveableChoice, name: string) {
	const id = push(choice);
	assumptions[name] = choice;
	if (0 === firstAssumption) {
		firstAssumption = id;
	}
	return id;
}

export function apply(solutionAddy: number, solutionMap: SolutionMap) {
	// Fetch all the true choices in the solution

	let heap32Offset = solutionAddy >> 2;
	let choice = glucoseModule.HEAP32[heap32Offset++];
	const solution = [];
	while (choice) {
		solution.push(choice);
		choice = glucoseModule.HEAP32[heap32Offset++];
	}

	// Optionally log them out

	if (textBasedClauses) {
		log("solution:");
		log(solution.join(", "));
	}

	// Due to side effects, we MUST apply the solution from the lowest 
	// choice variable to the highest

	_.each(solution, (i) => choices[i].apply(solutionMap));

	// Also apply GPIO choices solved for from the remaining pins
	_.each(requiredGPIOPins, (pin) => {
		pin.chosenChoice.apply(solutionMap);
	});
}

export function numChoices() {
	return choices.length - 1;
}

export function numAssumptions() {
	// Technically, errors are implemented as assumptions, so return the error count
	// plus the non-error assumption count

	const errorAssumptions = firstAssumption - firstError;
	return errorAssumptions + _.size(assumptions);
}

export function generateHeaderComments() {
	let text = "";
	for (let i = 1; i < choices.length; ++i) {
		text += "c " + i + " " + choices[i].name + "\n";
	}
	return text;
}

export function initializeAssumptions() {
	// We initially assume no errors (unless otherwise stated), but some warnings.  
	// If that doesn't work, we'll start assuming some errors to find a valid 
	// solution.  If it does work, we'll then start assuming less warnings to
	// find the best solution.

	if (0 !== firstError) {
		addAssumptions(firstError, numChoices(), false);
		if (0 !== firstAssumption) {
			for (let i = firstAssumption; i < choices.length; ++i) {
				changeAssumption(i, true);
			}
		}
		_.each(initiallyAssumedErrors, assumeError);
	}
}

export function assumeError(name: string) {
	if (name in errors.valid) {
		if (debug) {
			log("Error: " + name);
		}
		const errorChoice = errors.valid[name];
		errors.error[name] = errorChoice;
		delete errors.valid[name];
		if (errorChoice instanceof GPIOChoice) {
			errorChoice.chosenChoice = errorChoice.errorChoice;
		} else {
			changeAssumption(errorChoice.id, true);
		}
		if (errorChoice.restrictsGPIO) {
			++availableGPIOPins;
		}
	}
}

export function assumeNoError(name: string) {
	if (name in errors.error) {
		if (debug) {
			log("Valid: " + name);
		}
		const errorChoice = errors.error[name];
		errors.valid[name] = errorChoice;
		delete errors.error[name];
		if (errorChoice instanceof GPIOChoice) {
			errorChoice.chosenChoice = errorChoice.pinChoice;
		} else {
			changeAssumption(errorChoice.id, false);
		}
		if (errorChoice.restrictsGPIO) {
			--availableGPIOPins;
		}
	}
}

export function assume(name: string, value: boolean) {
	changeAssumption(assumptions[name].id, value);
}

function areGPIOPinsAvailable(setGPIOPinsNeeded: (amountShort: number) => boolean) {
	if (isGPIOOptimizable) {
		if (requiredGPIOPins.length > availableGPIOPins) {
			return setGPIOPinsNeeded(requiredGPIOPins.length - availableGPIOPins);
		}
		return setGPIOPinsNeeded(0);
	}
	return true;
}

export function solve(setGPIOPinsNeeded: (amountShort: number) => boolean) {
	if (textBasedClauses) {
		let text = "Assumptions:\n";
		_.each(errors.error, (choice) => {
			if (!(choice instanceof GPIOChoice)) {
				text += choice.id + " 0 c assume true\n";
			}
		});
		_.each(errors.valid, (choice) => {
			if (!(choice instanceof GPIOChoice)) {
				text += -choice.id + " 0 c assume false\n";
			}
		});
		log(text);
	}

	return areGPIOPinsAvailable(setGPIOPinsNeeded) && gfSolve();
}
