import * as _ from "lodash";

import React = require("react");
import { PinSelectRow } from "./pin";
import { mapInOrder } from "../../../components/ComponentUtils";
import {
	ConfigurableHeader,
	EnumerationHeader,
	NameToConfigurableHeader,
	BooleanHeader,
} from "./header";
import { MultiPinMgr } from "../multiPin";
import { IPinsViewProvider } from "../pins";
import { naturalSort, getDisplayName } from "../../utils";
import { CheckBox } from "../../../components/CheckBox";
import { IFormatter } from "../../formatting/formattingTypes";
import { DropDown } from "../../../components/DropDown";
import { TableRow, TableCell, IconButton } from "../../../imports/material-ui-imports";
import { Tooltip } from "../../../components/Tooltip";
import { SwapVertical } from "../../../imports/mdi-material-ui-imports";
import { IGlobalServiceProps } from "../../../components/IGlobalServicesProps";
import { commonStyles, CommonClasses, withCommonStyles } from "../../../components/styles/common";
import { ResourceLoader } from "../../resources/metaContentLoaders/resourceLoader";
import { PinMemberMgr, ExtendedPinMemberMgr } from "../pinObjectMembers";
import { ConfigStoreActions } from "../../configStore";
import { sortAlpha } from "../../toolTip";
import { CValidation } from "./validation";
import { Validations } from "../validations";
import { PinDisplayType } from "../../userPreferences";

const tableHeadingAlignStyle: React.CSSProperties = {
	display: "inline",
};

interface IPinRequirementsProps {
	pinsProvider: IPinsViewProvider;
	formatter: IFormatter;
	validations: Validations;
	resourceLoader: ResourceLoader;
	actions: ConfigStoreActions;
	highlightedMember: string;
	keyPrefix: string;
	displayScriptName: boolean;
	devicePinDisplayType: PinDisplayType[];
	headerPinDisplayType: PinDisplayType[];
	productLookupName: string;
	showUsed: boolean;
	showPinTable: boolean;
	columns?: number;
	withoutHeader?: boolean;
}

interface IState {
	sortDescending: boolean;
}

const headerCellStyle = _.omit(commonStyles.tableCellStyle, "borderStyle");

class StyledPinRequirements extends React.Component<IPinRequirementsProps & IGlobalServiceProps & CommonClasses, IState> {

	// keep track of sorting order between all instances
	private static sortDescending: boolean = false;
	private static sortPinInstances(pinInstances: (ExtendedPinMemberMgr | PinMemberMgr)[]) {
		let sorted = naturalSort(pinInstances, (p) => p.valueObjectMgr.getName());
		if (StyledPinRequirements.sortDescending) {
			sorted = sorted.reverse();
		}
		return sorted;
	}

	constructor(props: IPinRequirementsProps & IGlobalServiceProps & CommonClasses) {
		super(props);
		this.state = {
			sortDescending: StyledPinRequirements.sortDescending,
		};
	}

	public override render() {
		const provider = this.props.pinsProvider;
		const headerConfigurablesOrder = _.sortBy(_.keys(provider.getPinConfigurablesHeaders()));
		const renderAsTable = this.props.showPinTable || !_.isEmpty(headerConfigurablesOrder);
		const pinMemberMgrs = provider.getPinMemberMgrs();
		const sortedSinglePinReqs = renderAsTable ? StyledPinRequirements.sortPinInstances(pinMemberMgrs) : pinMemberMgrs;
		const multiPinInstance = provider.getMultiPinMgr();

		return (
			<React.Fragment>
				{
					renderAsTable && !this.props.withoutHeader && !_.isEmpty(pinMemberMgrs) &&
					this.renderPinHeader(headerConfigurablesOrder)
				}
				{this.renderPinInstances(sortedSinglePinReqs, headerConfigurablesOrder, !multiPinInstance, renderAsTable)}
				{
					multiPinInstance &&
					this.renderMultiPinHeader(multiPinInstance, headerConfigurablesOrder)
				}
				{
					multiPinInstance &&
					this.renderMultiPinRequirements(multiPinInstance, headerConfigurablesOrder)
				}
			</React.Fragment>
		);
	}

	private renderPinHeader(headerConfigurablesOrder: string[]) {
		const provider = this.props.pinsProvider;
		const selectAll = provider.isSelectAllEnabled();

		return <TableRow
			key="labels"
			style={{ border: this.props.theme.border }}
			className={this.props.classes.unselectedTableRowStyle}
		>
			<TableCell key="checkbox" style={headerCellStyle}>
				{this.props.showUsed &&
					<Tooltip title="Toggle All signals">
						<CheckBox
							id="Signals"
							onChange={(value: boolean) => {
								this.props.actions.setSelectAll(provider, value);
							}}
							value={selectAll}
							disabled={false}
						/>
					</Tooltip>
				}
				<span>Signals</span>
				<IconButton title={sortAlpha} style={{ padding: 6 }}
					onClick={() => {
						this.setState((prevState: IState) => {
							StyledPinRequirements.sortDescending = !prevState.sortDescending;
							return {
								sortDescending: StyledPinRequirements.sortDescending,
							};
						});
					}}>
					<SwapVertical
						id="reverseSortSignalsBtn"
						style={{ ...commonStyles.smallIcon }}
					/>
				</IconButton>
			</TableCell >
			<TableCell key="devicePins" id="req2Col2Head" style={headerCellStyle}>
				Pins
			</TableCell>
			{this.renderHeaderConfigurableLabels(headerConfigurablesOrder, provider.getPinConfigurablesHeaders())}
		</TableRow>;
	}

	private renderHeaderConfigurableLabels(
		headerConfigurablesOrder: string[],
		headers: NameToConfigurableHeader) {

		return mapInOrder(
			headers,
			headerConfigurablesOrder,
			(header: ConfigurableHeader) => {
				const id = "header" + header.name;

				if (header.isHidden()) {
					return (<TableCell key={header.name} style={headerCellStyle}></TableCell>);
				}

				return (<TableCell
					key={header.name}
					style={headerCellStyle}
				>
					<span
						className="headerItemLabel"
						id={"hdlbl" + header.name}
					>
						<span style={{ ...commonStyles.noWrap, display: "block" }} >
							{getDisplayName(header, this.props.displayScriptName)}
						</span>
						{
							header instanceof EnumerationHeader &&
							<span style={{ fontWeight: 400 }}>
								<DropDown
									id={id}
									disabled={header.isReadOnly()}
									enabledOptions={header.options}
									selectedOptionName={header.getSelectedOption().name}
									onChange={(val: string) => this.props.actions.setHeaderValue(header, val)}
									displayScriptName={this.props.displayScriptName}
								/>
							</span>
						}
						{
							header instanceof BooleanHeader &&
							<CheckBox
								id={id}
								disabled={header.isReadOnly()}
								value={header.getValue()}
								onChange={(val: boolean) => this.props.actions.setHeaderValue(header, val)}
							/>
						}
					</span>
				</TableCell>
				);

			});
	}

	private renderMultiPinHeader(multiPin: MultiPinMgr, headerConfigurablesOrder: string[]) {
		const colSpan = this.props.columns || (_.size(headerConfigurablesOrder) + 2);
		return (

			<TableRow
				style={{ border: this.props.theme.border }}
				className={this.props.classes.unselectedTableRowStyle}
			>
				<TableCell key="checkbox" style={commonStyles.tableCellStyle} colSpan={colSpan}>
					<CheckBox
						id="multiToggle"
						onChange={(value: boolean) => this.props.actions.setSelectAll(multiPin, value)}
						value={multiPin.getSelectAll()}
						disabled={false}
					/>
					<span style={tableHeadingAlignStyle}>Any</span>
					<div style={{ display: "inline-block", margin: 5 }}>
						<DropDown
							id="selectMultiPinCount"
							disabled={false}
							enabledOptions={_.map(multiPin.getNumOfPinsOptions(), (option) => ({ name: option.name.toString() }))}
							selectedOptionName={multiPin.getSelectedOption().name.toString()}
							onChange={(val: string) => this.props.actions.setCount(multiPin, Number(val))}
							displayScriptName={false}
						/>
					</div>
					<span style={tableHeadingAlignStyle}>of the following pins:
						<CValidation
							validatableObj={multiPin}
							validations={this.props.validations}
							formatter={this.props.formatter}
							actions={this.props.actions}
						/>
					</span>
				</TableCell>
			</TableRow>
		);
	}

	private renderMultiPinRequirements(multiPin: MultiPinMgr, headerConfigurablesOrder: string[]) {
		const pinReqs = StyledPinRequirements.sortPinInstances(multiPin.getPinMemberMgrs());
		return this.renderPinInstances(pinReqs, headerConfigurablesOrder, true, true);
	}

	private renderPinInstances(
		pinMemberMgrs: (ExtendedPinMemberMgr | PinMemberMgr)[],
		headerConfigurablesOrder: string[],
		isLastGroup: boolean,
		renderAsTable: boolean,
	) {
		const last = _.last(pinMemberMgrs);
		return _.map(pinMemberMgrs, (pinMemberMgr) =>
			<PinSelectRow
				{...this.props}
				key={`${this.props.keyPrefix}${pinMemberMgr.def.name}`}
				memberMgr={pinMemberMgr}
				configurablesOrder={headerConfigurablesOrder}
				borderSides={renderAsTable}
				borderBottom={pinMemberMgr === last && isLastGroup && renderAsTable}
			/>);
	}
}

export const PinRequirements = withCommonStyles(StyledPinRequirements);
