import * as _ from "lodash";
import * as path from "path";
import { fs } from "../fileSystem";
import { runTemplate } from "./templateRunner";
import { CodeGenTemplateFile, MetaViewTemplateFile } from "dataInterfaces";
import { Runtime } from "../resources/runtime";
import { Module } from "public/runtime";
import { isNode } from "../platform";
import { getDuplicates } from "../utils";
import { ITreeNode } from "../../components/TreeNode";
import { createFileOwnershipStatement } from "../scripting/serialize";

export const enum TemplateSelectionType {
	ALL,
	EXCLUDED,
	INCLUDED,
}

export interface GeneratedCode {
	fileName: string;
	contents: string;
	isExecutable?: boolean;
}
export class ViewGenerator {

	constructor(
		private readonly runtime: Runtime,
		private readonly views: MetaViewTemplateFile[],
	) {
	}

	public getViewTemplates() {
		return this.views;
	}

	public generate(view: MetaViewTemplateFile, selectedTreeNode: ITreeNode) {
		return new Promise<string>((resolve, reject) => {

			if (!view.ignoreErrors && this.runtime.hasErrors()) {
				return reject("View cannot be displayed when configuration errors exist");
			}

			const output = runTemplate(view, this.runtime.getResourceLoader(), [selectedTreeNode.getRuntimeSelection()]);
			resolve(output);
		});
	}
}

export class CodeGenerator {

	constructor(
		private readonly runtime: Runtime,
		private readonly modules: { [moduleName: string]: Module },
		private readonly templates: CodeGenTemplateFile[],
	) {
	}

	public getTemplates(assumeNoErrors = false, type: TemplateSelectionType = TemplateSelectionType.INCLUDED) {
		const runtimeHasErrors = !assumeNoErrors && this.runtime.hasErrors();
		const templates = _.filter(this.templates, (template) => {
			return (template.ignoreErrors || !runtimeHasErrors) && // runtime error condition
				this.templateModuleIsIncluded(template) && // module condition
				(
					type === TemplateSelectionType.ALL ||
					type === TemplateSelectionType.EXCLUDED && !!template.excluded ||
					type === TemplateSelectionType.INCLUDED && !template.excluded
				); // exclusion condition
		});
		const duplicates = getDuplicates(templates, (t) => t.name);
		if (!_.isEmpty(duplicates)) {
			throw new Error(`The following templates are declared more than once: ${duplicates}`);
		}
		return templates;
	}

	// get template from template path
	public getTemplate(fileName: string) {
		const template = _.find(this.templates, (t) => t.path === fileName);
		if (!template) {
			throw new Error(`No such template : ${fileName}, available templates ${_.map(this.templates, (t) => t.path)}`);
		}
		return template;
	}

	// get templates from output path
	public getTemplatesOfGenerated(outputPath: string) {
		const templates = _.filter(this.templates, (t) => t.name === outputPath);
		if (_.isEmpty(templates)) {
			throw new Error(`No template generate to ${outputPath}`);
		}
		return templates;
	}

	public generate(template: CodeGenTemplateFile) {
		return new Promise<string>((resolve, reject) => {

			// Generate arguments for the template

			const args = _.chain(this.modules)
				.filter((module) => module.templates && template.path in module.templates)
				.map((module) => module.templates[template.path])
				.value();

			// Determine if it's valid to run this template right now

			if (!_.some(this.templates, (t) => template.name === t.name && template.path === t.path)) {
				return reject(`The current context does not generate ${template.name}`);
			}
			if (!template.alwaysRun && _.isEmpty(args)) {
				return reject(`The current configuration no longer generates ${template.name}`);
			}
			if (!template.ignoreErrors && this.runtime.hasErrors()) {
				return reject(`${template.name} is not generated when configuration errors exist`);
			}

			// Actually run the template

			const output = runTemplate(template, this.runtime.getResourceLoader(), args);
			resolve(output);
		});
	}

	public generateAll(templates: CodeGenTemplateFile[]): Promise<GeneratedCode[]> {
		return Promise.all(_.map(templates, (template) => {
			return this.generate(template)
				.then((contents) => {
					return {
						fileName: template.excluded ? path.join("excluded", template.name) : template.name,
						contents,
						isExecutable: template.isExecutable,
					};
				});
		}));
	}

	public clearExclusion() {
		_.each(this.templates, (t) => {
			t.excluded = false;
		});
	}

	public exclude(template: CodeGenTemplateFile, value: boolean) {
		template.excluded = value;
	}

	public serialize() {
		return _.map(this.getTemplates(true, TemplateSelectionType.EXCLUDED), (f) => createFileOwnershipStatement(f.name));
	}

	private templateModuleIsIncluded(template: CodeGenTemplateFile) {
		return template.alwaysRun || _.some(this.modules, (module) => module.templates && template.path in module.templates);
	}
}

export function writeOutputFiles(
	baseOutputDirPath: string, allGenerated: GeneratedCode[], logProgress: (message: string) => void = () => { }) {
	if (!isNode()) {
		throw new Error("writeOutputFiles is only valid in a node environment");
	}
	_.each(allGenerated, (generated) => {
		const outFilePath = path.join(baseOutputDirPath, generated.fileName);
		const outputFileDir = path.dirname(outFilePath);
		fs.mkdir(outputFileDir, { recursive: true });
		if (fs.fileExists(outFilePath) && fs.readFile(outFilePath) === generated.contents) {
			logProgress("Unchanged " + outFilePath);
		} else {
			logProgress("Writing " + outFilePath);
			fs.writeFile(outFilePath, generated.contents, { mode: generated.isExecutable ? 0o777 : 0o666 });
		}
	});
}
