import { ModuleInstanceMgr } from "./moduleInstance";
import * as _ from "lodash";
import { ModuleInstanceArray } from "public/runtime";
import { SerializationOptions } from "../scripting/toScript";
import { createChildIdentifier } from "../scripting/serialize";
import { getDisplayName } from "../utils";
import { ModuleMgr } from "../instanceContainers/module";
import { Runtime } from "../resources/runtime";
import { AInstanceContainer } from "../instanceContainers/instanceContainer";
import { ModuleInstanceAdderRequirement, InstanceArgs } from "public/defs";
import { Node, MatchedPathRetType } from "./viewNodes";
import { InstanceArgType } from "./member";
import { getRemovedArgs, getUpdatedArgs, getNewArgs } from "./moduleArgs";
import { guardScriptingFunction } from "../scripting/scriptingGuard";
import { internalBoundary } from "../niceExceptions";
// This class contains the actual instances that the instance adder create.
// So it has all the functionalities to manipulate the instance array.
// This is also implementing the viewNode logic for the leaf node.
export class ModuleInstanceAdderMgr extends AInstanceContainer<ModuleInstanceMgr> implements Node {
	public userShowLongDescPref = false;
	public readonly type = "instanceArrayLeafNode";
	private readonly moduleMgr: ModuleMgr;

	constructor(
		public readonly def: ModuleInstanceAdderRequirement,
		runtime: Runtime,
		private readonly instanceCreator:
			(adderMgr: ModuleInstanceAdderMgr, index: number) => ModuleInstanceMgr,
	) {
		super(def.name);
		this.moduleMgr = runtime.getModuleMgr(def.moduleName);
	}

	public add(num: number) {
		if (this.getNumberOfUsed() + num > this.getMaxAllowed()) {
			throw Error(`Maximum amount of instances exceeded in ${this.getName()}`);
		}
		if (this.getFixedArgsLength() > this.getMinInstanceCount()) {
			throw Error("fixedArgs length should not exceed minInstanceCount");
		}
		if (this.getFixedRequiredArgsLength() > this.getMinInstanceCount()) {
			throw Error("fixedRequiredArgs length should not exceed minInstanceCount");
		}
		const newInstArray = _.map(_.range(num), (i) => {
			return this.instanceCreator(this, i + this.getNumberOfUsed());
		});
		this.instances.push(...newInstArray);
	}

	public create(num: number) {
		if (_.isInteger(num) && num >= 0) {
			if (num > 512) {
				throw Error(`Instance creation limit(512) exceeded:${num}`);
			}
			if (num < this.getMinInstanceCount()) {
				throw Error(`Minimum instance count violated in ${this.getName()}`);
			}
			this.destroyAll();
			this.add(num);
		}
	}

	public getName() {
		return this.def.name;
	}

	public override getID() {
		return this.getName();
	}

	public getDisplayName(displayScriptName: boolean) {
		return getDisplayName(this.def, displayScriptName);
	}

	public getNonInstUsedPins() {
		return new Set<string>();
	}

	public override getInstances() {
		return this.instances;
	}

	public updateArgs(newReq: ModuleInstanceAdderRequirement, parentObjectMgr: any) {
		const removedArgs = getRemovedArgs(this.def.args, newReq.args);
		const updatedArgs = getUpdatedArgs(this.def.args, newReq.args);
		const newArgs = getNewArgs(this.def.args, newReq.args);

		_.each(this.instances, (inst) => {
			inst.removeArgs(removedArgs);
			inst.removeReqArgs(this.def.requiredArgs, parentObjectMgr);
			inst.setValueFromRequiredArgs(newReq.requiredArgs, parentObjectMgr);
			inst.setValueFromArgs(newArgs, InstanceArgType.META);
			inst.setValueFromArgs(updatedArgs, InstanceArgType.META);
		});

		this.def.requiredArgs = newReq.requiredArgs;
		this.def.args = newReq.args;
	}

	public removeArgs(args: InstanceArgs) {
		_.each(this.instances, (inst) => {
			inst.removeArgs(args);
		});
	}

	public removeReqArgs(args: InstanceArgs, origin: ModuleInstanceMgr) {
		_.each(this.instances, (inst) => {
			inst.removeReqArgs(args, origin);
		});
	}

	public override getInstanceScriptIdentifier(inst: ModuleInstanceMgr) {
		const id = this.indexOf(inst);
		return createChildIdentifier(this.getScriptIdentifier(), id);
	}

	public getInstanceDisplayIdentifier(inst: ModuleInstanceMgr) {
		const id = this.indexOf(inst);
		return `${this.getDisplayName(false)} ${id}`;
	}

	public getScriptIdentifier() {
		return this.getName();
	}

	public generateScriptStatements(parentIdentifier: string, options: SerializationOptions) {
		return _.flatMap(
			this.instances,
			(instMgr, id) => instMgr.getScriptStatements(
				createChildIdentifier(parentIdentifier, id),
				{ ...options },
			),
		);
	}

	public destroyAll() {
		_.each(this.instances, (inst) => inst.remove());
		_.remove(this.instances, () => true);
	}

	public removeToMinimum() {
		const minCount = this.getMinInstanceCount();
		const toRemove = _.slice(this.instances, minCount);
		_.each(toRemove, (inst) => inst.remove());
		_.pullAll(this.instances, toRemove);
	}

	public removeInst(inst: ModuleInstanceMgr) {
		if (this.canRemove(inst)) {
			this.removeID(this.indexOf(inst));
		} else {
			throw Error("This (default) instance can not be removed");
		}
	}

	public removeID(id: number) {
		const targetInst = _.get(this.instances, id);
		if (targetInst) {
			if (this.getNumberOfUsed() <= this.getMinInstanceCount()) {
				throw Error(`Remove violates minimum instance count in ${this.getName()}`);
			}
			this.instances[id].remove();
			this.instances.splice(id, 1);
		}
	}

	public getManagedObj(): ModuleInstanceArray {
		const managedObj = _.map(this.instances, (m) => m.managedObject);
		Object.defineProperty(managedObj, "create", {
			value: internalBoundary(() => guardScriptingFunction((n: number) => this.create(n), "create")),
		});
		return Object.freeze(managedObj) as ModuleInstanceArray;
	}

	public getMinInstanceCount() {
		return this.def.minInstanceCount || 0;
	}

	public override setShowUserLongDescPref(status: boolean) {
		this.userShowLongDescPref = status;
	}

	public override instanceAddDisabled() {
		// either the instance adder's member limit is exceeded 
		// or the module's instance limit is exceeded
		return super.instanceAddDisabled() || this.moduleMgr.instanceAddDisabled();
	}

	public getModuleMgr() {
		return this.moduleMgr;
	}

	public indexOf(value: ModuleInstanceMgr) {
		return _.indexOf(this.instances, value);
	}

	public getMaxAllowed() {
		return this.def.maxInstanceCount ? this.def.maxInstanceCount : Number.POSITIVE_INFINITY;
	}

	public getNumberOfUsed() {
		return this.instances.length;
	}

	public getDescription() {
		return this.def.description;
	}

	public canRemove(inst?: ModuleInstanceMgr) {
		return this.indexOf(inst) > Math.max(this.getFixedRequiredArgsLength(), this.getFixedArgsLength()) - 1 &&
			this.canRemoveAll();
	}

	public getCannotRemoveReason(inst?: ModuleInstanceMgr) {
		const cannotRemoveReason =
			`Must have at least ${this.getMinInstanceCount()} instance${this.getMinInstanceCount() === 1 ? "" : "s"}.`;
		const fixedInstanceCanNotRemoveReason = "This instance is fixed and can never be removed";

		return this.indexOf(inst) < Math.max(this.getFixedRequiredArgsLength(), this.getFixedArgsLength())
			? fixedInstanceCanNotRemoveReason : cannotRemoveReason;
	}

	public canRemoveAll() {
		return this.getNumberOfUsed() > this.getMinInstanceCount();
	}

	public getKey() {
		return `${this.getName()}/child`;
	}

	// this should never be hidden
	public isHidden() {
		return false;
	}

	public matchSubItemPath(itemPath: string[]): MatchedPathRetType {
		const foundChild = _.find(this.instances, (inst) => inst.getName() === _.head(itemPath));
		if (foundChild) {
			const memberPath = _.slice(itemPath, 1);
			this.setSelection({
				instanceId: foundChild.getID(),
				memberPath,
			});
		}
		return [!!foundChild, itemPath];
	}

	public getNumColumns() {
		return 1;
	}

	public getRuntimeSelection() {
		return this.getSelectedMyListItem()?.managedObject;
	}

	private getFixedArgsLength() {
		return _.size(this.def.fixedArgs);
	}

	private getFixedRequiredArgsLength() {
		return _.size(this.def.fixedRequiredArgs);
	}
}

export const instanceAdderProxyHandler: ProxyHandler<ModuleInstanceAdderMgr> = {
	get: (target, key: Extract<PropertyKey, string | symbol>) => {
		const managedObject = target.getManagedObj();
		if (key === Symbol.iterator) {
			// this is to trap things like for ... of
			return managedObject[Symbol.iterator].bind(managedObject);
		} else if (key in managedObject) {
			// 'in' instead of hasOwnProperty because we also want the functions on the array prototype
			if (_.isFunction((managedObject as any)[key])) {
				return (managedObject as any)[key].bind(managedObject);
			} else {
				return (managedObject as any)[key];
			}
		} else {
			return undefined;
		}
	},
	ownKeys: (target) => {
		const managedObject = target.getManagedObj();
		return Object.getOwnPropertyNames(managedObject);
	},
	set: () => {
		throw new TypeError("read only object");
	},
	defineProperty: () => {
		throw new TypeError("read only object");
	},
	deleteProperty: () => {
		throw new TypeError("read only object");
	},
};
