// UI Views for meta content defined configurables
import * as React from "react";
import { IConfigurablesActions } from "../configurableActions";
import { TextConfigurableMgr } from "../../configurables/textConfigurableMgr";
import { MultilineInputBox } from "../../../../components/MultilineInputBox";

export class CLongTextConfigurable extends React.Component<{
	mgr: TextConfigurableMgr;
	actions: IConfigurablesActions;
}> {
	public override render() {
		const mgr = this.props.mgr;
		const actions = this.props.actions;
		return (
			<MultilineInputBox
				value={mgr.getValue()}
				type="text"
				placeholder={mgr.def.placeholder}
				id={mgr.def.name}
				onChange={(val) => actions.setConfigurableValue(mgr, val)}
				disabled={!!mgr.uiState.readOnly}
			/>
		);
	}
}
