// UI Views for meta content defined configurables
import * as React from "react";
import { IConfigurablesActions } from "../configurableActions";
import { MultiPartTextConfigurableMgr } from "../../configurables/multiPartTextConfigurableMgr";
import { PreprocessedDebouncedCombinationBox } from "../../../../components/higherOrderComponents/ComposedComponents";

export class CFormattedTextConfigurable extends React.Component<{
	mgr: MultiPartTextConfigurableMgr;
	actions: IConfigurablesActions;
}> {
	public override render() {
		const mgr = this.props.mgr;
		const actions = this.props.actions;
		return (
			<PreprocessedDebouncedCombinationBox
				preprocess={(val) => mgr.textFormatter.formatEntireString(val)}
				value={mgr.getValue()}
				onChange={(val) => actions.setConfigurableValue(mgr, val)}
				placeholder={mgr.def.placeholder}
				id={mgr.def.name}
				resyncTrigger={mgr}
				formatter={mgr.textFormatter}
				disabled={!!mgr.uiState.readOnly}
			/>
		);
	}
}
