import * as React from "react";
import {
	ListItem, ListItemText, ListItemSecondaryAction, SvgIconProps, IconButton, Typography,
} from "../../imports/material-ui-imports";
import {
	ChevronDown, ChevronRight, MenuDown,
	MenuRight, Folder, FolderOpen,
	FolderOutline, CloudUpload,
} from "../../imports/mdi-material-ui-imports";
import { CommonClasses, withCommonStyles, commonStyles } from "../styles/common";
import { IStorageFile } from "../../services/storage";
import {
	paddingPerLevel, statusIconSize, ICommonItemProps,
	getFileStatusDecorator, getFileNameAndSizeComponent,
} from "./common";
import { LocalFileBrowse } from "../local/LocalFileBrowse";

interface IDirectoryItemProps extends ICommonItemProps {
	directory: IStorageFile;
	expanded: boolean;
	onFolderSelect?: (file: IStorageFile) => void;
	onFileUpload?: (folder: IStorageFile, event: React.ChangeEvent<HTMLInputElement>) => void;
	onToggleExpansion: () => void;
}

// The UI component that shows one list entry of a specific directory.
interface IBaseDirectoryItemProps extends IDirectoryItemProps {
	style: React.CSSProperties;
	dense: boolean;
	fontSize: "small" | "default" | "large" | "inherit";
	statusDecorator?: JSX.Element;
	ExpandComponent: React.ComponentType<SvgIconProps>;
	CollapseComponent: React.ComponentType<SvgIconProps>;
	ExpandedIcon: React.ComponentType<SvgIconProps>;
	CollapsedIcon: React.ComponentType<SvgIconProps>;
	body: JSX.Element;
}

class StyledBaseDirectoryItem extends React.Component<IBaseDirectoryItemProps & CommonClasses> {
	public override render() {
		const className = (this.props.directory.path === this.props.selectedPath)
			? this.props.classes.selectedList
			: this.props.classes.unSelectedList;

		const { ExpandComponent, CollapseComponent, ExpandedIcon, CollapsedIcon } = this.props;
		return (
			<ListItem
				disabled={this.props.disabled}
				button
				id={this.props.directory.path + "_dir"}
				onClick={() => {
					if (this.props.onFolderSelect) {
						this.props.onFolderSelect(this.props.directory);
					}
				}}
				dense={this.props.dense}
				style={this.props.style}
				className={className}
			>
				{this.props.statusDecorator}
				{this.props.expanded
					? <React.Fragment>
						<ExpandComponent
							style={{ color: "grey" }}
							fontSize={this.props.fontSize}
							id={this.props.directory.path + "expand"}
							onClick={this.toggleExpansion} />
						<ExpandedIcon color="primary" fontSize={this.props.fontSize} />
					</React.Fragment>
					: <React.Fragment>
						<CollapseComponent
							style={{ color: "grey" }}
							fontSize={this.props.fontSize}
							id={this.props.directory.path + "expand"}
							onClick={this.toggleExpansion} />
						<CollapsedIcon color="primary" fontSize={this.props.fontSize} />
					</React.Fragment>
				}
				{this.props.body}
				{this.props.onFileUpload && <FileUpload {...this.props} />}
			</ListItem>
		);
	}

	private toggleExpansion = (e: React.MouseEvent<Element>) => {
		e.stopPropagation();
		this.props.onToggleExpansion();
	}
}

const BaseDirectoryItem = withCommonStyles(StyledBaseDirectoryItem);

export class FileExplorerDirectoryItem extends React.Component<IDirectoryItemProps> {
	public override render() {
		return <BaseDirectoryItem
			{...this.props}
			fontSize={"small"}
			dense={false}
			style={{
				...commonStyles.extraDenseList,
				paddingLeft: paddingPerLevel * this.props.level - (this.props.status ? statusIconSize : 0) + 3,
				color: commonStyles.modalTextColor,
			}}
			statusDecorator={getFileStatusDecorator(this.props.directory.relativePath, this.props.status)}
			ExpandComponent={MenuDown}
			ExpandedIcon={FolderOpen}
			CollapseComponent={MenuRight}
			CollapsedIcon={Folder}
			body={<ListItemText
				style={{ paddingLeft: "5px", paddingRight: "0px" }}
				primary={getFileNameAndSizeComponent(this.props.directory.name, this.props.getSize(this.props.directory))}
			/>}
		/>;
	}
}

export class DirectoryItem extends React.Component<IDirectoryItemProps> {
	public override render() {
		return <BaseDirectoryItem
			{...this.props}
			dense={false}
			fontSize={"default"}
			style={{
				paddingLeft: paddingPerLevel * this.props.level,
			}}
			ExpandComponent={ChevronDown}
			ExpandedIcon={FolderOutline}
			CollapseComponent={ChevronRight}
			CollapsedIcon={Folder}
			body={<ListItemText primary={<Typography>{this.props.directory.name}</Typography>} />}
		/>;
	}
}

class FileUpload
	extends React.Component<Pick<IBaseDirectoryItemProps, "onFileUpload" | "fnameFilter" | "directory" | "fontSize">> {
	public override render() {
		return <ListItemSecondaryAction>
			<LocalFileBrowse
				id={this.props.directory.path}
				accept={this.props.fnameFilter}
				onChangeEvent={(name) => this.props.onFileUpload(this.props.directory, name)}>
				<IconButton component="span">
					<CloudUpload style={{ ...commonStyles.smallIcon }} />
				</IconButton>
			</LocalFileBrowse>
		</ListItemSecondaryAction>;
	}
}
