import * as _ from "lodash";
import { SysConfig } from "./sysConfig";
import { Statement } from "./scripting/serialize";
import { updateRuntime } from "./scripting/updateRuntime";
import { AdaptedDeviceInfo } from "dataInterfaces";
import { memoizeOne } from "./utils";

const historyInitialStateText = "Initial state";

// If you add to this list, you must also handle it in getIcon() in HistoryView.tsx

export type HistoryPointDesc =
	"Initial state" |
	`Add${string}` |
	`Reserved${string}` |
	`Remove${string}` |
	`Change${string}` |
	`Locked${string}` |
	`Switch${string}` |
	`Ignore${string}` |
	`Don't ignore${string}` |
	`Clicked${string}` |
	`Cleared error${string}` |
	`Suppressed${string}` |
	`Un-suppressed${string}` |
	`Excluded${string}` |
	`Included${string}`;

export interface PointInHistoryLabel {
	title: HistoryPointDesc;
	key: number;
}

interface PointInHistory<SelectionInConfigStore> extends PointInHistoryLabel {
	selection: SelectionInConfigStore;

	// The serialization statements necessary to generate a serialization script for this point in
	// history

	configuration: Statement[][];

	// It is orders of magnitude faster to remove the current configuration and re-serialize into 
	// the same runtime, as the most expensive operation is loading/interpreting the meta-code, not
	// instancing modules.  As such, we save the runtime which contains pre-loaded meta-code and 
	// device data, and is thus faster to restore to.  We save this per history point as that 
	// allows us to treat target migration as just another history point.

	sysConfig: SysConfig;

	// The last change runtime is a clone of the real runtime.  While we could create
	// it on demand, 99% of the time it never changes, making it much more performant to clone
	// it when the real runtime changes vs as needed, and then restore it when that point in 
	// history is accessed.

	lastChangeSysConfig: SysConfig;
}

// Tracks changes the user made over time, and provides a way to set the current state to any point
// within that history.  Also enables undo/redo which just decrement/increment the current point by
// one

export class ChangeHistory<SelectionInConfigStore> {

	// Copy the state of the system at the specified time in history into a new runtime

	public copySysConfigAt = memoizeOne((displacement: number) => {
		if (!this.points[this.currentPointIndex + displacement]) {
			displacement = 0;
		}
		const point = this.points[this.currentPointIndex + displacement];
		const sysConfig = point.lastChangeSysConfig;
		updateRuntime(sysConfig, sysConfig.getRuntimes(), ...point.configuration);

		// Validate/solve, and check for errors

		sysConfig.validateAndSolve();

		return sysConfig;
	});

	private points: PointInHistory<SelectionInConfigStore>[] = [];
	private currentPointIndex: number = -1;
	private savedPoint: PointInHistoryLabel = null;
	private undoRedoCount: number = 0;
	private undoRedoPending: Promise<void> = null;
	private uniqueKeyCounter = 0;

	constructor(
		sysConfig: SysConfig,
		selection: SelectionInConfigStore,
		private readonly onPointChanged: (
			selection: SelectionInConfigStore,
			previousDeviceData: AdaptedDeviceInfo,
			sysConfig: SysConfig) => void,
		private readonly setDirty: (dirty: boolean) => void) {

		this.onUserChange(historyInitialStateText, selection, sysConfig);
		this.setDirty(false);
	}

	// Called by the ConfigStore when the system state changes

	public onUserChange(description: HistoryPointDesc, selection: SelectionInConfigStore, sysConfig: SysConfig) {
		this.points = _.take(this.points, this.currentPointIndex + 1);

		// Cloning the runtime has a real performance hit (needs to process all the components in
		// product.json - say 50+ms), so use the previous runtime if we can, but clone when 
		// necessary

		const lastChangeRuntime = sysConfig === _.last(this.points)?.sysConfig
			? _.last(this.points).lastChangeSysConfig
			: sysConfig.clone();

		// Save the point, not only the title, but everything necessary to restore it in the future

		this.points.push({
			title: description,
			key: this.uniqueKeyCounter++,
			selection,
			configuration: _.map(sysConfig.getRuntimes(),
				(r) => r.serialize({ includeUIState: true, includeNonSerializable: true })),
			sysConfig: sysConfig,
			lastChangeSysConfig: lastChangeRuntime,
		});
		if (description !== historyInitialStateText) {
			this.setDirty(true);
		}
		this.currentPointIndex++;
		this.copySysConfigAt.cache.clear();
	}

	// Get all the points in history

	public getPoints(): PointInHistoryLabel[] {
		return this.points;
	}

	// What point in history is the system currently at, by index

	public getCurrentPointIndex() {
		return this.currentPointIndex;
	}

	// What point in history is the system currently at

	public getCurrentPoint(): PointInHistoryLabel {
		return this.points[this.currentPointIndex];
	}

	// Revert the current state of the system to the previous point in history

	public undo() {
		--this.undoRedoCount;
		return this.queueUndoRedo();
	}

	// Re-apply the current state of the system to the next point in history

	public redo() {
		++this.undoRedoCount;
		return this.queueUndoRedo();
	}

	// Change the current state of the system to the point in history specified by index

	public setCurrentPoint(pointIndex: number, force = false) {
		this.restorePoint(pointIndex, force);
	}

	// UI state changed (collapse/expand of groups state), but the configuration did not.  Since we
	// want the history to only track configuration changes, we should re-serialize again to 
	// capture the new UI state

	public updateCurrent() {
		const point = this.points[this.currentPointIndex];
		point.configuration = _.map(point.sysConfig.getRuntimes(),
			(r) => r.serialize({ includeUIState: true, includeNonSerializable: true }));
	}

	// User hit save right now, so whatever the history is pointing to now matches what is on disk

	public setSavedPoint() {
		this.savedPoint = this.points[this.currentPointIndex];
		this.setDirty(false);
	}

	// Point in history where the user hit save

	public getSavedPoint() {
		return this.savedPoint;
	}

	private restorePoint(pointIndex: number, force = false) {
		if (this.currentPointIndex !== pointIndex || force) {

			const previousDeviceData = this.points[this.currentPointIndex].sysConfig.getDeviceData();
			const point = this.points[pointIndex];
			updateRuntime(point.sysConfig, point.sysConfig.getRuntimes(), ...point.configuration);

			// Notify listeners

			this.currentPointIndex = pointIndex;
			this.onPointChanged(point.selection, previousDeviceData, point.sysConfig);
			if (point === this.savedPoint) {
				this.setDirty(false);
			} else {
				this.setDirty(true);
			}
		}
		this.copySysConfigAt.cache.clear();
	}

	private queueUndoRedo() {

		// Undo/redo can take a bit of time (nuke everything, compile script, run script).  So instead
		// of doing it immediately, we'll queue undo/redo operations.  This allows the user to hit ctrl+z
		// multiple times quickly, but not immediately run the update.

		if (!this.undoRedoPending) {
			this.undoRedoPending = new Promise<void>((resolve) => {
				setTimeout(() => {
					const newPoint = _.clamp(this.currentPointIndex + this.undoRedoCount, 0, this.points.length - 1);
					this.undoRedoCount = 0;
					this.undoRedoPending = null;
					this.restorePoint(newPoint);
					resolve();
				});
			}).catch((e) => console.error(e));
		}
		return this.undoRedoPending;
	}
}
