import * as React from "react";
import { SecondaryButton } from "./SecondaryButton";
import { IOutputActions } from "../actions/IOutputActions";
import { ATheme } from "../styles/themes";
import { ViewWithMigrationButtonMgr } from "../../services/ui/outputView";

interface IProps {
	theme: ATheme;
	mgr: ViewWithMigrationButtonMgr;
	actions: IOutputActions;
}

// A button to initiate a target migration (dialog + migration after)

export function SwitchButton(props: IProps) {
	if (!props.mgr.isMigrationAllowed()) {
		return null;
	}
	return (
		<SecondaryButton
			theme={props.theme}
			id={"switchBoardOrDeviceBtn"}
			onClick={(e: React.MouseEvent<HTMLElement>) => {
				e.stopPropagation();
				props.actions.switchBoardOrDevice();
			}}>{"Switch"}
		</SecondaryButton>
	);
}
