import * as React from "react";
import * as _ from "lodash";
import { IFormatter } from "../services/formatting/formattingTypes";
import { OwnershipInfo } from "../services/IMyListItem";
interface IProps {
	formatter: IFormatter;
	reason: OwnershipInfo | string;
}
export class CannotBeRemovedPopup extends React.Component<IProps> {
	public override render() {
		return (
			<span>
				<span >Cannot be removed:</span><br />
				{
					_.isString(this.props.reason) &&
					<CannotBeRemovedLine
						text={this.props.reason}
					/>
				}
				{
					!_.isString(this.props.reason) &&
					this.props.reason.owner &&
					<CannotBeRemovedLine
						text={`Owned by ${this.props.formatter(this.props.reason.owner)}`}
					/>
				}
				{
					!_.isString(this.props.reason) &&
					!_.isEmpty(this.props.reason.sharer) &&
					_.map(this.props.reason.sharer, (s, i) => {
						return (
							<CannotBeRemovedLine key={i}
								text={`Shared by ${this.props.formatter(s)}`}
							/>
						);
					})
				}
			</span>
		);
	}
}

class CannotBeRemovedLine extends React.Component<{ text: string }> {
	public override render() {
		return (
			<React.Fragment>
				&nbsp;&nbsp;
				<span>
					{this.props.text}
				</span>
				< br />
			</React.Fragment>
		);
	}
}
