import * as React from "react";
import * as _ from "lodash";
import { Plus, Minus, ImageFilterCenterFocus } from "../../../../imports/mdi-material-ui-imports";
import { ButtonGroup } from "../../../../imports/material-ui-imports";
import { IFZoomloatingContentProps } from "../../../higherOrderComponents/WithZoom";
import { ButtonGroupIconButton } from "./ButtonGroupIconButton";

export function FloatingNavigation({ zoomIn, zoomOut, reset }: IFZoomloatingContentProps) {
	return <ButtonGroup orientation="vertical" variant="contained" >
		<ButtonGroupIconButton onClick={zoomIn} >
			<Plus fontSize="small" color="primary" />
		</ButtonGroupIconButton>
		<ButtonGroupIconButton onClick={zoomOut} >
			<Minus fontSize="small" color="primary" />
		</ButtonGroupIconButton>
		<ButtonGroupIconButton onClick={reset} >
			<ImageFilterCenterFocus fontSize="small" color="primary" />
		</ButtonGroupIconButton>
	</ButtonGroup>;
}
