import * as React from "react";
import * as _ from "lodash";
import { Table, TableRow, TableCell, TableBody, TableHead } from "../../imports/material-ui-imports";
import { ConfirmModal } from "./ConfirmModal";
import { CheckBox } from "../CheckBox";
import { Tooltip } from "../Tooltip";
import { DropDown } from "../DropDown";
import { commonStyles } from "../styles/common";
import { IModalMinProps } from "./BasicModal";
import { supportsProjectMigration, ITargetID } from "../../services/migration/migrate";
import { MarkdownContent } from "../MarkdownContent";
import { Alert, CloseCircle } from "../../imports/mdi-material-ui-imports";
import { MigrationOptions } from "../../services/migration/migrationOptions";
import { getDuplicates, keys } from "../../services/utils";
import { systemContext } from "../../services/args/argTypes";

export interface ITarget {
	board?: string;		// canonical name
	device: string;		// name === id
	part: string;		// Name, not id
	package: string;	// Name, not id
	targetDBDevice: string;
	contexts: string[];
}

interface IProps extends IModalMinProps {
	currentTarget: ITarget;
	migrationOptions: MigrationOptions;
	confirmAction: (newTarget: ITargetID, lockSolutionFirst: boolean) => void;
	cancelAction?: () => void;
}

interface IState {
	target: ITarget;
	lockSolutionFirst: boolean;
}

// A confirm/cancel dialog with a specific message for board->device migration
// Includes an option to lock the pinmux

export class SwitchBoardOrDevice extends React.Component<IProps, IState> {

	constructor(props: IProps) {
		super(props);

		this.state = {
			lockSolutionFirst: true,
			target: props.currentTarget,
		};
	}

	public override render() {

		const {
			currentTarget,
			confirmAction,
			cancelAction,
			migrationOptions,
			...rest } = this.props;

		const target = this.state.target;
		const boardOptions = migrationOptions.getBoardOptions();
		const deviceOptions = migrationOptions.getDeviceOptions(this.state.target.board);
		const discoveryData = migrationOptions.getDisoveryData();

		const boardOption = _.find(boardOptions, (board) => board.name === this.state.target.board);
		const boardError = boardOption?.isDisabled;
		const boardMessage = boardOption?.description as string;
		const deviceOption = _.find(deviceOptions, (device) => device.name === this.state.target.device);
		const deviceError = deviceOption?.isDisabled;
		const deviceMessage = deviceOption?.description as string;

		return (
			<ConfirmModal
				{...rest}
				title="Switch Board or Device"
				confirmAction={this.confirmAction}
				cancelAction={cancelAction}
				disableConfirmButton={boardError || deviceError || this.disableConfirmButton()}
			>
				<MarkdownContent
					markdownSrc={this.getMarkdown()}
					{...migrationOptions.getMarkdownProps()}
				/>

				<Table>
					<TableHead>
						<Option isHeading={true} label="Setting" currentValue="Current Value">
							{"New Value"}
						</Option>
					</TableHead>
					<TableBody>
						<Option label="Board" currentValue={this.getBoardDisplayText(currentTarget)}>
							<DropDown
								id={"boardDropDown"}
								enabledOptions={[{ name: "None" }, ...boardOptions]}
								selectedOptionName={target.board || "None"}
								withIcon={true}
								onChange={(board) => {
									board = _.first(_.split(board, " "));
									if (board === "None") {
										this.setState({ target: { ...target, board: null } });
									} else {
										const deviceInfo = this.getBoard(board);
										this.setState({
											target: {
												board,
												...deviceInfo,
												contexts: this.getDefaultContextChoices(deviceInfo.device),
											},
										});
									}
								}}
								disabled={false}
								displayScriptName={false}
							/>
							{boardMessage &&
								<MessageIcon title={boardMessage} isError={boardError} />
							}

						</Option>
						<Option label="Device" currentValue={currentTarget.device}>
							<DropDown
								id={"deviceDropDown"}
								enabledOptions={deviceOptions}
								selectedOptionName={target.device}
								withIcon={true}
								onChange={(device) => {
									device = _.first(_.split(device, " "));
									const part = discoveryData.getParts({ device })[0].name;
									this.setState({
										target: {
											board: target.board,
											device,
											part,
											package: _.first(discoveryData.getPackages({ device, part })).name,
											targetDBDevice: _.first(discoveryData.getTargetDBDevices({ device, part })),
											contexts: this.getDefaultContextChoices(device),
										},
									});
								}}
								disabled={_.size(deviceOptions) === 1}
								displayScriptName={false}
							/>
							{(!this.state.target.board || _.size(deviceOptions) !== 1) && deviceMessage &&
								<MessageIcon title={deviceMessage} isError={deviceError} />
							}
						</Option>
						<Option label="Part" currentValue={currentTarget.part}>
							<DropDown
								id={"partDropDown"}
								enabledOptions={_.sortBy(discoveryData.getParts(target), (part) => part.name)}
								selectedOptionName={target.part}
								withIcon={true}
								onChange={(part) => {
									const { device, contexts } = target;
									this.setState({
										target: {
											device,
											part,
											package: _.first(discoveryData.getPackages({ device, part })).name,
											targetDBDevice: _.first(discoveryData.getTargetDBDevices({ device, part })),
											contexts,
										},
									});
								}}
								disabled={!_.isEmpty(target.board)}
								displayScriptName={false}
							/>
						</Option>
						<Option label="Package" currentValue={currentTarget.package}>
							<DropDown
								id={"packageDropDown"}
								enabledOptions={_.sortBy(discoveryData.getPackages(target), (pkg) => pkg.name)}
								selectedOptionName={target.package}
								withIcon={true}
								onChange={(pkg) => {
									this.setState({
										target: {
											...target,
											package: pkg,
										},
									});
								}}
								disabled={!_.isEmpty(target.board)}
								displayScriptName={false}
							/>
						</Option>
						{supportsProjectMigration() && 1 < _.size(discoveryData.getTargetDBDevices(target)) &&
							<Option
								label="CCS Launch Device"
								currentValue={window.eclipseGetTargetDBDeviceDisplayName(currentTarget.targetDBDevice)}
							>
								<DropDown
									id={"targetDBSelection"}
									withIcon={true}
									enabledOptions={_.map(discoveryData.getTargetDBDevices(target), (name) => {
										return {
											name,
											displayName: window.eclipseGetTargetDBDeviceDisplayName(name),
										};
									})}
									selectedOptionName={target.targetDBDevice}
									onChange={(targetDBDevice) => this.setState({ target: { ...target, targetDBDevice } })}
									disabled={false}
									displayScriptName={false}
								/>
							</Option>
						}
						{this.shouldShowContexts() &&
							_.map(this.props.migrationOptions.getContextChoices(target.device), (options, index) =>
								<Option label="Context" currentValue={currentTarget.contexts[index]} key={currentTarget.contexts[index]}>
									<DropDown
										id={`context${currentTarget.contexts[index]}`}
										withIcon={true}
										enabledOptions={options}
										selectedOptionName={target.contexts[index]}
										onChange={(context) => {
											const contexts = _.clone(target.contexts);
											contexts[index] = context;
											this.setState({ target: { ...target, contexts } });
										}}
										disabled={false}
										displayScriptName={false}
									/>
									{this.hasContextError(index) &&
										<ErrorIcon id={`context${currentTarget.contexts[index]}Error`} title="Context already in use" />
									}
								</Option>
							)
						}
						<Option label="Lock PinMux">
							<Tooltip title={this.getLockToolTip()} >
								<CheckBox
									id={"lockSolutionFirst"}
									onChange={(lockSolutionFirst) => this.setState({ lockSolutionFirst })}
									value={this.state.lockSolutionFirst}
								/>
							</Tooltip>
						</Option>
					</TableBody>
				</Table>
			</ConfirmModal>
		);
	}

	private hasContextError(index: number) {
		return index !== _.indexOf(this.state.target.contexts, this.state.target.contexts[index]);
	}

	private disableConfirmButton() {
		const { target } = this.state;
		return isEqual(target, this.props.currentTarget) || !_.isEmpty(getDuplicates(target.contexts, (c) => c));
	}

	private confirmAction = () => {
		const { target } = this.state;
		const discoveryData = this.props.migrationOptions.getDisoveryData();
		const targetChoice = {
			...target,
			partID: discoveryData.getPart(target).partID,
			packageID: discoveryData.getPackage(target).packageID,
			targetDBDevice: target.targetDBDevice,
		};
		this.props.confirmAction(targetChoice, this.state.lockSolutionFirst);
	}

	private getBoard(board: string) {
		const boardInfo = this.props.migrationOptions.getBoardInfo(board);
		return {
			...boardInfo,
			targetDBDevice: _.first(this.props.migrationOptions.getDisoveryData().getTargetDBDevices(boardInfo)),
		};
	}

	private getDefaultContextChoices(device: string) {
		return _.map(this.props.migrationOptions.getContextChoices(device), (choices, index) => {
			const identicalChoice = _.find(choices, (choice) => choice.name === this.props.currentTarget.contexts[index]);
			return identicalChoice?.name ?? _.first(choices).name;
		});
	}

	private getBoardDisplayText({ board }: { board?: string }) {
		return _.isEmpty(board) ? "" : this.getBoard(board).displayName;
	}

	private getMarkdown() {

		let markdown = "This will migrate the current configuration to the board or device " +
			"selected below.  Any incompatibilities will be flagged as errors.";

		markdown += "\n\n";

		markdown += "The migration can be undone by using ctrl + z or the history view.  ";
		if (supportsProjectMigration()) {
			markdown += "Once satisfied with the conversion, saving the changes will initiate " +
				"the migration of the underlying project which cannot be undone.";
		} else {
			markdown += "Any underlying project or makefile is not modified, and likely " +
				"contains device-specific settings.  These settings will need to be migrated " +
				"manually.";
		}

		markdown += "\n\n";

		markdown += this.props.migrationOptions.getExtraMarkdown();

		return markdown;
	}

	private getLockToolTip() {
		if (this.state.lockSolutionFirst) {
			if (this.props.currentTarget.board && this.state.target.board) {
				return "Any unlocked choices will be locked, and the conversion will try to " +
					"maintain the same board header pins";
			} else {
				return "Any unlocked choices will be locked, and the conversion will try to " +
					"maintain the same internal signals";
			}
		} else {
			if (this.props.currentTarget.board && this.state.target.board) {
				return "The conversion will try to maintain the same board header pins only for locked choices";
			} else {
				return "The conversion will try to maintain the same internal signals only for locked choices";
			}
		}
	}

	private shouldShowContexts() {
		const choices = _.first(this.props.migrationOptions.getContextChoices(this.state.target.device));
		return _.size(this.props.currentTarget.contexts) !== 1 ||
			_.size(choices) !== 1 ||
			_.first(choices).name !== systemContext;
	}
}

// Returns all valid keys of ITarget

function getITargetKeys() {
	// Create an object of type ITarget
	// Required<> ensures optional keys are specified
	// : type vs as type ensures we aren't dropping anything

	const hasTargetKeys: Required<ITarget> = {
		board: "",
		device: "",
		part: "",
		package: "",
		targetDBDevice: "",
		contexts: [],
	};

	// Now, return the keys of that object, knowing we couldn't have dropped any

	return keys(hasTargetKeys);
}

// Returns true if the two targets are equivalent.  It ignores extra properties (due to assignments of super-types)

function isEqual(targetA: ITarget, targetB: ITarget) {

	return _.every(getITargetKeys(), (key) => _.isEqual(targetA[key], targetB[key]));
}

interface IOptionProps {
	label: string;
	currentValue?: string;
	isHeading?: boolean;
}

function Option(props: React.PropsWithChildren<IOptionProps>) {
	return (
		<TableRow hover={!props.isHeading} style={commonStyles.tableRowStyle}>
			<TableCell>{props.label}</TableCell>
			<TableCell>{props.currentValue}</TableCell>
			<TableCell style={{ width: "35%" }}>
				{props.children}
			</TableCell>
		</TableRow>
	);
}

function WarningIcon(props: { title: string; }) {
	return (
		<Tooltip title={props.title} >
			<Alert
				style={{ ...commonStyles.warningIcon, verticalAlign: "bottom" }}
			/>
		</Tooltip >
	);
}

function ErrorIcon(props: { title: string; id?: string }) {
	return (
		<Tooltip title={props.title} >
			<CloseCircle
				id={props.id}
				style={{ ...commonStyles.errorIcon, verticalAlign: "bottom" }}
			/>
		</Tooltip >
	);
}

function MessageIcon(props: { title: string; isError: boolean }) {
	return props.isError ? <ErrorIcon title={props.title} /> : <WarningIcon title={props.title} />;
}
