import * as _ from "lodash";
import { AbstractChoice } from "./common";
import { DevicePinChoices } from "./devicePin";
import { InterfacePinChoices } from "./interfacePin";
import { SolutionMap, pushGPIO } from "../choices";
import { GPIOInfo, GPIOMap } from "dataInterfaces";
import { ChoiceValidator } from "./choiceValidator";
import { nameChoices, formatNameChoice } from "../debug";
import { GPIO, Pin } from "../requirements";
import { addErrorToSolution, clearSolution, updateSolution } from "../../utils";
import { chooseAll } from "../clauseGeneration";

// -----------------------------------------------------------------------------
// GPIOPinChoices
// A factory for creating a choice of a specific gpio pin to meet a gpio 
// requirement.  When not an override, this just adds a requirement to the 
// clauses to fail solving if no free gpio pins are available.  When it is an
// override, a real device pin choice is created, dependent on a dummy choice
// that must always be taken (or an error choice must be taken).  That 
// restricts other pin requirements from stealing our override value.
// -----------------------------------------------------------------------------

export class GPIOPinChoices {
	private readonly nonTrivialChoices: GPIOPinChoices.NonTrivialChoice[] = [];

	constructor(
		private readonly choiceValidator: ChoiceValidator,
		private readonly interfacePinChoices: InterfacePinChoices,
		private readonly devicePinChoices: DevicePinChoices,
		private readonly freeGpioPins: GPIOMap,
		private readonly allGpioPins: GPIOMap,
		private readonly canOptimizeGPIO: boolean) { }

	public newChoice(gpioReq: GPIO, pinReq: Pin) {

		if (pinReq.userOverride ||
			pinReq.restrictTo ||
			!this.canOptimizeGPIO ||
			pinReq.canShareWith ||
			this.choiceValidator.isSolveRestricted()) {

			// If there are any restrictions on the GPIO choice, then we need to create a specific 
			// choice object for each possible choice.  But if not, then we can create one simple 
			// basic choice object that has some optimization tricks

			const specificChoice = new GPIOPinChoices.NonTrivialChoice(gpioReq, pinReq);
			this.nonTrivialChoices.push(specificChoice);
			const pinChoices = (pinReq.connectedToHardware || pinReq.userOverride) ? this.allGpioPins : this.freeGpioPins;
			const hasNoChoices = _.chain(pinChoices)
				.filter((info: GPIOInfo) => this.choiceValidator.isValid(pinReq, info.devicePin, info.peripheralPin))
				.map((info) => {
					const interfacePinChoice = this.interfacePinChoices.newChoice(specificChoice, info.peripheralPin, pinReq);
					return this.devicePinChoices.newChoice(interfacePinChoice, info.peripheralPin, info.devicePin, pinReq);
				})
				.isEmpty()
				.value();

			// If there weren't any valid choices, add a choice for nothing 
			// That ensures at least an error choice is created

			if (hasNoChoices) {
				this.interfacePinChoices.newChoice(specificChoice, null, pinReq);
			}
		} else {

			// No restrictions - we can just pick a free pin after the rest of the solving is done
			new GPIOPinChoices.BasicChoice(this.freeGpioPins, gpioReq, pinReq);
		}
	}

	public generateClauses() {
		chooseAll(this.nonTrivialChoices, null, "each pin requirement must choose one gpio pin mapping");
	}
}

export namespace GPIOPinChoices {

	function getErrorId(gpioReq: GPIO, pinReq: Pin) {
		return gpioReq.id + "->" + pinReq.getUnqualifiedName();
	}
	// This class represents a basic GPIO choice with no restrictions.  It's optimized to solve outside of the solver
	// and thus is a lot faster to use when possible

	export class BasicChoice {
		public readonly name?: string;

		constructor(
			private readonly gpioBalls: GPIOMap, gpioReq: GPIO, private readonly pinReq: Pin) {

			// Push a GPIO specific choice to the choice array.  
			// The choice array will just see if enough free "gpio" pins are left, and 
			// will indicate solved or not based only on that.

			// This completely eliminates a HUGE number of clauses being generated

			pushGPIO(this, {
				apply: () => {
					clearSolution(pinReq.solution);
					addErrorToSolution(pinReq.solution, "Resource conflict");
				},
			}, getErrorId(gpioReq, pinReq));

			if (nameChoices) {
				this.name = "GPIO choice";
			}
		}

		public apply(solutionMap: SolutionMap) {

			// Pick any GPIO choice from whatever is left

			const choice = _.find(this.gpioBalls, (info) => {
				return !(info.devicePin.name in solutionMap.devicePins);
			});

			// Use that choice as the answer, and update the solution objects as normal

			updateSolution(
				this.pinReq.solution, choice.devicePin.name, choice.peripheralPin.name, choice.interfacePin.name);

			const ball = choice.devicePin.name;
			const devicePins = solutionMap.devicePins[ball] || (solutionMap.devicePins[ball] = []);
			devicePins.push(this.pinReq);

			const name = choice.peripheralPin.name;
			const peripheralPins = solutionMap.peripheralPins[name] || (solutionMap.peripheralPins[name] = []);
			peripheralPins.push(this.pinReq);
		}
	}

	// This choice represents a restricted GPIO choice, and thus must generate underlying device pin choice objects and
	// operate through the SAT solver.

	export class NonTrivialChoice extends AbstractChoice {
		constructor(
			public readonly gpioReq: GPIO,
			pinReq: Pin) {
			super();

			if (nameChoices) {
				this.name = "GPIO SAT choice: " + formatNameChoice(pinReq);
			}
		}

		public apply() {
			// we don't need to do anything - device pin choice will update the solution
		}

		public getRequirementId() {
			return this.gpioReq.id;
		}

		public getShareHash() {
			return "";
		}

		public hasError() {
			return false;
		}
	}
}
