const basicSysConfigTitle = "SysConfig";

export function setDocumentTitle(newTitle: string, projectModified: boolean) {
	if (typeof document !== "undefined" && typeof document !== null) {
		document.title = formatDocumentTitle(newTitle, projectModified);
	}
}

export function clearTitle() {
	setDocumentTitle("", false);
}

export function formatDocumentTitle(newTitle: string, projectModified: boolean) {
	const formattedNewTitle = newTitle ? ` - ${newTitle}${projectModified ? "*" : ""}` : "";
	return `${basicSysConfigTitle}${formattedNewTitle}`;
}
