import * as React from "react";
import { ClassesType } from "../styling/clockTreeStyles";
import { GenericNode, IGenericNodeProps } from "./GenericNode";

// A normal node (square), but smaller with a + in the middle

export const AdderNode = React.memo((props: IGenericNodeProps & ClassesType) => {
	const { classes } = props;
	return (
		<GenericNode {...props} >
			<svg className={classes.svgNodeContainer}>
				<line x1="50%" y1="75%" x2="50%" y2="25%" className={classes.line} />
				<line x1="75%" y1="50%" x2="25%" y2="50%" className={classes.line} />
			</svg>
		</GenericNode>
	);
});
