import React = require("react");
import { commonStyles } from "./styles/common";
import { Typography } from "../imports/material-ui-imports";
import { assertUnreachable } from "../services/utils";

// align "cursor" means that the popup will follow the movement of the cursor
type PopupAlignType = "left" | "right" | "top" | "bottom";
interface IPopupProps {
	hoverTarget: JSX.Element;
	align: PopupAlignType;
	/* 
		This offsets on the axis that is not the one used for alignment. 
		Ex: if align="top", alignOffset work on the horizontal axis.
		This should be a number between 0-1. With a value of 0.5 
		to make the popup and hoverTarget align along the centerline.
	*/
	alignOffset?: number;
	getContent: () => JSX.Element;
}

interface IPopupState {
	isHovered: boolean;
}

export class Popup extends React.Component<IPopupProps, IPopupState> {
	private targetRef: HTMLSpanElement = null;
	constructor(props: IPopupProps) {
		super(props);
		this.state = { isHovered: false };
	}

	public override render() {
		return (
			<span
				onMouseEnter={this.handleMouseEnter}
				onMouseLeave={this.handleMouseLeave}
			>
				<span ref={this.setHoverTargetRef}>
					{this.props.hoverTarget}
				</span>
				{this.state.isHovered &&
					this.renderContent()
				}
			</span>
		);
	}

	private renderContent() {
		const content = this.props.getContent();
		if (!content) {
			return null;
		}
		return (
			<Typography variant="body2" component="span">
				<PopupContent
					{...this.props}
					hoverTargetBox={this.targetRef.getBoundingClientRect()}
				>
					{this.props.getContent ? this.props.getContent() : this.props.children}
				</PopupContent>
			</Typography>
		);
	}

	private setHoverTargetRef = (el: HTMLSpanElement) => this.targetRef = el;

	private handleMouseEnter = () => this.setState({ isHovered: true });

	private handleMouseLeave = () => this.setState({ isHovered: false });
}

interface IPopupContentProps {
	align: PopupAlignType;
	alignOffset?: number;
	hoverTargetBox: ClientRect | DOMRect;
}

interface IPopupContentStates {
	popupContentHeight: number;
	popupContentWidth: number;
}

class PopupContent extends React.Component<IPopupContentProps, IPopupContentStates> {
	constructor(props: IPopupContentProps) {
		super(props);
		this.state = {
			popupContentHeight: 0,
			popupContentWidth: 0,
		};
	}

	public override render() {
		let style: React.CSSProperties = commonStyles.popupStyle;

		const hoverTargetBox = this.props.hoverTargetBox;
		const contentWidth = this.state.popupContentWidth;
		const contentHeight = this.state.popupContentHeight;
		/*
			The CSS coordinate system and Javascript coordinate system are different.
			top, bottom, right, left in the CSS style uses the CSS coordinate system,
			they specify the absolute distance between respective edges. For example,
			top means the distance from the top side of the window to the top side
			of the element, while bottom means the distance from the bottom side of 
			window to the bottom side of the element.

			The bounding box returned from getBoundingClientRect uses the Javascript 
			coordinate. The top, bottom, right, left here are all measured vertically 
			from the top side of the window and horizontally from the left side. For
			example, top side is still the distance from the top side of the window 
			to the top side	of the element, while bottom becomes the distance from 
			the top side of the window to the bottom side of the element.
		*/
		if (hoverTargetBox) {
			let alignOffset = this.props.alignOffset ? this.props.alignOffset : 0;
			if (this.props.align === "top") {
				alignOffset = alignOffset * (contentWidth - hoverTargetBox.width);
				style = {
					...style,
					bottom: window.innerHeight - hoverTargetBox.top,
					left: hoverTargetBox.left - alignOffset,
				};
			} else if (this.props.align === "bottom") {
				alignOffset = alignOffset * (contentWidth - hoverTargetBox.width);
				style = {
					...style,
					top: hoverTargetBox.bottom,
					left: hoverTargetBox.left - alignOffset,
				};
			} else if (this.props.align === "left") {
				alignOffset = alignOffset * (contentHeight - hoverTargetBox.height);
				style = {
					...style,
					top: hoverTargetBox.top - alignOffset,
					right: window.innerWidth - hoverTargetBox.left + 6,
				};
			} else if (this.props.align === "right") {
				alignOffset = alignOffset * (contentHeight - hoverTargetBox.height);
				style = {
					...style,
					top: hoverTargetBox.top - alignOffset,
					left: hoverTargetBox.right,
				};
			} else {
				assertUnreachable(this.props.align);
			}
		}

		return (
			<div ref={this.setRef} style={style} className="popupErrorOrWarning">
				{this.props.children}
			</div>
		);
	}

	public setRef = (el: HTMLDivElement) => {
		if (!el) {
			return;
		}
		this.setState({
			popupContentHeight: el.clientHeight,
			popupContentWidth: el.clientWidth,
		});
	}
}
