class DeviceBoardViewBase extends ViewWithMigrationButtonMgr {
	public isApplicable() {
		return !this.runtime.getPinmuxUIOptions().hasNoPinmux;
	}

	public shouldShowModeTable() {
		const excludeList = ["CCXX", "LPRF", "MSP430", "TM4C"];
		const currentDiscoveryData = this.getCurrentDiscoveryData();
		return _.every(excludeList, (l) => !_.includes(currentDiscoveryData.family, l));
	}

	public getDevicePinSolutionMap() {
		return this.sysConfig.getDevicePinSolutionMap();
	}

	public getDeviceData() {
		return this.sysConfig.getDeviceData();
	}
}

export class DeviceViewMgr extends DeviceBoardViewBase {
	public readonly type = "device";
	constructor(
		sysConfig: SysConfig,
		runtime: Runtime,
		deviceDiscoveryData: DiscoveryJSON,
	) {
		super(
			sysConfig,
			runtime,
			"deviceView",
			"Device View",
			!isEclipse() && !sysConfig.getDeviceData().board,
			deviceDiscoveryData,
		);
	}

	public override getCardHeading() {
		const deviceData = this.getDeviceData();
		const currentDiscoveryData = _.find(this.deviceDiscoveryData.devices,
			(d) => d.name === deviceData.device);
		const currentPart = _.find(currentDiscoveryData.part, (p) => p.name === deviceData.part);
		const heading = [`${deviceData.device} (Device)`];
		if (1 < _.size(currentDiscoveryData.part)) {
			heading.push(`${deviceData.part} (Part)`);
		}

		if (1 < _.size(currentPart.packageDescriptions)) {
			heading.push(`${deviceData.package} (Package)`);
		}

		return heading;
	}

	public getNumGPIO() {
		return this.sysConfig.getNumGPIO();
	}

	public getNumGPIOLeft() {
		return this.sysConfig.getNumGPIOLeft();
	}
}

export class BoardViewMgr extends DeviceBoardViewBase {
	public readonly type = "board";
	constructor(
		sysConfig: SysConfig,
		runtime: Runtime,
		deviceDiscoveryData: DiscoveryJSON,
	) {
		super(
			sysConfig,
			runtime,
			"boardView",
			"Board View",
			!isEclipse(),
			deviceDiscoveryData,
		);
	}

	public override isApplicable() {
		return !!this.sysConfig.getDeviceData().board && super.isApplicable();
	}

	public override getCardHeading() {
		const board = this.getDeviceData().board;
		const device = this.getDeviceData().device;

		return board.device === device ? `${board.displayName}` : `${board.displayName} (emulating ${device} device) `;
	}

	public wouldDisplay() {
		return this.displayed;
	}
}

export class ProblemsViewMgr extends BaseViewMgr {
	public readonly type = "problems";
	private states = new Map(
		[
			["showErrors", true],
			["showWarnings", true],
			["showSuppressed", false],
			["showInfos", false],
			["sortByAsc", true],
		]
	);

	constructor(
		sysConfig: SysConfig,
		runtime: Runtime,
	) {
		super(
			sysConfig,
			runtime,
			"problemsView",
			"Problems",
			!isEclipse(),
		);
	}

	public isApplicable() {
		return true;
	}

	public getSummaryItems(includeSuppressed?: boolean) {
		return this.sysConfig.getSummaryItems(includeSuppressed);
	}

	public setStates(key: string, val: boolean) {
		this.states.set(key, val);
	}

	public getStates() {
		return this.states;
	}
}

export type OutputViewMgr = HistoryViewMgr | MetaViewMgr |
	UserPreferenceViewMgr | GeneratedFilesViewMgr | ReferencedFilesViewMgr |
	IOSetViewMgr | DeviceViewMgr | BoardViewMgr | ProblemsViewMgr;
