import * as React from "react";
import * as _ from "lodash";
import { BasicModal, IModalMinProps } from "./BasicModal";
import { defaultFontSize } from "../styles/themes";
import { ConfirmModal } from "./ConfirmModal";
import { CircularProgress, Typography } from "../../imports/material-ui-imports";
import { commonStyles } from "../styles/common";

interface LogoutProps extends IModalMinProps {
	confirmAction: () => void;
	savingPromise: Promise<void>;
}

interface LogoutState {
	saving: boolean;
}

export class LogoutModal extends React.Component<LogoutProps, LogoutState> {

	public override state = {
		saving: true,
	};

	public override componentDidMount() {
		const onSaveComplete = () => this.setState({ saving: false });
		if (this.props.savingPromise) {
			this.props.savingPromise.then(onSaveComplete, onSaveComplete);
		} else {
			this.setState({ saving: false });
		}
	}

	public override render() {
		const { confirmAction, savingPromise, ...rest } = this.props;
		if (this.state.saving) {
			return (
				<BasicModal
					{...rest}
					id={"saving"}
					onClose={() => { }}
				>
					<div>
						<CircularProgress color="primary" style={{ ...commonStyles.smallIcon }} />
						<span style={{ paddingLeft: "10px", fontSize: defaultFontSize }}>
							{"saving..."}
						</span>
					</div>
				</BasicModal>
			);
		} else {
			return (
				<ConfirmModal
					{...rest}
					title={"You have been logged out..."}
					id={"logoutModal"}
					confirmAction={confirmAction}
					confirmText={"Log in"}
				>
					<Typography variant="body2" style={{ whiteSpace: "pre" }}>
						{"You have been logged out from SysConfig. Please press Login to continue with your session."}
					</Typography>
				</ConfirmModal>
			);
		}
	}
}
