import * as _ from "lodash";
import React = require("react");
import { AsyncComponent } from "../AsyncComponent";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { assertUnreachable } from "../../services/utils";
import { MarkdownContent } from "../MarkdownContent";
import { ResourceType } from "../../services/resources/metaContentLoaders/resourceLoader";
import { OutputViewError } from "./OuputViewError";
import { ProgressBar } from "../ProgressBar";
import { MetaViewMgr } from "../../services/ui/outputView";
import { ITreeNode } from "../TreeNode";
import { IFormatter } from "../../services/formatting/formattingTypes";
import { ConfigStoreActions } from "../../services/configStore";

interface IState {
	currentContent: string;
	exception?: Error;
	failureReason?: string;
}

interface ICardForGeneratedProps {
	mgr: MetaViewMgr;
	selectedTreeNode: ITreeNode;
	actions: ConfigStoreActions;
	formatter: IFormatter;
}

// This is a special Card component that handles an async content source
export class CardForGenerated extends AsyncComponent<ICardForGeneratedProps & IGlobalServiceProps, IState> {
	public override state: IState = {
		currentContent: "",
	};

	public override render() {
		return (
			this.hasError() ?
				<OutputViewError
					{...this.props}
					exception={this.state.exception}
					failureReason={this.state.failureReason} /> :
				this.renderView()
		);
	}

	protected propsChanged(nextProps: Readonly<ICardForGeneratedProps>) {
		// This stopping condition is needed to prevent infinite loop
		// between setState and componentDidUpdate.
		// Right now it is depending on the fact that the props.getView functions
		// passed in do not equal when the parent re-renders.
		// It would be better if there is an explicit "key" that can 
		// make sure the props have changed.
		return !_.isEqual(this.props, nextProps);
	}

	protected clearAsyncData() {
		this.setState({
			exception: undefined,
			failureReason: undefined,
			currentContent: "",
		});
	}

	protected async fetchAsyncData() {
		let currentContent: string = "";
		let failureReason: string = "";
		let exception: Error = null;

		// Generate the current 
		try {
			currentContent = await this.props.mgr.generateView(this.props.selectedTreeNode);
		} catch (e) {
			if (_.isString(e)) {
				failureReason = e;
			} else {
				// Exception - save it to display it
				exception = e;
			}
		}

		return {
			failureReason,
			exception,
			currentContent,
		};
	}

	private renderView() {
		if (!this.state.currentContent) {
			return <ProgressBar title={"Generating"} />;
		} else {
			const viewFile = this.props.mgr.getViewFile();
			const viewType = viewFile.viewType;
			switch (viewType) {
				case "markdown":
					return <MarkdownContent
						markdownSrc={this.state.currentContent}
						canonicalName={viewFile.path}
						resourceType={ResourceType.TEMPLATE}
						formatter={this.props.formatter}
						resourceLoader={this.props.mgr.getResourceLoader()}
						actions={this.props.actions}
						style={this.props.mgr.isExpanded() ? { padding: "0 10px 0 10px" } :
							{ padding: "0 10px 0 10px", maxHeight: 320 }}
					/>;
				default:
					assertUnreachable(viewType);
			}
		}
	}

	private hasError() {
		return !!this.state.exception || !!this.state.failureReason;
	}
}
