import * as _ from "lodash";
import * as React from "react";
import { ButtonConfigurableMgr } from "../../../../services/objectManagers/configurables/buttonConfigurableMgr";
import { ModuleInstanceMgr, NonObjectMemberMgr } from "../../../../services/objectManagers/moduleInstance";
import { CConfigurable, IConfigurableProps } from "../../../../services/objectManagers/ui/configurables/configurable";

interface IProps {
	moduleMgr: ModuleInstanceMgr;
}

export function FloatingMetaButtons(props: IProps & Omit<IConfigurableProps, "mgr">) {
	const { moduleMgr, ...rest } = props;
	if (!moduleMgr) {
		return null;
	}

	const buttons = _.filter(moduleMgr.memberMgrs, (m) => m instanceof ButtonConfigurableMgr) as NonObjectMemberMgr[];
	return <>
		{_.map(buttons, (c) =>
			<CConfigurable {...rest} mgr={c} key={c.def.name} />
		)}
	</>;
}
