import * as _ from "lodash";
import { ManagedObjectProxyTarget } from "./objectManagers/proxyHandlers/managedObjectProxyHandler";
import { isUnderTest } from "./platform";
import { HardwareConfigurable, Module, StandardConfigurable } from "public/defs";
import { FunctionKeys } from "utility-types";

// Guard system.modules access
let moduleAccessEnabled = true;
export function isModuleAccessEnabled() {
	return moduleAccessEnabled;
}

// These are all the functions we guard.  We do not guard the validates as they should be able to access
// other modules, likewise for the calculated configurable's getValue

type GuardedCallbacks =
	Exclude<FunctionKeys<StandardConfigurable>, "getValue"> |
	Exclude<FunctionKeys<Module>, "validate" | "validatePinmux"> |
	FunctionKeys<HardwareConfigurable>;

let callbackName: GuardedCallbacks = null;
let currentCallbackContext: ManagedObjectProxyTarget;

export function getCurrentlyRunningCallbackName() {
	return callbackName;
}

export function getCurrentlyRunningCallbackContext() {
	return currentCallbackContext;
}

export function guardCallbackAccess<Ret>(
	cb: () => Ret,
	cbName: GuardedCallbacks,
	context?: ManagedObjectProxyTarget,
	moduleName?: string,
) {
	try {
		moduleAccessEnabled = false;
		callbackName = cbName;
		if (moduleName && context && !moduleShouldSkipContextCheck(moduleName)) {
			currentCallbackContext = context;
		}
		return cb();
	} finally {
		moduleAccessEnabled = true;
		callbackName = null;
		currentCallbackContext = undefined;
	}
}

function moduleShouldSkipContextCheck(moduleName: string) {
	if (isUnderTest()) {
		return false;
	}
	const exceptionList = ["/ti/drivers/Power", "/ti/drivers/power", "/ti/radioconfig/"];
	return _.some(exceptionList, (exception) => moduleName.includes(exception));
}
