import * as React from "react";
import * as _ from "lodash";
import { IPInstance } from "clockTree";
import { discriminate, IPInstanceShape } from "../../../services/clockTree/discriminate";
import { ConfigStoreActions } from "../../../services/configStore";
import { ClockTreeNode, GraphSettings } from "../../../services/instanceContainers/clockTreeNode";
import { assertUnreachable } from "../../../services/utils";
import { ClassesType, maxNodeWidth } from "../styling/clockTreeStyles";
import { ExtendedElkNode } from "../layout/customTypes";
import { DividerNode } from "./DividerNode";
import { GenericNode } from "./GenericNode";
import { MuxNode } from "./MuxNode";
import { PinFunctionNode } from "./PinFunctionNode";
import { MultiplierNode } from "./MultiplierNode";
import { OscillatorNode } from "./OscillatorNode";
import { GateNode } from "./GateNode";
import { NamedConnectionNode } from "./NamedConnectionNode";
import { AdderNode } from "./AdderNode";
import { Validations } from "../../../services/objectManagers/validations";
import { applyNodeStyles } from "./StyleNode";

export interface INodeProps {
	node: ExtendedElkNode;
	onSelect: (selection: string) => void;
	treeNode: ClockTreeNode;
	actions: ConfigStoreActions;
	displayScriptName: boolean;
	searchText: string,
	disabledInstances: string[],
	usedInstances: string[],
	classes: ClassesType["classes"],
	validations?: Validations,
	selected?: boolean,
}

export function isDynamic(node: ExtendedElkNode, frequencyLabels: string[]) {
	const discriminated = discriminate(node.data.ipInstance);
	switch (discriminated.shape) {
		case IPInstanceShape.DIVIDER:
			return _.size(discriminated.ipInstance.divideValues) > 1;		// Configurable dividers will have a drop down for the value
		case IPInstanceShape.MULTIPLIER:
			return _.size(discriminated.ipInstance.multiplyValues) > 1;		// Configurable multipliers will have a drop down for the value
		case IPInstanceShape.GATE:											// Gates have a checkbox to enable/disable the gate
		case IPInstanceShape.MUX:											// Muxes have radio buttons that change based on config		
			return true;
		case IPInstanceShape.NAMED_CONNECTION:
			return _.includes(frequencyLabels, node.data.ipInstance.name);	// Named connections display the frequency if in this list
		default:
			assertUnreachable(discriminated);
		case IPInstanceShape.PIN_FUNCTION:									// All other nodes are purely static rendering
		case IPInstanceShape.OSCILLATOR:
		case IPInstanceShape.ADDER:
		case IPInstanceShape.LARGE_SQUARE:
		case IPInstanceShape.MEDIUM_SQUARE:
		case IPInstanceShape.SMALL_SQUARE:
			return false;
	}
}

// Based on the ipInstance type, renders the appropriate underlying node component

export function NodeComponent(props: INodeProps & ClassesType) {
	const discriminated = discriminate(props.node.data.ipInstance);
	const classes = applyNodeStyles(props);

	// Filter out the props that are used just for styling so that nodes can render or not based on only the other settings

	const { selected, usedInstances, disabledInstances, searchText, validations, ...nodeProps } = props;
	switch (discriminated.shape) {
		case IPInstanceShape.DIVIDER:
			return <DividerNode {...nodeProps} classes={classes} />;
		case IPInstanceShape.MUX:
			return <MuxNode {...nodeProps} classes={classes} />;
		case IPInstanceShape.PIN_FUNCTION:
			return <PinFunctionNode {...nodeProps} classes={classes} />;
		case IPInstanceShape.MULTIPLIER:
			return <MultiplierNode {...nodeProps} classes={classes} />;
		case IPInstanceShape.OSCILLATOR:
			return <OscillatorNode {...nodeProps} classes={classes} />;
		case IPInstanceShape.GATE:
			return <GateNode {...nodeProps} classes={classes} />;
		case IPInstanceShape.ADDER:
			return <AdderNode {...nodeProps} classes={classes} />;
		case IPInstanceShape.NAMED_CONNECTION:
			return <NamedConnectionNode {...nodeProps} classes={classes} />;
		case IPInstanceShape.LARGE_SQUARE:
		case IPInstanceShape.MEDIUM_SQUARE:
		case IPInstanceShape.SMALL_SQUARE:
			return <GenericNode {...nodeProps} classes={classes} />;
		default:
			assertUnreachable(discriminated);
	}
}

const elkSpacingBetweenEdges = 10;	// https://www.eclipse.org/elk/reference/options/org-eclipse-elk-spacing-edgeEdge.html
const edgeThickness = 1;			// https://www.eclipse.org/elk/reference/options/org-eclipse-elk-edge-thickness.html
const pinSpacing = elkSpacingBetweenEdges + edgeThickness;
const maxPinsBeforeGrowth = Math.ceil(maxNodeWidth / pinSpacing);

// Based on the ipInstance type, returns an appropriate size for the node

export function getNodeInfo(node: IPInstance, { frequencyLabels }: GraphSettings) {
	const discriminated = discriminate(node);
	switch (discriminated.shape) {
		case IPInstanceShape.MULTIPLIER:
		case IPInstanceShape.DIVIDER:
			return { width: maxNodeWidth / 1.5, height: maxNodeWidth / 3.75 };

		case IPInstanceShape.MUX:

			// We have muxes with 36 inputs.  And the radio control it renders is much larger than the edge thickness
			// that we need for pins.  Hence the 25 multiplier (determined based on eyeballing it).

			const numPins = Math.max(4, _.size(node.inPins));
			return { width: maxNodeWidth / 2, height: 50 + numPins * 25 };

		case IPInstanceShape.ADDER:
		case IPInstanceShape.PIN_FUNCTION:
		case IPInstanceShape.SMALL_SQUARE:
			return { width: maxNodeWidth / 3.75, height: maxNodeWidth / 3.75 };

		case IPInstanceShape.NAMED_CONNECTION:
			if (discriminated.shape === IPInstanceShape.NAMED_CONNECTION && !_.includes(frequencyLabels, node.name)) {
				// a label only
				return { width: 0, height: 0 };
			}
			// a box displaying the frequency
			return { width: maxNodeWidth / 1.5, height: maxNodeWidth / 3.75 };

		case IPInstanceShape.OSCILLATOR:
		case IPInstanceShape.MEDIUM_SQUARE:
			return { width: maxNodeWidth / 2, height: maxNodeWidth / 2 };

		case IPInstanceShape.GATE:
			return { width: maxNodeWidth / 6, height: maxNodeWidth / 3 };

		case IPInstanceShape.LARGE_SQUARE:

			// Use a default square, but if it has many pins, grow the height by the number of extra pins over the 
			// normal max

			const extraPins = Math.max(maxPinsBeforeGrowth, _.size(node.inPins), _.size(node.outPins)) - maxPinsBeforeGrowth;
			return { width: maxNodeWidth, height: (extraPins * pinSpacing) + maxNodeWidth };

		default:
			assertUnreachable(discriminated);
	}
}
