import * as React from "react";
import * as _ from "lodash";
import { ExtendedElkLine, ExtendedElkNode } from "../layout/customTypes";
import { ConfigStoreActions } from "../../../services/configStore";
import { ClassesType } from "../styling/clockTreeStyles";
import { ClockTreeNode } from "../../../services/instanceContainers/clockTreeNode";
import { Nodes } from "../nodes/Nodes";
import { Lines } from "../edges/Lines";
import { Joints } from "../edges/joints";
import { FrequencyLabelTooltip } from "../edges/FrequencyLabelTooltip";
import { Validations } from "../../../services/objectManagers/validations";
import { Groups } from "../groups/Groups";
import { Port } from "clockTree";

// This component renders a clock tree graph based on the passed in ELK layout.
// If the layout contains groups, each group will render a group box, and then another one of these components.
// The highlighted signal path is passed in as a prop so that it is only calculated once for all groups, but it keeps
// keeps track itself of the currently hovered over line for a tool tip

export interface IClockTreeInnerGraphProps {
	layout: ExtendedElkNode;
	onSelect: (selection: string) => void;
	actions: ConfigStoreActions;
	treeNode: ClockTreeNode;
	validations: Validations;
	onMouseEnter: (line: ExtendedElkLine) => void;
	onMouseLeave: () => void;
	onClick: (line: ExtendedElkLine) => void;
	selectedSignalPath: Port[];
	highlightSignalPath: Port[];
	displayScriptName: boolean;
	usedInstances: string[];
	disabledInstances: string[];
	searchText: string;
}

interface IState {
	currentlyHighlightedLine: ExtendedElkLine;
}

export class ClockTreeInnerGraph extends React.Component<IClockTreeInnerGraphProps & ClassesType, IState> {
	public override state: IState = {
		currentlyHighlightedLine: null,
	};

	public override render() {
		const {
			layout,
			onSelect,
			onClick,
			treeNode,
			actions,
			validations,
			displayScriptName,
			usedInstances,
			disabledInstances,
			searchText,
			classes,
		} = this.props;

		const result = <>
			<Groups {...this.props} />
			<Nodes
				nodes={layout.children}
				validations={validations}
				onSelect={onSelect}
				treeNode={treeNode}
				actions={actions}
				usedInstances={usedInstances}
				disabledInstances={disabledInstances}
				classes={classes}
				displayScriptName={displayScriptName}
				searchText={searchText}
			/>
			<FrequencyLabelTooltip classes={classes} selectedLine={this.state.currentlyHighlightedLine} treeNode={treeNode} />
			<svg className={classes.svgLinesContainer}>
				<g>
					<Lines
						key="lines"
						lines={layout.lines}
						classes={classes}
						onMouseEnter={this.onMouseEnter}
						onMouseLeave={this.onMouseLeave}
						onClick={onClick}
						selectedSignalPath={this.props.selectedSignalPath}
						highlightSignalPath={this.props.highlightSignalPath}
					/>
					<Joints key="joints" joints={layout.joints} className={classes.joint} />
				</g>
			</svg>
		</>;
		return result;
	}

	private onMouseEnter = (currentlyHighlightedLine: ExtendedElkLine) => {
		this.setState({ currentlyHighlightedLine });
		this.props.onMouseEnter(currentlyHighlightedLine);
	}

	private onMouseLeave = () => {
		this.setState({ currentlyHighlightedLine: null });
		this.props.onMouseLeave();
	}
}
