	public async refreshFileTree(moduleMgr: FileModuleMgr) {
		const newRootPath = moduleMgr.getRequestedRootPath();
		let newTreeRoot: IStorageFile;
		if (!newRootPath) {
			newTreeRoot = undefined;
		} else {
			const children = await storage.readDirectory(storage.formatPathFromUser(newRootPath), newRootPath);
			newTreeRoot = {
				name: "/",
				path: newRootPath,
				relativePath: newRootPath,
				isDirectory: true,
				children,
			};
		}
		moduleMgr.refreshTree(newTreeRoot);
		this.sysConfig.validateAndSolve();
		this.history.updateCurrent();
		this.eventAnyChange.fire();
	}

	public requestFile(moduleMgr: FileModuleMgr, file: IStorageFile) {
		if (file.path === moduleMgr.getRootPath()) {
			this.setSelection(createSwitchInstanceSelection(this.selection, moduleMgr.static.getID()));
		} else if (!file.isDirectory) {
			if (!moduleMgr.getInstanceByRelativePath(file.relativePath)) {
				moduleMgr.createFileInstance(file);
			}
			const listItem = moduleMgr.getInstanceByRelativePath(file.relativePath);
			this.setSelection(createSwitchInstanceSelection(this.selection, listItem.getID()));
		}
		this.eventAnyChange.fire();
	}

	public toggleFolderExpansion(folder: IStorageFile, open: boolean) {
		folder.expanded = open;
		this.history.updateCurrent();
	}

	public focusOnMember(memberMgr: AnyMemberMgr) {
		const formmater = this.getMessageFormatter(true)(memberMgr.getParentRuntimeObj(), memberMgr.def.name);
		const msg = _.first(formmater.toParts());
		if (isFormattedLink(msg)) {
			msg.linkAction(this);
		}
	}

	// called by eclipse to navigate by parsing a CLI output message
	// currently only handles errors on the software and reservation tab
	// as those are they only known use cases.
	public navigateToByCliMsg(msg: string) {

		const runtimes = this.sysConfig.getRuntimes();
		if (_.size(runtimes) === 1) {
			// The message won't include the context if there's only one, so lets add it in 
			// ourselves so we can easily split on the next step

			msg = `${_.first(runtimes).getName()}${memberSeparator}${msg}`;
		}

		const [context, prefix, membersListStr] = _.split(msg, memberSeparator);
		const runtime = _.find(runtimes, (r) => r.getName() === context);
		const runtimeIndex = _.indexOf(runtimes, runtime);

		let memberPath = membersListStr ? _.split(membersListStr, ".") : [];

		const regexRes = prefix.match(/(.+)\((.+)\)/);

		let selection: SelectionInConfigStoreByName;
		if (regexRes && regexRes[2] === reservedMarkerText) {

			const instanceName = regexRes[1];
			// look up the interface
			const ifaceMgr
				= _.find(runtime.getInterfaceMgrs(),
					(iface) => _.some(iface.instances, (i) => i.getName() === instanceName));

			// Formatting is a bit specialized for peripherals such that
			// we omit $assign on peripheral conflicts. However, when we navigate
			// we do want to set the focus on the "Use Peripheral" configurable, so 
			// lets just add it here. This gives the desired behaviour and still
			// keeps the cli output clean

			if (_.isEmpty(memberPath)) {
				memberPath = ["$assign"];
			}

			selection = {
				runtimeIndex,
				tabName: TabName.RESERVATION,
				treeNodePath: ifaceMgr.getNodePath(),
				instanceName,
				memberPath,
			};

		} else {

			const moduleName = regexRes ? regexRes[2] : prefix;
			const moduleInstanceName = regexRes ? regexRes[1] : null;
			const moduleMgr = runtime.getModuleMgr(moduleName);

			selection = {
				runtimeIndex,
				tabName: TabName.SOFTWARE,
				treeNodePath: moduleMgr.getNodePath(),
				// if nothing in (), must be static
				instanceName: moduleInstanceName || moduleMgr.static.getName(),
				memberPath,
			};
		}

		if (this.setSelectionByName(selection)) {
			this.eventAnyChange.fire();
		}
	}

	public removeInstance(myListItem: IMyListItem) {
		this.changeConfiguration(() => {

			const instances = this.getSelectedNode().getInstances();
			const removedItemIndex = _.findIndex(instances, (i) => i === myListItem);
			const wasSelected = myListItem === this.getSelectedListItem();

			const name = myListItem.getNameMgr().getDisplayValue();

			// Optimize auto remove behavior.
			// Since, scripting always works as a two step add, once configuration is serialized
			// statics are always marked as user created, thus without this fix the auto removing
			// of statics is inconsistent between prior to saving to a script and after restore from a script. 
			// Since the view is optimized for static not to exist without an instance. Thus, It is reasonable 
			// to remove static once the last instance goes away.

			if (myListItem instanceof ModuleInstanceMgr) {
				const modMgr = myListItem.getModuleMgr();
				myListItem.remove();
				if (modMgr.getUIAdd() === "instanceOnly" && _.isEmpty(modMgr.instances)) {
					modMgr.removeModule();
				}
			} else {
				myListItem.remove();
			}

			if (wasSelected) {
				this.updateSelectionAfterDelete(removedItemIndex);
			}

			return `Removed instance of ${name}`;
		});
	}

	public setSelectedUseCase(req: InterfaceInstanceMgr, useCaseName: string) {
		this.changeConfiguration(() => {
			req.setUseCase(useCaseName);
			return `Changed "Use Case" on ${this.getSelectionDisplayName()}`;
		});
	}

	public setSelectedPeripheral(req: InterfaceInstanceMgr, assignTo: string, displayName = "Use Peripheral") {
		const needSolve = req.getSolverRequirement().solution.assignedToName !== assignTo;
		this.changeConfiguration(() => {
			// only need to re-solve if we are setting it to a different value

			req.setPeripheral(assignTo);
			return `Changed "${displayName}" on ${this.getSelectionDisplayName()}`;
		}, needSolve ? SolveType.FULL : SolveType.UPDATE);
	}

	public setSelectedVoltage(req: InterfaceInstanceMgr, voltage: string) {
		this.changeConfiguration(() => {
			req.setVoltage(voltage);
			return `Changed "Preferred Voltage" on ${this.getSelectionDisplayName()}`;
		});
	}

