	// IConfigurablesActions
	public setConfigurableValue<T1 extends AMemberMgr<T2>, T2>(
		configurable: T1,
		value: T2) {

		const selectedNode = this.getSelectedNode();
		const isPowerDomainConfig = selectedNode instanceof ModuleMgr && selectedNode.getName() === powerDomainsModuleName;

		this.changeConfiguration(() => {

			const cachedListItemName = this.getSelectionDisplayName();
			configurable.set(value, SetSource.USER_ASSIGN);
			return `Changed "${getDisplayName(configurable.def, false)}" on ${cachedListItemName}`;
		}, (!this.getSelectedRuntime().isCorePinmux() || isPowerDomainConfig) ? SolveType.FULL : SolveType.NONE);
	}

	// Sets value of NumberConfigurable by passing a string value
	// this is useful for GUI that need to store the value of a configurable as a string
	public setNumericConfigurableValue(configurable: NumericConfigurableMgr<any>, value: string) {
		this.changeConfiguration(() => {
			configurable.setValueAsString(value, SetSource.USER_ASSIGN);
			// sys config meta data can cause a change in solver reqs
			return `Changed "${getDisplayName(configurable.def, false)}" on ${this.getSelectionDisplayName()}`;
		}, this.getSelectedRuntime().isCorePinmux() ? SolveType.NONE : SolveType.FULL);
	}

