	public saveProjectAs(newFilePath: string) {
		return this.handleSave(() => {
			const script = this.getCurrentScript();
			if (script.get() !== newFilePath) {

				// The args also include the saved script, so update them

				const parsedArgs = parseArgs(this.cliArgs, true).parsedArgs;
				const context = this.getSelectedRuntime().getName();
				const scriptPath = script.get();
				const scriptArgs = _.find(parsedArgs.script,
					(args) => args.context?.value === context || args.script?.value === scriptPath);
				script.set(newFilePath);
				const scriptArg = { value: newFilePath, userArgName: "--script" };
				if (scriptArgs) {
					scriptArgs.script = scriptArg;
				} else {

					// Only include "context" if there is more than one
					// It's not necessarily a valid parameter otherwise

					const newScriptArgs = _.size(this.sysConfig.getRuntimes()) === 1
						? { script: scriptArg }
						: { script: scriptArg, context: { value: context, userArgName: "--context" } };
					parsedArgs.script.push(newScriptArgs);
				}
				this.cliArgs = toCLIArgs(parsedArgs);
			}
			return this.saveAllScripts();
		});
	}

