import * as React from "react";
import * as _ from "lodash";

import { IconButton } from "../imports/material-ui-imports";
import { ContentSave, ContentSaveAll } from "../imports/mdi-material-ui-imports";
import { Tooltip } from "./Tooltip";
import { commonStyles } from "./styles/common";
import { ITemplateActions } from "./actions/ITemplateActions";
import { isCloud } from "../services/platform";
import { ReferenceFile, CodeGenTemplateFile } from "dataInterfaces";
import { FileBrowse } from "./FileBrowse";
import { IGlobalServiceProps } from "./IGlobalServicesProps";

interface IProps<T> {
	actions: ITemplateActions<T>,
	files: T[],
	id: string,
	disabled?: boolean,
}

export class SaveGeneratedCode<T extends CodeGenTemplateFile | ReferenceFile>
	extends React.Component<IProps<T> & Pick<IGlobalServiceProps, "modalService" | "errorStore">> {

	public override render() {

		return (
			<Tooltip title={this.getTooltip()} placement="left">
				{!isCloud() && // In node we need to browse and write out to that folder					

					<FileBrowse
						modalService={this.props.modalService}
						errorStore={this.props.errorStore}
						id={this.props.id}
						folder={true}
						onChange={(folder) => {
							this.props.actions.downloadFiles(folder, this.props.files);
						}}
						disabled={this.props.disabled}
					>
						<IconButton style={{ cursor: "pointer" }} disabled={this.props.disabled} component="span">
							{this.getIcon()}
						</IconButton>
					</FileBrowse>
				}
				{isCloud() &&

					// In the cloud, we just need to create a download and let the user decide where downloads go

					<IconButton
						style={{ cursor: "pointer" }}
						id={this.props.id}
						onClick={() => {
							this.props.actions.downloadFiles(this.getCloudFileName(), this.props.files);
						}}
						disabled={this.props.disabled} >
						{this.getIcon()}
					</IconButton>
				}
			</Tooltip >
		);
	}

	private getTooltip() {
		if (this.props.disabled) {
			return "";
		}
		if (_.size(this.props.files) === 1) {
			return "Save File";
		}
		return "Save All Files";
	}

	private getCloudFileName() {
		if (_.size(this.props.files) === 1) {
			return _.first(this.props.files).name;				// single file
		} else if (_.every(this.props.files, (f) => f.category === _.first(this.props.files).category)) {
			return `${_.first(this.props.files).category}.zip`;	// single category (with multiple files)
		} else {
			return "all.zip";									// all files
		}
	}

	private getIcon() {
		if (_.size(this.props.files) !== 1) {
			return <ContentSaveAll color="primary" style={commonStyles.smallIcon} />;
		}
		return <ContentSave color="primary" style={commonStyles.smallIcon} />;
	}
}
