import { assertUnreachableNoThrow } from "../../utils";
import { SCHEMA, validateJSONschema, SCHEMAToType } from "../../JSONschemaValidator";
import { IPInstance } from "clockTree";
import { BigIntConfigurableMgr } from "./bigIntConfigurableMgr";
import { BooleanConfigurableMgr } from "./booleanConfigurableMgr";
import { CloudFileTextConfigurableMgr } from "./cloudFileTextConfigurableMgr";
import { DateConfigurableMgr } from "./dateConfigurableMgr";
import { DynamicEnumerationConfigurableMgr } from "./dynamicEnumerationConfigurableMgr";
import { EnumerationConfigurableMgr } from "./enumerationConfigurableMgr";
import { ExternalExecutableConfigurableMgr } from "./externalExecutableConfigurableMgr";
import { LocalFileTextConfigurableMgr } from "./localFileTextConfigurableMgr";
import { MultiPartTextConfigurableMgr } from "./multiPartTextConfigurableMgr";
import { MultiValueDynamicEnumerationConfigurableMgr } from "./multiValueDynamicEnumerationConfigurableMgr";
import { MultiValueEnumerationConfigurableMgr } from "./multiValueEnumerationConfigurableMgr";
import { NumberConfigurableMgr } from "./numberConfigurableMgr";
