export function validateConfigurable<T extends SCHEMA>(
	def: SCHEMAToType<T>, context: string, schema: T, isCorePinmux = false) {

	// Configurables from core-pinmux are already validated by the converter, so re-validating now wouldn't
	// catch anything.  Plus, there are extra properties on them that are used by the templates, so we'd
	// need special definitions

	if (!isCorePinmux) {
		const errors = validateJSONschema(schema, def);
		if (errors) {
			throw new Error(`${context}: Validation failed: ${errors}`);
		}
	}
}

/**
 * Create a configurable member manager from a configurable definition coming from meta content.
 * @param def
 * @param parentObjectMgr
 */
export function createMetaContentConfigurableMgr(
	def: StandardConfigurable,
	parentObjectMgr: AObjectMgr<any>,
	formattersMap: FormattersMap,
	context: string,
	isCorePinmux = false,
	ipInstance?: IPInstance,
	frequencyFormat?: FrequencyFormat,
): MetaContentConfigurableMgr {
	context = `Configurable "${def.name}" of "${context}"`;

	let mgr: MetaContentConfigurableMgr;

	if (isPinFrequencyConfigurable(def, ipInstance)) {
		validateConfigurable(def, context, SCHEMA.PinFrequencyConfigurable, isCorePinmux);
		mgr = new PinFrequencyConfigurableMgr(parentObjectMgr, formattersMap, def, frequencyFormat);
	} else if (isEnumerationConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.EnumConfigurable, isCorePinmux);
		mgr = new EnumerationConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else if (isDateConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.DateConfigurable, isCorePinmux);
		mgr = new DateConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else if (isMultiValueDynamicEnumerationConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.MultiValueDynamicEnumConfigurable, isCorePinmux);
		mgr = new MultiValueDynamicEnumerationConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else if (isMultiValueEnumerationConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.MultiValueEnumConfigurable, isCorePinmux);
		mgr = new MultiValueEnumerationConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else if (isBooleanConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.BooleanConfigurable, isCorePinmux);
		mgr = new BooleanConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else if (isNumberConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.NumberConfigurable, isCorePinmux);
		mgr = new NumberConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else if (isDynamicEnumerationConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.DynamicEnumConfigurable, isCorePinmux);
		mgr = new DynamicEnumerationConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else if (isTextConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.TextConfigurable, isCorePinmux);
		mgr = new TextConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else if (isBigIntConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.BigIntConfigurable, isCorePinmux);
		mgr = new BigIntConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else if (isMultiTextConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.MultiPartTextConfigurable, isCorePinmux);
		mgr = new MultiPartTextConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else if (isFileTextConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.FileTextConfigurable, isCorePinmux);
		// this check must be before check of textConfigurable
		mgr = isCloud() ?
			new CloudFileTextConfigurableMgr(parentObjectMgr, formattersMap, def) :
			new LocalFileTextConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else if (isExternalExecutableConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.ExternalExecutableConfigurable, isCorePinmux);
		mgr = new ExternalExecutableConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else if (isButtonConfigurable(def)) {
		validateConfigurable(def, context, SCHEMA.ButtonConfigurable, isCorePinmux);
		mgr = new StandardButtonConfigurableMgr(parentObjectMgr, formattersMap, def);
	} else {

		// Current version of typescript won't filter out the non-string enum template types, so we 
		// have to do that manually

		if (!isEnumerationConfigurable<number>(def) && !isMultiValueEnumerationConfigurable<number>(def) &&
			!isDynamicEnumerationConfigurable<number>(def) && !isMultiValueDynamicEnumerationConfigurable<number>(def)) {
			assertUnreachableNoThrow(def);
		}

		throw new Error(`${context} is of an unknown schema type`);
	}

	return mgr;
}

export type MetaContentConfigurableMgr =
	EnumerationConfigurableMgr
	| DateConfigurableMgr
	| MultiValueDynamicEnumerationConfigurableMgr
	| MultiValueEnumerationConfigurableMgr
	| BooleanConfigurableMgr
	| NumberConfigurableMgr
	| DynamicEnumerationConfigurableMgr
	| TextConfigurableMgr
	| BigIntConfigurableMgr
	| MultiPartTextConfigurableMgr
	| CloudFileTextConfigurableMgr
	| LocalFileTextConfigurableMgr
	| ExternalExecutableConfigurableMgr
	| PinFrequencyConfigurableMgr
	| StandardButtonConfigurableMgr;

export function isBooleanConfigurable(def: Configurable<any>): def is BooleanConfigurable {
	return typeof def.default === "boolean";
}

export function isNumberConfigurable(def: Configurable<any>): def is NumberConfigurable {
	return typeof def.default === "number" && !isEnumerationConfigurable(def) && !isDynamicEnumerationConfigurable(def);
}

export function isEnumerationConfigurable<T extends number | string = string>(def: Configurable<any>)
	: def is EnumerationConfigurable<T> {
	return (def as EnumerationConfigurable<T>).options &&
		!_.isFunction((def as EnumerationConfigurable<T>).options) &&
		!isMultiValueEnumerationConfigurable(def);
}

export function isDynamicEnumerationConfigurable<T extends number | string = string>(def: Configurable<any>):
	def is DynamicEnumerationConfigurable<T> {
	return (def as DynamicEnumerationConfigurable<T>).options &&
		_.isFunction((def as DynamicEnumerationConfigurable<T>).options) &&
		!isMultiValueDynamicEnumerationConfigurable(def);
}

export function isTextConfigurable(def: Configurable<any>): def is TextConfigurable {
	return typeof def.default === "string" &&
		!isEnumerationConfigurable(def) &&
		!isDynamicEnumerationConfigurable(def) &&
		!isFileTextConfigurable(def) &&
		!isMultiTextConfigurable(def) &&
		!isExternalExecutableConfigurable(def) &&
		!isButtonConfigurable(def);
}

function isExternalExecutableConfigurable(def: Configurable<any>): def is ExternalExecutableConfigurable {
	return !!(def as ExternalExecutableConfigurable).onLaunch;
}

function isButtonConfigurable(def: Configurable<any>): def is ButtonConfigurable {
	return !isExternalExecutableConfigurable(def) && !!(def as ButtonConfigurable).buttonText;
}

export function isMultiTextConfigurable(def: Configurable<any>): def is MultiPartTextConfigurable {
	return !!(def as MultiPartTextConfigurable).textType;
}

export function isFileTextConfigurable(def: Configurable<any>): def is FileTextConfigurable {
	return !isExternalExecutableConfigurable(def)
		&& !isButtonConfigurable(def)
		&& !!(def as FileTextConfigurable).fileFilter;
}

export function isDirectoryConfigurable(def: Configurable<any>): def is FileTextConfigurable {
	return isFileTextConfigurable(def) && def.pickDirectory;
}

export function isMultiValueEnumerationConfigurable<T extends number | string = string>(def: Configurable<any>)
	: def is MultiValueEnumerationConfigurable<T> {
	return _.isArray(def.default) &&
		(def as MultiValueEnumerationConfigurable<T>).options &&
		!_.isFunction((def as MultiValueEnumerationConfigurable<T>).options);
}

export function isBigIntConfigurable(def: Configurable<any>): def is BigIntConfigurable {
	return bigInt.isInstance(def.default);
}

export function isMultiValueDynamicEnumerationConfigurable<T extends number | string = string>(def: Configurable<any>):
	def is MultiValueDynamicEnumerationConfigurable<T> {
	return _.isArray(def.default) && (def as MultiValueDynamicEnumerationConfigurable<T>).options && _.isFunction((def as any).options);
}

export function isDateConfigurable(def: Configurable<any>)
	: def is DateConfigurable {
	return def.default instanceof Date;
}

export function isPinFrequencyConfigurable(def: Configurable<any>, ipInstance?: IPInstance): def is PinFrequencyConfigurable {
	return ipInstance && _.some([...ipInstance.outPins, ...ipInstance.inPins], (pin) => pin.name === def.name);
}
