import * as React from "react";
import * as _ from "lodash";
import { ElkPoint } from "elkjs";

// A small circle to indicate that two lines connect vs cross over each other

interface IProps {
	joint: ElkPoint;
	className: string;
}

export function JointComponent({ joint, className }: IProps) {
	return (
		<circle
			r={4}
			cx={joint.x}
			cy={joint.y}
			className={className}
		/>
	);
}
