import React = require("react");
import { ErrorBadge } from "../Badges";
import { ExceptionText } from "../ExceptionText";
import { IGlobalServiceProps } from "../IGlobalServicesProps";

export interface IOutputErrorProps {
	exception: Error;
	failureReason: string;
}

export class OutputViewError extends React.Component<IGlobalServiceProps & IOutputErrorProps> {
	public override render() {
		return (
			<span id="output_view_error">
				<ErrorBadge message={this.getMessage()} />
			</span>
		);
	}

	private getMessage() {
		return this.props.exception ?
			this.getExceptionText() :
			this.props.failureReason;
	}

	private getExceptionText() {
		return <ExceptionText
			theme={this.props.theme}
			description="An unexpected internal error occurred while generating this file:"
			exception={this.props.exception}
			inEditor={true}
		/>;
	}
}
