import * as _ from "lodash";
import { HardwareComponent } from "public/runtime";
import { ITreeNode } from "../../components/TreeNode";
import { ModuleToHardwareMap } from "../moduleToHardwareMap";

// A lightweight class that wraps ModuleToHardwareMap to expose some additional functions for 
// dealing with relationship between hardware and software
export class HardwareMgr {

	// If you make this object stateful, vs the simple wrapper it is now, please fix up
	// configStore to not re-create it every time
	constructor(private readonly moduleToHardwareMap: ModuleToHardwareMap) { }

	// get a list of associated Modules given a hardware Component
	// this uses the filterHardware() function in the module to get the list of modules that can use the provided HW
	public getSupportModules(component: HardwareComponent) {
		return this.moduleToHardwareMap.getModules(component);
	}

	// returns a list of list items that are using the given Component
	public getAddedListItems(component: HardwareComponent) {
		return _.chain(this.getSupportModules(component))
			.flatMap((moduleMgr) => {
				if (moduleMgr.isStaticOnly() && !!moduleMgr.static) {
					// add the static instance into the map if module is static only and instance is available
					return moduleMgr.static;
				} else {
					return moduleMgr.getInstances();
				}
			})
			.filter((listItems) => {
				return listItems.hardwareMemberMgr.getValue() === component;
			})
			.value();
	}

	public setTreeNode(component: HardwareComponent, treeNode: ITreeNode) {
		this.moduleToHardwareMap.setTreeNode(component, treeNode);
	}

	public resetTreeNodes() {
		this.moduleToHardwareMap.resetTreeNodes();
	}
}
