// Basic two column members view
// Takes a collection of members and renders them.

import React = require("react");
import * as _ from "lodash";
import { CommonClasses, commonStyles, withCommonStyles } from "../../../components/styles/common";
import { TableCell, TableRow } from "../../../imports/material-ui-imports";
import { AnyMemberMgr } from "../member";
import { Tooltip } from "../../../components/Tooltip";
import { IFormatter } from "../../formatting/formattingTypes";
import { LongDescription, DisplayLongDescButton } from "../../../components/LongDescription";
import { ResourceLoader, ResourceType } from "../../resources/metaContentLoaders/resourceLoader";
import { FormattedMsg } from "../../../components/FormattedMsg";
import { ILinkActions } from "../../../components/actions/ILinkActions";
import { mayBeScrollIntoView } from "../../../components/ComponentUtils";
import { IGlobalServiceProps } from "../../../components/IGlobalServicesProps";
import { CValidation } from "./validation";
import { Validations } from "../validations";
import { filterKeys } from "../../utils";
import { PinDisplayType } from "../../userPreferences";

export interface IMemberRowProps extends IGlobalServiceProps {
	memberMgr: AnyMemberMgr;
	formatter: IFormatter;
	validations: Validations;
	isStatic?: boolean;
	displayScriptName: boolean;
	devicePinDisplayType: PinDisplayType[];
	headerPinDisplayType: PinDisplayType[];
	resourceLoader: ResourceLoader;
	productLookupName: string;
	highlight: boolean;
	actions: ILinkActions;
	labelLeft?: JSX.Element;
	columns?: number;
	borderSides?: boolean;
	borderBottom?: boolean;
	style?: React.CSSProperties;
	conflictControl?: JSX.Element;
	hideValidation?: boolean;
}

interface IMemberRowStates {
	showDescription: boolean;
	isHover: boolean;
	memberUIHash: string;
}

const propKeysThatTriggerUpdate = filterKeys<IMemberRowProps>({
	memberMgr: true,
	formatter: false, // won't change without memberMgr changing
	validations: false, // won't change without memberMgr changing
	isStatic: false, // won't change without memberMgr changing
	displayScriptName: true,
	devicePinDisplayType: true, // these only affect pin display, but also don't change often
	headerPinDisplayType: true, // so we may as well always refresh regardless
	resourceLoader: false, // won't change without memberMgr changing
	productLookupName: false, // won't change without memberMgr changing
	highlight: true,
	actions: false, // won't change without memberMgr changing
	labelLeft: false, // won't change without memberMgr changing
	columns: false, // won't change without memberMgr changing
	borderSides: false, // won't change without memberMgr changing
	borderBottom: false, // won't change without memberMgr changing
	style: false, // won't change without memberMgr changing
	conflictControl: false, // won't change without memberMgr changing
	hideValidation: false, // won't change without memberMgr changing
	modalService: false, // won't change without memberMgr changing
	errorStore: false, // won't change without memberMgr changing
	theme: false, // not dynamic
	notificationService: false, // won't change without memberMgr changing
});

const stateKeysThatTriggerUpdate = filterKeys<IMemberRowStates>({
	memberUIHash: false, // explicitly checked
	showDescription: true,
	isHover: true,
});

class MemberRowImpl extends React.Component<IMemberRowProps, IMemberRowStates> {

	constructor(props: IMemberRowProps) {
		super(props);
		this.state = {
			showDescription: false,
			isHover: false,
			memberUIHash: undefined,
		};
	}

	public override shouldComponentUpdate(nextProps: Readonly<IMemberRowProps>, nextState: Readonly<IMemberRowStates>) {
		return (!this.state.memberUIHash || this.state.memberUIHash !== nextProps.memberMgr.getUIHash(nextProps.validations)) ||
			_.some(propKeysThatTriggerUpdate, (key) => nextProps[key] !== this.props[key]) ||
			_.some(stateKeysThatTriggerUpdate, (key) => nextState[key] !== this.state[key]);
	}

	public override componentDidUpdate() {

		// We updated - fetch the ui hash code so we don't always update over and over

		const uiHash = this.props.memberMgr.getUIHash(this.props.validations);
		if (uiHash !== this.state.memberUIHash) {
			this.setState({ memberUIHash: uiHash });
		}
	}

	public override render() {

		const memberMgr = this.props.memberMgr;
		if (memberMgr.uiState.hidden && !this.props.validations.getValidation(memberMgr)) {
			return null;
		}

		const scriptOrDisplayName = this.getDisplayName();
		const displayName = this.props.isStatic ? `${scriptOrDisplayName} (static)` : scriptOrDisplayName;
		const showDocDisplayBtn = memberMgr.def.longDescription && (this.state.isHover || this.state.showDescription);

		return (
			<React.Fragment>
				<ConfigTableRow
					id={"row_" + memberMgr.def.name}
					label={displayName}
					labelRight={
						< DisplayLongDescButton
							name={memberMgr.def.name}
							onClick={this.toggleShowDescription}
							hidden={!showDocDisplayBtn}
						/>
					}
					onMouseEnter={this.onMouseEnter}
					onMouseLeave={this.onMouseLeave}
					key={memberMgr.def.name}
					labelToolTip={memberMgr.def.description}
					valueToolTip={memberMgr.getToolTip()}
					onClick={this.onClick}
					formatter={this.props.formatter}
					actions={this.props.actions}
					modalService={this.props.modalService}
					notificationService={this.props.notificationService}
					errorStore={this.props.errorStore}
					theme={this.props.theme}
					highlight={this.props.highlight}
					style={this.props.style}
					labelLeft={this.props.labelLeft}
					columns={this.props.columns}
					borderSides={this.props.borderSides}
					borderBottom={this.props.borderBottom}
				>
					{this.childrenWithValidation()}
				</ConfigTableRow>
				<DescriptionRow
					memberMgr={memberMgr}
					turnOffDescription={this.toggleShowDescription}
					isVisible={memberMgr.def.longDescription && this.state.showDescription}
					resourceLoader={this.props.resourceLoader}
					productLookupName={this.props.productLookupName}
					formatter={this.props.formatter}
					actions={this.props.actions}
				/>
			</React.Fragment >
		);
	}

	protected getDisplayName() {
		return this.props.memberMgr.getDisplayName(this.props.displayScriptName);
	}

	private onMouseEnter = () => {
		this.setState({ isHover: true });
	}

	private onMouseLeave = () => {
		this.setState({ isHover: false });
	}

	private onClick = () => {
		this.props.actions.focusOnMember(this.props.memberMgr);
	}

	private toggleShowDescription = () => {
		const showDescription = !this.state.showDescription;
		this.props.memberMgr.setDescriptionVisibility(showDescription);
		this.setState({ showDescription });
	}

	private childrenWithValidation() {
		let isFirst = true;
		const memberMgr = this.props.memberMgr;

		return React.Children.map(this.props.children, (child) => {
			if (isFirst) {
				isFirst = false;
				return (
					<React.Fragment>
						{child}
						{!this.props.hideValidation &&
							<CValidation
								validations={this.props.validations}
								validatableObj={memberMgr}
								formatter={this.props.formatter}
								memberName={memberMgr.def.name}
								actions={this.props.actions}
								conflictControl={this.props.conflictControl}
							/>
						}
					</React.Fragment>
				);
			}
			return child;
		});
	}
}

interface IDescriptionRowProps {
	memberMgr: AnyMemberMgr;
	turnOffDescription: () => void;
	isVisible: boolean;
	resourceLoader: ResourceLoader;
	productLookupName: string;
	formatter: IFormatter;
	actions: ILinkActions;
}

class DescriptionRow extends React.Component<IDescriptionRowProps> {
	public override render() {
		if (this.props.isVisible) {
			return (
				< TableRow style={{ ...commonStyles.tableRowStyle, verticalAlign: "baseline" }} >
					<TableCell style={{ ...commonStyles.tableCellStyle }} colSpan={2} >
						<LongDescription
							id={this.props.memberMgr.def.name + "_documentation"}
							longDescription={this.props.memberMgr.def.longDescription}
							closeDescription={this.props.turnOffDescription}
							canonicalName={this.props.productLookupName}
							resourceType={ResourceType.CODE}
							resourceLoader={this.props.resourceLoader}
							actions={this.props.actions}
							formatter={this.props.formatter}
						/>
					</TableCell>
				</TableRow>
			);
		} else {
			return null;
		}
	}
}

interface IConfigTableRowProps extends IGlobalServiceProps {
	id?: string;
	label: string;
	labelToolTip?: string;
	valueToolTip: string;
	labelRight?: JSX.Element; // header at the beginning of row
	highlight?: boolean;
	onMouseEnter?: () => void;
	onMouseLeave?: () => void;
	formatter: IFormatter;
	actions: ILinkActions;
	onClick?: () => void;
	labelLeft?: JSX.Element;
	columns?: number;
	borderSides?: boolean;
	borderBottom?: boolean;
	style?: React.CSSProperties;
}

interface IConfigTableRowState {
	tooltipDisabled?: boolean;
}

class StyledConfigTableRow extends React.Component<IConfigTableRowProps & CommonClasses, IConfigTableRowState> {

	private rowRef: HTMLElement;

	constructor(props: IConfigTableRowProps & CommonClasses) {
		super(props);
		this.state = { tooltipDisabled: false };
	}

	public override componentDidMount() {
		mayBeScrollIntoView(this.props.highlight, this.rowRef);
	}

	public override render() {
		const numChildren = React.Children.count(this.props.children);
		const firstColumn = (this.props.columns || 2) - numChildren;
		return (
			<TableRow
				id={this.props.id}
				style={{ ...this.getRowStyle(), ...this.props.style }}
				hover
				onMouseEnter={this.props.onMouseEnter}
				onMouseLeave={this.props.onMouseLeave}
				onClick={this.props.onClick}
				className={this.props.highlight ? this.props.classes.selectedTableRowStyle : this.props.classes.unselectedTableRowStyle}
			>
				<TableCell style={this.getFirstCellStyle()} >
					{this.props.labelLeft}
					<Tooltip title={this.props.labelToolTip} placement={"top"}>
						<span className="cfgName"
							style={{ verticalAlign: "middle" }}
							ref={(el) => this.rowRef = el}
						>{this.props.label}</span>
					</Tooltip>
					{this.props.labelRight}
				</TableCell>
				{
					// Wrap each child in it's own TableCell
					// If the number of children doesn't span every column,
					// this increase the size fo the first (main) child

					React.Children.map(this.props.children, (child, index) => {
						const colSpan = index === 0 ? firstColumn : 1;
						return (
							<TableCell
								style={commonStyles.tableCellStyle}
								colSpan={colSpan}

								// If the underlying control is clicked, we want the tooltip to go away.  We can do this by 
								// handling onClick to disable the tooltip. However, we have to re-enable the tooltip
								// should the mouse leave and come back again (so it's not always disabled).
								// Note: This doesn't control the tooltip opening, just when it shouldn't open

								onClick={() => this.setState({ tooltipDisabled: true })}
								onMouseEnter={() => this.setState({ tooltipDisabled: false })}
							>
								<Tooltip
									title={this.props.valueToolTip ?
										<FormattedMsg
											message={this.props.formatter(this.props.valueToolTip)}
											actions={this.props.actions}
										/> : ""
									}
									placement={"right"} // it's interactive, and we don't want it to block configurables above/below
									disabled={this.state.tooltipDisabled}>
									<span> {/*To fix: for some directly wrapping children in tool tip does not work.*/}
										{child}
									</span>
								</Tooltip>
							</TableCell>
						);
					})
				}

			</TableRow >
		);
	}

	private getRowStyle() {

		const style: React.CSSProperties = {};

		if (this.props.borderBottom) {
			style.borderBottom = this.props.theme.border;
		}

		if (this.props.borderSides) {
			style.borderRight = this.props.theme.border;

			if (!this.props.highlight) {

				// For the left border, we need to override borderLeftColor/Width due to how
				// <TableRow> caches and re-applies these properties, and only if not selected

				style.borderLeftColor = this.props.theme.borderColor;
				style.borderLeftWidth = this.props.theme.borderWidth;
			}
		}
		return style;
	}

	private getFirstCellStyle() {
		// Standard cell left-padding is 6, but with a containing row left border of 4 (that is 
		// either transparent or solid depending on if it's selected).  However, if we are drawing 
		// a side border, the row boarder is 1 when unselected (as we want a thin containing wall), 
		// so we need less padding than the default to make everything line up.

		// You'd think that padding would be 3 (default = 6 left + 1 border should equal a selected
		// of x left + 4 border), but it's not.  The border doesn't draws pixels on one side, it 
		// grows both into the cell, and into the containing object.  So the actual padding that 
		// works is 4.5.  I don't know how to calculate that from the 6, 4 and 1 values coming out
		// of themes.ts/common.ts, so I'm just hard-coding it

		const specialPadding = (this.props.borderSides && this.props.highlight) ? { paddingLeft: 4.5 } : {};
		return {
			...commonStyles.tableCellStyle,
			...commonStyles.noWrap,
			...specialPadding,
		};
	}
}

export const ConfigTableRow = withCommonStyles(StyledConfigTableRow);

