import React = require("react");
import { IBasicInputProps } from "../InputBox";

interface IPreprocessInputProps {
	preprocess: (value: string) => string;
}

export function preprocessInput<T extends IBasicInputProps>(BaseInput: React.ComponentClass<T>) {
	class PreprocessedInput extends React.Component<T & IPreprocessInputProps, { value: string }> {
		public override render() {
			return (
				<BaseInput
					{...this.props}
					onChange={
						(value: string) => { this.props.onChange(this.props.preprocess(value)); }
					}
				/>
			);
		}
	}
	return PreprocessedInput;
}
