import * as _ from "lodash";
import { Requirements } from "./requirements";
import { SharedModuleInstanceRequirement, InstanceArgs } from "public/defs";
import { isCompatibleWithReq, ModuleInstanceMgrFactory } from "../moduleInstance";
import { Runtime } from "../../resources/runtime";
import { SharedInstanceMemberMgr } from "../moduleMemberMgrs/sharedInstanceMgr";
import { adaptNonStaticModuleReqs, compareInstanceReqs } from "../moduleArgs";

export class SharedModuleInstanceRequirements extends Requirements<"sharedModuleInstances"> {

	protected adaptReqs(reqs: SharedModuleInstanceRequirement[]) {
		return adaptNonStaticModuleReqs(reqs);
	}

	protected categorizeReqs(reqs: SharedModuleInstanceRequirement[]) {
		return compareInstanceReqs(
			this.currentRequirements,
			reqs,
			this.instanceMgr.getModuleMgr().module.recreateOnArgsChange,
		);
	}

	protected getFunctionName(): "sharedModuleInstances" {
		return "sharedModuleInstances";
	}

	protected resolve(newReqs: SharedModuleInstanceRequirement[], updatedReqs: SharedModuleInstanceRequirement[]) {
		_.each(newReqs, (req) => this.resolveRecreateReq(req));
		this.resolveUpdates(updatedReqs);
	}

	private resolveUpdates(reqs: SharedModuleInstanceRequirement[]) {
		_.each(
			reqs,
			(req) => {
				const memberMgr = this.instanceMgr.memberMgrs[req.name] as SharedInstanceMemberMgr;
				if (_.size(memberMgr.valueObjectMgr.getSharedBy()) > 1 || !memberMgr.valueObjectMgr.isUserModified()) {
					// 	- The existing child must not have more than 1 parent. 
					// 	Although it is possible to detect precisely whether updating a required arg 
					//  would create conflict with all existing parents, it introduces more behaviour variations
					//  so it was decided that updating the required args when the child is shared by other parents would cause
					//  the parent to go look for a new child.
					// 	- The child must have been user-modified/touched. 
					//  We don't want to preserve an auto created shared child, because there is no user change to preserve at all
					//  and we want the parent to throw away the auto child 
					//  and pick another existing compatible child whenever possible.
					//  - any updated-preserve reqs that do not satisfy these two conditions go back to becoming updated-recreate	
					this.instanceMgr.removeMember(memberMgr);
					return this.resolveRecreateReq(req);
				} else {
					return this.resolveUpdateReq(req);
				}
			});
	}

	private resolveRecreateReq(req: SharedModuleInstanceRequirement) {
		const runtime = this.runtime;

		let resolvedInstMgr = findCompatibleModuleToShare(
			runtime, req.moduleName, req.requiredArgs, req.shareWithByDefault);

		// can't resolve create new
		if (!resolvedInstMgr) {

			const mod = runtime.getModuleMgr(req.moduleName).module;

			resolvedInstMgr = ModuleInstanceMgrFactory.createInstance(
				runtime,
				mod,
				false,
				{});
		}
		const collapsed = !!req.hidden || (_.isUndefined(req.collapsed) ? resolvedInstMgr.isTopModule() : req.collapsed);
		return new SharedInstanceMemberMgr(this.runtime, resolvedInstMgr, req, this.instanceMgr, collapsed);
	}

	private resolveUpdateReq(req: SharedModuleInstanceRequirement) {
		const memberMgr = this.instanceMgr.memberMgrs[req.name] as SharedInstanceMemberMgr;
		memberMgr.updateArgs(req);
		return memberMgr;
	}

}

// Look for an existing module instance that isn't exclusively owned 
// And with members that are compatible with the args
function findCompatibleModuleToShare(
	runtime: Runtime,
	moduleName: string,
	requiredArgs: InstanceArgs,
	shareWithByDefault: string,
) {
	const moduleMgr = runtime.getModuleMgr(moduleName);
	return _.find(moduleMgr.instances, (instance) =>
		instance.canBeShared() &&
		isCompatibleWithReq(instance, requiredArgs) &&
		instance.getShareWithByDefault() === shareWithByDefault);
}
