import React = require("react");
import * as _ from "lodash";
import { isCompatibleWithReq } from "../moduleInstance";
import { ConfigStoreActions } from "../../configStore";
import { DropDown } from "../../../components/DropDown";
import { IGlobalServiceProps } from "../../../components/IGlobalServicesProps";
import { PlusCircleOutline } from "../../../imports/mdi-material-ui-imports";
import { commonStyles } from "../../../components/styles/common";
import { SharedInstanceMemberMgr } from "../moduleMemberMgrs/sharedInstanceMgr";

interface IProps {
	memberMgr: SharedInstanceMemberMgr;
	actions: ConfigStoreActions;
	displayScriptName: boolean;
}

const assignOptionName = "Create New";
export function SharedInstanceDropDown(props: IProps & IGlobalServiceProps) {
	const { memberMgr, actions, modalService, displayScriptName } = props;
	const options = memberMgr.getUIOptions();
	const assignOption = [{
		name: assignOptionName,
		displayName: assignOptionName,
		description: "Create and choose a new instance",
		compatible: "",
		isAction: true,
		icon: <PlusCircleOutline color="primary"
			style={{ ...commonStyles.smallIcon, color: "#118899", verticalAlign: "bottom", paddingLeft: "4px" }} />,
	}];

	return (
		<div>
			<span style={{ margin: "0px 5px 0px 5px" }}>
				<DropDown
					id={`${memberMgr.def.name}Assign`}
					enabledOptions={options.enabled}
					actionOptions={assignOption}
					disabledOptions={options.disabled}
					onChange={(val: string) => {
						const target = _.find(memberMgr.getInstancesOfValidType(), (inst) => inst.getName() === val);
						if (assignOptionName === val) {
							actions.addSharedInstance(memberMgr);
							// When picking an instance that can potentially become compatible(members required by parent is unlocked).
							// Warn the user that some settings will be change to conform to the parent's requirements.
							// Allow the user to "cancel" into a NOP
						} else if (!isCompatibleWithReq(target, memberMgr.def.requiredArgs)) {
							modalService.showConfirmModal(
								"Assigning a shared child instance",
								`This action will cause some settings on ${target.getName()} to be modified.`,
								() => actions.setConfigurableValue(memberMgr, target.managedObject),
								() => { },
							);
						} else {
							actions.setConfigurableValue(memberMgr, target.managedObject);
						}
					}}
					selectedOptionName={memberMgr.valueObjectMgr.getName()}
					disabled={false}
					displayScriptName={displayScriptName}
				/>
			</span>
		</div>
	);
}
