import * as _ from "lodash";
import React = require("react");
import { RequirementsList } from "../../../components/RequirementsList";
import { ConfigStoreActions } from "../../configStore";
import { ModuleInstanceAdderMgr } from "../moduleInstanceAdderMgr";
import { IFormatter } from "../../formatting/formattingTypes";
import { List, Divider } from "../../../imports/material-ui-imports";
import { layoutListStyle, LayoutListItem, InstanceContainer } from "../../../components/Requirements";
import { CModuleInstance } from "./moduleInstance";
import { ResourceLoader, ResourceType } from "../../resources/metaContentLoaders/resourceLoader";
import { ILinkActions } from "../../../components/actions/ILinkActions";
import { IGlobalServiceProps } from "../../../components/IGlobalServicesProps";
import { ModuleInstanceAdderHeader } from "../../../components/RequirementsHeader";
import { LongDescription } from "../../../components/LongDescription";
import { Validations } from "../validations";
import { PinDisplayType } from "../../userPreferences";

interface IProps {
	actions: ConfigStoreActions & ILinkActions;
	adderMgr: ModuleInstanceAdderMgr;
	formatter: IFormatter;
	validations: Validations;
	displayScriptName: boolean;
	devicePinDisplayType: PinDisplayType[];
	headerPinDisplayType: PinDisplayType[];
	resourceLoader: ResourceLoader;
	productLookupName: string;
	showUsed: boolean;
	showPinTable: boolean;
	arePowerDomainSettingsEnabled: boolean;
	focusedSubItemPath: string[];
}

export function CModuleInstanceAdder(props: IProps & IGlobalServiceProps) {
	const arrayMgr = props.adderMgr;

	const childFocusedSubItemPath =
		(arrayMgr.getNumberOfUsed() > 0 && arrayMgr.getSelectedMyListItem().getName() === _.head(props.focusedSubItemPath)) ?
			_.tail(props.focusedSubItemPath) :
			[];

	const shouldShowLongDescription = arrayMgr.getModuleMgr().getShowUserLongDescPref();

	const cannotRemoveReason =
		`Must have at least ${arrayMgr.getMinInstanceCount()} instance${arrayMgr.getMinInstanceCount() === 1 ? "" : "s"}.`;

	const addedText = _.isFinite(arrayMgr.getMaxAllowed()) ?
		`${arrayMgr.getNumberOfUsed()}/${arrayMgr.getMaxAllowed()} added` :
		`${arrayMgr.getNumberOfUsed()} added`;

	return (
		<List style={layoutListStyle}>
			<LayoutListItem key="instanceHeader">
				<ModuleInstanceAdderHeader
					{...props}
					selectedTreeNode={arrayMgr.getModuleMgr()}
					title={addedText}
					showLongDescription={shouldShowLongDescription}
					hideLongDescriptionButton={false}
					cannotRemoveReason={cannotRemoveReason}
				/>
			</LayoutListItem>
			{shouldShowLongDescription &&
				<LongDescription
					key="reqsDescription"
					id="module_documentation"
					closeDescription={() => props.actions.setShowUserLongDescPref(arrayMgr.getModuleMgr(), false)}
					longDescription={arrayMgr.getModuleMgr().getLongDescription()}
					canonicalName={arrayMgr.getModuleMgr().getName()}
					resourceType={ResourceType.CODE}
					disableClose={false}
					resourceLoader={props.resourceLoader}
					actions={props.actions}
					formatter={props.formatter}
				/>
			}
			<RequirementsList
				actions={props.actions}
				selectedTreeNode={arrayMgr}
				formatter={props.formatter}
				validations={props.validations}
				isRemovable={(item) => arrayMgr.canRemove(item)}
				getCannotRemoveReason={(item) => arrayMgr.getCannotRemoveReason(item)}
				getItemName={(item) => {
					if (item.getNameMgr().uiState.hidden) {
						return props.displayScriptName ?
							arrayMgr.getInstanceScriptIdentifier(item) :
							arrayMgr.getInstanceDisplayIdentifier(item);
					} else {
						return props.displayScriptName ?
							arrayMgr.getInstanceScriptIdentifier(item) :
							item.getName();
					}
				}}
				onSelect={(item) => props.actions.navigateToArrayMember(item)}
				onRemove={(item) => props.actions.adderRemoveInstance(arrayMgr, item)}
				instruction={
					<React.Fragment>Click the <b>Add</b> button to add a new element to {arrayMgr.getDisplayName(false)}</React.Fragment>
				}
			/>
			{arrayMgr.getNumberOfUsed() > 0 &&
				<React.Fragment>
					<Divider key="listOrInstDiv" />
					< LayoutListItem key="instance">
						<InstanceContainer isPreview={false} id="moduleInstanceContainer">
							<CModuleInstance
								{...props}
								instMgr={arrayMgr.getSelectedMyListItem()}
								productLookupName={arrayMgr.getModuleMgr().getName()}
								formatter={props.formatter}
								focusedSubItemPath={childFocusedSubItemPath}
							/>
						</InstanceContainer>
					</LayoutListItem>
				</React.Fragment>
			}
		</List>
	);
}
