import * as _ from "lodash";
import { BoardParser } from "../boardSupport/boardParser";
import { Runtime } from "../resources/runtime";

export class HardwareImpl {

	constructor(private readonly runtime: Runtime) { }

	public readonly add = (component: string, headerName?: string) => {

		// We can only do this if no other requirements have been added yet

		const modules = this.runtime.getModuleMgrs();
		const interfaces = this.runtime.getInterfaceMgrs();
		if (_.some(modules, (c) => !_.isEmpty(c.instances)) ||
			_.some(interfaces, (c) => !_.isEmpty(c.instances))) {
			throw new Error("addHardware cannot be called after adding instances");
		}

		// Parse boosterpack

		const deviceData = this.runtime.getDeviceData();
		const parser = new BoardParser(this.runtime.getResourceLoader(), deviceData);
		const boosterPackComponents = parser.loadBoosterPack(component, headerName);

		// Notify the solver

		this.runtime.boardDataChanged();

		// Return just the components that were added

		return { components: boosterPackComponents };
	}
}
