import * as React from "react";
import { ModalButton } from "../buttons/ModalButton";
import { BasicModal, IBasicModalProps } from "./BasicModal";
import { Alert, AlertCircle } from "../../imports/mdi-material-ui-imports";
import { tiStatusColor } from "../styles/colors";
import { commonStyles } from "../styles/common";

interface IConfirmModalProps extends Omit<IBasicModalProps, "onClose"> {
	confirmAction?: () => void;
	cancelAction?: () => void;
	confirmText?: string;
	cancelText?: string;
	isErrorModal?: boolean;
	hideConfirmButton?: boolean;
	disableConfirmButton?: boolean;
}

// Add confirm/cancel buttons to modal
export class ConfirmModal extends React.Component<IConfirmModalProps> {
	public override render() {
		const {
			confirmAction,
			cancelAction,
			confirmText,
			cancelText,
			isErrorModal,
			hideConfirmButton,
			disableConfirmButton,
			...rest } = this.props;
		const titleIcon = isErrorModal ? <AlertCircle
			style={{ ...commonStyles.smallIcon, color: tiStatusColor.error, verticalAlign: "text-bottom" }} />
			: <Alert
				style={{ ...commonStyles.smallIcon, color: tiStatusColor.warning, verticalAlign: "text-bottom" }} />;
		return (
			<BasicModal {...rest}
				titleIcon={titleIcon}
				onClose={cancelAction}
				actions={
					<span>
						{confirmAction && !hideConfirmButton &&
							<ModalButton id="confirmYesBtn" onClick={confirmAction} disabled={disableConfirmButton}>
								{confirmText ? confirmText : "Confirm"}
							</ModalButton>}
						{cancelAction &&
							<ModalButton id="confirmNoBtn" onClick={cancelAction}>
								{cancelText ? cancelText : "Cancel"}
							</ModalButton>}
					</span>
				}
			/>
		);
	}
}
