import * as React from "react";
import * as _ from "lodash";
import { ElkPoint } from "elkjs";
import { JointComponent } from "../edges/JointComponent";

// Renders a collection of joints

export const Joints = React.memo(({ joints, className }: { joints: ElkPoint[], className: string }) => {
	return <>
		{_.map(joints, (joint) => {
			return <JointComponent
				key={joint.x + " " + joint.y + " joint"}
				joint={joint}
				className={className}
			/>;
		})}
	</>;
});
