import React = require("react");
import * as _ from "lodash";

import { PinRequirements } from "./pins";
import { Table, TableBody } from "../../../imports/material-ui-imports";
import { MemberRow } from "./memberRows";
import { GPIOInterfaceInstanceMgr } from "../gpioInterfaceInstance";
import { IFormatter } from "../../formatting/formattingTypes";
import { DropDown } from "../../../components/DropDown";
import { ConfigStoreActions } from "../../configStore";
import { IGlobalServiceProps } from "../../../components/IGlobalServicesProps";
import { ResourceLoader } from "../../resources/metaContentLoaders/resourceLoader";
import { CTextConfigurable } from "./configurables/textConfigurable";
import { CValidation } from "./validation";
import { Validations } from "../validations";
import { PinDisplayType } from "../../userPreferences";

// React shared props
interface IConfigProps extends IGlobalServiceProps {
	req: GPIOInterfaceInstanceMgr;
	actions: ConfigStoreActions;
	maxAllowed?: number;
	formatter: IFormatter;
	validations: Validations;
	displayScriptName: boolean;
	devicePinDisplayType: PinDisplayType[];
	headerPinDisplayType: PinDisplayType[];
	resourceLoader: ResourceLoader;
	productLookupName: string;
	focusedSubItemPath: string[];
}

export class Config
	extends React.Component<IConfigProps & IGlobalServiceProps, {}> {
	public override render() {
		const req = this.props.req;
		const formatter = this.props.formatter;
		const { enabledOptions, disabledOptions } = req.getNumPinsMgr().getUIOptions();
		const highlightedMember = _.size(this.props.focusedSubItemPath) === 1 ? _.first(this.props.focusedSubItemPath) : "";

		return (
			<span>
				<span>
					<div>
						<CValidation
							validations={this.props.validations}
							validatableObj={req}
							formatter={formatter}
							actions={this.props.actions}
						/>
						<Table>
							<TableBody>
								<MemberRow key="name"
									{...this.props}
									memberMgr={req.getNameMgr()}
									highlight={highlightedMember === req.getNameMgr().def.name}
								>
									<CTextConfigurable mgr={req.getNameMgr()} actions={this.props.actions} />
								</MemberRow>
								<MemberRow key="numGpio"
									{...this.props}
									memberMgr={req.getNumPinsMgr()}
									highlight={highlightedMember === req.getNumPinsMgr().def.name}
								>
									<DropDown
										id="numberOfGPIOPins"
										disabled={false}
										enabledOptions={enabledOptions}
										disabledOptions={disabledOptions}
										selectedOptionName={req.getNumPinsMgr().getSelectedOption().name.toString()}
										onChange={(val: string) => this.props.actions.setNumOfGPIOPins(req, Number(val))}
										displayScriptName={this.props.displayScriptName}
									/>
								</MemberRow>
							</TableBody>
						</Table>
					</div>
					<div className="dividerDiv"></div>
				</span>
				<div>
					<Table id="requirementsTable">
						<TableBody>
							<PinRequirements
								{...this.props}
								pinsProvider={req}
								showUsed={true}
								keyPrefix="GPIO"
								highlightedMember={highlightedMember}
								showPinTable={true}
							/>
						</TableBody>
					</Table>
				</div>
			</span>
		);
	}
}
