import * as _ from "lodash";
import { InterfacePin, AdaptedDeviceInfo } from "dataInterfaces";
import { PinMap } from "../pinMap";

export class Solution {

	public assignedToName = "";
	public ioSet?: string;
	public errorText = "";
	public warningText = "";
	public errorDetailsText: string[] = [];
	public warningDetailsText: string[] = [];
}

export class PinSolution extends Solution {
	public assignedPeripheralPin = "";
	public assignedInterfacePin = "";
}

export class Resource {
	public userOverride?: string;
	public userAllowedConflicts = false;

	public readonly solution: Solution;

	// It's ok for this resource to have a conflict with another
	// resource also marked as allowed
	// Also overrides the resource, which must remain overridden for this
	// to continue being allowed

	public allowConflicts(userOverride: string) {
		this.userAllowedConflicts = true;
		this.userOverride = userOverride;
	}

	// It's not ok for this resource to have a conflict (the default)

	public disallowConflicts() {
		this.userAllowedConflicts = false;
	}

	// True if it's ok for this resource to have a conflict

	public areConflictsAllowed() {
		return this.userOverride && this.userAllowedConflicts;
	}
}

export class Pin extends Resource {

	// Is the pin requirement being used in the solution.  If the user disables the pin, this is
	// set to false, and the solver can ignore it

	public used = true;

	// The final solution the solver comes up with

	public override readonly solution = new PinSolution();

	// The map of peripheral pin names to device names that this pin requirement is restricted to 
	// using.  This is set either because the module set it (certain configurables may mean that
	// only some pins can be used), or because the requirement is connected to hardware that's 
	// wired down to the board in a set way.

	public restrictTo?: { [signal: string]: string[] };

	// True if the requirement is connected to hardware.  If set to true, then restrictTo must be
	// set.  The reason we need a separate member than just testing restrictTo is that restrictTo 
	// may be set based on module preferences based on all free pins, but the solver may want to 
	// still limit the solution to just the free pins on the default header if it can.  However, 
	// when connected to hardware, then any of those hardware pins can be considered.

	public connectedToHardware = false;

	// The list of pins that the solver should "prefer" over other pins.  The solver will make a 
	// best effort to find a solution with only these pins, but will not limit solutions to just
	// these pins

	public preferredPins?: string[];

	constructor(

		// Name of this specific pin requirement.  It's unique per peripheral requirement, but not
		// across peripheral requirements

		private readonly name: string,

		// The interface pins that can be used to satisfy this requirement

		public interfacePins: InterfacePin[],

		// If set, any pin requirements with the same value are "ok" with
		// being resolved to the same interface pin.  Obviously, this only
		// matters if the parent peripheral requirement is shared, and the
		// solver resolves the parent peripheral reqs to the same peripheral
		// (if the parent peripheral reqs aren't the same in the first place)

		public readonly canShareWith?: string,
		public readonly reserved: boolean = false) {
		super();
	}

	// Name for just this pin alone

	public getUnqualifiedName() {
		return this.name;
	}

	public restrictsGPIO(pinMap: PinMap) {
		if (this.connectedToHardware || _.isEmpty(this.interfacePins) ||
			(this.userOverride && !_.includes(pinMap.getFreePins(), this.userOverride))) {
			return "never";
		}

		if (_.every(this.interfacePins, (pin) => pin.restrictsGPIO === "always")) {
			return "always";
		} else if (_.every(this.interfacePins, (pin) => pin.restrictsGPIO === "never")) {
			return "never";
		}
		return "sometimes";
	}
}

export class Peripheral extends Resource {
	public userVoltageOverride?: string;
	public restrictTo?: string[];
	public pinRequirements: Pin[] = [];
	public override readonly solution = new Solution();
	public readonly voltageSolution = new Solution();

	// The "name" could actually be changed at any time by the user. 
	// Thus, we need to keep an id for tracking that is constant.

	constructor(
		public readonly id: string,
		public readonly interfaceName: string,

		// If set, all peripheral requirements with the same value are "ok" with
		// being resolved to the same peripheral.  Obviously, pin requirements 
		// aren't necessarily shareable, and the peripherals must be of the same
		// interface

		public readonly canShareWith?: string,

		// If set, and canShareWith is also set, this is the maximum number of 
		// times that the peripheral can be shared

		public readonly maxShareCount?: number) {
		super();
	}
}

export class GPIO {

	public pinRequirements: Pin[] = [];

	// The "name" could actually be changed at any time by the user. 
	// Thus, we need to keep an id for tracking that is constant.

	constructor(
		public readonly id: string,
		public readonly interfaceName: string) {
	}
}

export interface InterfaceGroupMap {
	[s: string]: InterfaceGroup;
}

export interface PowerDomainSettings {
	[key: string]: string;
}

export interface DevicePinSolutionMap {
	[ballName: string]: Pin[];
}

export class Device {
	public devicePinMap: DevicePinSolutionMap = {};
	public powerDomainSettings: PowerDomainSettings = {};
	public interfaceRequirementsMap: InterfaceGroupMap = {};
	public gpioPinsUsed = 0;	// solver will set the value after each solve
	public gpioPinsTotal = 0;	// solver will calculate the right value at startup
	constructor(deviceData: AdaptedDeviceInfo) {
		this.powerDomainSettings = _.chain(deviceData.powerDomains)
			.pickBy((powerDomain) => !_.isEmpty(powerDomain.powerValue))
			.mapValues((powerDomain) => _.first(powerDomain.powerValue))
			.value();
	}
}

/**
 * Group of requirements.
 * @param name
 * @returns
 */
class GBaseGroup<T> {

	public name: string;
	public id: string;
	public requirements: T[] = [];

	constructor(pname: string) {
		this.name = pname;
		this.id = pname;
	}
}

export class InterfaceGroup extends GBaseGroup<Peripheral | GPIO> {
}
