import React = require("react");
import { Typography, withStyles } from "../imports/material-ui-imports";
import { MarkdownRenderProps, markdownToHtml } from "../services/MarkdownConverter";
import { defaultFontSize } from "./styles/themes";
import { IFormatter } from "../services/formatting/formattingTypes";
import { ILinkActions } from "./actions/ILinkActions";

interface IProps extends MarkdownRenderProps {
	markdownSrc: string;
	style?: React.CSSProperties;
	formatter: IFormatter;
	actions: ILinkActions;
	classes: { linkClass: string };
}

// Should rendering markdown fail, return the exception.  This allows the exception to appear in the view vs taking 
// down the whole config page.  This can be quite likely if the markdown set being rendered is old and contains 
// navigation links, but such a case should immediately re-render correctly.

function safeMarkdownToHtml(markdownText: string, renderProps: MarkdownRenderProps) {
	try {
		return markdownToHtml(markdownText, renderProps);
	} catch (e) {
		return e.stack;
	}
}

function StyledMarkdownContent(props: IProps) {
	const { markdownSrc, style, ...renderProps } = props;

	return <Typography style={{
		fontSize: defaultFontSize,
		display: "inline-block",
		overflow: "auto",
		...style,
	}} dangerouslySetInnerHTML={{
		__html: safeMarkdownToHtml(markdownSrc, { ...renderProps, linkClass: props.classes.linkClass }),
	}} />;
}

export const MarkdownContent = withStyles((theme) => {
	return {
		linkClass: { color: theme.palette.primary.main },
	};
})(StyledMarkdownContent);
