import * as React from "react";
import * as _ from "lodash";
import { Divider, ListItemSecondaryAction, MenuItem, ListItemText, Typography } from "../../imports/material-ui-imports";
import { DockBottom } from "../../imports/mdi-material-ui-imports";
import { OutputMenuEntry } from "./OutputMenuEntry";
import { OutputViewMgr } from "../../services/ui/outputView";
import { Dock, IOutputActions } from "../actions/IOutputActions";
import { ATheme } from "../styles/themes";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { TripleDotMenu, CheckedMenuItem } from "./TripleDotMenu";
import { ITreeNode } from "../TreeNode";
import { ClockTreeNode } from "../../services/instanceContainers/clockTreeNode";
import { commonStyles } from "../styles/common";

interface IProps {
	selectedTreeNode: ITreeNode;
	actions: IOutputActions;
	viewMgrs: OutputViewMgr[];
	theme: ATheme;
}

export class OutputMenu extends React.Component<IProps & IGlobalServiceProps, {}> {

	public override render() {
		const { viewMgrs } = this.props;
		const topViewsCount = 4;
		const topViews = _.slice(viewMgrs, 0, topViewsCount); // top views are icons controlled
		const extendedViews = _.slice(viewMgrs, topViewsCount); // remaining views are in the extended menu
		const someViewExpanded = _.some(viewMgrs, (v) => v.isExpanded());
		return (
			<ListItemSecondaryAction>
				{
					_.map(topViews, (viewMgr) => {
						return <OutputMenuEntry
							theme={this.props.theme}
							key={viewMgr.id}
							mgr={viewMgr}
							actions={this.props.actions}
							disabled={someViewExpanded}
						/>;
					})
				}
				{
					!_.isEmpty(extendedViews) &&
					<TripleDotMenu
						{...this.props}
						buttonId={"extendedMenuIcon"}
						menuId={"extendedMenu"}
						disabled={someViewExpanded}>
						{_.map(extendedViews, (viewMgr) => {
							return <CheckedMenuItem
								key={viewMgr.id}
								text={viewMgr.displayName}
								id={viewMgr.id}
								onClick={() => this.props.actions.toggleOutputView(viewMgr)}
								checked={viewMgr.isDisplayed()}
							/>;
						})}
						{(this.props.selectedTreeNode instanceof ClockTreeNode) &&
							<>
								<Divider orientation="horizontal" />
								<DockBottomButton actions={this.props.actions} />
							</>
						}
					</TripleDotMenu>
				}
			</ListItemSecondaryAction>
		);
	}
}

class DockBottomButton extends React.Component<{ actions: IOutputActions }> {
	public override render() {
		return < MenuItem
			onClick={this.onClick}
			style={commonStyles.extendOutputMenuStyle}
		>
			<DockBottom style={commonStyles.smallIcon} />
			<ListItemText>
				<Typography>
					Dock Bottom
				</Typography>
			</ListItemText>
		</MenuItem >;
	}

	private onClick = () => this.props.actions.setOutputDocking(Dock.BOTTOM);
}
