import * as _ from "lodash";
import * as JSZip from "jszip";
import { GeneratedCode } from "./codeGeneration/codeGenerator";
import { isCloud } from "./platform";
import { saveAs } from "file-saver";
import { isSafari } from "./utils";
import pathModule = require("path");
import { storage } from "./storage";
import { fs } from "./fileSystem";

async function downloadFilesDesktop(generatedCode: GeneratedCode[], folder: string) {
	await Promise.all(_.map(generatedCode, (nameAndContents) => {
		const savePath = folder + "/" + nameAndContents.fileName;
		fs.mkdir(pathModule.normalize(pathModule.dirname(savePath)), { recursive: true });
		return storage.saveFile(savePath, nameAndContents.contents);
	}));
}

// generates a download link given a name and the content
export function generateDownloadLink(name: string, content: any, myType: string) {
	if (isSafari() && (myType === "application/zip")) {
		const a = document.createElement("a");
		a.setAttribute("href", "data:application/zip;base64," + content);
		a.setAttribute("download", name);
		a.click();
	} else {
		const fileNameToSaveAs = name;
		const textToWrite = content;
		const textFileAsBlob = new Blob([textToWrite], {
			type: myType,
		});

		saveAs(textFileAsBlob, fileNameToSaveAs);
	}
}

// given the fileList and selectedCategory, generate the single file or zip for download
async function downloadFilesCloud(
	generatedCode: GeneratedCode[],
	fileOrZipName: string,
) {

	if (1 === generatedCode.length) {
		// If there's only one file, then offload to the single file function
		downloadFile(generatedCode[0], fileOrZipName);
	} else {

		// Generate each output file from the template, and add it to the zip

		const zip = new JSZip();

		_.each(generatedCode, (nameAndContents) => {
			zip.file(nameAndContents.fileName, nameAndContents.contents);
		});

		const content = await zip.generateAsync({ type: isSafari() ? "base64" : "blob" });
		generateDownloadLink(fileOrZipName, content, "application/zip");
	}
}

// download the file associated with the given fileEntry
function downloadFile(
	generatedCode: GeneratedCode,
	fileName: string) {

	generateDownloadLink(fileName, generatedCode.contents, "text/plain");
}

export async function downloadFiles(
	generatedCode: GeneratedCode[], folderOrZipName: string) {
	if (isCloud()) {
		await downloadFilesCloud(generatedCode, folderOrZipName);
	} else {
		await downloadFilesDesktop(generatedCode, folderOrZipName);
	}
}
