import * as _ from "lodash";
import React = require("react");
import { ErrorBadge, InfoBadge, WarningBadge } from "../../../components/Badges";
import { IFormatter } from "../../formatting/formattingTypes";
import { FormattedMsg } from "../../../components/FormattedMsg";
import { ILinkActions } from "../../../components/actions/ILinkActions";
import { Tooltip } from "../../../components/Tooltip";
import { List, ListItem, ListItemText } from "../../../imports/material-ui-imports";
import { getShortValidationString, getValidationKey } from "../../utils";
import { DetailedText, Validations, IValidatable, Validation } from "../validations";
import { StatusType } from "../../../components/Decorators";

interface IProps {
	validations: Validations;
	validatableObj: IValidatable;
	formatter: IFormatter;
	memberName?: string;
	actions: ILinkActions;
	conflictControl?: JSX.Element;
	withoutIcon?: boolean;

	// These members should be used when we want to display a single detail message
	statusType?: StatusType,
	singleMsg?: string
}
export class CValidation
	extends React.PureComponent<IProps> {

	public override render() {

		const validation = this.props.validations.getValidation(this.props.validatableObj);
		const displaySingle = this.props.statusType && this.props.singleMsg;
		return (
			<React.Fragment>
				{!displaySingle && this.renderMultiDetails(validation)}
				{displaySingle && this.renderDetail(this.props.statusType, [this.props.singleMsg])}
				{this.props.conflictControl}
			</React.Fragment>
		);
	}

	private renderMultiDetails(validation: Validation) {
		return (
			<div>
				{validation && validation.errors.length > 0 &&
					this.renderDetail(StatusType.Error, validation.errors)
				}
				{validation && validation.warnings.length > 0 &&
					this.renderDetail(StatusType.Warning, validation.warnings)
				}
				{validation && validation.suppressedWarnings.length > 0 &&
					this.renderDetail(StatusType.SuppressedWarning, validation.suppressedWarnings)
				}
				{validation && validation.infos.length > 0 &&
					this.renderDetail(StatusType.Info, validation.infos)
				}
			</div>
		);
	}

	private renderDetail(statusType: StatusType, detailText: (string | DetailedText)[]) {
		const memberName = this.props.memberName || "$instance";
		return (
			<div>
				{statusType === StatusType.Error &&
					<span key={memberName + "Error"} id={memberName + "ValidationError"}>
						{this.renderValidation(ErrorBadge, memberName + "Error", detailText)}
					</span>
				}
				{statusType === StatusType.Warning &&
					<span key={memberName + "Warning"} id={memberName + "ValidationWarning"}>
						{this.renderWarningValidation(memberName + "Warning", detailText, false)}
					</span>
				}
				{statusType === StatusType.SuppressedWarning &&
					<span key={memberName + "Warning"} id={memberName + "ValidationWarning"}>
						{this.renderWarningValidation(memberName + "Warning", detailText, true)}
					</span>
				}
				{statusType === StatusType.Info &&
					<span key={memberName + "Info"} id={memberName + "ValidationInfo"}>
						{this.renderValidation(InfoBadge, memberName + "Info", detailText)}
					</span>
				}
			</div>
		);
	}

	private renderWarningValidation(id: string, msgs: (string | DetailedText)[], suppressed: boolean) {
		return (
			<div>
				{
					_.map(msgs, (msg, index) => {
						const tooltip = suppressed ? "un-suppress" : "suppress";
						const onClick = () => this.props.actions.suppress(
							this.props.validatableObj,
							getValidationKey(msg).matcher,
							!suppressed,
						);
						return (
							<WarningBadge
								id={id}
								key={index}
								message={this.renderDetailsItem(msg)}
								onClick={onClick}
								tooltip={tooltip}
								suppressed={suppressed}
								withoutIcon={this.props.withoutIcon} />
						);
					})
				}
			</div>
		);
	}

	private renderValidation(
		// in conflict with react rule which expects Component names to begin with capital
		Badge: (typeof ErrorBadge | typeof InfoBadge),
		id: string,
		msgs: (string | DetailedText)[]) {
		return (
			<div>
				{
					_.map(msgs, (msg, index) => {
						return (
							<Badge
								id={id}
								key={index}
								message={this.renderDetailsItem(msg)}
								withoutIcon={this.props.withoutIcon} />
						);
					})
				}
			</div>
		);
	}

	private renderDetailsItem(detailText: string | DetailedText) {
		let toolTip = null;
		if (!_.isString(detailText) && !_.isEmpty(detailText.longTexts)) {
			toolTip = <List disablePadding style={{ overflow: "auto" }}>
				{
					_.map(detailText.longTexts, (detail, index) => {
						return this.renderDetailsTooltip(detail, index);
					})
				}</List>;
		}
		return (
			<Tooltip
				disabled={!toolTip}
				title={toolTip}
				placement="top"
				noWrap={true}
			>
				<FormattedMsg
					message={this.props.formatter(getShortValidationString(detailText))}
					actions={this.props.actions}
				/>
			</Tooltip>
		);
	}

	private renderDetailsTooltip(longText: string, index: number) {
		return (
			<ListItem key={index} >
				<ListItemText
					primaryTypographyProps={{
						variant: "caption",
						color: "inherit",
					}}
				>
					<FormattedMsg
						message={this.props.formatter(longText)}
						actions={this.props.actions}
					/>
				</ListItemText>
			</ListItem>
		);
	}
}
