import * as _ from "lodash";
import React = require("react");
import util = require("../../utils");
import { DropDown } from "../../../components/DropDown";

import { InterfaceInstanceMgr } from "../interfaceInstance";
import { SelectionSupplementary } from "../../../components/SelectionSupplementary";
import { IFormatter } from "../../formatting/formattingTypes";
import { ILinkActions } from "../../../components/actions/ILinkActions";

interface IVoltageSelectionProps {
	instMgr: InterfaceInstanceMgr;
	arePowerDomainSettingsEnabled: boolean;
	onChange: (useCaseName: string) => void;
	formatter: IFormatter;
	actions: ILinkActions;
}

export class VoltageSelection extends React.Component<IVoltageSelectionProps, {}> {

	public override state = { isHover: false };

	public override render() {

		const configurable = this.props.instMgr.getVoltageMgr();
		const selected = configurable.getValue();
		const voltages = _.filter(configurable.def.options, (o) => o.name !== util.Const.ANY);
		const solution = this.props.instMgr.getSolverRequirement().voltageSolution;

		const anyOption = {
			name: util.Const.ANY,
			displayName: util.decorateAny(solution.assignedToName),
		};

		return (
			<span
				id={configurable.def.name}
				onMouseEnter={() => { this.setState({ isHover: true }); }}
				onMouseLeave={() => { this.setState({ isHover: false }); }}
			>
				<DropDown
					id="reqVoltage"
					onChange={this.onChange}
					selectedOptionName={selected}
					enabledOptions={[anyOption, ...voltages]}
					disabled={!this.props.arePowerDomainSettingsEnabled}
					withIcon={true}
					displayScriptName={false}
				/>
				<SelectionSupplementary
					solution={solution}
					selectedValue={selected}
					formatter={this.props.formatter}
					onChange={this.props.onChange}
					isHover={this.state.isHover}
					actions={this.props.actions}
					memberName={configurable.def.name}
				/>
			</span>
		);
	}

	private onChange = (value: string) => {
		this.props.onChange(value);
	}

}
