import React = require("react");
import { InterfaceInstanceMgr } from "../interfaceInstance";
import { CAssign } from "./assign";
import { IFormatter } from "../../formatting/formattingTypes";
import { ILinkActions } from "../../../components/actions/ILinkActions";
import { IConflictActions } from "../../../components/actions/IConflictActions";
import { Validations } from "../validations";

interface IPeripheralSelectionProps {
	instMgr: InterfaceInstanceMgr;
	formatter: IFormatter;
	validations: Validations;
	onChange: (selected: string) => void;
	actions: ILinkActions & IConflictActions;
}

export class PeripheralSelection extends React.Component<IPeripheralSelectionProps, {}> {

	public override render() {

		const { instMgr } = this.props;
		const solverReq = instMgr.getSolverRequirement();
		const solution = solverReq.solution;
		const assignMgr = instMgr.getUsePeripheralMemberMgr();
		const conflictMgr = instMgr.getConflictMgr();
		const selected = assignMgr.getSelectedOption().name;

		return (
			<CAssign
				wrapperClass="peripheralSelect"
				wrapperId="usePeripheralRow"
				selectedOptionName={selected}
				onChange={this.props.onChange}
				disabled={false}
				solution={solution}
				formatter={this.props.formatter}
				validations={this.props.validations}
				actions={this.props.actions}
				assignMgr={assignMgr}
				conflictMgr={conflictMgr}
			/>
		);
	}

}
