import * as React from "react";
import { ClassesType } from "../styling/clockTreeStyles";
import { ExtendedElkNode } from "../layout/customTypes";
import { NodeLabels } from "./NodeLabels";
import { PositionedNode } from "./PositionedNode";

// Any node that isn't one of the specific types with custom rendering

export interface IGenericNodeProps {
	node: ExtendedElkNode;
	onSelect: (selection: string) => void;
	displayScriptName: boolean;
}

export const GenericNode = React.memo((
	{ node, onSelect, displayScriptName, classes, children }: React.PropsWithChildren<IGenericNodeProps & ClassesType>) => {
	return (
		<PositionedNode
			node={node}
			onSelect={onSelect}
			className={classes.genericNode}
		>
			<NodeLabels key="labels" node={node} displayScriptName={displayScriptName} classes={classes} />
			{children}
		</PositionedNode>
	);
});
