import * as _ from "lodash";
import { SysConfig } from "../../sysConfig";
import { ContextRuntime } from "public/runtime";

// This is a proxy handler to be used in a proxy for system.contexts

const contextsProxyHandler: ProxyHandler<SysConfig> = {
	get: (target, contextName: string) => {
		const runtime = _.find(target.getRuntimes(), (r) => r.getName() === contextName);
		if (runtime) {
			return {
				scripting: runtime.getScripting(),
				system: runtime.createSystemObj(),
			};
		}
		return undefined;
	},

	set: () => {
		throw new TypeError("read only object");
	},

	ownKeys: (target) => {
		return _.map(target.getRuntimes(), (r) => r.getName());
	},

	has: (target, contextName: string) => {
		return _.some(target.getRuntimes(), (r) => r.getName() === contextName);
	},

	defineProperty: () => {
		return false; // disallow
	},

	deleteProperty: () => {
		return false; // disallow
	},

	getOwnPropertyDescriptor: (target, contextName: string) => {
		if (contextsProxyHandler.has(target, contextName)) {

			// Node won't let us return that it's not configurable, so instead we'll return 
			// getters/setters vs the raw value at least

			return {
				configurable: true,
				enumerable: true,
				get: () => contextsProxyHandler.get(target, contextName, null),
				set: () => {
					throw new TypeError("read only object");
				},
			};
		}
		return undefined;
	},

	setPrototypeOf: () => {
		return false; // disallow
	},
};

export function createContexts(sysConfig: SysConfig) {
	return new Proxy(sysConfig, contextsProxyHandler) as any as Record<string, ContextRuntime>;
}
