// UI Views for meta content defined configurables
import * as React from "react";
import * as _ from "lodash";
import { ATheme } from "../../../../components/styles/themes";
import { ErrorStore } from "../../../errorStore";
import { Tooltip } from "../../../../components/Tooltip";
import { ModalService } from "../../../ui/modals";
import { Validations } from "../../validations";
import { ButtonConfigurableMgr } from "../../configurables/buttonConfigurableMgr";
import { SecondaryButton } from "../../../../components/buttons/SecondaryButton";
import { FileBrowse } from "../../../../components/FileBrowse";
import { blockingProcessAction } from "../../../../components/BlockingProcessAction";
import { ResourceLoader, ResourceType } from "../../../resources/metaContentLoaders/resourceLoader";
import { IConfigurablesActions } from "../configurableActions";

class SyncButtonConfigurable extends React.Component<{
	mgr: ButtonConfigurableMgr<unknown>;
	errorStore: ErrorStore;
	modalService: ModalService;
	theme: ATheme;
	validations: Validations;
	onClick: (filePath?: string) => void;
}> {
	public override render() {
		const mgr = this.props.mgr;
		const isDisabled = mgr.isDisabled(this.props.validations);
		const id = mgr.def.name + "_Button";

		return (
			<Tooltip title={_.isString(isDisabled) ? isDisabled : mgr.def.description}>
				{(mgr.def.fileFilter || mgr.def.pickDirectory) &&
					<FileBrowse
						onChange={this.props.onClick}
						errorStore={this.props.errorStore}
						modalService={this.props.modalService}
						id={id}
						disabled={!!isDisabled}
						folder={mgr.def.pickDirectory}
						accept={mgr.def.fileFilter}
					>
						<SecondaryButton
							theme={this.props.theme}
							disabled={!!isDisabled}
							id={id}
						>
							{mgr.def.buttonText}
						</SecondaryButton>
					</FileBrowse>
				}
				{!(mgr.def.fileFilter || mgr.def.pickDirectory) &&
					<SecondaryButton
						theme={this.props.theme}
						onClick={this.onClickWithoutPath}
						disabled={!!isDisabled}
						id={id}
					>
						{mgr.def.buttonText}
					</SecondaryButton>
				}
			</Tooltip>
		);
	}

	private onClickWithoutPath = () => this.props.onClick();
}

const BlockingButtonConfigurable = blockingProcessAction(SyncButtonConfigurable);

export class CButtonConfigurable<T> extends React.Component<{
	mgr: ButtonConfigurableMgr<T>;
	actions: IConfigurablesActions;
	errorStore: ErrorStore;
	modalService: ModalService;
	resourceLoader: ResourceLoader;
	theme: ATheme;
	validations: Validations;
}> {
	public override render() {
		return <BlockingButtonConfigurable
			{...this.props}
			onClick={this.onClick}
			title={this.props.mgr.getDelayReason()}
			id={this.props.mgr.def.name}
		/>;
	}

	private onClick = async (filePath?: string) => {
		const { mgr, resourceLoader } = this.props;
		const productPath = resourceLoader.getProduct(mgr.parentObjectMgr.getModuleName(), ResourceType.CODE).file.path;
		const result = await mgr.getClickResult(productPath, filePath);
		this.props.actions.buttonClicked(this.props.mgr, result);
	}
}
