import * as _ from "lodash";
import React = require("react");

import { Typography, Link } from "../imports/material-ui-imports";
import { ConfigPage } from "./ConfigPage";
import { RouteComponentProps } from "react-router-dom";
import { runScripts, LegacyBoardFile, ScriptRunError } from "../services/scripting/runScript";
import {
	MissingArgsError,
	ArgsError,
	ResolvedArgs,
	SetupError,
} from "../services/args/argTypes";
import {
	extractArgsFromRoute,
	constructRoute,
	startPage,
	configPage,
	extractStringFromRoute,
	extractModeFromRoute,
	Mode,
} from "../services/routing";
import { AsyncComponent } from "./AsyncComponent";
import { ProgressBar } from "./ProgressBar";
import { ConfigStore } from "../services/configStore";
import { createLoader, ScriptLoadError } from "../services/resources/otherLoaders/scriptAndProductLoader";
import { fs } from "../services/fileSystem";
import { createAvailableProducts } from "../services/product/available";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { ErrorStore } from "../services/errorStore";
import { ErrorBoundary } from "./ErrorBoundary";
import { clearTitle } from "../services/ui/documentTitle";
import { InvalidAssignmentReason, capture } from "../services/objectManagers/invalidAssignment";
import { openExternalLink } from "../services/externalLink";
import { SysConfig } from "../services/sysConfig";
import { InvalidMinToolVersion } from "../services/product/versionCheck";
import { recordLoadConfig } from "../services/analytics";
import { getDeviceDescriptions } from "../services/data";
import { preFetchForResponsiveUI } from "../services/tabs";
import { parseAndResolveArgs } from "../services/args/parseAndResolveArgs";
import { clearSysConfigCache, getSysConfig } from "../services/sysConfigFactory";
import { DiscoveryJSON } from "dataInterfaces";

interface IState {
	configStore: ConfigStore;
}

type IProps = RouteComponentProps<{
}> & IGlobalServiceProps;

export class LoadConfigPage extends AsyncComponent<IProps, IState> {

	private readonly errorStore = new ErrorStore();

	constructor(props: IProps) {
		super(props);
		this.state = {
			configStore: null,
		};
	}

	public override componentDidMount() {
		clearTitle();
		super.componentDidMount();
	}

	public override componentWillUnmount() {
		if (this.state.configStore) {
			this.state.configStore.onAnyChange().removeListener(this.handleConfigStoreUpdate);
		}
		super.componentWillUnmount();
	}

	public override render() {

		if (this.state.configStore) {

			// There is already an ErrorBoundary in Index.tsx, but we don't want to use that one.  
			// If we did, this component would re-render after the dialog is dismissed, which would
			// cause us to re-create the runtime model.  We don't want to do that if we can avoid 
			// it because that would cause us to loose all the user's changes thus far.
			//
			// The solution is to create our own error boundary here, and pass it our own error 
			// store for exceptions.  The same error store is passed to sysconfig/configstore.
			// Now, when an exception occurs, the config page only will be hidden (so we don't get
			// cascading errors), a modal is displayed.  Once "ok" is hit, the config page is re-
			// created with the same configstore (but with the last change undone).  Thus the 
			// user's changes will be preserved

			const propsWithLocalErrorStore = {
				...this.props,
				errorStore: this.errorStore,
			};

			return <ErrorBoundary {...propsWithLocalErrorStore}>
				<ConfigPage
					{...propsWithLocalErrorStore}
					deviceId={this.state.configStore.getDeviceData().deviceId}
					configStore={this.state.configStore}
					showPreferredVoltage={this.state.configStore.getDeviceData().showPreferredVoltage}
					openSessionHandler={this.handleOpen}
					restartSessionHandler={this.handleRefresh}
				/>
			</ErrorBoundary>;
		}

		return <ProgressBar id="configProgress" title="Setting up SysConfig..." />;
	}

	protected propsChanged(nextProps: Readonly<IProps>, nextState: Readonly<IState>) {

		// save-as will update the location to include the new file name.  However, it would be crazy to re-generate 
		// the config store for that change.  As such, save-as also updates config store.  So, when comparing new to
		// old args, we have to look at the config store's saved args.  However, if the configStore has been nulled out
		// in the next state, then ignore those args and look at the location prop instead - we are mid-updating config
		// store already!

		const prevArgs = (this.state.configStore && nextState.configStore) ?
			this.state.configStore.getCurrentArgs() : extractArgsFromRoute(this.props.location);
		const newArgs = extractArgsFromRoute(nextProps.location);
		const argsDiffer = this.argsDiffer(prevArgs, newArgs);

		// True if the args derived from the properties changed
		// or true if we're not mid-loading, and the cached SysConfig is gone (it's cleared when a re-load of the same
		// script is requested in the nav bar's "open")

		return argsDiffer ||
			(!this.isLoading() && null === getSysConfig(this.errorStore))
			|| !_.isEqual(extractModeFromRoute(nextProps.location), extractModeFromRoute(this.props.location));
	}

	protected clearAsyncData() {
		if (this.state.configStore) {
			this.state.configStore.onAnyChange().removeListener(this.handleConfigStoreUpdate);
		}
		this.setState({ configStore: null });
	}

	protected async fetchAsyncData() {
		try {
			// Parse arguments and get the initial config parameters
			const { args, deviceDiscoveryData, resolvedArgs, mode } = await this.getConfigParamters();
			// Create the SysConfig and then the ConfigStore based on it
			return await this.createConfigStore(args, deviceDiscoveryData, resolvedArgs, mode);
		} catch (e) {
			return this.processError(e);
		}
	}

	private processError(e: Error) {
		if (e instanceof InvalidMinToolVersion) {
			this.props.modalService.showUpdateModal(e, this.goBackToStart);
		} else if (e instanceof MissingArgsError || e instanceof ArgsError || e instanceof SetupError) {
			this.props.modalService.showErrorModal(e.message, null, this.goBackToStart);
		} else if (e instanceof ScriptLoadError) {
			this.props.modalService.showErrorModal(`Error loading ${e.script}`, e.originalError, this.goBackToStart);
		} else if (e instanceof LegacyBoardFile) {
			this.props.modalService.showModal(`Error loading ${e.pinmuxFile}`, this.getLegacyBoardMessage(e.link), this.goBackToStart);

		} else if (e instanceof ScriptRunError) {
			this.props.modalService.showErrorModal(`Error running ${e.script}`, e,
				async () => {
					// No
					this.goBackToStart();
				}, async () => {
					// Yes
					this.compatabilityMode();
				}, "Yes", "No", "Would you like to re-try in compatability mode?");
		}
		else {
			this.props.modalService.showErrorModal(e.message, e, this.goBackToStart);
		}
		return {};
	}

	private async getConfigParamters() {
		const args = extractArgsFromRoute(this.props.location);
		const loader = createLoader(fs);
		const knownProducts = await createAvailableProducts();
		const resolvedArgs = await parseAndResolveArgs(args, loader, knownProducts);
		const deviceDiscoveryData = await getDeviceDescriptions();
		const mode = extractModeFromRoute(this.props.location);
		return { args, deviceDiscoveryData, resolvedArgs, mode };
	}

	private async createConfigStore(args: string[], deviceDiscoveryData: DiscoveryJSON,
		resolvedArgs: ResolvedArgs, mode: Mode) {
		// Create the SysConfig and then the ConfigStore based on it
		const reason = mode === Mode.Compatibility ? InvalidAssignmentReason.TARGET_MIGRATION
			: InvalidAssignmentReason.BACKWARDS_COMPATIBILITY;
		const sysConfig = await this.createSysConfig(resolvedArgs, reason);
		await preFetchForResponsiveUI(_.first(sysConfig.getRuntimes()));
		const configStore = new ConfigStore(
			sysConfig,
			this.props.notificationService,
			this.props.modalService,
			this.errorStore,
			args,
			deviceDiscoveryData,
		);
		configStore.onAnyChange().addListener(this.handleConfigStoreUpdate);
		const defaultModuleName = extractStringFromRoute(this.props.location, "module");
		recordLoadConfig(resolvedArgs, defaultModuleName);
		return ({ configStore });
	}

	private getLegacyBoardMessage(link: string) {
		return <Typography variant="body2" id="legacyBoardMessage">
			{"Support for MSP432P401R Launchpad configuration projects has migrated to SysConfig.  "}
			{"To load this project as-is, you can "}
			<Link
				component="button"
				display="inline"
				underline="hover"
				variant="body2"
				onClick={() => {
					openExternalLink(link);
				}}>
				download
			</Link>
			{" and install an older version of the standalone TI PinMux tool.  Alternatively, you can port "}
			{"your configuration to a SysConfig project with a newer version of the SimpleLink SDK."}
		</Typography>;
	}

	private handleOpen = (scriptPath: string) => {
		const currentArgs = extractArgsFromRoute(this.props.location);
		if (this.argsDiffer(currentArgs, [scriptPath])) {

			// Args changed, so just redirect to self with new args
			this.props.history.push(constructRoute(configPage, [scriptPath]));
		} else {

			// Args didn't change, so just clear the cache and re-fetch the same data
			clearSysConfigCache();
			this.reFetchAsyncData();
		}
	}

	private handleRefresh = () => {
		clearSysConfigCache();
		this.reFetchAsyncData();
	}

	private handleConfigStoreUpdate = () => {
		const currentArgs = this.state.configStore.getCurrentArgs();
		const routeArgs = extractArgsFromRoute(this.props.location);
		if (this.argsDiffer(currentArgs, routeArgs)) {
			this.props.history.replace(constructRoute(configPage, currentArgs));
		}
	}

	private addDefaultModule(sysConfig: SysConfig) {
		const defaultModuleName = extractStringFromRoute(this.props.location, "module");
		if (defaultModuleName) {
			const modMgr = _.first(sysConfig.getRuntimes()).getModuleMgr(defaultModuleName);
			modMgr.addInstance();
		}
	}

	private async createSysConfig(resolvedArgs: ResolvedArgs, reason: InvalidAssignmentReason) {
		// Create SysConfig and initialize with any script specified on the command line

		const sysConfig = (await capture(
			reason,
			() => runScripts(resolvedArgs, this.errorStore))).result;

		// Add any default module (analog links may request a specific analog sensor to add)

		this.addDefaultModule(sysConfig);

		return sysConfig;
	}

	private argsDiffer(args1: string[], args2: string[]) {
		return (_.size(args1) !== _.size(args2)) ||
			!_.isEmpty(_.difference(args1, args2));
	}

	private goBackToStart = () => {
		clearSysConfigCache();
		this.props.history.push(constructRoute(startPage, extractArgsFromRoute(this.props.location)));
	}

	private compatabilityMode = () => {
		clearSysConfigCache();
		this.props.history.push(constructRoute(configPage, extractArgsFromRoute(this.props.location), Mode.Compatibility));
	}
}
