import * as _ from "lodash";
import * as React from "react";
import { ATheme, ColorIndex } from "./styles/themes";

interface IProps {
	borderAfterChild: boolean; // true if the border is rendered to the right or below the child element
	position: number;
	displayed: boolean;
	showBorder?: boolean;
	percentage?: boolean;
	onPositionChanged: (position: number) => void; // exact position
	theme: ATheme;
	horizontal: boolean;
	backgroundColor?: string;
}

interface IState {
	hover: boolean;
	drag: boolean;
	pos: number;
}

const commonStyleHorizontal = {
	height: "100%",
	cursor: "col-resize",
};

const commonStyleVertical = {
	width: "100%",
	cursor: "row-resize",
};

const portalStyleCommon = {
	position: "absolute",
	width: "100%",
	height: "100%",
	zIndex: 2147483647,
	bottom: 0,
	right: 0,
} as const;

const portalStyleHorizontal = {
	...portalStyleCommon,
	cursor: "col-resize",
};

const portalStyleVertical = {
	...portalStyleCommon,
	cursor: "row-resize",
};

export class ResizableBorder extends React.Component<IProps, IState> {
	public override state = { hover: false, drag: false, pos: 0 };
	private prevPosition = 0;
	private overlayElem: HTMLElement;
	private contentElem: HTMLElement;

	public override render() {
		// the main content to show
		const content = (
			<div
				key="content"
				style={this.getContainerStyle()}
				ref={(el: HTMLDivElement) => this.contentElem = el}
			>
				{this.props.displayed && this.props.children}
			</div>
		);

		// the border line that is draggable
		const dragabbleBorder = (
			this.props.displayed ?
				<div
					key="draggable"
					style={this.getBorderStyle()}
					onMouseDown={this.onMouseDown}
					onMouseEnter={this.onMouseEnter}
					onMouseLeave={this.onMouseLeave}
				/>
				: (null)
		);

		// when mouse is down, we need to create a full screen area to capture the mouse events during drag
		const overlayContainer = (
			<div
				key="portal"
				style={this.getPortalStyle()}
				ref={(elem) => this.overlayElem = elem}
			>
				{this.state.drag &&
					<div style={this.getDraggingStyle()} />
				}
			</div>
		);

		// determine if the draggable border is on the left or right
		const contentArr = (this.props.borderAfterChild) ?
			[content, dragabbleBorder, overlayContainer] : [dragabbleBorder, content, overlayContainer];

		return contentArr;
	}

	// calculate the position (width or height) based on what side the container is on
	private calculatePosition(currentPos: number) {
		// current position
		const positionInPixels = (this.props.percentage) ? this.getClientSize() : this.props.position;

		// change in position
		const positionDelta = currentPos - this.prevPosition;

		// new position
		const position = (this.props.borderAfterChild) ?
			this.props.position + positionDelta : positionInPixels - positionDelta;

		// If requested, convert back to a percentage
		if (this.props.percentage) {
			return position / this.getClientSize() * this.props.position;
		}

		return position;

	}

	private getContainerStyle() {
		// convert the width to a CSS pixel or percentage string
		let position = (this.props.displayed ? this.props.position : 0).toString();
		position = (this.props.percentage) ? position + "%" : position + "px";

		const style = {
			height: "100%",
			transition: "0.15s all linear",
			backgroundColor: this.props.backgroundColor ?? this.props.theme.theme.palette.background.default,
		};

		if (this.props.horizontal) {
			return {
				...style,
				width: position,
				maxWidth: position,
				minWidth: position,
			};
		}
		return {
			...style,
			height: position,
			maxHeight: position,
			minHeight: position,
		};
	}

	// add border style, depending on the given props
	private getBorderStyle() {
		let borderColour = "transparent";
		if (this.state.hover) {
			borderColour = this.props.theme.colors[ColorIndex.SELECTEDICONCOLOR];
		} else if (this.props.showBorder) {
			borderColour = this.props.theme.colors[ColorIndex.BORDERCOLOR];
		}

		const borderStyle = "3px solid " + borderColour;
		if (this.props.horizontal) {
			return (this.props.borderAfterChild) ?
				{ ...commonStyleHorizontal, borderRight: borderStyle } : { ...commonStyleHorizontal, borderLeft: borderStyle };
		} else {
			return (this.props.borderAfterChild) ?
				{ ...commonStyleVertical, borderBottom: borderStyle } : { ...commonStyleVertical, borderTop: borderStyle };
		}
	}

	private getDraggingStyle(): React.CSSProperties {
		const common = {
			border: "6px solid #ddd",
			position: "absolute",
			opacity: 0.3,
		} as const;
		if (this.props.horizontal) {
			return {
				...common,
				height: "100%",
				left: this.state.pos,
			};
		}
		return {
			...common,
			width: "100%",
			top: this.state.pos,
		};
	}

	private onMouseDown = (mdEvent: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
		this.prevPosition = this.getPosition(mdEvent);

		// set up the mouse event listeners on the overlay
		this.overlayElem.addEventListener("mousemove", this.doDrag, false);
		this.overlayElem.addEventListener("mouseup", this.stopDrag, false);
		this.setState({ drag: true, pos: this.prevPosition });

		// reset the position when resizing a hidden child
		if (!this.props.displayed) {
			this.props.onPositionChanged(0);
		}
		mdEvent.stopPropagation();
		mdEvent.preventDefault();
	}

	private onMouseEnter = () => this.setState({ hover: true })
	private onMouseLeave = () => this.setState({ hover: false })

	// when dragging the mouse, it should display a grid line of the current position
	private doDrag = (mmEvent: MouseEvent) => {
		this.setState({ pos: this.getPosition(mmEvent) });
		mmEvent.stopPropagation();
		mmEvent.preventDefault();
	}

	// when mouse is up, calculate the new position, and remove the listeners
	private stopDrag = (muEvent: MouseEvent) => {
		this.props.onPositionChanged(this.calculatePosition(this.getPosition(muEvent)));

		this.overlayElem.removeEventListener("mousemove", this.doDrag, false);
		this.overlayElem.removeEventListener("mouseup", this.stopDrag, false);
		this.setState({ drag: false });

		muEvent.stopPropagation();
		muEvent.preventDefault();
	}

	private getPosition(e: { clientX: number, clientY: number }) {
		return this.props.horizontal ? e.clientX : e.clientY;
	}

	private getClientSize() {
		return this.props.horizontal ? this.contentElem.clientWidth : this.contentElem.clientHeight;
	}

	private getPortalStyle() {
		if (!this.state.drag) {
			return { display: "none" };
		} else if (this.props.horizontal) {
			return portalStyleHorizontal;
		} else {
			return portalStyleVertical;
		}
	}
}
