import React = require("react");
import {
	Card, List, ListItem, ListItemSecondaryAction,
	CardContent, Divider, Typography, IconButton,
} from "../imports/material-ui-imports";
import { HelpCircleOutline, WindowClose } from "../imports/mdi-material-ui-imports";
import { Tooltip } from "./Tooltip";
import { commonStyles } from "./styles/common";
import { ResourceLoader, ResourceType } from "../services/resources/metaContentLoaders/resourceLoader";
import { isUnderTest } from "../services/platform";
import { spacingUnit, defaultFontSize } from "./styles/themes";
import { MarkdownContent } from "./MarkdownContent";
import { IFormatter } from "../services/formatting/formattingTypes";
import { ILinkActions } from "./actions/ILinkActions";

interface LongDescriptionProps {
	id?: string;
	closeDescription: () => void; // Callback for the close icon at the top right corner of the card
	longDescription: string; // The documentation string that will be fed into the markdown converter
	divider?: boolean; // The divider marks the end of the documentation when the division is not obvious
	canonicalName?: string; // The lookup name to find the product 
	resourceType?: ResourceType; // The correct extension of the lookup name to find the product
	disableClose?: boolean; // Make the documentation uncloseable
	resourceLoader?: ResourceLoader;
	formatter: IFormatter;
	actions: ILinkActions;
}

export class LongDescription extends React.Component<LongDescriptionProps> {
	public override render() {
		return (
			<React.Fragment>
				<Card
					style={commonStyles.markedDescriptionStyle}
					id={this.props.id}>
					<List >
						<ListItem>
							<Typography variant="body2" style={commonStyles.cardTitleStyle}>Description</Typography>
							{
								!this.props.disableClose &&
								<ListItemSecondaryAction >
									<IconButton
										id={this.props.id + "_close"}
										onClick={() => this.props.closeDescription()}
									>
										<WindowClose color="primary" style={{ ...commonStyles.smallIcon }} />
									</IconButton>
								</ListItemSecondaryAction>
							}
						</ListItem>
					</List>
					<CardContent style={{ fontSize: defaultFontSize, paddingTop: 0, paddingLeft: spacingUnit * 6 }}>
						<MarkdownContent
							canonicalName={this.props.canonicalName}
							resourceType={this.props.resourceType}
							markdownSrc={this.props.longDescription}
							resourceLoader={this.props.resourceLoader}
							formatter={this.props.formatter}
							actions={this.props.actions}
						/>
					</CardContent>
				</ Card >
				{
					this.props.divider &&
					<Divider style={{ marginBottom: "4px" }} />
				}
			</React.Fragment >
		);
	}
}

const iconStyle: React.CSSProperties = {
	margin: 0,
	padding: "0px 2px 0px 2px",
	position: "relative",
	verticalAlign: "text-bottom",
};

interface IDisplayLongDescButtonProps {
	name: string;
	onClick: (ev: React.MouseEvent<HTMLElement>) => void;
	hidden: boolean;
	toolTipTitle?: string; // change the tooltip title
	style?: React.CSSProperties;
}

export class DisplayLongDescButton extends React.Component<IDisplayLongDescButtonProps> {
	public override render() {
		const isVisible = !this.props.hidden || isUnderTest();
		const style = iconStyle;
		return (
			<Tooltip title={this.props.toolTipTitle ? this.props.toolTipTitle : "Show/hide detailed help"}
				placement="right"
				disabled={this.props.hidden}
			>
				<IconButton
					id={`${this.props.name}_showdoc`}
					onClick={(ev) => this.props.onClick(ev)}
					style={{ ...style, visibility: isVisible ? "visible" : "hidden", ...this.props.style }}
				>
					<HelpCircleOutline style={{ fontSize: 12 }} />
				</IconButton>
			</Tooltip >
		);
	}
}
