import React = require("react");
import { AppBar, Toolbar, Typography } from "../imports/material-ui-imports";
import { IProjectActions } from "./actions/IProjectActions";
import { startPage, constructRoute, extractArgsFromRoute } from "../services/routing";
import { RouteComponentProps } from "react-router";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { isNode, isCloud, isUnderTest } from "../services/platform";
import { NavButton } from "./buttons/NavButton";
import { defaultTheme } from "./styles/themes";
import { FileMenu } from "./FileMenu";
import { getToolVersion } from "../services/toolVersion";
import { ConfigStore } from "../services/configStore";
import { UserStatus } from "./UserStatus";
import { Tooltip } from "./Tooltip";
import { clearSysConfigCache } from "../services/sysConfigFactory";

interface INavProps {
	actions?: IProjectActions;
	deviceName?: string;
	openSessionHandler?: (sessionPath: string) => void;
	restartSessionHandler?: () => void;
	configStore?: ConfigStore;
}

type IProps = INavProps & IGlobalServiceProps & RouteComponentProps<{}>;

interface IState {
	currentScript: string;
	saving: boolean;
	error: Error;
	fileSaveAsOpen: boolean;
	fileOpenOpen: boolean;
	savingPromise: Promise<void>;
}

export class Nav extends React.PureComponent<IProps, IState> {
	constructor(props: IProps) {
		super(props);
		this.state = {
			currentScript: null,
			saving: false,
			error: null,
			fileSaveAsOpen: false,
			fileOpenOpen: false,
			savingPromise: null,
		};
	}

	public override render() {
		const autoSaveText = this.getAutoSaveText();
		const textColor = this.props.theme.theme.palette.text.primary;
		return <div>
			<AppBar position="static" color="secondary" id="navBar" elevation={0}>
				<Toolbar style={{ minHeight: "48px" }}>

					{this.props.deviceName &&
						<React.Fragment>
							<FileMenu
								modalService={this.props.modalService}
								notificationService={this.props.notificationService}
								errorStore={this.props.errorStore}
								theme={this.props.theme}
								onFileNew={this.handleFileNew}
								onFileOpen={this.props.openSessionHandler}
								onFileSave={() => this.props.actions.saveProject()}
								onFileSaveAs={(fPath) => this.props.actions.saveProjectAs(fPath)}
								currentScript={this.state.currentScript}
							/>
							<NavButton
								id="aboutBtn"
								onClick={() => {
									this.props.modalService.showModal(`SysConfig (${getToolVersion()})`,
										<React.Fragment>
											<br />
											<Typography variant="body2" id="copyrightText" style={{ color: textColor }}>
												&#169; Copyright <img src="icons/apps/ti_logo_red.svg"
													style={{
														height: this.props.theme.theme.typography.fontSize + 2,
														padding: "0 1px",
														top: this.props.theme.theme.spacing(1),
														position: "relative",
													}} />
												<span
													style={{ fontWeight: 500 }}>Texas Instruments
												</span> {(new Date()).getFullYear()}. All rights reserved. </Typography>
										</React.Fragment>,
										() => { },
										true,
									);
								}}
							>
								About
							</NavButton>
							{autoSaveText &&
								<Tooltip title={this.getAutoSaveTooltip()}>
									<Typography variant="subtitle2" id="autoSaveText" color="inherit">{autoSaveText}</Typography>
								</Tooltip>
							}
						</React.Fragment>
					}
					<div style={{ flexGrow: 1 }} />
					{this.props.deviceName && isNode() &&
						<NavButton
							id="resetBtn"
							onClick={() => {
								this.props.modalService.showConfirmModal(
									"Restart",
									"Unsaved changes will be lost. Are you sure?",
									this.props.restartSessionHandler,
									() => { },
								);
							}}
						>
							Restart
						</NavButton>
					}
					{isCloud() &&
						<Typography variant="body2" component="div" id="userStatus" color="inherit"
							style={{ paddingLeft: defaultTheme.theme.spacing(1) }}>
							<UserStatus
								savingPromise={this.props.configStore ? this.state.savingPromise : null}
								modalService={this.props.modalService}
								notificationService={this.props.notificationService}
								theme={this.props.theme}
								errorStore={this.props.errorStore}>
							</UserStatus>
						</Typography>
					}
				</Toolbar>
			</AppBar>
		</div >;
	}

	public override componentDidUpdate(prevProps: Readonly<IProps & IGlobalServiceProps>) {
		if (this.props.configStore !== prevProps.configStore) {
			if (prevProps.configStore) {
				prevProps.configStore.onAnyChange().removeListener(this.anyChangeListener);
				if (isCloud()) {
					prevProps.configStore.onUserChange().removeListener(this.userChangeListener);
				}
			}
			if (this.props.configStore) {
				this.props.configStore.onAnyChange().addListener(this.anyChangeListener);
				if (isCloud()) {
					this.props.configStore.onUserChange().addListener(this.userChangeListener);
				}
			}
		}
	}

	public override componentDidMount() {
		if (isNode() && !isUnderTest()) {
			const gui = require("nw.gui");
			// Listen to main window's close event
			gui.Window.get().on("close", () => {
				if (this.props.configStore?.getCurrentScript().isDirty()) {
					this.props.modalService.showConfirmModal(
						"Close program",
						"Unsaved changes will be lost. Are you sure?",
						this.closeGUI,
						() => { },
					);
				} else {
					this.closeGUI();
				}
			});
		}

		if (this.props.configStore) {

			this.props.configStore.onAnyChange().addListener(this.anyChangeListener);
			this.setState({
				currentScript: this.props.configStore.getLoadedScript(),
				saving: false,
			});

			if (isCloud()) {
				this.props.configStore.onUserChange().addListener(this.userChangeListener);
			}
		}
	}

	public override componentWillUnmount() {
		if (isNode()) {
			const gui = require("nw.gui");
			// Listen to main window's close event
			gui.Window.get().removeAllListeners("close");
		}

		if (this.props.configStore) {

			this.props.configStore.onAnyChange().removeListener(this.anyChangeListener);

			if (isCloud()) {
				this.props.configStore.onUserChange().removeListener(this.userChangeListener);
			}
		}
	}

	private anyChangeListener = () => {
		if (this.props.configStore.getLoadedScript() !== this.state.currentScript) {
			this.setState({ currentScript: this.props.configStore.getLoadedScript() });
		}
	}

	private userChangeListener = () => {
		if (this.props.configStore.getLoadedScript()) {
			this.setState({ saving: true, error: null }, () => {
				const savingPromise = this.props.configStore.autoSave();
				this.setState({ savingPromise }, () => {
					this.state.savingPromise.then(
						() => this.setState({ saving: false }),
						(error) => this.setState({ saving: false, error }),
					);
				});
			});
		}
	}

	private closeGUI() {
		if (isNode()) {
			const gui = require("nw.gui");
			gui.App.quit();
		}
	}

	private handleFileNew = () => {
		this.props.modalService.showConfirmModal(
			"New Design",
			"Unsaved changes will be lost. Are you sure?",
			() => {
				clearSysConfigCache();
				this.props.history.push(constructRoute(startPage, extractArgsFromRoute(this.props.location)));
			},
			() => { },
		);
	}

	private getAutoSaveText() {
		if (isCloud() && this.props.configStore) {
			if (!this.state.currentScript) {
				return "Changes are unsaved";
			} else if (this.state.saving) {
				return "Saving...";
			} else if (this.state.error) {
				return "Failed to save changes";
			}
			return "All changes are saved";
		}
		return null;
	}

	private getAutoSaveTooltip() {
		if (isCloud() && this.props.configStore) {
			if (this.state.error) {
				return this.state.error.message;
			} else if (this.state.currentScript) {
				return `Every change is automatically saved to ${this.state.currentScript}`;
			}
		}
		return "";
	}
}
