import * as _ from "lodash";
import { keys, memoizeOne } from "../../../services/utils";
import { ClassesType } from "../styling/clockTreeStyles";

// Returns a new classes object that will apply the passed in style on top of normal styling for all child elements.  
// This is done by creating a new classes object where all values are the original style combined with the passed in 
// style which is done by concatenating the two strings.

function applyStyle(styleToAdd: keyof ClassesType["classes"]) {
	return memoizeOne((classes: ClassesType["classes"]) => {
		return _.mapValues(classes, (value) => {
			return `${value} ${classes[styleToAdd]}`;
		});
	});
}

// Returns new classes object where any style that matches the prefix is then applied to the style it prefixed.  
// This is done by creating a new classes object where all values are the original style combined with the matching
// prefixed style by concatenating the two strings.

function applyPrefixedStyle(prefix: string) {
	return memoizeOne((classes: ClassesType["classes"]) => {
		return {
			...classes,
			..._.chain(keys(classes))
				.filter((key) => _.startsWith(key, prefix))
				.map((key) => [key.slice(prefix.length), key])
				.filter((keyPair): keyPair is (keyof ClassesType["classes"])[] => keyPair[0] in classes)
				.map(([styleToUpdate, key]) =>
					[styleToUpdate, `${classes[styleToUpdate]} ${classes[key]}`])
				.fromPairs()
				.value(),
		};
	});
}

export const applyFiltered = applyStyle("filtered");
export const applySelected = applyPrefixedStyle("selected_");
export const applyError = applyPrefixedStyle("error_");
export const applyWarning = applyPrefixedStyle("warning_");
export const applyUnused = applyPrefixedStyle("unused_");
export const applyDisabled = applyPrefixedStyle("disabled_");
