// contains functions to check min tool version and perform other generic version comparison.
import * as _ from "lodash";
import { MinProductFile } from "./types";
import { devVersion } from "../toolVersion";
import * as semver from "semver";

// for testing to trigger a compatibility failure
const greaterThanCurrent = "greater_than_current";

export function verifyMinToolVersion(
	products: MinProductFile[], toolVersion: string) {

	const invalid = _.filter(products, (p) => {
		// if no minToolVersion, it should be considered compatible any version of the tool
		// that has this check
		return p.raw.minToolVersion && isGreaterThan(p.raw.minToolVersion, toolVersion);
	});
	if (!_.isEmpty(invalid)) {
		throw new InvalidMinToolVersion(invalid);
	}

	return true;
}

const guideUrl = "https://software-dl.ti.com/ccs/esd/sysconfig/docs/guide/update.html";
export class InvalidMinToolVersion extends Error {

	// keep the message in separate parts so it can be
	// rendered nicely in a dialog

	public readonly baseMessageText: string;
	public readonly moreInfoText = "For more information";
	public readonly moreInfoLink = guideUrl;

	constructor(public readonly products: MinProductFile[]) {
		super();
		const invalidMsgs = _.map(products, (p) => this.getProductErrorMessage(p));

		// Message printed to consoles, will be shown on CLI
		this.baseMessageText = `${_.join(invalidMsgs, "\n")}`;
		this.message = `${this.baseMessageText}\n${this.moreInfoText}: ${this.moreInfoLink} `;
	}

	public getProductErrorMessage(p: MinProductFile) {
		const productName = p.raw.displayName || p.raw.name;
		return (
			`Error: ${productName} version ${p.raw.version} requires at least version ${p.raw.minToolVersion} of SysConfig.`
		);
	}
}

// check min is greater than current
export function isGreaterThan(min: string, current: string) {

	// handle special versions
	// greaterThanCurrent > devVersion > normal versions
	// current can't be set to greaterThanCurrent
	if (min === current) {
		return false;
	} else if (min === devVersion) {
		return true;
	} else if (min === greaterThanCurrent) {
		return true;
	} else if (current === devVersion) {
		return false;
	}

	if (!semver.valid(min)) {
		throw new Error(`Invalid version format: "${min}`);
	}

	return semver.gt(min, current);
}
