import * as _ from "lodash";
import { Product } from "../product/types";
import { ResourceType } from "../resources/metaContentLoaders/resourceLoader";
import { ProductComponent } from "public/defs";
import { SCHEMA, validateMeta } from "../JSONschemaValidator";
import { SysConfig } from "../sysConfig";
import { filterProductsByContext } from "../contexts";

// Looks for the migration dialog info function exposed by the meta-content.  As specified in 
// defs.d.ts, this will look in the components in the order listed and in the products in the 
// order specified on the command line.  First found version is used.

// This function will also returned a auto-verifying version so that json validation is used
// to check all returns

export function findMigrationDialogInfoFn(sysConfig: SysConfig) {
	const { canonicalName, getMigrationDialogInfo, resourceLoader } = findMetaFunction(sysConfig) || {};
	if (getMigrationDialogInfo) {
		return {
			canonicalName,
			resourceLoader,
			getMigrationDialogInfo: withVerification(getMigrationDialogInfo, canonicalName),
		};
	}
	return {};
}

// Finds the first getMigrationDialogInfo according to the rules specified in defs.d.ts

function findMetaFunction(sysConfig: SysConfig) {
	return _.chain(sysConfig.getProducts())
		.reject((product) => _.isEmpty(product.file.components))
		.flatMap((product) => {
			const resourceLoader = findFirstRuntimeFor(product, sysConfig).getResourceLoader();
			return _.map(product.file.components, (canonicalName) => ({ canonicalName, resourceLoader }));
		})
		.map(({ canonicalName, resourceLoader }) => {
			try {
				const { getMigrationDialogInfo } = resourceLoader.getResource(canonicalName, ResourceType.CODE) as ProductComponent;
				return {
					canonicalName,
					resourceLoader,
					getMigrationDialogInfo,
				};
			} catch (e) {
				// It's 100% valid for component.js files do not exist.  In such a case, we are to silently ignore them
				return null;
			}
		})
		.compact()
		.find((result) => _.isFunction(result.getMigrationDialogInfo))
		.value();
}

// This finds the first runtime for which the product indicates it supports 

function findFirstRuntimeFor(product: Product, sysConfig: SysConfig) {
	return _.find(sysConfig.getRuntimes(), (r) => !_.isEmpty(filterProductsByContext([product], r.getName(), sysConfig.getDeviceData())));
}
// Wraps getMigrationDialogInfo with with verification provided by JSON schema

function withVerification(
	getMigrationDialogInfo: ProductComponent["getMigrationDialogInfo"],
	canonicalName: string,
): ProductComponent["getMigrationDialogInfo"] {
	return () => {
		const { extraMarkdown, isValid } = validateMeta(getMigrationDialogInfo(), canonicalName, SCHEMA.MigrationDialogInfo);
		return {
			extraMarkdown,
			isValid: (args) => {
				return validateMeta(isValid(args), canonicalName, SCHEMA.MigrationTargetValid);
			},
		};
	};
}
