import * as _ from "lodash";
import child_processMod = require("child_process");
import { isNode, isEclipse } from "./platform";
import { resolveRelativePathToProduct } from "./utils";
import { ExternalExecutableConfigurableResult } from "public/defs";
import { fs } from "./fileSystem";
import { fsUtils } from "./fsutil";
import { ExternalLaunchParams } from "./objectManagers/configurables/externalExecutableConfigurableMgr";
type ExternalCallResponse = Omit<ExternalExecutableConfigurableResult, "data">;

// Use project specific data dir, such that we can support multiple projects with sysconfig
// open at the same time.
// This is a function, vs a const value, as getTempProjectFilePath creates the path, and we don't want to do that 
// unnecessarily (say in the command line build).  See PMUX-3324
export function getExternalComFilePath() {
	return fsUtils.getTempProjectFilePath("pinmuxExternalComFile.json");
}

// resolve all the relative paths in the launch params
export function resolveExternalLaunchParams(productPath: string, launchParams: ExternalLaunchParams) {
	const { command, args, initialData, inSystemPath, filePath } = launchParams;
	// don't resolve the command as a relative path if it is a command within the system path
	const resolvedCommand = inSystemPath ?
		command :
		resolveRelativePathToProduct(productPath, command);
	// replace all reference to the communication file in the args to the correct full path
	const resolvedArgs = _.map(args, (arg) => {
		if (arg === "$comFile") {
			return getExternalComFilePath();
		} else if (arg === "$browsedFile") {
			return filePath;
		} else {
			return arg;
		}
	});
	return { resolvedCommand, resolvedArgs, initialData };
}

export async function launchExternalExecutable(productPath: string, launchParams: ExternalLaunchParams) {
	const {
		resolvedCommand,
		resolvedArgs,
	} = preLaunch(productPath, launchParams);
	const response = await launch(resolvedCommand, resolvedArgs);
	return postLaunch(response);
}

function preLaunch(productPath: string, launchParams: ExternalLaunchParams) {
	const {
		resolvedCommand,
		resolvedArgs,
		initialData,
	} = resolveExternalLaunchParams(productPath, launchParams);
	fs.writeFile(getExternalComFilePath(), initialData);
	return {
		resolvedCommand,
		resolvedArgs,
	};
}

function postLaunch(response: ExternalCallResponse): ExternalExecutableConfigurableResult {
	const comFilePath = getExternalComFilePath();
	const dataFromCommunicationFile = fs.fileExists(comFilePath) ?
		fs.readFile(comFilePath) :
		`Communication file: ${comFilePath} does not exist`;
	return {
		...response,
		data: dataFromCommunicationFile,
	};
}

function launch(command: string, args: string[]): Promise<ExternalCallResponse> {
	if (isNode()) {
		// Spawn child process
		const childProcess = require("child_process") as typeof child_processMod;
		const child = childProcess.spawn(command, args);
		return new Promise((resolve, reject) => {
			child.on("error", (err) => reject(err));
			child.on("exit", (code, signal) => resolve({ exitCode: code, killSignal: signal }));
		});
	} else if (isEclipse()) {
		const eclipseCommand = `${command} ${_.join(_.map(args, (arg) => `"${arg}"`), " ")}`;
		const responsePromise = new Promise((resolve, reject) => {
			(window as any).eclipseSpawnCallback = (response: IEclipseSpawnResponse) => {
				if (response.error) {
					reject(new Error(response.error));
				} else {
					resolve({
						exitCode: response.exitCode,
					});
				}
			};
		});
		eclipseSpawn(eclipseCommand, "eclipseSpawnCallback");
		return responsePromise;
	} else {
		return Promise.reject(new Error("Cannot launch external executable from the current platform"));
	}
}
