import * as _ from "lodash";
import React = require("react");
import {
	ListItem, ListItemSecondaryAction, ListItemText, Typography, IconButton,
} from "../imports/material-ui-imports";
import { DeleteOutline } from "../imports/mdi-material-ui-imports";
import { commonStyles, withCommonStyles, CommonClasses } from "./styles/common";
import { InstanceStatusDecorator } from "./Decorators";
import { IMyListItemActions } from "../services/configStore";
import { Popup } from "./Popup";
import { CannotBeRemovedPopup } from "./CannotBeRemovedPopup";
import { IFormatter } from "../services/formatting/formattingTypes";
import { OwnershipInfo } from "../services/IMyListItem";
import { ILinkActions } from "./actions/ILinkActions";
import { InstanceMgr, AInstanceContainer } from "../services/instanceContainers/instanceContainer";
import { Validations } from "../services/objectManagers/validations";

interface IListItemProps<T extends InstanceMgr> {
	name: string;
	remove: (item: T) => void;
	isSelected: boolean;
	isRemovable: boolean;
	select: (item: T) => void;
	index: number;
	formatter: IFormatter;
	validations: Validations;
	cannotRemoveReason?: OwnershipInfo | string;
	item: T;
}

class StyledItem<T extends InstanceMgr> extends React.PureComponent<IListItemProps<T> & CommonClasses> {
	public override render() {
		const className = this.props.isSelected ? this.props.classes.selectedList : this.props.classes.unSelectedList;

		return (
			// wrap and id for testing
			<ListItem
				id={"req" + this.props.index}
				button
				onClick={this.onSelect}
				className={className}
			>
				<InstanceStatusDecorator
					id={"decorators" + this.props.index}
					key="decorators"
					instanceMgr={this.props.item}
					validations={this.props.validations}
				/>
				<ListItemText id="requirementText"
					primary={<Typography variant="subtitle2">{this.props.name}</Typography>} />
				<Popup
					align="left"
					getContent={this.getPopupContent}
					hoverTarget={
						<ListItemSecondaryAction>
							<IconButton
								key="iconButton"
								disabled={!this.props.isRemovable}
								onClick={this.onRemove}
							>
								<DeleteOutline style={{ ...commonStyles.smallIcon }} />
							</IconButton>
						</ListItemSecondaryAction>
					}
				/>
			</ListItem>
		);
	}

	private onSelect = () => {
		this.props.select(this.props.item);
	}

	private onRemove = (e: React.MouseEvent<HTMLButtonElement, MouseEvent>) => {
		e.stopPropagation();
		this.props.remove(this.props.item);
	}

	private getPopupContent = () => {
		return !this.props.isRemovable &&
			this.props.cannotRemoveReason &&
			<CannotBeRemovedPopup
				formatter={this.props.formatter}
				reason={this.props.cannotRemoveReason}
			/>;
	}
}

const ItemImpl = withCommonStyles(StyledItem);

function Item<T extends InstanceMgr>(props: IListItemProps<T>) {
	return <ItemImpl {...props as any} />;
}

interface IProps<T extends InstanceMgr> {
	actions: IMyListItemActions & ILinkActions;
	selectedTreeNode: AInstanceContainer<T>;
	formatter: IFormatter;
	validations: Validations;
	onSelect: (item: T) => void;
	onRemove: (item: T) => void;
	isRemovable: (item: T) => boolean;
	getCannotRemoveReason: (item: T) => OwnershipInfo | string;
	getItemName: (item: T) => string;
	instruction?: JSX.Element;
}

export const requirementsListStyle: React.CSSProperties = {
	overflowY: "auto",
	width: "100%",
	maxHeight: 200, // shows 5 entries before overflow
	padding: 0,
};

// Container for the entire list view
export class RequirementsList<T extends InstanceMgr> extends React.Component<IProps<T>, {}> {
	public override render() {
		const selectedMyListItem = this.props.selectedTreeNode.getSelectedMyListItem();
		const listItems: T[] = this.props.selectedTreeNode.getInstances();
		const showInstructions = listItems.length === 0;
		if (showInstructions) {
			return (
				<Instructions
					instruction={
						this.props.instruction ?
							this.props.instruction :
							<React.Fragment>
								Click the <b>Add</b> button to add a {this.props.selectedTreeNode.getDisplayName(false)} to your design
							</React.Fragment>
					}
				/>
			);
		}
		return (
			<div style={requirementsListStyle}>
				{
					_.map(listItems, (item, index) => {
						return (
							<Item
								key={item.getID()}
								name={this.props.getItemName(item)}
								index={index}
								item={item}
								isSelected={item === selectedMyListItem}
								formatter={this.props.formatter}
								cannotRemoveReason={this.props.getCannotRemoveReason(item)}
								select={this.props.onSelect}
								remove={this.props.onRemove}
								isRemovable={this.props.isRemovable(item)}
								validations={this.props.validations}
							/>
						);
					})
				}
			</div>
		);
	}
}

class Instructions extends React.PureComponent<{ instruction: JSX.Element }> {
	public override render() {
		return (
			<Typography variant="body2" style={{ textAlign: "center", width: "100%" }}>
				{this.props.instruction}
			</Typography>
		);
	}
}
