import * as _ from "lodash";
import { DiscoveryData } from "../discoveryData";
import { Product, ValidTargets } from "../product/types";
import { MigrationDialogInfo, MigrationTarget } from "public/defs";
import { FormattedDropDownOption } from "../../components/ComponentUtils";
import { MarkdownRenderProps } from "../MarkdownConverter";
import { filterProductsByContext, getUIContextChoices } from "../contexts";
import { AdaptedDeviceInfo } from "dataInterfaces";
import { isEclipse } from "../platform";
import { systemContext } from "../args/argTypes";
import { allowMigrationTo } from "./migrate";

// This encapsulates everything that the migration dialog will need.  It generates the drop down 
// options from the discovery data, but also uses the meta-content information to disable or warn
// for specific options.  
// The design intentionally takes the result of calling getMigrationDialogInfo vs calling it on 
// demand.  That way the dialog text won't update on a re-render.

export class MigrationOptions {
	private readonly extraMarkdown: string;
	private readonly availableDevices: FormattedDropDownOption[];
	private readonly availableDevicesPerBoard: { [Key: string]: FormattedDropDownOption[] } = {};
	private readonly availableBoards: FormattedDropDownOption[];
	private readonly contextChoicesPerDevice: FormattedDropDownOption[][][];

	constructor(
		migrationDialogInfo: MigrationDialogInfo,
		private readonly discoveryData: DiscoveryData,
		products: Product[],
		private readonly validTargets: ValidTargets,
		private readonly markdownProps: MarkdownRenderProps,
		contexts: string[],
		deviceData: AdaptedDeviceInfo,
	) {
		this.extraMarkdown = migrationDialogInfo.extraMarkdown;
		const isValid = this.checkEclipseVersion(migrationDialogInfo.isValid, contexts, products);

		this.availableDevices = buildBaseDeviceOptions(discoveryData, validTargets, products, isValid);

		this.contextChoicesPerDevice = this.getContextChoicesPerDevice(contexts, products, deviceData);

		this.availableBoards = this.buildBoardOptions(isValid);
	}

	public getMarkdownProps() {
		return this.markdownProps;
	}

	public getDisoveryData() {
		return this.discoveryData;
	}

	public getExtraMarkdown() {
		return this.extraMarkdown;
	}

	public getBoardOptions() {
		return this.availableBoards;
	}

	public getDeviceOptions(board?: string) {
		if (!board) {
			return this.availableDevices;
		}
		return this.availableDevicesPerBoard[board];
	}

	public getContextChoices(device: string) {
		return this.contextChoicesPerDevice[_.findIndex(this.availableDevices, (d) => d.name === device)];
	}

	public getBoardInfo(board: string) {
		return _.find(this.validTargets.boards, (b) => b.name === board);
	}

	private checkEclipseVersion(isValid: MigrationDialogInfo["isValid"], contexts: string[], products: Product[]) {
		if (isEclipse() && !window.eclipseMigrateProject2) {

			// Extend isValid to check that we aren't migrating multi-core setup within an older CCS that doesn't support it

			return (args: MigrationTarget) => {
				const contextChoices = _.chain(products)
					.flatMap(({ file }) => getUIContextChoices(file, this.discoveryData.getDevice(args)))
					.map(({ name }) => name)
					.uniq()
					.value();

				if (_.size(contexts) !== 1 ||
					_.first(contexts) !== systemContext ||
					_.size(contextChoices) !== 1 ||
					_.first(contextChoices) !== systemContext
				) {
					return { disable: "The current version of CCS does not support project migration to/from multi-core devices" };
				}
				return isValid(args);
			};
		}
		return isValid;
	}

	private getContextChoicesPerDevice(contexts: string[], products: Product[], deviceData: AdaptedDeviceInfo) {

		// No products - only choice is the system context

		if (_.isEmpty(products)) {
			return _.map(this.availableDevices, () => [[{ name: systemContext }]]);
		}

		// Determine which products apply to which context, then find out what contexts on the new device all of those 
		// products can support.  That way, we don't allow migrating a context supported by only one of two products to
		// a context on the new device only supported by the other product

		const validProductsPerContext = _.map(contexts, (context) => filterProductsByContext(products, context, deviceData));
		return _.map(this.availableDevices, ({ name }) => {
			return _.map(validProductsPerContext, (validProducts) => {
				const contextChoicesPerProduct = _.map(validProducts,
					({ file }) => getUIContextChoices(file, this.discoveryData.getDevice({ device: name })));
				const intersection = _.intersectionBy(...contextChoicesPerProduct, (named) => named.name);
				return intersection;
			});
		});
	}

	private buildBoardOptions(isValid: MigrationDialogInfo["isValid"]) {
		return _.map(this.validTargets.boards, (board) => {
			const emulatedDevices = _.chain(board.emulated)
				.filter((emulatedDevice) => _.some(this.availableDevices, (d) => d.name === emulatedDevice.device))
				.map((emulatedDevice) => ({ name: emulatedDevice.device, displayName: emulatedDevice.device + " (emulated)" }))
				.value();

			this.availableDevicesPerBoard[board.name] = _.map([{ name: board.device }, ...emulatedDevices],
				(device) => {
					const valid = isValid({ board: board.name, device: device.name });
					return {
						...device,
						isDisabled: !!valid.disable,
						description: valid.disable || valid.warn,
					};
				});

			const allDisabled = _.every(this.availableDevicesPerBoard[board.name], (device) => device.isDisabled);
			const descriptions = _.chain(this.availableDevicesPerBoard[board.name])
				.map((device) => device.description)
				.uniq()
				.value();

			return {
				name: board.name,
				displayName: board.displayName,
				isDisabled: allDisabled,
				description: (allDisabled || _.size(descriptions) === 1) ? _.first(descriptions) : "",
			};
		});
	}
}

function buildBaseDeviceOptions(
	discoveryData: DiscoveryData,
	validTargets: ValidTargets,
	products: Product[],
	isValid: MigrationDialogInfo["isValid"],
) {
	return _.chain(discoveryData.getDevices())
		.map((device) => device.name)
		.filter(validTargets.deviceValid)
		.filter((device) => allowMigrationTo(discoveryData.getDevice({ device }), products))
		.map((device) => {
			const valid = isValid({ device });
			return {
				name: device,
				isDisabled: !!valid.disable,
				description: valid.disable || valid.warn,
			};
		})
		.value();
}
