import * as _ from "lodash";
// funcs to deal with creating and collecting ISummaryItems.
import { Validation, IValidatable } from "./objectManagers/validations";
import { getShortValidationString, getLongValidationString } from "./utils";

// Items (errors,warnings,infos) rendered by the summary view and output on console.
export interface ISummaryItem {
	location: string;
	text: string;
	details: string[];
	type: keyof Validation;
	validation: Validation;
	validatableObj: IValidatable;
}

// location must be a call back that is evaluated only if errors exists
// this a work around to deal with multiPin issues.

export function mapValidation(
	validation: Validation,
	getLocation: () => string,
	validatableObj: IValidatable,
	includeSuppressed: boolean,
): ISummaryItem[] {
	const validationTypes = includeSuppressed ?
		["errors", "warnings", "infos", "suppressedWarnings"] as const :
		["errors", "warnings", "infos"] as const;
	return (
		_.chain(validationTypes)
			.filter((type) => !_.isEmpty(validation[type]))
			.flatMap((type) => {
				return _.map(validation[type], (text) => {
					return {
						location: getLocation(),
						text: getShortValidationString(text),
						details: getLongValidationString(text),
						type,
						validation,
						validatableObj,
					};
				});
			})
			.value()
	);
}
