import * as _ from "lodash";
import { EnumerationConfigurable } from "public/defs";
import { RuntimeObject } from "public/runtime";
import { AccessType, validateDeprecatedAccess } from "../../deprecatedAccessGuard";
import { FormattersMap } from "../../formatting/formattersMap";
import { isModuleInstance } from "../../utils";
import { AObjectMgr } from "../object";
import { IOptions } from "../options";
import {
	BaseEnumerationConfigurableMgr,
	unknownOptionError,
	validateDisabledOptions,
	verifyOptionTypes,
} from "./baseEnumerationConfigurableMgr";

export class EnumerationConfigurableMgr<
	RuntimeObjectType extends RuntimeObject = RuntimeObject,
	T extends number | string = string>
	extends BaseEnumerationConfigurableMgr<T, T, RuntimeObjectType, EnumerationConfigurable<T>>
	implements IOptions<T> {

	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObjectType>,
		formattersMap: FormattersMap,
		def: EnumerationConfigurable<T>,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			def,
		);

		verifyOptionTypes(this.def.options);

		// option names and default must be of the same type
		if (typeof this.def.options[0].name !== typeof this.def.default) {
			throw new Error("default and option names must be of the same type.");
		}

		this.validateValue(this.value);

	}

	public getSelectedOption() {
		return _.find(this.def.options, (o) => o.name === this.value);
	}

	public getOptions() {
		// Get the disabled options from the meta-data
		const inst = this.getParentRuntimeObj();
		const disabledOptions = this.def.getDisabledOptions ?
			this.def.getDisabledOptions(isModuleInstance(inst) ? inst : undefined) :
			[];
		const optionsByName = this.getOptionsByName();
		validateDisabledOptions(disabledOptions, this.def.name, (o) => {
			if (!optionsByName[o.name]) {
				throw new Error(`${this.def.name}: attempted to disable unknown option '${o.name}'`);
			}
		});

		// Return both the disabled and enabled options

		const enabledOptions = _.differenceWith(this.def.options, disabledOptions, (a, b) => a.name === b.name);
		return { disabledOptions, enabledOptions };
	}

	protected getOptionsByName() {
		const currentOptions = this.def.options;
		return _.keyBy(currentOptions, (o) => o.name);
	}

	protected override validateValue(newVal: T, forceWrite?: boolean) {

		// Extend the base preSet method to validate and map input value to an option. By default
		// input value must exactly match the name of one of the options. However, this function
		// adds hooks to allow map child classes to map via any criteria. This is needed to support ease of 
		// use in scripting. For example pin names on some devices can be fairly long, it is desired that 
		// user specify only part of the name in the script which if possible 
		// should be mapped to th

		// validate type

		super.validateValue(newVal, forceWrite);

		// is valid option

		const val = this.transform(newVal);
		const option = _.find(this.def.options, (o) => o.name === val);

		if (!option) {
			unknownOptionError(newVal, this.validOptions());
		}
	}

	/**
	 * List of valid options to print on invalid input. 
	 */
	protected validOptions() {
		return _.map(this.def.options, (o) => o.name);
	}

	protected override transform(val: T): T {
		// check if it is a legacy name
		// class may not be constructed, so legacyNamesMap might not exist
		if (this.legacyNamesMap?.has(val)) {
			validateDeprecatedAccess(AccessType.WRITE);
			return this.legacyNamesMap.get(val);
		}
		return val;
	}
}

export function getOptionWithLegacyName(legacyName: string, config: EnumerationConfigurable) {
	const option = _.find(config.options, (o) => {
		return _.includes(o.legacyNames, legacyName);
	});

	return option?.name;
}
