// This module is the set of functions that are dynamically exposed from the
// enscriptem glucose module.  Comparatively, the glucose module is the raw
// enscriptem compiled code as well as the functions necessary to find 
// dynamically exposed functions.

import * as _ from "lodash";
import { logicError as debugLogicError, profileGlucose, log } from "./debug";

type ArgType = "number" | "void";
type FunctionNames =
	"initializeClauses" |
	"addAssumptions" |
	"changeAssumption" |
	"setBudget" |
	"setVerbosity" |
	"solve" |
	"getSolution";

namespace Functions {
	export type initializeClauses = (numVars: number, numClauses: number, clauseArray: number) => boolean;
	export type addAssumptions
		= (firstAssumptionVar: number, lastAssumptionVar: number, assumptionValue: boolean) => void;
	export type changeAssumption = (assumptionVar: number, assumptionValue: boolean) => boolean;
	export type setBudget = (conflictBudget: number, propagationBudget: number, restartBudget: number) => void;
	export type setVerbosity = (verbosity: number, verbEveryConflicts: number) => void;
	export type solve = () => boolean;
	export type getSolution = () => number;
	export type Any =
		initializeClauses | addAssumptions | changeAssumption | setBudget | setVerbosity | solve | getSolution;
}

interface Module {
	HEAP32: Int32Array;
	cwrap(name: FunctionNames, retType: ArgType, argTypes: ArgType[]): Functions.Any;
	_realloc(buffer: number, size: number): number;
}

export const glucoseModule: Module = require("./glucose");

const logicError = debugLogicError;
let glucoseTime = 0;

export function resetGlucoseTime() {
	glucoseTime = 0;
}

export function getGlucoseTime() {
	return glucoseTime;
}

// Glucose is a wasm module with with "SINGLE_FILE" set to true.  This means means that the binary data is encoded into
// a buffer in js, but it still has to asynchronously call WebAssembly.instantiateStreaming.  As such, while we can 
// fetch functions immediately, we can't call them till this is complete.  
//
// This function returns a promise that is resolved once this has taken place.  As such, it needs to resolve before
// using the solver.

export function waitForGlucoseToInit() {
	return new Promise<void>((resolve) => {
		waitForWasmToSelfLoad(resolve);
	});

	function waitForWasmToSelfLoad(cb: () => void) {
		if (!("asm" in glucoseModule)) { // this key exists only once WebAssembly.instantiateStreaming resolves
			setTimeout(() => waitForWasmToSelfLoad(cb), 1);
		} else {
			cb();
		}
	}
}

function dlsym<T>(name: FunctionNames, ret: ArgType, args: ArgType[]) {
	return {
		name,
		fun: glucoseModule.cwrap(name, ret, args) as any as T,
	};
}

function dlsym_initializeClauses() {
	return dlsym<Functions.initializeClauses>(
		"initializeClauses",
		"number",
		["number", "number", "number"]);
}

function dlsym_addAssumptions() {
	return dlsym<Functions.addAssumptions>(
		"addAssumptions",
		"void",
		["number", "number", "number"]);
}

function dlsym_changeAssumption() {
	return dlsym<Functions.changeAssumption>(
		"changeAssumption",
		"number",
		["number", "number"]);
}

function dlsym_setBudget() {
	return dlsym<Functions.setBudget>(
		"setBudget",
		"void",
		["number", "number", "number"]);
}

function dlsym_setVerbosity() {
	return dlsym<Functions.setVerbosity>(
		"setVerbosity",
		"void",
		["number", "number"]);
}

function dlsym_solve() {
	return dlsym<Functions.solve>(
		"solve",
		"number",
		[]);
}

function dlsym_getSolution() {
	return dlsym<Functions.getSolution>(
		"getSolution",
		"number",
		[]);
}

function glucoseFunction<T>(fun: { name: string, fun: T }) {
	if (profileGlucose) {
		// We need a non-arrow function in order to access "arguments"
		// We need a space as the auto-formatter does that?
		const doProfiling = function () {
			log("calling " + fun.name);
			const start = new Date().getTime();
			const raw = fun.fun as any as (...args: any[]) => any;
			const ret = raw.apply(void 0, Array.from(arguments));
			const end = new Date().getTime();
			log(fun.name + " took " + (end - start));
			glucoseTime += (end - start);
			return ret;
		};
		return doProfiling as any as T;
	}
	return fun.fun;
}

function createEmptyCache() {
	return {
		start: 0,
		current: [] as number[],
		cache: [] as { solved: boolean, assumptions: string }[],
		currentSolution: null as string,
	};
}
let assumptionCache = createEmptyCache();
function clearAssumptionCache() {
	assumptionCache = createEmptyCache();
}

export const initializeClauses = (() => {
	const glucoseInitializeClauses = glucoseFunction(dlsym_initializeClauses());
	return (numVars: number, numClauses: number, clauseArray: number) => {
		clearAssumptionCache();
		const result = glucoseInitializeClauses(numVars, numClauses, clauseArray);
		if (!result) {
			logicError("Initialize clauses failed");
		}
		return result;
	};
})();

export const addAssumptions = (() => {
	const glucoseAddAssumptions = glucoseFunction(dlsym_addAssumptions());
	return (firstError: number, numChoices: number, bool: boolean) => {
		clearAssumptionCache();
		assumptionCache.current = _.times(numChoices, () => {
			return bool ? 1 : 0;
		});
		glucoseAddAssumptions(firstError, numChoices, bool);
	};
})();

export const changeAssumption = (() => {
	const glucoseChangeAssumption = dlsym_changeAssumption().fun;
	return (num: number, bool: boolean) => {
		if (!glucoseChangeAssumption(num, bool)) {
			logicError("Invalid assumption change");
		}
		assumptionCache.current[num - assumptionCache.start] = bool ? 1 : 0;

		// Return of real function is just to catch errors above
		// But we need to return a bool here to match the signature

		return true;
	};
})();

export const solve = (() => {
	const glucoseSolve = glucoseFunction(dlsym_solve());
	return () => {
		const current = assumptionCache.current.join("");
		const cache = _.find(assumptionCache.cache, (cache2) => {
			return cache2.assumptions === current;
		});
		if (cache) {
			return cache.solved;
		} else {
			const solved = glucoseSolve();
			assumptionCache.cache.push({
				solved,
				assumptions: current,
			});
			assumptionCache.currentSolution = current;
			return solved;
		}
	};
})();

export const setBudget = (() => {
	const glucoseSetBudget = glucoseFunction(dlsym_setBudget());
	return (a: number, b: number, c: number) => {
		assumptionCache.cache = [];
		assumptionCache.currentSolution = null;
		return glucoseSetBudget(a, b, c);
	};
})();

export const getSolution = (() => {
	const glucoseGetSolution = glucoseFunction(dlsym_getSolution());
	return () => {
		if (assumptionCache.currentSolution !== assumptionCache.current.join("")) {
			assumptionCache.cache = [];
			assumptionCache.currentSolution = null;
			if (!solve()) {
				// So we know this solution is valid, so the only logical reason it could fail would be 
				// budget limitations.  Clear those and retry.  
				setBudget(-1, -1, -1);
				if (!solve()) {
					logicError("solve failed for previously solvable configuration");
				}
			}
		}
		return glucoseGetSolution();
	};
})();

export const setVerbosity = glucoseFunction(dlsym_setVerbosity());
