import * as React from "react";
import * as _ from "lodash";
import { ExtendedElkLine } from "../layout/customTypes";
import { ClassesType } from "../styling/clockTreeStyles";
import { ClockTreeNode } from "../../../services/instanceContainers/clockTreeNode";
import { PinFrequencyConfigurableMgr } from "../../../services/objectManagers/configurables/pinFrequencyConfigurableMgr";
import { PositionedDiv } from "../nodes/PositionedDiv";
import { Tooltip } from "../../Tooltip";

// This component renders a tooltip for the frequency value if a line is selected

interface IFrequencyProps {
	selectedLine: ExtendedElkLine;
	treeNode: ClockTreeNode;
}

// Note that the frequency on a specific line can change as you update module settings.  As such, we can't use 
// React.memo on this function, as we explicitly WANT to update if the parent re-renders

export function FrequencyLabelTooltip({ selectedLine, treeNode, classes }: IFrequencyProps & ClassesType) {
	if (!selectedLine) {
		return null;
	}
	// The edge will always have one source, but multiple targets

	const source = _.first(selectedLine.data.edges).signal.source;
	const inst = treeNode.getIpInstanceMgr(source.instName);
	const pinMgr = inst.memberMgrs[source.pinName] as PinFrequencyConfigurableMgr;

	return <PositionedDiv
		x={(selectedLine.start.x + selectedLine.end.x) / 2}
		y={(selectedLine.start.y + selectedLine.end.y) / 2}
		width={1}
		height={1}
		className={classes.positionedDiv}
	>
		<Tooltip title={pinMgr.getValueAsString()} open={true} />
	</PositionedDiv>;
}
