import React = require("react");
import { Snackbar, SnackbarContent, IconButton } from "../imports/material-ui-imports";
import { Close } from "../imports/mdi-material-ui-imports";
import { defaultFontSize } from "./styles/themes";
import { commonStyles } from "./styles/common";

interface IProps {
	msg: string;
	iconColor: string;
	onClose: () => void;
}

export class Notification extends React.Component<IProps> {
	public override render() {
		return (
			<Snackbar
				open={true}
				anchorOrigin={{ vertical: "bottom", horizontal: "right" }}
				autoHideDuration={3000}
				onClose={this.closeNotification}
			>
				<SnackbarContent
					id="notificationMsg"
					message={<span style={{ fontSize: defaultFontSize }}>{this.props.msg}</span>}
					action={
						<IconButton
							id="notificationCloseBtn"
							onClick={(e: React.SyntheticEvent<any>) => this.closeNotification(e, "")}
						>
							<Close style={{ ...commonStyles.smallIcon, color: this.props.iconColor }} />
						</IconButton>
					}
				/>
			</Snackbar>
		);
	}

	private closeNotification = (_event: React.SyntheticEvent<any>, reason: string) => {
		if (reason === "clickaway") { return; }	// ignore the clickaway event
		this.props.onClose();
	}
}
