import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/clockTreeStyles";
import { Group } from "./Group";
import { IClockTreeInnerGraphProps } from "../graph/ClockTreeInnerGraph";

// This component will render a <Group> node for every group in the layout passed in

export function Groups(props: IClockTreeInnerGraphProps & ClassesType) {
	const { layout, ...rest } = props;
	return <>
		{_.chain(layout.children)
			.filter((child) => !_.isEmpty(child.children))
			.map((child) => {
				return <Group
					{...rest}
					layout={child}
					key={`group_${child.id}`}
				/>;
			})
			.value()}
	</>;
}
