import React = require("react");
import * as path from "path";
import { ILocalFileBrowseProps } from "../local/LocalFileBrowse";
import { ModalService } from "../../services/ui/modals";
import { ErrorStore } from "../../services/errorStore";
import { CloudFileTree } from "../fileTrees/CloudFileTree";
import { InputBox } from "../InputBox";
import {
	Button,
	Dialog,
	DialogTitle,
	DialogActions,
	DialogContent,
	Typography,
} from "../../imports/material-ui-imports";
import { storage, syscfgWorkspace } from "../../services/storage";

interface IProps extends Omit<ILocalFileBrowseProps, "onChange"> {
	onClose: () => void;
	open: boolean;
	errorStore: ErrorStore;
	modalService: ModalService;
	title: string;
	initialName: string;
	onChange: (fpath: string) => void;
}

export class CloudFileSaveAsDialog
	extends React.Component<IProps, { filePath: string }> {

	constructor(props: IProps) {
		super(props);
		this.state = {
			filePath: storage.formatPathForUser(this.props.initialName || path.join(syscfgWorkspace, "untitled.syscfg")),
		};
	}

	public override render() {
		return (
			<span id="cloudFileSaveAsDialog">
				<Dialog
					open={this.props.open}
					fullWidth={true}
					onClose={this.props.onClose}
				>
					<DialogTitle>{this.props.title}</DialogTitle>
					<DialogContent>
						<div style={{
							overflow: "auto",
							height: "300px",
						}}
						>
							<CloudFileTree
								onFolderSelect={this.onFolderSelect}
								onFileSelect={this.onFileSelect}
								modalService={this.props.modalService}
								errorStore={this.props.errorStore}
								fnameFilter={this.props.accept}
								hideUpload={true}
							/>
						</div>
						<Typography variant="subtitle2">File name</Typography>
						<InputBox
							id={"SaveAsInputBox"}
							onChange={this.onInputChange}
							value={this.state.filePath}
							disabled={false}
							type={"text"}
						/>
					</DialogContent>
					<DialogActions>
						<Button onClick={this.onSave} id="SaveButton">Save</Button>
						<Button onClick={this.props.onClose} id="CancelButton">Cancel</Button>
					</DialogActions>
				</ Dialog>
			</span>
		);
	}

	private onSave = () => {
		try {
			const realPath = storage.formatPathFromUser(this.state.filePath);
			this.props.onClose();
			this.props.onChange(realPath);
		} catch (e) {
			this.props.modalService.showErrorModal(e.message, null);
		}
	}

	private onFolderSelect = (folder: string) => {
		const fileName = path.basename(this.state.filePath);
		this.setState({ filePath: storage.formatPathForUser(path.join(folder, fileName)) });
	}

	private onFileSelect = (filePath: string) => {
		this.setState({ filePath: storage.formatPathForUser(filePath) });
	}

	private onInputChange = (filePath: string) => {
		this.setState({ filePath });
	}
}
