import * as _ from "lodash";

class SimpleEventRegistration<T extends (...args: any[]) => void> {

	protected readonly listeners: T[] = [];

	public addListener(cb: T) {
		this.listeners.push(cb);
	}

	public removeListener(cb: T) {
		_.pull(this.listeners, cb);
	}
}

export class SimpleEvent<T extends (...args: any[]) => void = () => void> extends SimpleEventRegistration<T> {

	public fire(...args: Parameters<T>) {
		_.each(_.clone(this.listeners), (listener) => {
			listener(...args);
		});
	}

	// This allows our owner to return a registration interface for clients to use, but leverages
	// typescript type checking to prevent them from accessing "fire".  Technically, raw javascript
	// could work around this, but we don't care.

	public asRegistration(): SimpleEventRegistration<T> {
		return this;
	}
}
