import * as _ from "lodash";
import { http } from "./http";
import { isCloud } from "./platform";
import { getToolVersion } from "./toolVersion";
import { ResolvedArgs } from "./args/argTypes";

export function recordLoadConfig(args: ResolvedArgs, defaultModuleName: string) {

	if (isCloud()) {
		const data = {
			script: valOrUndefined(args.script),
			products: valOrUndefined(_.map(args.products, (p) => `${p.file.name}@${p.file.version}`)),
			board: args.boardId,
			device: {
				device: args.deviceId,
				part: args.partId,
				package: args.packageId,
			},
			defaultModuleName: valOrUndefined(defaultModuleName),
		};

		record("configuration", data);
	}
}

// map null (falsy) values to undefined, so it doesn't get logged saving DB space
function valOrUndefined<T>(val: T) {

	if (_.isArray(val)) {
		return _.isEmpty(val) ? undefined : val;
	}

	return val ? val : undefined;
}

function record(action: string, data = {}) {

	const toolVersion = getToolVersion();
	data = {
		app: "sysconfig",
		version: toolVersion,
		...data,
	};

	http.post(
		"/analytics", JSON.stringify({ action, data }), "application/json")
		.catch((e) => console.error(e)); // log and swallow;

}
