import * as _ from "lodash";
import { AMemberMgr, InstanceArgType } from "./member";
import { AObjectMgr } from "./object";
import { Member, InstanceArgs } from "public/defs";
import { RuntimeObject } from "public/runtime";
import { FormattersMap } from "../formatting/formattersMap";
import { SerializationOptions } from "../scripting/toScript";
import { ModuleInstanceMgr } from "./moduleInstance";
import { Validations } from "./validations";

export abstract class ObjectMemberManager<
	// Type of runtime object manager, that manages the runtime object which is the value of this member
	ValueManagerType extends AObjectMgr<ValueType>,
	// Type of the runtime object which is the value of this member
	ValueType extends RuntimeObject,
	// Object manager that for the parent runtime object
	ParentType extends AObjectMgr<RuntimeObject>,
	// Type of the the definition, which may be an extension of a basic member def
	DefinitionType extends Member = Member
	> extends AMemberMgr<ValueType, RuntimeObject, DefinitionType> {

	constructor(
		public valueObjectMgr: ValueManagerType,
		formattersMap: FormattersMap,
		def: DefinitionType,
		public override parentObjectMgr: ParentType,
		options: {
			internalReference?: boolean,
		} = {},
	) {
		super(parentObjectMgr, formattersMap, def, valueObjectMgr?.managedObject, options.internalReference);
	}

	public override getUIHash(_validations: Validations): string {
		// super.getUIHash() is based around converting this.value into a string.  But for object managers, this.value
		// is an object.  As such, every object manager has to override what AMemberMgr returns.  To ensure that we 
		// don't miss one, return undefined by default.  undefined means "always update"

		// Also, we aren't likely to see 10s of object members, other than pins.  As such, optimizing each one is 
		// likely not worth it (and PinMemberManager has an override that works)

		return undefined;
	}

	public override validate(validations: Validations, validateChild = true) {
		super.validate(validations);
		if (validateChild) {
			this.valueObjectMgr.validate(validations);
		}
	}

	public setValueFromRequiredArgs(args: InstanceArgs, origin: ModuleInstanceMgr): void {
		this.valueObjectMgr.setValueFromRequiredArgs(args, origin);
	}

	public setValueFromArgs(args: InstanceArgs, argType: InstanceArgType): void {
		this.valueObjectMgr.setValueFromArgs(args, argType);
	}

	public removeArgs(args: InstanceArgs) {
		this.valueObjectMgr.removeArgs(args);
	}

	public removeReqArgs(args: InstanceArgs, origin: ModuleInstanceMgr) {
		this.valueObjectMgr.removeReqArgs(args, origin);
	}

	public generateScriptStatements(parentIdentifier: string, options: SerializationOptions) {
		return this.valueObjectMgr.getScriptStatements(this.createScriptIdentifier(parentIdentifier), options);
	}

	public override isUserModified() {
		return this.valueObjectMgr.isUserModified();
	}

	public override remove() {
		super.remove();
		this.valueObjectMgr.remove();
		this.postRemove();
	}

	// allow child classes to clean up after the member has been removed
	protected postRemove() { }

	protected override shouldSerialize() {
		return true;
	}
}
