import { MultiPartTextConfigurable, TextType } from "public/defs";
import { RuntimeObject } from "public/runtime";
import { FormattersMap } from "../../formatting/formattersMap";
import { InputFormatter, IPv4InputFormatter, MACInputFormatter } from "../../formatting/inputFormatter";
import { AObjectMgr } from "../object";
import { Validations } from "../validations";
import { ConfigurableMgr } from "./configurableMgr";

export class MultiPartTextConfigurableMgr extends ConfigurableMgr<string>  {

	public textFormatter: InputFormatter;
	private textType: TextType;
	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObject>,
		formattersMap: FormattersMap,
		public override readonly def: MultiPartTextConfigurable,
	) {
		super(parentObjectMgr, formattersMap, def);
		this.textType = def.textType.toLowerCase() as TextType;
		if (this.textType === "ipv4_address") {
			this.textFormatter = new IPv4InputFormatter();
		} else if (this.textType === "mac_address_48" || this.textType === "mac_address") {
			this.textFormatter = new MACInputFormatter(48);
		} else if (this.textType === "mac_address_64") {
			this.textFormatter = new MACInputFormatter(64);
		} else {
			throw new Error("Invalid text type");
		}
	}

	public override validate(validations: Validations) {
		super.validate(validations);
		if (!this.textFormatter.noPartIsEmpty(this.value)) {
			validations.logError("Should specify all parts.", this);
		}
	}

	protected override onSet(newVal: string) {
		if (!this.textFormatter.verifyEntireString(newVal)) {
			throw new Error(`"${newVal}" is not a valid ${this.textFormatter.formatName}`);
		}
	}
}
