import * as React from "react";
import * as _ from "lodash";
import { CodeGenTemplateFile } from "dataInterfaces";
import { BaseFileList } from "../../FileList";
import { GeneratedFilesViewMgr } from "../../../services/ui/outputView";
import { IGlobalServiceProps } from "../../IGlobalServicesProps";
import { ITemplateActions } from "../../actions/ITemplateActions";
import { FilePreview } from "../FilePreview";
import { IOutputActions } from "../../actions/IOutputActions";
import { UserPreference } from "../../../services/userPreferences";
import { ResourceLoader } from "../../../services/resources/metaContentLoaders/resourceLoader";
import { IUserPreferenceActions } from "../../actions/IUserPreferenceActions";
import { PointInHistoryLabel } from "../../../services/changeHistory";
import { unstable_IdlePriority, unstable_scheduleCallback } from "scheduler";
import { assertNeverThrows } from "../../../services/utils";

interface IProps {
	actions: ITemplateActions & IOutputActions & IUserPreferenceActions;
	mgr: GeneratedFilesViewMgr;
	userPreference: UserPreference;
	resourceLoader: ResourceLoader;
	currentHistoryPoint: PointInHistoryLabel;
}

class GenerationError extends Error { }
type GenerationOutput = string | GenerationError;

interface IState {
	filesThatChanged: Set<string>,
	prevGenerations: Record<string, GenerationOutput>;
}

export class GeneratedFileView extends React.Component<IProps & IGlobalServiceProps, IState> {
	public override state = {
		filesThatChanged: new Set<string>(),
		prevGenerations: {} as Record<string, GenerationOutput>,
	}
	public override render() {
		const fileToPreview = this.props.mgr.getPreviewFile();
		return this.props.mgr.getPreviewFileStatus() ?
			<FilePreview
				{...this.props}
				toggleFilePreview={() => this.props.actions.closePreview(this.props.mgr)}
				file={fileToPreview}
				getCode={() => this.props.actions.generateCode(fileToPreview)}
				getPreviousCode={() => this.props.actions.generateLastChangeCode(fileToPreview)}
				userPref={this.props.userPreference}
			/> :
			<BaseFileList<CodeGenTemplateFile>
				id="generated"
				files={this.props.mgr.getTemplates()}
				hasErrors={this.props.mgr.hasErrors()}
				onFileOpen={this.onFileOpen}
				actions={this.props.actions}
				showGenerateOption={true}
				showSaveIcons={this.props.mgr.showSaveIcons()}
				modalService={this.props.modalService}
				errorStore={this.props.errorStore}
				filesThatChanged={this.state.filesThatChanged}
			/>;
	}

	public override componentDidMount() {
		assertNeverThrows(this.props.errorStore, async () => this.indicateFilesChanged(this.props.currentHistoryPoint));
	}

	public override componentDidUpdate(prevProps: Readonly<IProps & IGlobalServiceProps>) {
		if (!_.isEqual(this.props.currentHistoryPoint, prevProps.currentHistoryPoint)) {
			assertNeverThrows(this.props.errorStore,
				async () => this.indicateFilesChanged(this.props.currentHistoryPoint, prevProps.currentHistoryPoint));
		}
	}

	private onFileOpen = (file: CodeGenTemplateFile) => {
		this.props.actions.showPreview(this.props.mgr, file);
	}

	private async indicateFilesChanged(currHistoryPoint: PointInHistoryLabel, prevHistoryPoint?: PointInHistoryLabel) {
		// it's possible the current history may update while we are still in this function
		// throughout this method compare currentKey to props and if they differ end the execution
		const currentKey = currHistoryPoint.key;
		const filesThatChanged = new Set<string>();
		const templates = this.props.mgr.getTemplates();
		let prevGenerations: Record<string, GenerationOutput> = {};
		const currentGenerations: Record<string, GenerationOutput> = {};

		// Generate all current instances of file
		for (const file of templates) {
			if (currentKey !== this.props.currentHistoryPoint.key) return;
			currentGenerations[file.name] = await this.getCurrentGeneration(file);
		}

		// If we just started sysconfig then we don't want to try to generate old code or do any compares 
		// Because generateLastChangeCode will always reject
		if (currentKey === 0) {
			this.setState({ prevGenerations: currentGenerations });
			return;
		}

		// if the histories are not the most recent apart regenerate all prev histories
		// if prevHistory is undefined, this method is called from componentDidMount and regenerate anyways
		if (!prevHistoryPoint || currentKey - 1 !== prevHistoryPoint.key) {
			for (const file of templates) {
				if (currentKey !== this.props.currentHistoryPoint.key) return;
				prevGenerations[file.name] = await this.getPrevGeneration(file);
			}
		} else {
			prevGenerations = this.state.prevGenerations;
		}

		for (const file of templates) {
			if (currentKey !== this.props.currentHistoryPoint.key) return;
			if (!_.isEqual(currentGenerations[file.name], prevGenerations[file.name]) &&
				!this.fileHasException(prevGenerations[file.name], currentGenerations[file.name])) {
				filesThatChanged.add(file.name);
			}
		}
		this.setState({ filesThatChanged: filesThatChanged, prevGenerations: currentGenerations });
	}

	private async getPrevGeneration(template: CodeGenTemplateFile) {
		return doWhenIdle(() => this.props.actions.generateLastChangeCode(template).catch((err) => new GenerationError(err)));
	}

	private async getCurrentGeneration(template: CodeGenTemplateFile) {
		return doWhenIdle(() => this.props.actions.generateCode(template).catch((err) => new GenerationError(err)));
	}

	// If the file from before/after has exception, don't indicate a change
	private fileHasException(prev: GenerationOutput, current: GenerationOutput) {
		if (current instanceof GenerationError || prev instanceof GenerationError) {
			return true;
		}
		return false;
	}

}

function doWhenIdle<T>(func: () => Promise<T>): Promise<T> {
	return new Promise<T>((resolve, reject) => {
		unstable_scheduleCallback(unstable_IdlePriority, () => {
			func().then(resolve, reject);
		});
	});
}
