import React = require("react");
import { Checkbox as MUICheckBox } from "../imports/material-ui-imports";
import { CheckboxBlankOutline, CheckboxMarked } from "../imports/mdi-material-ui-imports";
import { commonStyles } from "./styles/common";
import { defaultTheme, defaultFontSize } from "./styles/themes";

interface ICheckBoxProps {
	id: string;
	onChange: (value: boolean) => void;
	value: boolean;
	disabled?: boolean;
	alignInput?: boolean;
}

// aligns checkboxes with other input fields
const alignInputStyle: React.CSSProperties = {
	right: defaultTheme.theme.spacing(1),
	padding: defaultTheme.theme.spacing(1),
};

const defaultInputStyle = {
	padding: defaultTheme.theme.spacing(1),
	marginBottom: "2px",
	height: defaultFontSize,
} as const;

export const defaultCheckBoxHeight = defaultInputStyle.padding + defaultInputStyle.height;

export class CheckBox extends React.PureComponent<ICheckBoxProps, {}> {

	public override render() {
		// span wrapping with id is needed to keep tests functioning.
		return (
			<span>
				<MUICheckBox
					inputProps={{ id: this.props.id }}
					checked={this.props.value}
					onChange={(_e, checked) => {
						this.props.onChange(checked);
					}}
					disabled={this.props.disabled}
					style={this.props.alignInput ? alignInputStyle : defaultInputStyle}
					color="primary"
					icon={<CheckboxBlankOutline style={commonStyles.smallIcon} />}
					checkedIcon={<CheckboxMarked style={commonStyles.smallIcon} />}
				/>
			</span>
		);
	}
}
