import * as _ from "lodash";
import { Runtime } from "../../resources/runtime";
import { ModuleInstanceMgr } from "../moduleInstance";
import { SetSource, AnyMemberMgr } from "../member";
import { DynamicReqFunction, validateReqs, FunctionToType } from "../moduleValidation";
import { extendException } from "../../niceExceptions";
import { guardCallbackAccess } from "../../moduleAccessGuard";

type ReqType<FunctionName extends DynamicReqFunction> = FunctionToType<FunctionName> & { name: string };

// Base class for managing requirements
export abstract class Requirements<FunctionName extends DynamicReqFunction> {

	protected currentRequirements: ReqType<FunctionName>[] = [];
	constructor(
		protected readonly runtime: Runtime,
		protected readonly instanceMgr: ModuleInstanceMgr) {
	}

	public resolveRequirements(cause?: AnyMemberMgr, reason?: SetSource) {
		const inst = this.instanceMgr.managedObject;
		const func = inst.$module[this.getFunctionName()];
		if (func) {
			this.newRequirements(
				guardCallbackAccess(() =>
					func(inst),
					this.getFunctionName(),
					this.instanceMgr,
					this.instanceMgr.getModuleName(),
				),
				cause,
				reason,
			);
		}
	}

	public getCurrentRequirements() {
		return this.currentRequirements;
	}

	protected abstract adaptReqs(reqs: FunctionToType<FunctionName>[]): ReqType<FunctionName>[];

	protected abstract categorizeReqs(
		reqs: ReqType<FunctionName>[],
		cause?: AnyMemberMgr,
	): {
		newReqs: ReqType<FunctionName>[],
		updateReqs?: ReqType<FunctionName>[],
		removedReqs: ReqType<FunctionName>[],
	};

	protected abstract resolve(
		newReqs: ReqType<FunctionName>[], updateReqs?: ReqType<FunctionName>[], reason?: SetSource): void;

	protected abstract getFunctionName(): FunctionName;

	private newRequirements(
		reqs: FunctionToType<FunctionName>[],
		cause?: AnyMemberMgr,
		reason?: SetSource,
	) {

		try {
			validateReqs(reqs, this.getFunctionName(), this.runtime.getDeviceData().gpio.isOptimizable);
			const adaptedReqs = this.adaptReqs(reqs);

			const { newReqs, updateReqs, removedReqs } = this.categorizeReqs(adaptedReqs, cause);
			_.each(removedReqs, (req) => this.instanceMgr.removeMember(this.instanceMgr.memberMgrs[req.name]));
			this.resolve(newReqs, updateReqs, reason);

			this.currentRequirements = adaptedReqs;
		} catch (e) {
			extendException(
				`while processing ${this.getFunctionName()}() of ${this.instanceMgr.managedObject.$module.$name}`, e);
		}
	}
}
