import React = require("react");
import { List } from "../../imports/material-ui-imports";
import { DirectoryItem, FileExplorerDirectoryItem } from "./DirectoryItem";
import { FileItem, FileExplorerFileItem } from "./FileItem";
import * as _ from "lodash";
import { ICommonProps, FileStatusType } from "./common";
import { IStorageFile } from "../../services/storage";

interface IFileNodeProps extends ICommonProps {
	fileTree: IStorageFile;
	level: number;
	disabled: boolean;
	style: "fileExplorer" | "cloudBrowser";
	onFileDelete?: (file: IStorageFile) => void;
	onFileDownload?: (file: IStorageFile) => void;
	onFileUpload?: (folder: IStorageFile, event: React.ChangeEvent<HTMLInputElement>) => void;
	onFileSelect: (file: IStorageFile) => void;
	onFolderSelect?: (file: IStorageFile) => void;
	onFolderExpand?: (folder: IStorageFile, open: boolean) => void;
	fileHasStatus?: (file: IStorageFile) => FileStatusType;
	getSize: (file: IStorageFile) => number;
}

// Individual node that represent one file. Which includes it and its children
export class FileNode extends React.Component<IFileNodeProps, { open: boolean }> {
	public constructor(props: IFileNodeProps) {
		super(props);
		this.state = { open: props.fileTree.expanded };
	}
	public override render(): JSX.Element {
		const DirectoryComponent = this.props.style === "fileExplorer" ? FileExplorerDirectoryItem : DirectoryItem;
		const FileComponent = this.props.style === "fileExplorer" ? FileExplorerFileItem : FileItem;
		const onClick = () => {
			if (this.props.onFolderExpand) {
				this.props.onFolderExpand(this.props.fileTree, !this.state.open);
			}
			this.setState({ open: !this.state.open });
		};
		return (
			<List disablePadding>
				<DirectoryComponent
					{...this.props}
					disabled={false}
					directory={this.props.fileTree}
					expanded={this.state.open}
					onToggleExpansion={onClick}
					status={this.props.fileHasStatus ? this.props.fileHasStatus(this.props.fileTree) : undefined}
				/>
				{this.state.open &&
					<List disablePadding>
						{_.chain(this.props.fileTree.children)
							.sortBy((child) => child.isDirectory ? "a" + child.name : "b" + child.name)
							.map((child, index) => {
								const key = index.toString();
								const level = this.props.level + 1;
								return (child.isDirectory ?
									(<FileNode
										{...this.props}
										key={key}
										fileTree={child}
										level={level}
									/>)
									: (!this.props.pickDir &&
										<FileComponent
											{...this.props}
											disabled={false}
											key={key}
											level={level}
											file={child}
											status={this.props.fileHasStatus ? this.props.fileHasStatus(child) : undefined}
										/>));
							})
							.value()}
					</List>
				}
			</List>
		);
	}
}
