import React = require("react");
import * as _ from "lodash";
import { Solution } from "../../solver/requirements";
import { DropDown } from "../../../components/DropDown";
import { SelectionSupplementary } from "../../../components/SelectionSupplementary";
import { IFormatter } from "../../formatting/formattingTypes";
import { ILinkActions } from "../../../components/actions/ILinkActions";
import { OverrideMgr, AllowConflictsMgr } from "../assignMembers";
import { InterfaceInstance, Pin } from "public/runtime";
import { Const, decorateAny } from "../../utils";
import { CValidation } from "./validation";
import { Validations } from "../validations";

interface IProps {
	wrapperId: string;
	wrapperClass: string;
	onChange: (value: string) => void;
	title?: string;
	selectedOptionName: string;
	disabled: boolean;
	solution: Solution;
	formatter: IFormatter;
	validations: Validations;
	actions: ILinkActions;
	assignMgr: OverrideMgr<InterfaceInstance | Pin>;
	conflictMgr: AllowConflictsMgr<InterfaceInstance | Pin>;
}

export class CAssign extends React.PureComponent<IProps, { isHover: boolean }> {
	constructor(props: IProps) {
		super(props);
		this.state = { isHover: false };
	}

	public override render() {
		const { enabledOptions, disabledOptions } = this.props.assignMgr.getUIOptions();
		const solutionDisplayName = this.props.solution.assignedToName ?
			_.find([...enabledOptions, ...disabledOptions],
				(o) => o.name === this.props.solution.assignedToName).displayName : "";
		const anyOption = {
			name: Const.ANY,
			displayName: decorateAny(solutionDisplayName),
		};
		return (
			<span
				id={this.props.wrapperId}
				className={this.props.wrapperClass}
				onMouseEnter={this.onMouseEnter}
				onMouseLeave={this.onMouseLeave}
			>
				<DropDown
					{...this.props}
					enabledOptions={[anyOption, ...enabledOptions]}
					disabledOptions={disabledOptions}
					id={this.props.wrapperId + "Select"}
					withIcon={true}
					displayScriptName={false}
				/>
				<SelectionSupplementary
					solution={this.props.solution}
					selectedValue={this.props.selectedOptionName}
					formatter={this.props.formatter}
					onChange={this.props.onChange}
					isHover={this.state.isHover}
					actions={this.props.actions}
					memberName={this.props.wrapperId}
				/>
				<CValidation
					validations={this.props.validations}
					validatableObj={this.props.assignMgr}
					formatter={this.props.formatter}
					actions={this.props.actions}
					memberName={this.props.assignMgr.def.name}
				/>
				<CValidation
					validations={this.props.validations}
					validatableObj={this.props.conflictMgr}
					formatter={this.props.formatter}
					actions={this.props.actions}
					memberName={this.props.conflictMgr.def.name}
				/>
			</span>
		);
	}

	private onMouseEnter = () => this.setState({ isHover: true });
	private onMouseLeave = () => this.setState({ isHover: false });
}
