import * as _ from "lodash";
import { MultiValueDynamicEnumerationConfigurable } from "public/defs";
import { ModuleInstance } from "public/runtime";
import { FormattersMap } from "../../formatting/formattersMap";
import { AObjectMgr } from "../object";
import { isNumberEnumerationConfigurable, toDropDownOptions, validateDisabledOptions } from "./baseEnumerationConfigurableMgr";
import { BaseMultiValueEnumerationConfigurableMgr } from "./baseMultiValueEnumerationConfigurableMgr";
import { getOptionsForDynamicEnum } from "./dynamicEnumerationConfigurableMgr";

export class MultiValueDynamicEnumerationConfigurableMgr<
	T extends number | string = string>
	extends BaseMultiValueEnumerationConfigurableMgr<T, ModuleInstance> {
	public override readonly def: MultiValueDynamicEnumerationConfigurable<T>;
	constructor(
		parentObjectMgr: AObjectMgr<ModuleInstance>,
		formattersMap: FormattersMap,
		def: MultiValueDynamicEnumerationConfigurable<T>,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			def,
		);

		// validate default
		try {
			this.validateValue(this.def.default);
		} catch (e) {
			throw new Error(`Can't set default: ${e.message}`);
		}
		// freeze the init value
		this.onSet(this.value);
	}

	public override getUIOptions() {
		const { enabledOptions, disabledOptions } = this.getOptions();
		const displayFormat = isNumberEnumerationConfigurable(this.def) ? this.def.displayFormat : null;
		return {
			disabledOptions: toDropDownOptions(disabledOptions, displayFormat),
			enabledOptions: toDropDownOptions(enabledOptions, displayFormat),
		};
	}

	public getOptions() {
		const inst = this.getParentRuntimeObj();
		const disabledOptions = this.def.getDisabledOptions ?
			this.def.getDisabledOptions(inst) : [];
		const selectedOptions = this.getValue();
		const optionsByName = this.getOptionsByName();
		validateDisabledOptions(disabledOptions, this.def.name, (o) => {
			if (!optionsByName[o.name]) {
				throw new Error(`${this.def.name}: attempted to disable unknown option '${o.name}'`);
			}
		});
		return getOptionsForDynamicEnum(
			inst,
			this.def.options,
			this.def.name,
			disabledOptions,
			selectedOptions);
	}

	public override getUIHash(): string {
		return undefined;
	}

	protected getCurrentOptions() {
		const inst = this.getParentRuntimeObj();
		return this.def.options(inst);
	}

	protected transform(newVal: T[]) {
		return _.sortBy(newVal);
	}

	protected getOptionsByName() {
		const inst = this.getParentRuntimeObj();
		const currentOptions = this.def.options(inst);
		return _.keyBy(currentOptions, (o) => o.name);
	}

	protected override validateValue(newVal: T[]) {

		if (!_.isArray(newVal)) {
			this.typeMismatch("array", typeof newVal);
		}
	}

	protected getSelectedOptions() {
		return (_.isEmpty(this.value) ? "" : "Selected: \n") +
			_.chain(this.getOptions().enabledOptions)
				.filter((option) => _.includes(this.get(), option.name))
				.map((o) => o.displayName ?? o.name.toString())
				.join("\n")
				.value() || "";
	}
}

