import * as _ from "lodash";
import * as DeviceData from "dataInterfaces";
import { EnumerationConfigurableMgr } from "./configurables/enumerationConfigurableMgr";
import { InterfaceInstanceMgr } from "./interfaceInstance";
import { EnumerationConfigurable, EnumerationOption } from "public/defs";
import { InterfaceInstance } from "public/runtime";
import { FormattersMap } from "../formatting/formattersMap";

const memberName: keyof InterfaceInstance = "$useCase";

function createDef(
	ifaceData: DeviceData.Interface, defaultUseCaseName: string): EnumerationConfigurable {

	const options: EnumerationOption[] = _.map(ifaceData.useCases, (u) => {
		return {
			name: u.name,
			displayName: u.description,
		};
	});

	return {
		name: memberName,
		displayName: "Use Case",
		default: defaultUseCaseName,
		options,
	};
}

export class UseCaseMgr extends EnumerationConfigurableMgr {
	constructor(
		public override parentObjectMgr: InterfaceInstanceMgr,
		formattersMap: FormattersMap,
		interfaceData: DeviceData.Interface,
		defaultUseCaseName: string) {
		super(
			parentObjectMgr, formattersMap, createDef(interfaceData, defaultUseCaseName),
		);
	}
}
