import * as React from "react";
import * as _ from "lodash";
import { IContextActions, UIContextSelection, UIContext } from "./actions/IContextActions";
import {
	Tabs,
	Tab,
	Divider,

	// Note that we are using the MUI tooltip, and not our own wrapper.  We do 
	// this because our wrapper adds a <span> over top of the child in order to
	// work with disabled and internal components, and also so that the 
	// onChange of Tabs gets a callback.  Ideally, we need to fix our wrapper 
	// so it can be used	
	Tooltip,
} from "../imports/material-ui-imports";
import { CloseCircle, Alert } from "../imports/mdi-material-ui-imports";
import { commonStyles } from "./styles/common";
import { tiStatusColor } from "./styles/colors";
import { assertUnreachable } from "../services/utils";
import { generateToolTipProps } from "./Tooltip";
import { ValidationSummary } from "../services/objectManagers/validations";

interface IProps {
	contextSelection: UIContextSelection;
	actions: IContextActions;
}

export class ContextSelector extends React.PureComponent<IProps> {

	public override render() {
		const numContexts = _.size(this.props.contextSelection.contexts);
		if (numContexts === 1) {
			return null;
		}
		const minWidth = `${100 / numContexts}%`;
		return (
			<React.Fragment>
				<Tabs
					value={this.props.contextSelection.selectedIndex}
					onChange={this.onChange}
					indicatorColor={"primary"}
				>
					{_.map(this.props.contextSelection.contexts, (context) =>
						<Tooltip
							{...generateToolTipProps(context.description)}
							key={context.name}
						>
							<Tab
								label={this.getLabel(context)}
								id={"contextSelector" + context.name}
								style={{ minWidth }} />
						</Tooltip>
					)}
				</Tabs>
				<Divider />
			</React.Fragment>
		);
	}

	private onChange = (_event: React.ChangeEvent<{}>, index: number) => {
		this.props.actions.setSelectedContext(index);
	}

	private getLabel(context: UIContext) {
		if (context.problemType === ValidationSummary.None) {
			return context.name;
		}
		return <span>
			{this.getBadge(context)}
			{context.name}
		</span>;
	}

	private getBadge(context: UIContext) {
		switch (context.problemType) {
			case ValidationSummary.Error:
				return <CloseCircle id={context.name + "Error"}
					style={{ ...commonStyles.smallIcon, color: tiStatusColor.error, verticalAlign: "top" }} />;
			case ValidationSummary.Warning:
				return <Alert id={context.name + "Warning"}
					style={{ ...commonStyles.smallIcon, color: tiStatusColor.warning, verticalAlign: "top" }} />;
			default:
				assertUnreachable(context.problemType);
			case ValidationSummary.None:
				return null;
		}
	}
}
