import React = require("react");
import * as _ from "lodash";
import { Tree } from "./Tree";
import { ConfigStoreActions } from "../services/configStore";
import { Tab } from "../services/tabs";
import { commonStyles } from "./styles/common";
import { TextField, InputAdornment, IconButton } from "../imports/material-ui-imports";
import { FilterVariant, ChevronDoubleLeft, Close } from "../imports/mdi-material-ui-imports";
import { ResizableBorder } from "./ResizableBorder";
import { IconMenu } from "./IconMenu";
import { Tooltip } from "./Tooltip";
import { IBasicInputProps } from "./InputBox";
import { debounceInput } from "./higherOrderComponents/DebounceInput";
import { filterInput } from "./higherOrderComponents/FilterInput";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { ATheme, ColorIndex, defaultFontSize, spacingUnit } from "./styles/themes";
import { filterPeripherals } from "../services/toolTip";
import { Validations } from "../services/objectManagers/validations";

interface IProps {
	actions: ConfigStoreActions;
	tabs: Tab[];
	searchText: string;
	selectedTab: Tab;
	col1Width: number;
	col1Displayed: boolean;
	theme: ATheme;
	validations: Validations;
	displayScriptName: boolean;
}

export class Col1 extends React.Component<IProps & IGlobalServiceProps> {
	public override render() {
		const { actions, searchText, selectedTab } = this.props;

		return (
			<div id="col1">
				<div style={commonStyles.rowFlexLayout}>
					<IconMenu
						{...this.props} />
					<ResizableBorder
						theme={this.props.theme}
						showBorder
						borderAfterChild={true}
						position={this.props.col1Width}
						displayed={this.props.col1Displayed}
						onPositionChanged={this.updateWidth}
						horizontal={true}
						backgroundColor={this.props.theme.colors[ColorIndex.ALTBACKGROUNDCOLOR]}
					>
						<div style={commonStyles.columnFlexLayout} id="navTree">
							<DebouncedTreeFilterInput
								id={"peripheralFilterInput"}
								actions={this.props.actions}
								onChange={(val) => this.props.actions.setSearchText(val)}
								filter={(val) => /^[a-zA-Z0-9,\s]*$/.test(val)}
								value={this.props.searchText}
								disabled={false}
								theme={this.props.theme}
							/>
							<div style={{ flex: 1, overflowY: "auto", overflowX: "hidden" }}>
								<div id="viewInterfaces">
									<Tree
										theme={this.props.theme}
										treeNodes={selectedTab.getNodes()}
										actions={actions}
										searchText={searchText}
										selectedTreeNode={selectedTab.getSelectedNode()}
										validations={this.props.validations}
										displayScriptName={this.props.displayScriptName}
									/>
								</div>
							</div>
						</div>
					</ResizableBorder>
				</div>
			</div>
		);
	}

	private updateWidth = (width: number) => {
		this.props.actions.setCol1Width(width);
	}
}

interface ITreeFilterInput extends IBasicInputProps {
	actions: ConfigStoreActions;
	theme: ATheme;
}

class TreeFilterInput extends React.Component<ITreeFilterInput> {
	public override render() {
		return (
			<TextField
				id={this.props.id}
				placeholder="Type Filter Text..."
				onChange={(e) => this.props.onChange(e.target.value)}
				value={this.props.value}
				fullWidth
				inputProps={{
					style: {
						height: defaultFontSize * 2 + spacingUnit - 3,
						padding: spacingUnit,
					},
				}}
				InputProps={{
					startAdornment: (
						<Tooltip title={filterPeripherals} placement={"bottom-start"}>
							<InputAdornment position="start" style={{ paddingLeft: spacingUnit * 2 }}>
								<FilterVariant color="primary" style={{ ...commonStyles.smallIcon, color: "#777" }} />
							</InputAdornment>
						</Tooltip>
					),
					endAdornment: (
						<InputAdornment position="end" style={{ paddingRight: 6, marginLeft: 2 }}>
							<Tooltip title="Clear filter" key="clearFilter">
								<IconButton
									id="clearFilterButton"
									onClick={() => this.props.onChange("")}
								>
									<Close color="primary" style={commonStyles.smallIcon} />
								</IconButton>
							</Tooltip>
							<Tooltip title="Hide column" key="hideIcon">
								<IconButton
									id="hideTreeButton"
									onClick={() => this.props.actions.setCol1Display(false)}
								>
									<ChevronDoubleLeft color="primary" style={commonStyles.smallIcon} />
								</IconButton>
							</Tooltip>
						</InputAdornment>
					),
				}}
			/>
		);
	}
}

const DebouncedTreeFilterInput = debounceInput(filterInput(TreeFilterInput));
