// Args after being read in from an argv array
export interface ParsedArg<T> {
	value: T; // argument value
	userArgName: string; // argument name supplied by user
}

type ParsedArgType<T extends OptionLongName> = ArgTypes[T] extends Array<any> ? ParsedArg<ArgTypes[T][0]>[] : ParsedArg<ArgTypes[T]>

type ParsedScriptArgs<T = ParsedArgType<"script">> = {
	[key in keyof ScriptArgTypes]?: ParsedArgType<key>;
} & { script?: T };

type GlobalParsedKeys = Exclude<keyof GlobalArgTypes, "script">;

export type ParsedArgs<T = ParsedArgType<"script">> =
	{
		[key in GlobalParsedKeys]?: ParsedArgType<key>
	} & {
		script?: ParsedScriptArgs<T>[];
	};

export interface Script {
	path: string;
	contents: string;
}

interface ResolvedScriptArgs {
	script?: Script;
	output?: string;
	context: string;
	argsForScript: string[];
	dependentScripts: Script[];
}

// Validated and properly formatted args
export interface ResolvedArgs {
	theme: ThemeType;
	script: ResolvedScriptArgs[]
	treatWarningsAsErrors: boolean;
	products: Product[];
	boardId?: string;
	deviceId: string;
	partId: string;
	packageId: string;
	loadSOCMetaData: boolean;
	listGeneratedFiles: boolean;
	listReferencedFiles: boolean;
	compiler: CompilerType;
	ccxxImageMode: boolean;
	showAllContexts: boolean;
	ipcf: string;
	showSaveIcons: boolean;
	rtos: string;
	quiet: boolean;
}

export class ArgsError extends Error {
	constructor(error: string | Error) {
		super(error instanceof Error ? error.message : error);
		if (error instanceof Error) {
			this.stack = error.stack;
		}
	}
}

export class InvalidArgError extends ArgsError {
	constructor(msg: string | Error, decorator: string) {
		super(msg);
		this.message = `${decorator}: ${this.message}`;
	}
}

export class MissingArgsError extends ArgsError {
	constructor(message: string) {
		super(message);
	}
}

export class SetupError extends Error {
	constructor(msg: string, decorator: string) {
		super(msg);
		this.message = `${decorator}: ${this.message}`;
	}
}
