import { isWin } from "../platform";
import { ResourceLoader, ResourceType } from "../resources/metaContentLoaders/resourceLoader";
import { TemplateFile } from "dataInterfaces";
import { allowPathVisibility } from "../pathsVisibility";

type TemplateFunctionType = (args?: any[]) => string;
export function runTemplate(
	templateFunc: TemplateFunctionType,
): string;
export function runTemplate(
	templateFile: TemplateFile,
	resourceLoader: ResourceLoader,
	args: any[],
): string;
export function runTemplate(
	templateFileOrTemplateFunc: TemplateFile | TemplateFunctionType,
	resourceLoader?: ResourceLoader,
	args?: any[],
) {

	// Load and execute the template
	const templateFunc: TemplateFunctionType = resourceLoader ?
		resourceLoader.getResource(
			(templateFileOrTemplateFunc as TemplateFile).path,
			ResourceType.TEMPLATE,
		)
		: templateFileOrTemplateFunc;

	let text = allowPathVisibility(() => templateFunc(args));

	// Convert everything to unix style line endings

	text = text.replace(/\r\n/g, "\n");

	// On windows only, convert it to windows-style.  
	// We can't just do this from the start as we don't want to 
	// replace \r\n with \r\r\n

	if (isWin()) {
		text = text.replace(/\n/g, "\r\n");
	}

	return text;
}
