import * as _ from "lodash";
import * as path from "path";

import { isNode, isEclipse } from "./platform";
import { fsUtils } from "./fsutil";

export function openExternalLink(link: string) {
	if (isNode()) {
		try {
			const opn = require("opn");
			if (_.includes(link, "file:")) {
				const fs = require("fs");
				const tempHTMLPath = path.join(fsUtils.getAppDataDir(), "temp.html");
				const redirectHTML = `<html><head><meta http-equiv="refresh" content="0;url=${link}"/></head></html>`;
				fs.writeFileSync(tempHTMLPath, redirectHTML);
				opn(tempHTMLPath);
			} else {
				opn(link);
			}
		} catch (e) {
			// swallow
		}
	} else if (isEclipse()) {
		eclipseOpenBrowser(link);
	} else {
		window.open(link, "_blank");
	}
}
