import * as React from "react";
import * as _ from "lodash";
import { ExtendedElkNode } from "../layout/customTypes";
import { ClassesType } from "../styling/clockTreeStyles";
import { INodeProps, NodeComponent } from "./NodeFactory";

// Renders just the node that is currently selected.  This is just rendered on top of the other node, and differs only 
// in that selected is passed to NodeComponent

interface IProps extends Omit<INodeProps, "node"> {
	nodes: ExtendedElkNode[];
}

export function NodeSelectionIndicator(props: IProps & ClassesType) {
	const { nodes, treeNode } = props;
	const selection = treeNode.getSelection().instanceId;
	return <>
		{
			_.chain(nodes)
				.filter((n) => n.data.ipInstance.name === selection)
				.map((node) => <NodeComponent {...props} node={node} selected={true} key={node.id} />)
				.value()
		}
	</>;
}
