import * as React from "react";
import * as _ from "lodash";
import { ClockTreeNode } from "../../../services/instanceContainers/clockTreeNode";
import { ClassesType } from "../styling/clockTreeStyles";
import { PinFrequencyConfigurableMgr } from "../../../services/objectManagers/configurables/pinFrequencyConfigurableMgr";
import { ExtendedElkNode } from "../layout/customTypes";
import { MainLabel } from "./NodeLabels";
import { PositionedNode } from "./PositionedNode";
import { defaultFontSize } from "../../styles/themes";

// A square box with the current frequency displayed inside

interface IProps {
	treeNode: ClockTreeNode;
	node: ExtendedElkNode;
	onSelect: (selection: string) => void;
	displayScriptName: boolean;
}

const FrequencyLabelNodeImpl = React.memo(
	({ node, onSelect, displayScriptName, classes, frequency }: IProps & ClassesType & { frequency: string }) => {
		const fontSize = getFontSize(node, frequency);
		return (
			<PositionedNode
				node={node}
				onSelect={onSelect}
				className={classes.frequencyLabelNode}
			>
				<MainLabel node={node} displayScriptName={displayScriptName} classes={classes} />
				<div className={classes.centralText} style={{ fontSize }}>
					{frequency}
				</div>
			</PositionedNode>
		);
	});

export function FrequencyLabelNode(props: IProps & ClassesType) {
	return <FrequencyLabelNodeImpl {...props} frequency={getFrequency(props.node, props.treeNode)} />;
}

function getFrequency(node: ExtendedElkNode, treeNode: ClockTreeNode) {
	const { ipInstance } = node.data;
	const instMgr = treeNode.getIpInstanceMgr(ipInstance.name);
	const pinToRead = _.first(ipInstance.inPins) ?? _.first(ipInstance.outPins);
	return (instMgr.memberMgrs[pinToRead.name] as PinFrequencyConfigurableMgr).getValueAsString();
}

function getFontSize(node: ExtendedElkNode, text: string) {
	const width = node.width;
	const textLength = text.length;

	// 1.5 is a scaling factor that seems to work (to compare box width against font size)

	const size = Math.min(defaultFontSize, width / textLength * 1.5);
	return `${size}px`;
}
