import * as React from "react";
import * as _ from "lodash";
import { ConfigStoreActions } from "../../../services/configStore";
import { ExtendedElkNode } from "../layout/customTypes";
import { NodeLabels } from "./NodeLabels";
import { PositionedNode } from "./PositionedNode";
import { ClassesType, svgStrokeWidth } from "../styling/clockTreeStyles";
import { ClockTreeNode } from "../../../services/instanceContainers/clockTreeNode";

// A mux node (trapezoid), drawn using svg inside a positioned div

interface IProps {
	node: ExtendedElkNode;
	onSelect: (selection: string) => void;
	treeNode: ClockTreeNode;
	actions: ConfigStoreActions;
	displayScriptName: boolean;
}

class MuxNodeImpl extends React.PureComponent<IProps & ClassesType & { selectedInput: string }> {
	public override render() {
		const { node, onSelect, displayScriptName, selectedInput, classes } = this.props;

		const lineAdjustment = svgStrokeWidth / 2;
		const slopeOffset = node.width / 3;
		const topLeft = `${0 + lineAdjustment},${0 + lineAdjustment}`;
		const bottomLeft = `${0 + lineAdjustment},${node.height - lineAdjustment}`;
		const bottomRight = `${node.width - lineAdjustment},${(node.height - slopeOffset) - lineAdjustment}`;
		const topRight = `${node.width - lineAdjustment},${slopeOffset + lineAdjustment}`;
		return (
			<PositionedNode
				node={node}
				onSelect={onSelect}
				className={classes.positionedDiv}
			>
				<NodeLabels
					key="labels"
					node={node}
					checked={selectedInput}
					onChecked={this.onSelectedInputChanged}
					displayScriptName={displayScriptName}
					classes={classes}
				/>
				<svg className={classes.svgNodeContainer}>
					<polygon
						points={`${topLeft} ${bottomLeft} ${bottomRight} ${topRight}`}
						className={classes.svgNode}
					/>
				</svg>
			</PositionedNode>
		);
	}

	private onSelectedInputChanged = (selectedInput: string) => {

		// Change the selection and then set the configurable.  The selection change ensures that the history remains 
		// correct

		const { actions, onSelect, treeNode, node } = this.props;
		const ipInstance = node.data.ipInstance;
		onSelect(ipInstance.name);
		const inst = treeNode.getIpInstanceMgr(ipInstance.name);
		actions.setConfigurableValue(inst.memberMgrs.inputSelect, selectedInput);
	}
}

export function MuxNode(props: IProps & ClassesType) {
	const { node, treeNode } = props;
	const ipInstance = node.data.ipInstance;
	const selectedInput: string = treeNode.getIpInstanceMgr(ipInstance.name).memberMgrs.inputSelect.getValue();
	return <MuxNodeImpl {...props} selectedInput={selectedInput} />;
}
