import React = require("react");
import { Button } from "../../imports/material-ui-imports";
import { IButtonProps } from "./IButtonProps";
import { commonStyles } from "../styles/common";

export class ModalButton extends React.Component<IButtonProps> {
	public override render() {
		return (
			<Button
				color="primary"
				id={this.props.id}
				onClick={this.props.onClick}
				style={this.props.disabled ? commonStyles.disabledButtonStyle : commonStyles.buttonStyle}
				disabled={this.props.disabled}
			>
				{this.props.children}
			</Button>
		);
	}
}
