import * as React from "react";
import * as _ from "lodash";
import { ExtendedElkNode } from "../layout/customTypes";
import { NodeLabels } from "./NodeLabels";
import { PositionedNode } from "./PositionedNode";
import { ClassesType, svgStrokeWidth } from "../styling/clockTreeStyles";

// An oscillator node, a circle with a sine-wave symbol inside.  Drawn using svg inside a positioned div

interface IProps {
	node: ExtendedElkNode;
	onSelect: (selection: string) => void;
	displayScriptName: boolean;
}

export const OscillatorNode = React.memo(({ node, onSelect, displayScriptName, classes }: IProps & ClassesType) => {
	const radius = node.height / 2;
	return (
		<PositionedNode
			node={node}
			onSelect={onSelect}
			className={classes.positionedDiv}
		>
			<NodeLabels
				key="labels"
				node={node}
				displayScriptName={displayScriptName}
				// Two nodes means they will not be centered on the circle, so we pad to avoid overlap with the circle's edge
				extraPadding={_.size(node.ports) === 2 ? 2 : 0}
				classes={classes}
			/>
			<svg className={classes.svgNodeContainer}>
				<circle
					cx={radius}
					cy={radius}

					// The line is drawn at the radius, so half inside/half outside.
					// To hit the edge, we need to subtract half of the line so the other half of that width hits the true edge

					r={radius - svgStrokeWidth / 2}
					className={classes.svgNode}
				/>

				<polyline
					points={squareWave(node.height)}
					className={classes.line}
				/>
			</svg>
		</PositionedNode>
	);
});

function squareWave(size: number) {
	const min = size * .3;
	const max = size * .7;
	const mid = size / 2;
	return `${min},${mid} ${min},${min} ${mid},${min} ${mid},${max} ${max},${max} ${max} ${mid}`;
}
