import * as _ from "lodash";

import { ITreeNode } from "../components/TreeNode";
import { ModuleMgr } from "./instanceContainers/module";
import { InterfaceMgr } from "./instanceContainers/interface";
import { HardwareComponentMgr } from "./instanceContainers/hardwareComponent";
import { Runtime } from "./resources/runtime";
import { FormatStyle } from "./formatting/formattingTypes";
import { FormattersMap } from "./formatting/formattersMap";
import { FormattedMsg } from "./formatting/link";
import { ModuleInstanceMgr } from "./objectManagers/moduleInstance";

// This is a helper class related to a modules preview related functionality.

class PreviewImpl {

	public constructor(private readonly runtime: Runtime) { }

	// determine if an instance should be shown in preview mode or not
	public showInstancePreview(treeNode: ITreeNode) {
		if (treeNode instanceof ModuleMgr) {
			return !treeNode.isStaticOnly() && _.isEmpty(treeNode.instances);
		} else if (treeNode instanceof InterfaceMgr) {
			return _.isEmpty(treeNode.instances);
		} else if (treeNode instanceof HardwareComponentMgr) {
			return false;
		} else {
			throw Error(`Unknown ITreeNode ${treeNode.getDisplayName(false)}`);
		}
	}

	// determine if the static of tree node should be shown in preview or not
	public showStaticPreview(treeNode: ITreeNode) {
		if (treeNode instanceof ModuleMgr) {
			return !treeNode.static;
		} else {
			throw Error(`Unknown ITreeNode ${treeNode.getDisplayName(false)}`);
		}
	}

	public getPreviewModuleMgr(mod: ModuleMgr) {

		this.runtime.reset();

		const previewModMgr = this.runtime.getModuleMgr(mod.module.$name);

		let inst: ModuleInstanceMgr = previewModMgr.addStatic();

		if (!previewModMgr.isStaticOnly()) {
			inst = previewModMgr.addInstance();
		}
		inst.applyUIDefaults();

		return previewModMgr;
	}

	public getPreviewInterfaceMgr(ifaceMgr: InterfaceMgr) {
		const previewIfaceMgr = this.runtime.getInterfaceMgr(ifaceMgr.iface.name);
		if (_.isEmpty(previewIfaceMgr.instances)) {
			previewIfaceMgr.addInstance();
		}

		return previewIfaceMgr;
	}

	public getFormatter() {
		return this.runtime.getMessageFormatter({ style: FormatStyle.UI });
	}
}

// The formatter is only used for creating links for navigation in errors, pin view, etc.  As such,
// we don't really need that feature to display a preview.  Since there is a lot of registration/
// un-registration necessary, and we would need to blow it away on each preview, we're creating a 
// dummy one that does nothing

class PreviewFormattersMap implements FormattersMap {

	public set() {
		return 0;
	}

	public delete() {
	}

	public getEncodingTag() {
		return "";
	}

	public getFormatter() {
		return () => new FormattedMsg();
	}

	public verifySize() {
		return 0;
	}

	public clear() {
	}
}

export interface Preview extends PreviewImpl { }

const previewMap = new WeakMap<Runtime, Preview>();
export function getPreview(runtime: Runtime) {
	if (!previewMap.has(runtime)) {
		previewMap.set(runtime, new PreviewImpl(runtime.cloneForPreview(new PreviewFormattersMap())));
	}
	return previewMap.get(runtime);
}
