import * as _ from "lodash";
import React = require("react");
import { List, ListItem, ListItemIcon, Typography } from "../../../imports/material-ui-imports";
import {
	Bell,
	BellOff,
	Power,
	Plus,
	Minus,
	Pencil,
	CheckboxBlankOutline,
	Lock,
	Resize,
	OpenInNew,
	Wrench,
	TextBoxRemoveOutline,
	TextBoxCheckOutline,
} from "../../../imports/mdi-material-ui-imports";
import { commonStyles, withCommonStyles, CommonClasses } from "../../styles/common";
import { HistoryViewMgr } from "../../../services/ui/outputView";
import { HistoryPointDesc } from "../../../services/changeHistory";

interface IProps {
	mgr: HistoryViewMgr;
}

const divStyle = {
	maxHeight: 320,
};

const listStyle = {
	margin: "0 5px 5px 5px",
};

const textStyle: React.CSSProperties = {
	color: "#999",
};

// returns the history list in reverse order (latest at the top)
function StyledHistoryView(props: IProps & CommonClasses) {
	const items = props.mgr.getHistoryUIItems();
	const history = props.mgr.getHistory();
	return (
		<div style={divStyle}>
			<List dense style={listStyle}>
				{_.map(items, (item) => {
					const { marker, index, selected, title, key } = item;
					return <ListItem
						id="history-entry"
						dense
						button
						onClick={() => history.setCurrentPoint(index)}
						key={key}
						className={selected ? props.classes.selectedList : props.classes.unSelectedList}
					>
						<ListItemIcon style={{ ...commonStyles.smallIcon, ...textStyle }}>
							<HistoryIcon text={title} />
						</ListItemIcon>
						<Typography variant="body2" style={{ flexGrow: 1 }}>{title}</Typography>
						<Typography variant="body2" className="history-marker" style={textStyle}>
							{marker}
						</Typography>
					</ListItem>;
				})
				}
			</List>
		</ div>
	);
}

export const HistoryView = withCommonStyles(StyledHistoryView);

function HistoryIcon({ text }: { text: HistoryPointDesc }) {
	if (text === "Initial state") {
		return <Power color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Add") || _.startsWith(text, "Reserved")) {
		return <Plus color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Remove")) {
		return <Minus color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Change")) {
		return <Pencil color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Locked")) {
		return <Lock color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Switch")) {
		return <Resize color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Ignore")) {
		return <BellOff color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Don't ignore")) {
		return <Bell color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Clicked")) {
		return <OpenInNew color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Cleared error")) {
		return <Wrench color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Suppressed")) {
		return <BellOff color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Un-suppressed")) {
		return <Bell color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Excluded")) {
		return <TextBoxRemoveOutline color="primary" style={commonStyles.smallIcon} />;
	} else if (_.startsWith(text, "Included")) {
		return <TextBoxCheckOutline color="primary" style={commonStyles.smallIcon} />;
	}
	// unknown action type (display a blank box)
	// We should be able to make this assertNeverOccurs once we upgrade to typescript 4.5
	return <CheckboxBlankOutline color="primary" style={commonStyles.smallIcon} />;
}
