type TreeNodeType = ModuleMgr | InterfaceMgr | FileModuleMgr;

interface IProps<T extends TreeNodeType = TreeNodeType> extends IGlobalServiceProps {
	actions: ConfigStoreActions;
	showPreferredVoltage: boolean;
	selectedTreeNode: T;
	arePowerDomainSettingsEnabled: boolean;
	formatter: IFormatter;
	validations: Validations;
	displayScriptName: boolean;
	devicePinDisplayType: PinDisplayType[];
	headerPinDisplayType: PinDisplayType[];
	resourceLoader: ResourceLoader;
	focusedSubItemPath: string[];
	preview: Preview;
	showUsed: boolean;
	showPinTable: boolean;
}

export class Requirements extends React.Component<IProps> {
	public override render() {
		const selectedTreeNode = this.props.selectedTreeNode;
		if (selectedTreeNode instanceof InterfaceMgr) {
			return (
				<CInterfaceMgr {...this.props} selectedTreeNode={selectedTreeNode} />
			);
		} else if (selectedTreeNode instanceof FileModuleMgr || selectedTreeNode instanceof ModuleMgr) {

			// additional calculated props for the modules views

			const moduleMgr = this.props.selectedTreeNode as FileModuleMgr | ModuleMgr;
			const isInstancePreview = this.props.preview.showInstancePreview(moduleMgr);
			const isStaticPreview = this.props.preview.showStaticPreview(moduleMgr);

			// getPreviewModuleMgr() creates a new instance every time, so only call if necessary

			const previewModuleMgr = (isInstancePreview || isStaticPreview)
				? this.props.preview.getPreviewModuleMgr(moduleMgr) : null;
			const instMgr = isInstancePreview ? previewModuleMgr.instances[0] : moduleMgr.getSelectedMyListItem();
			const staticInstMgr = isStaticPreview ? previewModuleMgr.static : moduleMgr.static;
			const showLongDescription
				= shouldShowLongDescription(moduleMgr, isInstancePreview && isStaticPreview);

			const additionalProps
				= { isInstancePreview, isStaticPreview, moduleMgr, instMgr, staticInstMgr, showLongDescription };

			const previewFormatter = this.props.preview.getFormatter();

			return (
				<CModuleMgr
					{...this.props}
					{...additionalProps}
					moduleMgr={selectedTreeNode}
					selectedTreeNode={selectedTreeNode}
					previewFormatter={previewFormatter}
				/>
			);

		} else {
			throw new Error("Can't render tree node");
		}
	}
}

class CModuleMgr extends React.Component<ModuleMgrProps<FileModuleMgr | ModuleMgr>, {}> {

	public override render() {

		const moduleMgr = this.props.selectedTreeNode;
		const addType = moduleMgr.getUIAdd();

		let view: JSX.Element;

		if (moduleMgr instanceof FileModuleMgr) {
			view = <CFileModuleMgr {...this.props} selectedTreeNode={moduleMgr} moduleMgr={moduleMgr} />;
		} else {
			switch (addType) {
				case "staticOnly":
					view = <CStaticOnly {...this.props} />;
					break;
				case "summary":
				case "instanceOnly":
					view = <CInstanceOnly {...this.props} />;
					break;
				case "staticAndInstance":
					view = <CStaticAndInstance {...this.props} />;
					break;
				default:
					assertUnreachable(addType);
			}
		}

		return (view);
	}

}

interface ModuleMgrProps<T extends ModuleMgr | FileModuleMgr> extends IProps<T> {
	moduleMgr: T;
	isInstancePreview: boolean;
	isStaticPreview: boolean;
	instMgr: ModuleInstanceMgr;
	staticInstMgr: StaticModuleInstanceMgr;
	showLongDescription: boolean;
	previewFormatter: IFormatter;
}

class CStaticOnly extends React.Component<ModuleMgrProps<ModuleMgr>, {}> {
	public override render() {

		const { isStaticPreview, moduleMgr, staticInstMgr, showLongDescription, displayScriptName } = this.props;

		const titleStatic = getModuleNameText(moduleMgr, displayScriptName);
		const formatter = isStaticPreview ? this.props.previewFormatter : this.props.formatter;

		return (
			<List style={layoutListStyle}>
				<LayoutListItem key="staticHeader">
					<StaticHeader {...this.props} title={titleStatic} />
				</LayoutListItem>
				{showLongDescription &&
					<LongDescription
						key="reqsDescription"
						id="module_documentation"
						closeDescription={() => this.props.actions.setShowUserLongDescPref(moduleMgr, false)}
						longDescription={moduleMgr.getLongDescription()}
						canonicalName={moduleMgr.getName()}
						resourceType={ResourceType.CODE}
						disableClose={isStaticPreview}
						resourceLoader={this.props.resourceLoader}
						formatter={formatter}
						actions={this.props.actions}
					/>
				}
				<LayoutListItem key="statics">
					<InstanceContainer isPreview={isStaticPreview} id="staticInstanceContainer">
						<CView
							{...this.props}
							instMgr={staticInstMgr}
							viewNodes={staticInstMgr.getStaticContainerViewNodes()}
							productLookupName={moduleMgr.getName()}
							readOnly={false}
							formatter={formatter}
						/>
					</InstanceContainer>
				</LayoutListItem>
			</List>
		);
	}
}

class CInstanceOnly extends React.Component<ModuleMgrProps<ModuleMgr>, {}> {

	public override render() {

		const {
			isInstancePreview, isStaticPreview, moduleMgr, instMgr, staticInstMgr, showLongDescription, displayScriptName }
			= this.props;

		const title = `${getModuleNameText(moduleMgr, displayScriptName)} ${getInstanceAllocationText(moduleMgr)}`;
		const isSummary = moduleMgr.getUIAdd() === "summary";
		const staticFormatter = isStaticPreview ? this.props.previewFormatter : this.props.formatter;
		const instanceFormatter = isInstancePreview ? this.props.previewFormatter : this.props.formatter;
		return (
			<List style={layoutListStyle}>
				{!staticInstMgr.getViewNodes()[0].isHidden() &&
					<React.Fragment>
						<LayoutListItem key="statics">
							<InstanceContainer isPreview={isStaticPreview} id="staticInstanceContainer">
								<CView
									{...this.props}
									instMgr={staticInstMgr}
									viewNodes={staticInstMgr.getViewNodes()}
									productLookupName={moduleMgr.getName()}
									readOnly={false}
									formatter={staticFormatter}
								/>
							</InstanceContainer>
						</LayoutListItem>
						<Divider key="headerDiv" />
					</React.Fragment>
				}
				<LayoutListItem key="instanceHeader">
					<InstanceHeader {...this.props} title={title} />
				</LayoutListItem>
				{showLongDescription &&
					<LongDescription
						key="reqsDescription"
						id="module_documentation"
						closeDescription={() => this.props.actions.setShowUserLongDescPref(moduleMgr, false)}
						longDescription={moduleMgr.getLongDescription()}
						canonicalName={moduleMgr.getName()}
						resourceType={ResourceType.CODE}
						disableClose={this.props.isInstancePreview}
						resourceLoader={this.props.resourceLoader}
						formatter={instanceFormatter}
						actions={this.props.actions}
					/>
				}
				<LayoutListItem key="requirementsList">
					<RequirementsList
						actions={this.props.actions}
						selectedTreeNode={this.props.selectedTreeNode}
						formatter={instanceFormatter}
						validations={this.props.validations}
						isRemovable={(item) => item.isRemovable()}
						getCannotRemoveReason={(item) => item.getOwnershipInfo()}
						getItemName={(item) => item.getName()}
						onSelect={(item) => this.props.actions.setSelectedMyListItem(this.props.selectedTreeNode, item)}
						onRemove={(item) => this.props.actions.removeInstance(item)}
						key="requirementList"
						instruction={isSummary ? <React.Fragment>{this.props.selectedTreeNode.getDisplayName(false)}
							will be appear when added elsewhere</React.Fragment>
							: undefined
						}
					/>
				</LayoutListItem>
				<Divider key="listOrInstDiv" />
				<LayoutListItem key="instance">
					<InstanceContainer isPreview={isInstancePreview} id="moduleInstanceContainer">
						<CModuleInstance
							{...this.props}
							instMgr={instMgr}
							productLookupName={moduleMgr.getName()}
							formatter={instanceFormatter}
						/>
					</InstanceContainer>
				</LayoutListItem>
			</List>
		);

	}
}

class CStaticAndInstance extends React.Component<ModuleMgrProps<ModuleMgr>, {}> {
	public override render() {

		const {
			isInstancePreview, isStaticPreview, moduleMgr, instMgr, staticInstMgr, showLongDescription, displayScriptName }
			= this.props;

		const titleStatic = getModuleNameText(moduleMgr, displayScriptName);
		const titleInstances = `Instances ${getInstanceAllocationText(moduleMgr)}`;
		const staticFormatter = isStaticPreview ? this.props.previewFormatter : this.props.formatter;
		const instanceFormatter = isInstancePreview ? this.props.previewFormatter : this.props.formatter;
		return (
			<List style={layoutListStyle} >

				<LayoutListItem key="staticHeder">
					<StaticHeader {...this.props} title={titleStatic} />
				</LayoutListItem>

				{showLongDescription &&
					<LongDescription
						key="reqsDescription"
						id="module_documentation"
						closeDescription={() => this.props.actions.setShowUserLongDescPref(moduleMgr, false)}
						longDescription={moduleMgr.getLongDescription()}
						canonicalName={moduleMgr.getName()}
						resourceType={ResourceType.CODE}
						disableClose={this.props.isStaticPreview}
						resourceLoader={this.props.resourceLoader}
						formatter={staticFormatter}
						actions={this.props.actions}
					/>
				}

				<LayoutListItem key="statics">
					<InstanceContainer isPreview={isStaticPreview} id="staticInstanceContainer">
						<CView
							{...this.props}
							instMgr={staticInstMgr}
							viewNodes={staticInstMgr.getViewNodes()}
							productLookupName={moduleMgr.getName()}
							readOnly={false}
							formatter={instanceFormatter}
						/>
					</InstanceContainer>
				</LayoutListItem>
				<Divider key="headerDiv" />
				<LayoutListItem key="instanceHeader">
					<InstanceHeader {...this.props} hideLongDescriptionButton={true} title={titleInstances} />
				</LayoutListItem>
				<LayoutListItem key="requirementsList">
					<RequirementsList
						actions={this.props.actions}
						selectedTreeNode={this.props.selectedTreeNode}
						formatter={instanceFormatter}
						validations={this.props.validations}
						isRemovable={(item) => item.isRemovable()}
						getCannotRemoveReason={(item) => item.getOwnershipInfo()}
						getItemName={(item) => item.getName()}
						onSelect={(item) => this.props.actions.setSelectedMyListItem(this.props.selectedTreeNode, item)}
						onRemove={(item) => this.props.actions.removeInstance(item)}
						key="requirementList"
					/>
				</LayoutListItem>
				<Divider key="listOrInstDiv" />
				<LayoutListItem key="instance">
					<InstanceContainer isPreview={isInstancePreview} id="moduleInstanceContainer">
						<CModuleInstance
							{...this.props}
							instMgr={instMgr}
							productLookupName={moduleMgr.getName()}
							formatter={instanceFormatter}
						/>
					</InstanceContainer>
				</LayoutListItem>
			</List >
		);

	}
}

class CFileModuleMgr extends React.Component<ModuleMgrProps<FileModuleMgr>, {}> {
	public override render() {

		const { isStaticPreview, moduleMgr, staticInstMgr, showLongDescription, displayScriptName } = this.props;

		const title = getModuleNameText(moduleMgr, displayScriptName);

		return (
			<List style={layoutListStyle}>
				<LayoutListItem key="header">
					<FileRequirementHeader
						{...this.props}
						moduleMgr={moduleMgr}
						title={title}
					/>
				</LayoutListItem>

				{showLongDescription &&
					<LongDescription
						key="reqsDescription"
						id="module_documentation"
						closeDescription={() => this.props.actions.setShowUserLongDescPref(moduleMgr, false)}
						longDescription={moduleMgr.getLongDescription()}
						canonicalName={moduleMgr.getName()}
						resourceType={ResourceType.CODE}
						disableClose={this.props.isStaticPreview}
						resourceLoader={this.props.resourceLoader}
						formatter={this.props.formatter}
						actions={this.props.actions}
					/>
				}

				<Divider key="headerDiv" />
				{!isStaticPreview && moduleMgr.getRequestedRootPath() &&
					<div style={requirementsListStyle}>
						<FileExplorer
							{...this.props}
							moduleMgr={moduleMgr}
						/>
					</div>
				}
				<Divider key="listOrInstDiv" />
				<LayoutListItem key="instance">
					<InstanceContainer isPreview={isStaticPreview} id="moduleInstance">
						<CModuleInstance
							{...this.props}
							instMgr={isStaticPreview ? staticInstMgr : moduleMgr.getSelectedMyListItem()}
							productLookupName={moduleMgr.getName()}
							formatter={isStaticPreview ? this.props.previewFormatter : this.props.formatter}
						/>
					</InstanceContainer>
				</LayoutListItem>
			</List>
		);
	}
}

class CInterfaceMgr extends React.Component<IProps<InterfaceMgr>, {}> {
	public override render() {

		const interfaceMgr = this.props.selectedTreeNode;
		const isPreview = this.props.preview.showInstancePreview(interfaceMgr);
		const previewInterfaceMgr = this.props.preview.getPreviewInterfaceMgr(interfaceMgr);
		const selectedMyListItem
			= isPreview ? previewInterfaceMgr.getSelectedMyListItem() : interfaceMgr.getSelectedMyListItem();

		let instMgr: InterfaceInstanceMgr;
		let gpioInstMgr: GPIOInterfaceInstanceMgr;

		if (selectedMyListItem instanceof GPIOInterfaceInstanceMgr) {
			gpioInstMgr = selectedMyListItem;
		} else {
			instMgr = selectedMyListItem;
		}

		const title = `${interfaceMgr.getName()} ${getInstanceAllocationText(interfaceMgr)}`;

		return (
			<List style={layoutListStyle}>
				<LayoutListItem key="header">
					<InterfacesHeader {...this.props} showLongDescription={false} title={title} />
				</LayoutListItem>
				<Divider key="headerDiv" />
				<RequirementsList
					actions={this.props.actions}
					selectedTreeNode={this.props.selectedTreeNode}
					formatter={this.props.formatter}
					validations={this.props.validations}
					isRemovable={(item) => item.isRemovable()}
					getCannotRemoveReason={() => undefined} // Interface reqs are never not removable
					getItemName={(item) => item.getName()}
					onSelect={(item) => this.props.actions.setSelectedMyListItem(this.props.selectedTreeNode, item)}
					onRemove={(item) => this.props.actions.removeInstance(item)}
					key="requirementList"
				/>
				<Divider key="listOrInstDiv" />
				<LayoutListItem key="instance">
					<InstanceContainer isPreview={isPreview} id="interfaceInstanceContainer">
						{instMgr &&
							<CInterfaceInstance
								{...this.props}
								instMgr={instMgr}
								productLookupName={this.props.selectedTreeNode.getName()}
							/>
						}
						{gpioInstMgr &&
							<Config
								{...this.props}
								req={gpioInstMgr}
								maxAllowed={this.props.selectedTreeNode.getMaxAllowed()}
								productLookupName={this.props.selectedTreeNode.getName()}
								focusedSubItemPath={this.props.focusedSubItemPath}
							/>
						}
					</InstanceContainer>
				</LayoutListItem>
			</List>
		);
	}
}

export class LayoutListItem extends React.Component<{}, {}> {
	public override render() {
		return (
			<ListItem style={{ paddingLeft: 0, paddingRight: 0 }}>
				{this.props.children}
			</ListItem>
		);
	}
}

export class InstanceContainer extends React.Component<{ isPreview: boolean, id: string }, {}> {
	public override render() {
		const currentInstanceItemStyle = this.props.isPreview ? previewInstanceItemStyle : instanceItemStyle;
		return (
			<span style={currentInstanceItemStyle} id={this.props.id} >
				{this.props.children}
			</span>
		);
	}
}

const instanceItemStyle: React.CSSProperties = {
	width: "100%",
};

const previewInstanceItemStyle: React.CSSProperties = {
	pointerEvents: "none",
	...instanceItemStyle,
	...commonStyles.disabled,
};

export const layoutListStyle: React.CSSProperties = {
	marginLeft: defaultTheme.theme.spacing(1),
	marginRight: defaultTheme.theme.spacing(1),
	paddingTop: 0,
};

function getInstanceAllocationText(cont: AInstanceContainer) {
	const count = _.size(cont.getInstances());
	const max = cont.getMaxAllowed();
	return (`(${count} ${isFinite(max) ? (" of " + max) : ""} Added)`);
}

function getModuleNameText(moduleMgr: ModuleMgr, displayScriptName: boolean) {
	return moduleMgr.getDisplayName(displayScriptName);
}
