import * as _ from "lodash";
import { ITreeNode } from "../../components/TreeNode";
import { SelectionInNode } from "../objectManagers/ui/selection";
import { RuntimeInstance } from "public/runtime";
import { Runtime } from "../resources/runtime";
import { Tab } from "../tabs";
import { getAlgorithm } from "../../components/clockTree/layout/filterInstances";
import { Validations, ValidationSummary } from "../objectManagers/validations";
import { TreeNodeStatus } from "./treeStatus";
import { TreeNodeStatusType } from "../treeNodeStatusType";
import { ButtonDisplay } from "../treeNodeButtonDisplay";
import { TreeEntry } from "public/defs";

export type GraphSettings = Pick<TreeEntry, "layout" | "frequencyLabels" | "brokenConnections">;

// A node in the left pane that represents a specific IP instance node in the clock tree

export class ClockTreeNode implements ITreeNode {

	private expanded = true;
	private selection: SelectionInNode;
	private readonly treeNodePath: string[];
	private readonly iconStatus: TreeNodeStatus;

	constructor(
		private readonly entry: TreeEntry,
		private readonly parentNode: ITreeNode,
		private readonly runtime: Runtime,
	) {
		this.treeNodePath = [...parentNode.getNodePath(), entry.displayName];

		// The selection will be the first selectable instance we can find, first searching what the entry names, but 
		// then trying all the instances in the graph

		const instancesInGraph = this.getInstancesInGraph();
		const defaultSelection = _.first(entry.ipInstances);
		this.selection = {
			instanceId: defaultSelection,
			memberPath: [],
		};
		this.runtime.registerClockTreeNode(this, instancesInGraph, entry.defaultFor);
		this.iconStatus = new TreeNodeStatus(TreeNodeStatusType.BADGE, "ipInstance" + defaultSelection + "Icon");
	}

	public getStaticConfiguration() {
		const staticConfig = this.runtime.getTopModules().getClockTreeStaticConfig();
		if (staticConfig) {
			return this.runtime.getModuleMgr(staticConfig).static;
		}
		return null;
	}

	public getUIHash(validations: Validations): string {
		return validations.getSummary(this).toString();
	}

	public getParentNode() {
		return this.parentNode;
	}

	public getParentTab(): Tab {
		return null;
	}

	public getIpInstanceMgr(name: string) {
		return this.runtime.getIpInstanceMgr(name);
	}

	public getClockTree() {
		return this.runtime.getClockTreeGraph();
	}

	public getInstancesInGraph() {
		return getAlgorithm(this.entry)(this.getClockTree().connectivity, this.entry.ipInstances);
	}

	public getInstances() {
		const instances = this.getInstancesInGraph();
		return _.map(instances, (i) => this.runtime.getIpInstanceMgr(i));
	}

	public getID() {
		return this.entry.displayName;
	}

	public getDisplayName() {
		return this.entry.displayName;
	}

	public getChildren(): ITreeNode[] {
		return [];
	}

	public isTitle() {
		return false;
	}

	public getTooltip() {
		return this.entry.description;
	}

	public getStatus(validations: Validations) {
		const summary = validations.getSummary(this);
		const error = summary === ValidationSummary.Error;
		const warning = summary === ValidationSummary.Warning;
		this.iconStatus.setStatus({
			error,
			warning,
			success: false,
		});
		return [this.iconStatus];
	}

	public isExpanded() {
		return false;
	}

	public toggleExpanded() {
		this.expanded = !this.expanded;
	}

	public isDisabled() {
		return false;
	}

	public showButton() {
		return ButtonDisplay.Remove;
	}

	public getSelectedMyListItem() {
		return this.runtime.getIpInstanceMgr(this.selection.instanceId);
	}

	public setShowUserLongDescPref(_status: boolean) {
	}

	public getAlwaysShowUserLongDesc() {
		return false;
	}

	public getSelection() {
		return this.selection;
	}

	public setSelection(selection: SelectionInNode) {
		_.each(this.getInstances(), (i) => i.viewedUsing(this));
		this.selection = selection;
	}

	public getNodePath() {
		return this.treeNodePath;
	}

	public getUsedPins() {
		return this.getSelectedMyListItem().getUsedPins();
	}

	public getRuntimeSelection(): RuntimeInstance {
		return this.getSelectedMyListItem().managedObject;
	}

	public getGraphSettings(): GraphSettings {
		return {
			layout: this.entry.layout ?? {},
			frequencyLabels: this.entry.frequencyLabels,
			brokenConnections: this.entry.brokenConnections,
		};
	}

	// for testing

	public getDefaultFor() {
		return this.entry.defaultFor;
	}
}
