import * as _ from "lodash";
import * as path from "path";
import React = require("react");
import {
	Typography, List, ListItem, Card, ListItemIcon, ListItemSecondaryAction, IconButton,
} from "../imports/material-ui-imports";
import { Delete, DeleteOutline } from "../imports/mdi-material-ui-imports";
import { constructRoute, configPage } from "../services/routing";
import { ModalService } from "../services/ui/modals";
import { IRecentProject } from "./StartPage";
import { RouteComponentProps } from "react-router";
import { commonStyles } from "./styles/common";
import { initSettings } from "../services/settings";
import { assertNeverThrows } from "../services/utils";
import { ErrorStore } from "../services/errorStore";
import { Tooltip } from "./Tooltip";
import { isCloud } from "../services/platform";

interface IProps {
	id: string;
	heading: string;
	modalService: ModalService;
	errorStore: ErrorStore;
	iconDecorator?: JSX.Element;
}

interface IState {
	recentProjects: IRecentProject[];
}

export class RecentDesign extends React.Component<IProps & RouteComponentProps<{}>, IState> {
	constructor(props: IProps & RouteComponentProps<{}>) {
		super(props);
		this.state = {
			recentProjects: [] as IRecentProject[],
		};
	}

	public override componentDidMount() {
		this.getLocalFileList().catch((e) => this.props.errorStore.registerException(e));
	}
	public override render() {
		const curExpandedStyle = commonStyles.expandedCardStyle;
		const cardBodyStyle = curExpandedStyle;
		return (
			<Card id={this.props.id} style={commonStyles.cardStyle}>
				<List style={{ ...commonStyles.headingStyle, minWidth: "0", display: "flex", flexDirection: "row" }} >
					<ListItem>
						<ListItemIcon>{this.props.iconDecorator}</ListItemIcon>
						<Typography variant="body2">{this.props.heading}</Typography>
					</ListItem>
					<ListItem style={{ justifyContent: "flex-end" }}>
						<Tooltip title={"Clear Recent Designs"} placement={"right"}>
							<IconButton style={{ display: "inline" }}
								onClick={() => {
									this.props.modalService.showConfirmModal(
										"Clear Recent Designs",
										"This project will be removed from recent designs. Are you sure?",
										() => assertNeverThrows(this.props.errorStore, async () => {
											const settings = await initSettings();
											await settings.clearRecentProjects();
											this.setState({ recentProjects: [] });
										}),
										() => { },
										"Yes",
										"No",
									);
								}}>
								<Delete color="primary" style={{ ...commonStyles.smallIcon }} />
							</IconButton>
						</Tooltip>
					</ListItem>
				</List>
				<div id={this.props.id + "Body"} style={cardBodyStyle}>
					<div style={{ margin: "0 20px 14px 20px", maxHeight: 200 }}>
						{
							_.isEmpty(this.state.recentProjects) &&
							<Typography variant="body2">No saved projects available</Typography>
						}
						{
							!_.isEmpty(this.state.recentProjects) &&
							<List style={{ textAlign: "left", padding: 0 }}>
								{
									_.map(this.state.recentProjects, (recentProject) => {
										return (
											<ListItem
												button
												id={recentProject.path}
												title={recentProject.path}
												key={recentProject.path}
												onClick={
													() =>
														this.props.history.push(constructRoute(
															configPage,
															[recentProject.path],
														))}
											>
												<Typography variant="body2">{recentProject.description}</Typography>
												<ListItemSecondaryAction>
													<Tooltip title={"Remove"} placement={"right"}>
														<IconButton style={{ display: "inline" }}
															onClick={() => {
																this.props.modalService.showConfirmModal(
																	"Remove project",
																	"Are you sure you want to remove this project from recent designs?",
																	() => assertNeverThrows(this.props.errorStore, async () => {
																		const settings = await initSettings();
																		await settings.removeProject(recentProject.path);
																		// eslint-disable-next-line max-len
																		this.getLocalFileList().catch((e) => this.props.errorStore.registerException(e));
																	}),
																	() => { },
																	"Yes",
																	"No",
																);
															}}>
															<DeleteOutline color="primary" style={{ ...commonStyles.smallIcon }} />
														</IconButton>
													</Tooltip>
												</ListItemSecondaryAction>
											</ListItem>
										);
									})
								}
							</List>
						}
					</div>
				</div>
			</Card >
		);
	}

	private async getLocalFileList() {
		const settings = await initSettings();
		const projectPaths = settings.getRecentProjects();
		const recentProjects = _.map(projectPaths, (projectPath) => {
			const fileName = path.basename(projectPath);
			// The pinmux tool kept a list of recently used designs but did not provide the 
			// full workspace path (IE it only saves the file name). SysConfig assumes the full path
			// is provided in this file so, although the list contains .pinmux projects they cannot be opened in sysconfig.
			const fileExtension = _.last(_.split(fileName, "."));
			if (isCloud() && !_.startsWith(projectPath, "/") && fileExtension === "pinmux") {
				projectPath = path.join("/", "pinmux", "default", fileName);
			}
			return {
				path: projectPath,
				description: fileName,
			};
		});
		this.setState({ recentProjects });
	}
}
