import React = require("react");
import { PinMgr } from "../pin";
import { CAssign } from "./assign";
import { IFormatter } from "../../formatting/formattingTypes";
import { ILinkActions } from "../../../components/actions/ILinkActions";
import { IConflictActions } from "../../../components/actions/IConflictActions";
import { Validations } from "../validations";

interface IDevicePinSelectionProps {
	pinRequirement: PinMgr;
	formatter: IFormatter;
	validations: Validations;
	onChange: (value: string) => void;
	actions: ILinkActions & IConflictActions;
}

export class DevicePinSelection extends React.Component<IDevicePinSelectionProps, {}> {
	public override render() {

		const assignMgr = this.props.pinRequirement.getOverrideMember();
		const conflictMgr = this.props.pinRequirement.getConflictMember();
		const solution = this.props.pinRequirement.getSolution();
		const selected = this.props.pinRequirement.getSelectedDevicePin();

		return (
			<CAssign
				wrapperId={"pinSelect" + this.props.pinRequirement.getName()}
				wrapperClass="pinSelect"
				title="Select output pin"
				disabled={false}
				selectedOptionName={selected}
				onChange={(val: string) => this.props.onChange(val)}
				solution={solution}
				formatter={this.props.formatter}
				validations={this.props.validations}
				actions={this.props.actions}
				assignMgr={assignMgr}
				conflictMgr={conflictMgr}
			/>
		);
	}
}
