import * as _ from "lodash";
import { Pin, RuntimeObject } from "public/runtime";
import { ModuleInstanceMgr } from "../objectManagers/moduleInstance";
import { AObjectMgr } from "../objectManagers/object";
import { ObjectMemberManager } from "../objectManagers/objectMember";
import { Runtime } from "../resources/runtime";
import { getDisplayName } from "../utils";

// migratingFromRuntime
const oldRuntimes = new Map<number, Runtime>();

function getOldRuntime(id: number) {
	return oldRuntimes.get(id);
}

export function insertOldRuntime(id: number, runtime: Runtime) {
	oldRuntimes.set(id, runtime);
}

export function clearOldRuntimes() {
	oldRuntimes.clear();
}

export function getOldModInstMgr(newModInstMgr: ModuleInstanceMgr) {
	if (!newModInstMgr) {
		return null;
	}
	const id = newModInstMgr.getContextId();
	const oldRuntime = getOldRuntime(id);
	if (oldRuntime) {
		return getModuleInstanceMgr(oldRuntime, newModInstMgr.getModName(), newModInstMgr.getName());
	}
	return null;
}

export function getOldDisplayName(path: string[], mgr: AObjectMgr<RuntimeObject>): string {
	const { modInstMgr, memberPath } = mgr.getContainingModule();

	const copyPath = [...memberPath, ...path];
	const oldModMgr = getOldModInstMgr(modInstMgr);
	let displayName;
	if (oldModMgr) {
		const memberMgr = getOldMemberMgr(oldModMgr, copyPath);
		displayName = memberMgr ? getDisplayName(memberMgr.def, false) : displayName;
	}

	return displayName;
}

function getModuleInstanceMgr(runtime: Runtime, modulePath: string, instName: string) {
	return _.find(runtime.getModuleMgr(modulePath).allInstancesIncludingStatic(), (inst) => inst.getName() === instName);
}

export function getOldMemberMgr(oldModMgr: ModuleInstanceMgr, path: string[]) {
	let objMgr: AObjectMgr<RuntimeObject> = oldModMgr;
	let memberMgr;
	while (!_.isEmpty(path)) {
		const memberName = path.shift();
		if (!_.includes(writablePinMembers, memberName)) {
			memberMgr = objMgr.memberMgrs[memberName];
			if (memberMgr instanceof ObjectMemberManager) {
				objMgr = memberMgr.valueObjectMgr;
			} else {
				break;
			}
		}
	}
	return memberMgr;
}

export function getOldIpInstance(name: string) {
	// Clocktree data is the same across all contexts, so we can simply look at any runtime

	const [runtime] = oldRuntimes.values();
	return runtime.getIpInstanceMgr(name);
}

const writablePinMembers: (keyof Pin)[] = ["$assign", "$suggestSolution", "$assignAllowConflicts"];
