import * as React from "react";
import * as _ from "lodash";
import { BasicModal } from "./modals/BasicModal";
import { CircularProgress } from "../imports/material-ui-imports";
import { assertNeverThrows } from "../services/utils";
import { ErrorStore } from "../services/errorStore";
import { ATheme } from "./styles/themes";

// Properties for the higher order component
interface IProps {
	id: string;
	title: string;
	errorStore: ErrorStore;
	onClick: (arg?: string) => Promise<void>;
	theme: ATheme;
}

interface IState {
	uiBlocked: boolean;
}

// Properties for the internal component that this higher order component wraps
interface IBlockingActionProps {
	onClick: (arg?: string) => void;
}

// This component is for rendering a button that renders a un-dismissible modal
// on click. It should be used to launch some tasks that should block any further 
// UI interaction before completion.
export function blockingProcessAction<T extends {}>(ActionComponent: React.ComponentClass<T & IBlockingActionProps>) {

	class BlockingProcessAction extends React.Component<T & IProps, IState> {
		public override state = { uiBlocked: false };

		public override render() {
			return (
				<React.Fragment>
					<ActionComponent
						{...this.props}
						onClick={this.performAction}
					/>
					{this.state.uiBlocked &&
						<BasicModal
							theme={this.props.theme}
							title={this.props.title}
							modalProps={{
								disableBackdropClick: true,
								disableEscapeKeyDown: true,
								open: this.state.uiBlocked,
								children: <div></div>,
							}}
							id={this.props.id + "_BlockingModal"}
							onClose={() => { }}
							registerSubModalMountPoint={null}
						>
							<div style={{ textAlign: "center" }}>
								<CircularProgress />
							</div>
						</BasicModal>
					}
				</React.Fragment>
			);
		}

		private asyncSetState(s: IState) {
			return new Promise<void>((resolve) => this.setState(s, resolve));
		}

		private performAction = (arg?: string) => {
			assertNeverThrows(this.props.errorStore, async () => {

				// Set uiBlocked state to true to cause us to render a progress spinner to block out the UI
				// However, we debounce this in case the asynchronous action is very quick.

				let promise: Promise<void> = null;
				const debounced = _.debounce(() => { promise = this.asyncSetState({ uiBlocked: true }); }, 250);
				debounced();

				// Perform the async action

				try {
					await this.props.onClick(arg);
				} finally {

					// Now, cancel the state set done above.  If the promise is not set, then the state was never 
					// changed, and we don't have to do anything.  If it is set, then we should wait on it and revert 
					// the state to be unblocked

					// Note: this needs to be in the finally block to ensure that outstanding promises/debounces are 
					// complete when under test so as to unblock the test task queue.

					debounced.cancel();
					if (promise) {
						await promise;
						await this.asyncSetState({ uiBlocked: false });
					}
				}
			});
		}
	}

	return BlockingProcessAction;
}
