import { ButtonConfigurable } from "public/defs";
import { ModuleInstance } from "public/runtime";
import { ModuleInstanceMgr } from "../moduleInstance";
import { Validations, ValidationSummary } from "../validations";
import { ConfigurableMgr } from "./configurableMgr";

export abstract class ButtonConfigurableMgr<
	ResultType, MemberDefinition extends ButtonConfigurable<ResultType> = ButtonConfigurable<ResultType>>
	extends ConfigurableMgr<string, ModuleInstance, MemberDefinition> {
	public override parentObjectMgr: ModuleInstanceMgr;
	private accessErrorMsg = `${this.def.name} has no value.  It is only to provide a button in the UI.`;

	public override get(): string {
		return undefined;
	}

	public override set() {
		throw Error(this.accessErrorMsg);
	}

	public override shouldSerialize() {
		return false;
	}

	public isDisabled(validations: Validations): string | boolean {
		if (this.uiState.readOnly) {
			return true;
		}
		const disabled = !this.def.ignoreErrors && validations.getOverallSummary() === ValidationSummary.Error;
		return disabled ? "Action unavailable when design errors exist" : false;
	}

	public override getUIHash(validations: Validations): string {
		if (this.isDisabled(validations)) {
			return undefined;
		}
		return super.getUIHash(validations);
	}

	// Do whatever the button was designed to do, and return the object to pass back into the callback functions

	public abstract getClickResult(productPath: string, filePath?: string): Promise<ResultType>;

	// Return the reason why getClickResult didn't return immediately.  This is used in the UI to show a reason for 
	// a progress spinner.

	public abstract getDelayReason(): string;
}
