import * as _ from "lodash";
import { Requirements } from "./requirements";
import { ModuleRequirement } from "public/defs";
import { ModuleMemberMgr } from "../moduleMemberMgrs/moduleMemberMgr";

export class ModuleRequirements extends Requirements<"modules"> {

	protected adaptReqs(reqs: ModuleRequirement[]) {
		// even though the modules don't need to provide a name
		// we still need it for our internal house keeping

		return _.map(reqs, (req) => ({ ...req, name: req.moduleName }));
	}

	protected categorizeReqs(
		reqs: ModuleRequirement[],
	) {
		const updatedOrNew = _.differenceWith(reqs, this.currentRequirements, _.isEqual);
		const removed = _.differenceWith(this.currentRequirements, reqs, _.isEqual);
		return { newReqs: updatedOrNew, removedReqs: removed };
	}

	protected resolve(reqs: ModuleRequirement[]) {
		_.each(
			reqs,
			(req) => {

				const mod = this.runtime.getModuleMgr(req.moduleName);

				if (!mod) {
					throw new Error(`No module ${req.moduleName} found`);
				}

				const staticInstanceMgr = mod.initStatic(false);
				staticInstanceMgr.addSharedBy(this.instanceMgr);

				return new ModuleMemberMgr(this.runtime, staticInstanceMgr, req, this.instanceMgr, true);
			},
		);
	}

	protected getFunctionName(): "modules" {
		return "modules";
	}
}
