import React = require("react");
import { Nav } from "./Nav";
import { Config } from "./Config";
import { ConfigStore } from "../services/configStore";
import { RouteComponentProps } from "react-router";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { isEclipse } from "../services/platform";
import { commonStyles } from "./styles/common";

interface IConfigPageProps {
	configStore: ConfigStore;
	showPreferredVoltage: boolean;
	deviceId: string;
	openSessionHandler: (sessionPath: string) => void;
	restartSessionHandler: () => void;
}

type IProps = IConfigPageProps & IGlobalServiceProps & RouteComponentProps<{}>;

export class ConfigPage extends React.Component<IProps> {

	public override componentDidMount() {
		const { configStore } = this.props;
		const navHistory = configStore.getNavHistory();
		window.onpopstate = (e: PopStateEvent) => navHistory.handleBrowserEvent(e);
		if (isEclipse()) {
			window.pinmuxRequestSave = () => {
				try {
					configStore.saveProject();
				} catch (e) {
					this.props.errorStore.registerException(e);
				}
			};
			window.pinmuxGetJSONToSave = window.pinmuxRequestSave;
		}
	}

	public override componentWillUnmount() {
		window.onpopstate = () => { };
		if (isEclipse()) {
			window.pinmuxRequestSave = () => { };
			window.pinmuxGetJSONToSave = window.pinmuxRequestSave;
		}
	}

	public override render() {
		return (
			<div style={commonStyles.columnFlexLayout}>
				{!isEclipse() &&
					<Nav
						{...this.props}
						actions={this.props.configStore}
						deviceName={this.props.deviceId}
					/>
				}
				<Config {...this.props} />
			</div>
		);
	}
}
