import * as _ from "lodash";
import { ConfigurableGroup, Member } from "public/defs";
import { RuntimeObject } from "public/runtime";

import { FormattersMap } from "../formatting/formattersMap";
import { getValidationKey } from "../utils";
import { ITreeNode } from "../../components/TreeNode";
import { Tab } from "../tabs";
import { Statement } from "../scripting/serialize";
import { ISummaryItem, mapValidation } from "../summaryItems";
import { InstanceMgr } from "../instanceContainers/instanceContainer";

// Something that can have validation messages associated with it or it's members

export interface IValidatableObject {
	managedObject: RuntimeObject;

	// Returns all InstanceMgrs for which a summary of issues on this object should be shown

	getContainingInstanceMgrs(): InstanceMgr[];

	// Returns all ITreeNodes for which a summary of issues on this object should be shown

	getContainingTreeNodes(): ITreeNode[];
}

// The member of a validatable object that can itself have validation messages associated with it

export interface IValidatableMember {
	parentObjectMgr: IValidatableObject;
	def: Member,
}

export type IValidatable = IValidatableObject | IValidatableMember;

export type ISummarizeable = Tab | ITreeNode | Validations | ConfigurableGroup | InstanceMgr;

// Note: these are in order such that Warning replaces None and Error replaces both.  That way, Math.max() can be used
// to return the correct combination of two summaries

export const enum ValidationSummary {
	None,
	Warning,
	Error,
}

export interface DetailedText {
	shortText: string;
	longTexts?: string[];
}

/**
 * Container for validation results.
 */
export interface Validation {
	/**
	 * Error messages.
	 */
	errors: Array<string | DetailedText>;

	/**
	 * Warning messages.
	 */
	warnings: Array<string | DetailedText>;

	/**
	 * Info messages.
	 */
	infos: Array<string | DetailedText>;

	/**
	 * Suppressed Warning messages
	 */
	suppressedWarnings: Array<string | DetailedText>;
}

export function toSummary(validation?: Validation) {
	if (validation) {
		if (!_.isEmpty(validation.errors)) {
			return ValidationSummary.Error;
		}
		if (!_.isEmpty(validation.warnings)) {
			return ValidationSummary.Warning;
		}
	}
	return ValidationSummary.None;
}

export class Validations {

	private readonly suppressions = new Map<IValidatable, string[]>();
	private validations = new Map<IValidatable, Validation>();
	private summaries = new Map<ISummarizeable, ValidationSummary>();

	// APIs to get validation or validation summary information

	public getValidation(obj: IValidatable) {
		return this.validations.get(obj);
	}

	public getOverallSummary() {
		return this.getSummary(this);
	}

	public getSummary(obj: ISummarizeable) {
		return this.summaries.get(obj) ?? ValidationSummary.None;
	}

	public getSummaryItems(formattersMap: FormattersMap, includeSuppressed?: boolean) {
		const items: ISummaryItem[] = [];
		this.validations.forEach((validation, obj) => {
			items.push(...mapValidation(validation, () => {
				if (isValidatableObject(obj)) {
					return formattersMap.getEncodingTag(obj.managedObject);
				} else {
					return formattersMap.getEncodingTag(obj.parentObjectMgr.managedObject, obj.def.name);
				}
			}, obj, includeSuppressed));
		});
		return items;
	}

	// APIs to log new validation messages

	public logError(message: string | DetailedText, obj: IValidatable) {
		const validation = this.getOrCreateValidation(obj);
		validation.errors.push(message);
		this.recordSummary(obj, ValidationSummary.Error);
	}

	public logWarning(message: string | DetailedText, obj: IValidatable) {
		const validation = this.getOrCreateValidation(obj);
		const suppressions = this.suppressions.get(obj);
		if (suppressions) {
			const key = getValidationKey(message).key;
			if (_.some(suppressions, (s) => new RegExp(s).test(key))) {
				validation.suppressedWarnings.push(message);
				return;
			}
		}
		validation.warnings.push(message);
		this.recordSummary(obj, ValidationSummary.Warning);
	}

	public logInfo(message: string, obj: IValidatable) {
		const validation = this.getOrCreateValidation(obj);
		validation.infos.push(message);
	}

	// APIs to suppress warning messages

	public suppress(key: string, obj: IValidatable) {
		const suppressions = this.suppressions.get(obj) ?? [];
		suppressions.push(key);
		this.suppressions.set(obj, suppressions);

		// We do not need to update the maps, as validate will run after a suppression changes
	}

	public unsuppress(key: string, obj: IValidatable) {
		const suppressions = this.suppressions.get(obj) ?? [];
		this.suppressions.set(obj, _.pull(suppressions, key));

		// We do not need to update the maps, as validate will run after a suppression changes
	}

	// APIs to control the validate cycle.  
	// At the beginning, we must clear all validation messages

	public reset() {
		this.validations.clear();
		this.summaries.clear();
	}

	// At the end of a validation cycle, we must clear suppression messages for warnings that have been resolved

	public clearUnusedSuppression() {
		this.suppressions.forEach((suppressions, validatableObj) => {
			const suppressedWarnings = this.validations.get(validatableObj)?.suppressedWarnings;
			const used = _.filter(suppressions, (matcher) => {
				const regex = new RegExp(matcher);
				return _.some(suppressedWarnings, (s) => regex.test(getValidationKey(s).key));
			});
			if (_.isEmpty(used)) {
				this.suppressions.delete(validatableObj);
			} else {
				this.suppressions.set(validatableObj, used);
			}
		});
	}

	// If UI elements change, this will re-summarize all existing errors outside of a validation cycle

	public reSummarize() {
		this.summaries.clear();
		this.validations.forEach((validation, obj) => {
			const summary = toSummary(validation);
			if (summary !== ValidationSummary.None) {
				this.recordSummary(obj, summary);
			}
		});
	}

	public getScriptStatements(): Statement[] {
		if (this.suppressions.size > 0) {
			// throw new Error("TODO");
		}
		return [];
	}

	private getOrCreateValidation(obj: IValidatable) {
		let validation = this.validations.get(obj);
		if (!validation) {
			validation = {
				errors: [],
				warnings: [],
				infos: [],
				suppressedWarnings: [],
			};
			this.validations.set(obj, validation);
		}
		return validation;
	}

	private recordSummary(obj: IValidatable, summary: ValidationSummary.Error | ValidationSummary.Warning) {
		const inst = isValidatableObject(obj) ? obj : obj.parentObjectMgr;

		// Record instance managers

		_.chain(inst.getContainingInstanceMgrs())
			.uniq()
			.each((i) => this.combineSummary(i, summary))
			.value();

		// Record tree nodes and tabs

		_.chain(inst.getContainingTreeNodes())
			.flatMap((treeNode) => [treeNode, ...getAllParents(treeNode)])
			.uniq()
			.each((treeNode) => this.combineSummary(treeNode, summary))
			.value();

		// Record context

		this.combineSummary(this, summary);
	}

	private combineSummary(obj: ISummarizeable, summary: ValidationSummary.Error | ValidationSummary.Warning) {

		// Error trumps warning, so if it's already an error, there's nothing we could update it to beyond that.

		if (ValidationSummary.Error !== this.summaries.get(obj)) {

			// However, if it's a warning or nothing, then updating it to anything is always fine:
			// nothing -> warning = warning
			// nothing -> error = error
			// warning -> warning = warning
			// warning -> error = error

			this.summaries.set(obj, summary);
		}
	}
}

export type InternalValidationLogger = Pick<Validations, "logError" | "logWarning" | "logInfo">;

function getAllParents(treeNode: ITreeNode): (ITreeNode | Tab)[] {
	const parent = treeNode.getParentNode();
	if (parent) {
		return [parent, ...getAllParents(parent)];
	} else {
		const parentTab = treeNode.getParentTab();
		if (parentTab) {
			return [parentTab];
		}
		return [];
	}
}

function isValidatableObject(obj: IValidatable): obj is IValidatableObject {
	return "managedObject" in obj;
}
