import Ajv, { ValidateFunction } from "ajv";
import ajvFormats from "ajv-formats";
import typeofKeyword from "ajv-keywords/dist/keywords/typeof";
import * as JSON5 from "json5";
import { SCHEMA, SCHEMAToType, schemata } from "./JSONschemata";
export { SCHEMA, SCHEMAToType } from "./JSONschemata";

const ajv = new Ajv({ allowUnionTypes: true });

typeofKeyword(ajv);
ajvFormats(ajv, { formats: ["date-time"] });

const validateFunctions: { [key: number]: ValidateFunction } = {};

export function validateJSONschema<T extends SCHEMA>(which: T, data: SCHEMAToType<T>) {
	let validate = validateFunctions[which];
	if (!validate) {
		validate = validateFunctions[which] = ajv.compile(schemata[which]);
	}
	if (validate(data)) {
		return null;
	}
	return JSON.stringify(validate.errors, null, 2);
}

// parse meta content JSON, provides type safety, stripping comments, error handling and validation.

export function parseMetaJSON<T extends SCHEMA>(content: string, filePath: string, schema: T) {

	const parsed: SCHEMAToType<T> = parseJSON(content, filePath);

	return validateMeta(parsed, filePath, schema);
}

function parseJSON(content: string, filePath: string) {
	try {
		return JSON5.parse(content);
	} catch (e) {
		e.message = `Unable to parse ${filePath}: ${e.message}`;
		throw e;
	}
}

// validate and cast meta content objects

export function validateMeta<T extends SCHEMA>(obj: any, context: string, schema: T): SCHEMAToType<T> {
	const errors = validateJSONschema(schema, obj as SCHEMAToType<T>);
	if (errors) {
		throw new Error(`${context}: Validation failed: ${errors}`);
	}

	return obj as SCHEMAToType<T>;
}
