import * as _ from "lodash";
import { http } from "./http";
import { getIdleInterval } from "./accountManagement";
import { isCloud } from "./platform";
import { SimpleEvent } from "./simpleEvent";
import * as portal from "portal";

// We are using socket.io-client ^0.9.16 which does not have a corresponding @types
// As a result, we directly import the submodule
// We do not close the socket b/c the socket gets closed whenever the page refreshes/closes

const socketConnect: (typeof portal.connect) = require("socket.io-client/dist/socket.io").connect;

class LoginServer {
	private event = new SimpleEvent<(status: boolean) => void>();
	private socket: portal.connect;
	private allowPings: boolean;
	private idleInterval: number;
	private pingInterval: NodeJS.Timer;

	constructor() {
		this.init().catch((e) => { console.error(e); });
	}

	public onLoginChanged() {
		return this.event.asRegistration();
	}

	public async init() {
		this.socket = new socketConnect(location.origin);
		this.idleInterval = await getIdleInterval();
		this.setPing();
		this.socket.on("login", () => {
			this.notify(true);
			location.reload();
		});

		this.socket.on("logout", () => {
			this.notify(false);
		});

		this.socket.on("preparelogout", () => {
			this.socket.emit("logoutready");
			return;
		});

		this.socket.on("asklogout", (data: portal.LogOutData) => {
			const iframe = document.getElementById("authIFrame") as HTMLIFrameElement;
			iframe.src = "/logout?reason=" + data.reason + "&redirect=/emptypage";
		});
	}

	public userEvent = () => {
		this.allowPings = true;
	}

	public async handleLogOut() {
		this.clearPing();
		await http.get("/logout?reason=click");
	}

	public handleLogIn() {
		window.location.href = "/login?redirect=" + window.location.toString();
	}

	private setPing() {
		this.pingInterval = setInterval(() => this.ping(), this.idleInterval);
	}

	private clearPing() {
		clearInterval(this.pingInterval);
	}

	private async ping() {
		try {
			if (this.allowPings) {
				this.allowPings = false;
				const app = "?app=sysconfig";
				await http.get("/timeouts/renewIdle" + app);
			}
		} catch (e) {
			console.error(e);
		}
	}

	private notify(status: boolean) {
		this.event.fire(status);
	}
}

export const loginServer = isCloud() ? new LoginServer() : null;
