import * as React from "react";
import * as _ from "lodash";
import { IconButton } from "../../../../imports/material-ui-imports";

// This is a workaround to allow having an IconButton within a ButtonGroup
// Taken from here: https://github.com/mui/material-ui/issues/17226#issuecomment-672980848

type IProps = React.ComponentProps<typeof IconButton>;
export function ButtonGroupIconButton(props: IProps) {
	// intercept props only implemented by `Button`
	return <IconButton {..._.omit(props, ["disableElevation", "fullWidth", "variant"])} style={iconStyle} />;
}

const iconStyle = {
	borderRadius: 0,
	minWidth: 20,
};
