import * as _ from "lodash";
// UI Views for meta content defined configurables

import * as React from "react";
import { IConfigurablesActions } from "../configurableActions";
import { IGlobalServiceProps } from "../../../../components/IGlobalServicesProps";
import { IFormatter } from "../../../formatting/formattingTypes";
import { HardwareMemberMgr } from "../../hardwareMember";
import { CHardware } from "./hardware";
import { ILinkActions } from "../../../../components/actions/ILinkActions";
import { assertUnreachable } from "../../../utils";
import { ResourceLoader } from "../../../resources/metaContentLoaders/resourceLoader";
import { CMultiValueDynamicEnumerationConfigurable } from "./multiValueDynamicEnumerationConfigurable";
import { CEnumerationConfigurable } from "./enumerationConfigurable";
import { CBooleanConfigurable } from "./booleanConfigurable";
import { CNumericConfigurable } from "./numericConfigurable";
import { CDynamicEnumerationConfigurable } from "./dynamicEnumerationConfigurable";
import { CLongTextConfigurable } from "./longTextConfigurable";
import { CFormattedTextConfigurable } from "./formattedTextConfigurable";
import { CFileConfigurable } from "./fileConfigurable";
import { CMultiValueEnumerationConfigurable } from "./multiValueEnumerationConfigurable";
import { CTextConfigurable } from "./textConfigurable";
import { CDateConfigurable } from "./dateConfigurable";
import { PinFrequencyConfigurable } from "./pinFrequencyConfigurable";
import { Validations } from "../../validations";
import { BooleanConfigurableMgr } from "../../configurables/booleanConfigurableMgr";
import { MetaContentConfigurableMgr } from "../../configurables/configurable";
import { DateConfigurableMgr } from "../../configurables/dateConfigurableMgr";
import { DynamicEnumerationConfigurableMgr } from "../../configurables/dynamicEnumerationConfigurableMgr";
import { EnumerationConfigurableMgr } from "../../configurables/enumerationConfigurableMgr";
import { FileTextConfigurableMgr } from "../../configurables/fileTextConfigurableMgr";
import { MultiPartTextConfigurableMgr } from "../../configurables/multiPartTextConfigurableMgr";
import { MultiValueDynamicEnumerationConfigurableMgr } from "../../configurables/multiValueDynamicEnumerationConfigurableMgr";
import { MultiValueEnumerationConfigurableMgr } from "../../configurables/multiValueEnumerationConfigurableMgr";
import { NumericConfigurableMgr } from "../../configurables/numericConfigurableMgr";
import { PinFrequencyConfigurableMgr } from "../../configurables/pinFrequencyConfigurableMgr";
import { TextConfigurableMgr } from "../../configurables/textConfigurableMgr";
import { ButtonConfigurableMgr } from "../../configurables/buttonConfigurableMgr";
import { CButtonConfigurable } from "./buttonConfigurable";

export interface IConfigurableProps extends IGlobalServiceProps {
	mgr: MetaContentConfigurableMgr | HardwareMemberMgr,
	actions: IConfigurablesActions & ILinkActions,
	formatter: IFormatter,
	resourceLoader: ResourceLoader,
	validations: Validations;
	displayScriptName: boolean;
}

// Wrapper component to delegate rendering a configurable to a particular component
export function CConfigurable(props: IConfigurableProps) {

	const { validations, displayScriptName, mgr, ...rest } = props;

	if (mgr instanceof HardwareMemberMgr) {
		return <CHardware {...rest} displayScriptName={displayScriptName} memberMgr={mgr} />;
	} else if (mgr instanceof DateConfigurableMgr) {
		return <CDateConfigurable {...rest} mgr={mgr} />;
	} else if (mgr instanceof EnumerationConfigurableMgr) {
		return <CEnumerationConfigurable {...rest} displayScriptName={displayScriptName} mgr={mgr} />;
	} else if (mgr instanceof BooleanConfigurableMgr) {
		return <CBooleanConfigurable {...rest} mgr={mgr} />;
	} else if (mgr instanceof NumericConfigurableMgr) {
		return <CNumericConfigurable {...rest} mgr={mgr} />;
	} else if (mgr instanceof MultiValueDynamicEnumerationConfigurableMgr) {
		return <CMultiValueDynamicEnumerationConfigurable {...rest} displayScriptName={displayScriptName} mgr={mgr} />;
	} else if (mgr instanceof DynamicEnumerationConfigurableMgr) {
		return <CDynamicEnumerationConfigurable {...rest} displayScriptName={displayScriptName} mgr={mgr} />;
	} else if (mgr instanceof TextConfigurableMgr) {
		if (mgr.def.multiline) {
			return <CLongTextConfigurable {...rest} mgr={mgr} />;
		}
		return <CTextConfigurable {...rest} mgr={mgr} />;
	} else if (mgr instanceof MultiPartTextConfigurableMgr) {
		return <CFormattedTextConfigurable {...rest} mgr={mgr} />;
	} else if (mgr instanceof FileTextConfigurableMgr) {
		return <CFileConfigurable {...rest} mgr={mgr} />;
	} else if (mgr instanceof MultiValueEnumerationConfigurableMgr) {
		return <CMultiValueEnumerationConfigurable {...rest} displayScriptName={displayScriptName} mgr={mgr} />;
	} else if (mgr instanceof ButtonConfigurableMgr) {
		return <CButtonConfigurable<unknown> {...rest} mgr={mgr} validations={validations} />;
	} else if (mgr instanceof PinFrequencyConfigurableMgr) {
		return <PinFrequencyConfigurable mgr={mgr} />;
	} else {
		assertUnreachable(mgr);
	}
}
