import * as React from "react";
import * as _ from "lodash";
import { withStyles } from "../../../imports/material-ui-imports";
import { ExtendedElkLine, ExtendedElkNode } from "../layout/customTypes";
import { ConfigStoreActions } from "../../../services/configStore";
import { ClassesType, clockTreeStyles } from "../styling/clockTreeStyles";
import { ClockTreeNode } from "../../../services/instanceContainers/clockTreeNode";
import { Validations } from "../../../services/objectManagers/validations";
import { ClockTreeInnerGraph } from "./ClockTreeInnerGraph";
import { PinFrequencyConfigurableMgr } from "../../../services/objectManagers/configurables/pinFrequencyConfigurableMgr";
import { ClockIpInstanceMgr } from "../../../services/objectManagers/clockIpInstanceMgr";
import { memoizeResult } from "../../../services/utils";

// This component renders a clock tree graph based on a passed in ELK layout
// Specifically, it assumes the layout has one root group which it will pass to a ClockTreeInnerGraph to render, but this
// component keeps track of the last line hovered on so the signal path is calculated only once for all groups.

interface IProps {
	layout: ExtendedElkNode;
	onSelect: (selection: string) => void;
	actions: ConfigStoreActions;
	treeNode: ClockTreeNode;
	validations: Validations;
	displayScriptName: boolean;
	ipInstances: ClockIpInstanceMgr[];
	searchText: string;
}

interface IState {
	hoveredOnLine: ExtendedElkLine;
	selectedLine: ExtendedElkLine;
}

class ClockTreeGraphImpl extends React.Component<IProps & ClassesType, IState> {
	public override state: IState = {
		hoveredOnLine: null,
		selectedLine: null,
	};

	public override render() {
		const { ipInstances, ...rest } = this.props;
		return <ClockTreeInnerGraph
			{...rest}
			usedInstances={getUsedInstances(ipInstances)}
			disabledInstances={getDisabledInstances(ipInstances)}
			onMouseEnter={this.onMouseEnter}
			onMouseLeave={this.onMouseLeave}
			onClick={this.onClick}
			selectedSignalPath={this.getSignalPath(this.state.selectedLine)}
			highlightSignalPath={this.getSignalPath(this.state.hoveredOnLine)}
		/>;
	}

	private onMouseEnter = (hoveredOnLine: ExtendedElkLine) => {
		this.setState({ hoveredOnLine });
	}

	private onMouseLeave = () => {
		if (this.state.hoveredOnLine) { // prevent additional re-renders just because we got an extra event
			this.setState({ hoveredOnLine: null });
		}
	}

	private onClick = (selectedLine: ExtendedElkLine) => {
		this.setState({ selectedLine });
	}

	private getSignalPath(line: ExtendedElkLine) {
		if (line) {
			// The edge will always have one source, but multiple targets

			const source = _.first(line.data.edges).signal.source;
			const inst = this.props.treeNode.getIpInstanceMgr(source.instName);
			const pinMgr = inst.memberMgrs[source.pinName] as PinFrequencyConfigurableMgr;

			// So that we don't highlight every connection from a source, lets filter out the source ports
			// and only look at the destination ports

			return [
				...pinMgr.getSignalPath(),
				..._.map(line.data.edges, (e) => e.target),
			];
		}
		return [];
	}
}

const getUsedInstances = memoizeResult(ClockIpInstanceMgr.getUsed);

const getDisabledInstances = memoizeResult((ipInstances: ClockIpInstanceMgr[]) => {
	return _.chain(ipInstances)
		.filter((i) => i.isDisabled())
		.map((i) => i.getID())
		.value();
});

export const ClockTreeGraph = withStyles(clockTreeStyles)(ClockTreeGraphImpl);
