import * as _ from "lodash";
import React = require("react");
import { Tooltip as MuiTooltip, withStyles, Typography, TooltipProps } from "../imports/material-ui-imports";
import { isUnderTest } from "../services/platform";

type PlacementType = TooltipProps["placement"];

export interface IProps {
	title?: React.ReactNode;
	placement?: PlacementType;
	noWrap?: boolean;	// if true, tooltip will show on a single line
	disabled?: boolean;
	open?: boolean;
}

const MuiTooltipNoWrap = withStyles({
	tooltip: {
		maxWidth: "none",
		maxHeight: "250px",
		overflow: "auto",
	},
})(MuiTooltip);

const TOOLTIP_ENTER_DELAY = 350;
const TOOLTIP_LEAVE_DELAY = 100;

const disabledToolTipStyle = { style: { display: "none" } };
const enabledToolTipStyle = {};

// Tooltip wrapper
//  - Does not show if text is empty
//  - Uses default delay of 500ms
//  - Works on disabled components (via the addition of a span)
//  - Works to wrap our own components (via the addition of a span)

export function Tooltip(props: React.PropsWithChildren<IProps>) {
	const TooltipComp = props.noWrap ? MuiTooltipNoWrap : MuiTooltip;
	return <TooltipComp {...convertProps(props)} >
		<span>{props.children}</span>
	</TooltipComp>;
}

// If the title is just text, replace it with a typography component so we always have the
// same font for tooltips

function styleTooltipTitle(title: React.ReactNode) {
	return _.isString(title) && !_.isEmpty(title) ?
		<Typography
			display="inline"
			variant="caption"
			color="inherit"
		>
			{title}
		</Typography>
		: title;
}

// This returns props that are can be passed to the material UI Tooltip component.  Components that cannot use the 
// wrapper above (either due to event forwarding, speed, layout etc) should use this to generate props that are 
// reasonable for SysConfig.  This will handle:
//  - Empty titles (no tooltip will be displayed)
//  - Default delay of 500ms
// Note: The MUI tooltip does NOT work on disabled components (use ToolTip wrapper above)

export function generateToolTipProps(title: string) {
	return convertProps({ title });
}

function convertProps(props: IProps) {
	const disableTooltip =
		_.isEmpty(props.title) || 	// Don't show empty tooltips
		props.disabled ||			// Allow parent to indicate tooltips are invalid
		isUnderTest();				// Tool tips may block clicks when testing

	// Why aren't we using Tooltip 'open' prop vs hiding the underlying popper with styling?
	// Tooltip reads if open is defined when constructed, and sets internal state that's not 
	// part of state/props.  As such, a re-render with new props won't respect if open is now
	// defined/undefined.  So to use open, we'd have to always define it and then handle 
	// enterDelay ourselves.  I'm convinced this is a MUI bug, but they've rejected it.  
	// See https://github.com/mui-org/material-ui/issues/12443

	const popperStyle = disableTooltip ? disabledToolTipStyle : enabledToolTipStyle;

	const title = props.title ?? "";

	return {
		title: styleTooltipTitle(title),
		placement: props.placement,
		enterDelay: TOOLTIP_ENTER_DELAY,
		PopperProps: popperStyle,
		interactive: !_.isString(title),
		leaveDelay: TOOLTIP_LEAVE_DELAY,
		enterNextDelay: TOOLTIP_ENTER_DELAY,
		open: props.open,
	};
}
