import * as _ from "lodash";
import React = require("react");
import { CardContent, Typography } from "../../../imports/material-ui-imports";
import { Formatted2ColRow } from "../../Formatted2ColRow";
import { MultiDropDown } from "../../DropDown";
import { assertUnreachable } from "../../../services/utils";
import { PreferenceType, MultiSelectPreference, UserPreference } from "../../../services/userPreferences";
import { CheckBox } from "../../CheckBox";
import { SecondaryButton } from "../../buttons/SecondaryButton";
import { IGlobalServiceProps } from "../../IGlobalServicesProps";
import { UserPreferenceViewMgr } from "../../../services/ui/outputView";
import { IUserPreferenceActions } from "../../actions/IUserPreferenceActions";
import { commonStyles } from "../../styles/common";
import { Tooltip } from "../../Tooltip";
import { SwitchButton } from "../../buttons/SwitchButton";
import { IOutputActions } from "../../actions/IOutputActions";

interface IProps {
	mgr: UserPreferenceViewMgr;
	actions: IUserPreferenceActions & IOutputActions;
}

export class UserPreferenceView extends React.Component<IProps & IGlobalServiceProps> {

	public override render() {
		const uPref = this.props.mgr.getUserPreferences();
		const hasBoard = this.props.mgr.hasBoard();
		return (
			<CardContent>
				<table>
					<UserPrefGrouping
						heading="Preferences"
						key="userPrefGroup"
						top
						content={
							_.map(uPref.getPreferences(), (curPref, name) => {
								if (curPref.requireBoard && !hasBoard) {
									return null;
								}
								let col2Content = null;	// empty DOM element

								if (PreferenceType.MULTISELECT === curPref.type) {
									col2Content =
										<span>
											<MultiDropDown
												id={name + "MultiSelect"}
												disabled={false}
												onChange={(values: string[]) => {
													if (!_.isEmpty(values)) {
														this.setMultiSelectValues(curPref, values);
													}
												}}
												selectedOptionName={this.getMultiSelectValues(curPref)}
												enabledOptions={this.getMultiSelectOptions(curPref)}
												displayScriptName={false}
											/>
										</span>;
								} else if (PreferenceType.CHECKBOX === curPref.type) {
									col2Content = <CheckBox
										id={curPref.name}
										onChange={(value: boolean) => {
											this.props.actions.setPreferenceValue(curPref, value);
										}}
										value={curPref.getValue()}
										alignInput
									/>;
								} else {
									return assertUnreachable(curPref);
								}

								return (
									<Formatted2ColRow
										key={name}
										col1={<Typography style={{ marginLeft: 12 }}>{curPref.description}</Typography>}
										col2={col2Content}
									/>
								);
							})}
					/>
					<UserPrefGrouping
						heading="Actions"
						key="userActionsGroup"
						content={[
							...this.getUserPreferenceActions(uPref, hasBoard),
							this.getSwitchAction(),
						]}
					/>
				</table>
			</CardContent >
		);
	}

	private getSwitchAction() {
		if (!this.props.mgr.isMigrationAllowed()) {
			return null;
		}
		return (
			<Formatted2ColRow
				key="Switch"
				col1={
					<Tooltip
						title={""}
						placement="top"
					>
						<Typography style={{ marginLeft: 12 }}>{"Switch Target"}</Typography>
					</Tooltip>
				}
				col2={
					<SwitchButton
						theme={this.props.theme}
						mgr={this.props.mgr}
						actions={this.props.actions}
					/>
				}
			/>
		);
	}

	private getUserPreferenceActions(uPref: UserPreference, hasBoard: boolean): JSX.Element[] {
		return _.map(uPref.getActions(), (curPref, name) => {

			if (curPref.requireBoard && !hasBoard) {
				return null;
			}

			return (
				<Formatted2ColRow
					key={name}
					col1={
						<Tooltip
							title={curPref.tooltip}
							placement="top"
						>
							<Typography style={{ marginLeft: 12 }}>{curPref.description}</Typography>
						</Tooltip>
					}
					col2={
						<SecondaryButton
							theme={this.props.theme}
							id={`userPreferencesBtn${curPref.buttonName}`}
							onClick={() => curPref.onClick(this.props.actions)}
						>
							{curPref.buttonName}
						</SecondaryButton>
					}
				/>
			);
		});
	}

	// convert the preference options array to the dropdown array format
	private getMultiSelectOptions(curPref: MultiSelectPreference<number>) {
		return _.map(
			curPref.getAllSelectableOptions(), (o) => {
				return { name: o.id.toString(), displayName: o.optionText, description: o.description };
			});
	}

	private getMultiSelectValues(curPref: MultiSelectPreference<number>) {
		return _.map(curPref.getSelectedEnums(), (selected) => selected.toString());
	}

	private setMultiSelectValues(curPref: MultiSelectPreference<number>, values: string[]) {
		this.props.actions.setPreferenceValue(curPref, _.map(values, (value) => parseInt(value, 10)));
	}
}

class UserPrefGrouping extends React.Component<{
	heading: string,
	content: JSX.Element[],
	top?: boolean,
}, {}> {
	public override render() {
		return ([
			<thead key={"userPrefHead" + this.props.heading} >
				<tr>
					<th>
						<Typography
							style={this.props.top ?
								{ ...commonStyles.headingStyleTop } : { ...commonStyles.headingStyleNotTop }}>
							{this.props.heading}</Typography>
					</th>
				</tr>
			</thead >,
			<tbody key={"userPrefBody" + this.props.heading}>
				{this.props.content}
			</tbody>,
		]
		);
	}
}
