import React = require("react");
import { spacingUnit } from "./styles/themes";

interface IProps {
	col1: JSX.Element;
	col2: JSX.Element;
}

const col1Style: React.CSSProperties = {
	width: "1%",	// this will make this column take only the necessary width
	whiteSpace: "nowrap",
	paddingRight: spacingUnit,
	paddingBottom: spacingUnit,
};

const col2Style = {
	width: "99%",	// this will make this column use up the rest of the space available on this row
	paddingBottom: spacingUnit,
};

export class Formatted2ColRow extends React.Component<IProps, {}> {

	public override render() {
		return (
			<tr>
				<td style={col1Style}>{this.props.col1}</td>
				<td style={col2Style}>{this.props.col2}</td>
			</tr>
		);
	}
}
