import * as React from "react";
import * as _ from "lodash";
import { Slide, TextField, ButtonGroup } from "../../../../imports/material-ui-imports";
import { Close, Magnify } from "../../../../imports/mdi-material-ui-imports";
import { defaultFontSize, spacingUnit } from "../../../styles/themes";
import { ButtonGroupIconButton } from "./ButtonGroupIconButton";

// This represent a search button floating in the corner.  It will start with just a button that when clicked will open
// a search box field.  When closed, it will notify the parent that the search text is empty again.

interface IProps {
	searchText: string;
	onSearchTextChanged: (filterText: string) => void;
}

interface IState {
	open: boolean;
}

export class FloatingSearch extends React.Component<IProps, IState> {

	public override state = {
		open: false,
	}

	public override componentDidMount() {
		if (!_.isEmpty(this.props.searchText)) {
			this.setState({ open: true });
		}
	}

	public override render() {
		return <>
			<Slide direction="down" in={this.state.open} mountOnEnter unmountOnExit>
				<TextField
					placeholder="Type Filter Text..."
					onChange={this.onChange}
					value={this.props.searchText}
					variant={"outlined"}
					inputProps={textFieldInputStyle}
					style={textFieldStyle}
					autoFocus={true}
					id="floatingSearchField"
				/>
			</Slide>

			<ButtonGroup variant="contained" >
				<ButtonGroupIconButton onClick={this.onClick} id="floatingSearchButton">
					{this.state.open ? <Close fontSize="small" color="primary" /> : <Magnify fontSize="small" color="primary" />}
				</ButtonGroupIconButton>
			</ButtonGroup>
		</>;
	}

	private onClick = () => {
		this.setState({ open: !this.state.open });
		this.props.onSearchTextChanged("");
	}

	private onChange = (e: React.ChangeEvent<HTMLInputElement>) => this.props.onSearchTextChanged(e.target.value);
}

// This pads the text field so it's aligned with the search button

const textFieldStyle = {
	marginRight: 4,
	top: 2,
};

// This adjusts the input text to be more inlined with the other input box sizes

const textFieldInputStyle = {
	style: {
		height: defaultFontSize * 2 + spacingUnit - 5,
		padding: spacingUnit,
		margin: "0 4px",
	},
};
