import * as React from "react";
import { IConfigurablesActions } from "../configurableActions";
import { DateConfigurableMgr } from "../../configurables/dateConfigurableMgr";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";
const isValid = require("date-fns/isValid");
import { OnBlurInputBox } from "../../../../components/higherOrderComponents/ComposedComponents";

interface IProps {
	handleDateChange: (val: string) => void;
	value?: string;
	onClick?: () => void;
}

export class CDateConfigurable extends React.Component<{
	mgr: DateConfigurableMgr;
	actions: IConfigurablesActions;
}> {
	public override render() {
		const mgr = this.props.mgr;
		const actions = this.props.actions;
		return (
			<DatePicker
				adjustDateOnChange={true}
				popperPlacement={"auto-start"}
				customInput={<StartDate
					handleDateChange={this.handleDateChange} />}
				dateFormat="yyyy-MM-dd"
				selected={mgr.getValue()}
				onChange={(val) => {
					actions.setConfigurableValue(mgr, val);
				}}
				showYearDropdown
				todayButton="Today"
			/>
		);
	}

	private handleDateChange = (val: string) => {
		const d = new Date(val);
		if (isValid(d)) {
			this.props.actions.setConfigurableValue(this.props.mgr, d);
		}
	}
}

class StartDate extends React.Component<IProps> {
	public override render() {
		return (
			<OnBlurInputBox
				type={"text"}
				id={"date-input"}
				disabled={false}
				value={this.props.value}
				onClick={this.props.onClick}
				onChange={(value) => this.props.handleDateChange(value)}
				placeholder="yyyy-mm-dd"
			/>
		);
	}
}
