import { Theme, WithStyles, createStyles, red, amber, blue, yellow } from "../../../imports/material-ui-imports";

// This re-declares the theme so that the full colorPalette object can be referenced, which is what the material ui 
// maintainers recommend in order to have it work with typescript

declare module "@material-ui/core/styles/createPalette" {
	interface PaletteColor extends ColorPartial { }
}

const animations = {
	"@keyframes dash": {
		from: {
			strokeDashoffset: 24,
		},
		to: {
			strokeDashoffset: 0,
		},
	},
};

const positionedDiv = {
	position: "absolute" as const, // prevent type widening which would prevent us treating it as a style
};

export const svgStrokeWidth = 1;
export const maxNodeWidth = 150;

function getThemeColours(theme: Theme) {
	return theme.palette.type === "light" ? getLightThemeColours(theme) : getDarkThemeColours(theme);
}

// Error trumps warnings trumps disabled trumps unused

export function getLightThemeColours(theme: Theme) {

	const lineColour = theme.palette.grey[600];
	return {
		lineColour,
		normal: {
			outline: theme.palette.primary[800],
			fill: theme.palette.primary[200],
			hover: theme.palette.primary[100],
		},
		error: {
			outline: red[900],
			fill: red[200],
			hover: red[100],
		},
		warning: {
			outline: amber[600],
			fill: amber[200],
			hover: amber[100],
		},
		disabled: {
			outline: lineColour,
			fill: theme.palette.grey[400],
			hover: theme.palette.grey[300],
		},
		unused: {
			outline: lineColour,
			fill: theme.palette.grey[100],
			hover: theme.palette.grey[200],
		},
		textColor: undefined as string,
		groupFillColour: theme.palette.grey[400],
	};
}

function getDarkThemeColours(theme: Theme) {
	const lineColour = theme.palette.grey[400];
	return {
		lineColour,
		normal: {
			outline: blue[700],
			fill: "#1b5c87",
			hover: "#0E639C",
		},
		error: {
			outline: red[400],
			fill: red[900],
			hover: red[700],
		},
		warning: {
			outline: yellow[700],
			fill: yellow[900],
			hover: yellow[800],
		},
		disabled: {
			outline: theme.palette.grey[500],
			fill: theme.palette.grey[700],
			hover: theme.palette.grey[800],
		},
		unused: {
			outline: theme.palette.grey[500],
			fill: "#313131",
			hover: theme.palette.grey[800],
		},
		textColor: theme.palette.text.primary,
		groupFillColour: theme.palette.grey[800],
	};
}

function divStyle({ outline, fill, hover }: { outline: string, fill: string, hover: string }) {
	return {
		"outlineColor": outline,
		"backgroundColor": fill,
		"&:hover": {
			backgroundColor: hover,
		},
	};
}

function svgStyle({ outline, fill, hover }: { outline: string, fill: string, hover: string }) {
	return {
		"stroke": outline,
		"fill": fill,
		"&:hover": {
			fill: hover,
		},
		"opacity": "100% !important", // Ensures filtering doesn't double filter (PMUX-3472)
	};
}

export const clockTreeStyles = (theme: Theme) => {
	const {
		lineColour,
		normal,
		error,
		warning,
		disabled,
		unused,
		textColor,
		groupFillColour,
	} = getThemeColours(theme);

	const nodeOrGroup = {
		...positionedDiv,
		pointerEvents: "all",
		outline: "1px solid",
	} as const;

	const pin = {
		...positionedDiv,
		fontSize: 8,
		padding: 3,
		color: textColor,
	};

	const svg = {
		width: "100%",
		height: "100%",
		overflow: "visible", 		// so growing the border on a child svg still works
		opacity: "100% !important", // Ensures filtering doesn't double filter (PMUX-3472)
	};

	const animatedLine = {
		strokeDasharray: "10,2",
		animation: "$dash 1s linear infinite",
		strokeWidth: 3,
		fill: "none",
	};

	const ipBlockLabel = {
		...positionedDiv,
		overflow: "hidden",
		textOverflow: "ellipsis",
		width: maxNodeWidth,
		textAlign: "center",
		color: textColor,
	} as const;

	const hidden = {
		display: "none",
	};

	return createStyles({

		// Properties for the signal connections (edges) between nodes
		// Note that the connections are rendered after nodes, so they appear on top of them

		svgLinesContainer: {						// The root svg node that holds 
			...svg,
			position: "absolute",					// Position needed or it will always render underneath the positioned nodes
			pointerEvents: "none",					// Do not steal pointer events, or nodes will be unable to respond to them
		},
		line: {										// Standard line
			stroke: lineColour,
			strokeWidth: 1,
			fill: "none",
		},
		highlightedLine: {							// Highlighted line - uses a dash animation
			...animatedLine,
			stroke: "rgb(0, 192, 255)",
		},
		selectedLine: {								// Selected line - uses a dash animation, but of a different colour
			...animatedLine,
			stroke: "rgb(0, 100, 255)",
		},
		hoverSelectLine: {							// Invisible line to intercept hover events
			stroke: "grey", 						// Needs to have some stroke or it won't render, but strokeOpacity will hide it
			strokeOpacity: 0,
			strokeWidth: 10,						// ELK defaults to a spacing of 10 px between edges, so we can't be thicker than this
			pointerEvents: "all",
		},
		joint: {									// Small circle where signals split
			fill: lineColour,
		},

		// Properties for the ip instances (nodes)

		positionedDiv,								// Invisible outline that can be used to position children within it

		svgNodeContainer: {							// Root <svg> element that svg nodes can be rendered within
			...svg,
		},
		genericNode: {
			...nodeOrGroup,							// Default html-based node 
			...divStyle(normal),
		},
		svgNode: {									// Default svg-based node
			pointerEvents: "all",
			strokeWidth: svgStrokeWidth,
			...svgStyle(normal),
		},
		selected_genericNode: {						// Additional styles to apply to selected nodes
			outlineWidth: 4,
		},
		selected_svgNode: {
			strokeWidth: 4,
		},
		error_genericNode: divStyle(error),			// Additional styles to apply to nodes based on their intrinsic state
		error_svgNode: svgStyle(error),				// Error trumps warnings trumps disabled trumps unused
		warning_genericNode: divStyle(warning),
		warning_svgNode: svgStyle(warning),
		disabled_genericNode: divStyle(disabled),
		disabled_svgNode: svgStyle(disabled),
		unused_genericNode: divStyle(unused),
		unused_svgNode: svgStyle(unused),

		frequencyLabelNode: {						// Frequency label nodes cannot be selected or hovered on
			...positionedDiv,
			outline: "1px solid",
			outlineColor: lineColour,
		},
		selected_frequencyLabelNode: {
			outlineWidth: 4,
		},
		error_frequencyLabelNode: divStyle(error),
		warning_frequencyLabelNode: divStyle(warning),

		// Properties for abstract groups surrounding one or more nodes

		genericGroupNodeOutline: {					// The outline/label of a group (fill handled below)
			...nodeOrGroup,
			outlineColor: lineColour,
		},
		genericGroupNodeFill: {						// The fill of a group 
			...nodeOrGroup,							// This is handled separate to the outline so that it can have a 
			backgroundColor: groupFillColour,		// 50% opacity and get darker as groups overlap
			ourline: 0,
			opacity: "50%",
		},

		// Properties for labels

		inPinLabel: {								// Input pins are labeled to the right and thus are justified normally
			...pin,
		},
		outPinLabel: {								// Output pins are labeled to the left and thus need to be justified all the way right
			...pin,
			textAlign: "end",
		},
		ipBlockLabel,								// Main label for a node or group
		inputOnlyConnectionLabel: {					// Main label for a broken connection with only inputs
			...ipBlockLabel,
			textAlign: "right",
		},
		outputOnlyConnectionLabel: {				// Main label for a broken connection with only outputs
			...ipBlockLabel,
			textAlign: "left",
		},
		selected_ipBlockLabel: hidden,				// Since the label will be on top of the original, hide it so that 
		error_ipBlockLabel: hidden,					// it doesn't appear to be bold
		warning_ipBlockLabel: hidden,
		selected_inputOnlyConnectionLabel: hidden,
		error_inputOnlyConnectionLabel: hidden,
		warning_inputOnlyConnectionLabel: hidden,
		selected_outputOnlyConnectionLabel: hidden,
		error_outputOnlyConnectionLabel: hidden,
		warning_outputOnlyConnectionLabel: hidden,

		// Properties for inner controls within nodes

		radioButton: {								// Muxes can be changed via radio buttons
			padding: theme.spacing(1),
			height: theme.typography.fontSize,
		},
		dropDown: {									// Multipliers/dividers can be changed via drop downs
			textAlign: "center",
			padding: "10px",
		},
		centralText: {								// The central text on a frequency label 
			textAlign: "center",
			display: "flex",
			justifyContent: "center",
			alignContent: "center",
			flexDirection: "column",
			height: "100%",
		},
		selected_centralText: hidden,				// Prevents the text being written over top of itself when selected
		error_centralText: {						// That caused the text to appear to "bold" itself
			display: "flex",						// But when the background is no longer transparent, we need to 
		},											// display normally again
		warning_centralText: {
			display: "flex",
		},

		// These are additive styles that can be applied on top of any other styles

		filtered: {							// Default svg-based node who's outputs are not consumed
			opacity: "40%",
		},

		// CSS animations that are referred to above

		...animations,
	});
};

export type ClassesType = WithStyles<typeof clockTreeStyles>;
