import * as _ from "lodash";
import { contextifyMetaCode, appendSource } from "../contextify";
import { fs } from "../../fileSystem";
import { IMetaContentLoader } from "./resourceLoader";
import { compileTemplate } from "../templateCompiler";
import { Product } from "../../product/types";
import { isNode, isEclipse, getProcess } from "../../platform";
import { trueCasePathSync, toLinuxPath } from "../../utils";
import * as JSON5 from "json5";

function wrapJSON(fullPath: string, source: string) {
	// Strip comments, then parse and re-stringify to remove any whitespace, and also to verify
	// that this really is pure-json and not executable code

	try {
		return "return " + JSON5.stringify(JSON5.parse(source)) + ";";
	} catch (e) {
		throw appendSource(e, fullPath);
	}
}

function wrapScript(source: string) {
	// Historically, we told people to assign exported variables to exports using one of the 
	// following syntaxes:
	// exports = {var1, var2, ...}                    // option 1
	// exports.var1 = var1;  exports.var2 = var2; ... // option 2
	// However, the commonjs format uses either option 2 above, or the following:
	// module.exports = {var1, var2, ...}             // option 3
	// So, if we want to support typescript transpiling, we need to support all 3 styles

	return "let exports = {}; let module = {exports}; {" + source + "\n} return _.isEqual(exports, {}) ? module.exports : exports;";
}

let env: {
	TI_SYSCONFIG_TEMPLATE_COMPILED_DIR?: string;
} = {};

if (isNode()) {
	env = getProcess().env;
} else if (isEclipse()) {
	env = eclipseEnv;
}

// This class loads resources from the file system relative to a root path

export class FileSystemLoader implements IMetaContentLoader {

	private readonly path = require("path");
	private readonly compiledSourceDir = env.TI_SYSCONFIG_TEMPLATE_COMPILED_DIR;
	constructor(private readonly rootPath: string, private readonly product: Product) { }

	public hasResource(fullPath: string) {
		const combinedPath = this.getCombinedPath(fullPath);
		return fs.fileExists(combinedPath) && this.matchesCase(combinedPath, fullPath);
	}

	public loadResource(fullPath: string) {
		const source = this.loadResourceSource(fullPath);
		let fsPath = this.path.join(this.rootPath, fullPath);
		if (this.compiledSourceDir && _.endsWith(fullPath, ".xdt")) {
			fsPath = this.path.join(this.compiledSourceDir, fullPath) + ".compiled";
			fs.mkdir(this.path.dirname(fsPath), { recursive: true });
			fs.writeFile(fsPath, source);
		}
		return contextifyMetaCode(fsPath, source);
	}

	public loadResourceSource(fullPath: string) {
		const source = fs.readFile(this.path.join(this.rootPath, fullPath)).toString();
		if (_.endsWith(fullPath, ".js")) {
			return wrapScript(source);
		} else if (_.endsWith(fullPath, ".xdt")) {
			return compileTemplate(source);
		} else if (_.endsWith(fullPath, ".json")) {
			return wrapJSON(fullPath, source);
		} else {
			throw new Error("Invalid resource extension: " + fullPath);
		}
	}

	public getProduct() {
		return this.product;
	}

	public listResources(fullPath: string): string[] {
		try {
			return _.map(fs.readdir(this.path.join(this.rootPath, fullPath)), toLinuxPath);
		} catch (e) {
			return [];
		}
	}

	public isFile(fullPath: string): boolean {
		return fs.isFile(this.path.join(this.rootPath, fullPath));
	}

	public getCombinedPath(fullPath: string): string {
		return this.path.join(this.rootPath, fullPath);
	}

	private matchesCase(combinedPath: string, fullPath: string) {
		// The meta content is generally intended to 
		// be portable, but development is often done on windows and thus we'd like
		// to enforce the case-ing there to catch any path issues early. 
		const trueFullPath = trueCasePathSync(combinedPath).slice(combinedPath.length - fullPath.length);

		// normalize full path to handle differences in path separators
		return trueFullPath === this.path.normalize(fullPath);
	}
}
