// UI Views for meta content defined configurables
import * as React from "react";
import { IConfigurablesActions } from "../configurableActions";
import { BooleanConfigurableMgr } from "../../configurables/booleanConfigurableMgr";
import { CheckBox } from "../../../../components/CheckBox";

export class CBooleanConfigurable extends React.Component<{
	mgr: BooleanConfigurableMgr;
	actions: IConfigurablesActions;
}> {
	public override render() {
		const mgr = this.props.mgr;
		const actions = this.props.actions;
		return (
			<CheckBox
				id={mgr.def.name}
				disabled={!!mgr.uiState.readOnly}
				value={mgr.getValue()}
				onChange={(val: boolean) => actions.setConfigurableValue(mgr, val)} />
		);
	}
}
