import React = require("react");
import { Redirect, RouteComponentProps } from "react-router-dom";
import { constructRoute, configPage, eclipseLandingPage } from "../services/routing";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { parseArgsStringToArgv } from "../services/args/stringToArgv";
import { clearSysConfigCache } from "../services/sysConfigFactory";

let registered = false;

export class LaunchFromEclipse extends React.PureComponent<IGlobalServiceProps & RouteComponentProps<{}>, {}> {

	public override render() {

		// Register a callback handler for all time that fetches the current sysconfig and saves it

		if (!registered) {
			window.pinmuxRestartFromEclipse = () => {
				this.props.modalService.showConfirmModal(
					"Restart",
					"Project properties have changed, SysConfig needs to restart.\nUnsaved changes will be lost.",
					() => {
						clearSysConfigCache();
						this.props.history.push(constructRoute(eclipseLandingPage, []));
					},
					() => { },
					"Restart now",
					"Restart later",
				);
			};
			registered = true;
		}

		return <Redirect to={constructRoute(configPage, parseArgsStringToArgv(eclipseGetCLIArgsString()))} />;
	}
}
