// UI Views for meta content defined configurables
import * as React from "react";
import * as _ from "lodash";
import { IConfigurablesActions } from "../configurableActions";
import { MultiValueEnumerationConfigurableMgr } from "../../configurables/multiValueEnumerationConfigurableMgr";
import { MultiDropDown } from "../../../../components/DropDown";
import { IFormatter } from "../../../formatting/formattingTypes";
import { ILinkActions } from "../../../../components/actions/ILinkActions";
import { CBaseEnumConfigurable } from "./baseEnumConfigurable";

export class CMultiValueEnumerationConfigurable extends CBaseEnumConfigurable<{
	mgr: MultiValueEnumerationConfigurableMgr<string | number>;
	actions: IConfigurablesActions & ILinkActions;
	formatter: IFormatter;
	displayScriptName: boolean;
}> {
	public override render() {
		const mgr = this.props.mgr;
		const actions = this.props.actions;
		const { enabledOptions, disabledOptions } = mgr.getUIOptions();
		// selected options
		const selectedOptions = _.map(mgr.getValue(), (v) => v.toString());
		return (
			<MultiDropDown
				id={mgr.def.name}
				disabled={!!mgr.uiState.readOnly}
				selectedOptionName={selectedOptions}
				enabledOptions={this.formatOptions(enabledOptions)}
				disabledOptions={this.formatOptions(disabledOptions)}
				key={this.state.key} // Force re-render (closing drop down) when navigating away via tooltip
				withNoneOption={mgr.def.placeholder}
				clearable={mgr.minSelections === 0}
				displayScriptName={this.props.displayScriptName}
				onChange={(selectedValues) => {
					if (selectedValues.length < mgr.minSelections) {
						return;
					}
					if (isNumberMultiValueEnumeration(mgr)) {
						actions.setConfigurableValue(mgr, _.map(selectedValues, (v) => Number(v)));
					} else if (isStringMultiValueEnumeration(mgr)) {
						actions.setConfigurableValue(mgr, selectedValues);
					} else {
						throw new Error("Should not get here!");
					}
				}}
			/>
		);
	}
}

function isNumberMultiValueEnumeration(mgr: MultiValueEnumerationConfigurableMgr<string | number>):
	mgr is MultiValueEnumerationConfigurableMgr<number> {
	return typeof mgr.def.options[0].name === "number";
}

function isStringMultiValueEnumeration(mgr: MultiValueEnumerationConfigurableMgr<string | number>):
	mgr is MultiValueEnumerationConfigurableMgr<string> {
	return typeof mgr.def.options[0].name === "string";
}
