import { toScript } from "./scripting/toScript";
import { storage } from "./storage";
import { Runtime } from "./resources/runtime";
import { Settings } from "./settings";

export class CurrentScript {
	private scriptDirty: boolean = false;

	constructor(
		private currentScript: string = null,
	) {
	}

	public set(scriptPath: string) {
		this.currentScript = scriptPath;
	}

	public get() {
		return this.currentScript || "";
	}

	public isDirty() {
		return this.scriptDirty;
	}

	public setDirty(dirty: boolean) {
		this.scriptDirty = dirty;
	}

	public async save(runtime: Runtime, settings: Settings) {

		const script = await toScript(runtime, this.get());
		const fileInfo = await storage.saveFile(this.get(), script);
		await settings.addRecent(fileInfo.path);
	}
}
