import * as React from "react";
import * as _ from "lodash";
import { ExtendedElkNode, ExtendedElkPort } from "../layout/customTypes";
import { PositionedDiv } from "./PositionedDiv";
import { assertUnreachable, getDisplayName } from "../../../services/utils";
import { ClassesType, maxNodeWidth } from "../styling/clockTreeStyles";
import { Radio } from "../../../imports/material-ui-imports";

// When instantiated as a child of a node, will render all the labels (pins as well as name of node)

interface IProps {
	node: ExtendedElkNode;
	checked?: string;
	onChecked?: (port: string) => void;
	displayScriptName: boolean;
	extraPadding?: number;
}

export function NodeLabels(props: IProps & ClassesType) {

	// x === 0 means on the left (ie input), but x can be negative if ports have a size

	const [inPorts, outPorts] = _.partition(props.node.ports, (port) => port.x <= 0);
	return <>
		<MainLabel {...props} />
		{
			// Ensure out ports are rendered first, so inputs (with radio checks) are on top

			_.map(outPorts, (port) =>
				<OutputLabel
					key={port.id}
					port={port}
					{...props}
				/>
			)
		}
		{
			_.map(inPorts, (port) =>
				<InputLabel
					key={port.id}
					port={port}
					{...props}
				/>
			)
		}
	</>;
}

export const enum Alignment {
	CENTER,
	LEFT,
	RIGHT,
}

interface IMainLabelProps {
	node: ExtendedElkNode;
	displayScriptName: boolean;
	alignment?: Alignment;
}

const labelWidth = maxNodeWidth;

export function MainLabel({ node, displayScriptName, alignment, classes }: IMainLabelProps & ClassesType) {
	alignment = alignment ?? Alignment.CENTER;
	return <PositionedDiv 										// Main label (name of the ip block)
		x={getXPosition(node, alignment)}
		y={node.height} 										// Underneath the ip block
		className={getClassName(classes, alignment)}
	>
		{getDisplayName(node.data.ipInstance, displayScriptName)}
	</PositionedDiv>;
}

function getClassName(classes: ClassesType["classes"], alignment: Alignment) {
	switch (alignment) {
		case Alignment.CENTER:
			return classes.ipBlockLabel;
		case Alignment.LEFT:
			return classes.outputOnlyConnectionLabel;
		case Alignment.RIGHT:
			return classes.inputOnlyConnectionLabel;
		default:
			assertUnreachable(alignment);
	}
}

function getXPosition(node: ExtendedElkNode, alignment: Alignment) {
	switch (alignment) {
		case Alignment.CENTER:
			return node.width / 2 - labelWidth / 2;	// Center justified based on the label width and the node width, 
		case Alignment.LEFT:
			return 0;								// Start to the left side of the node
		case Alignment.RIGHT:
			return node.width - labelWidth;			// Have the right side end at the width of the node
		default:
			assertUnreachable(alignment);
	}
}

const portHeightAdjustment = 8;

function InputLabel({ port, checked, onChecked, displayScriptName, classes }: { port: ExtendedElkPort } & IProps & ClassesType) {
	return <PositionedDiv
		x={0}													// Left justified
		y={port.y - portHeightAdjustment}						// At the height of the port
		className={classes.inPinLabel}
	>
		{checked && onChecked &&
			<Radio
				id={`muxCheck${port.data.pin.name}`}
				onChange={() => onChecked(port.data.pin.name)}
				checked={checked === port.data.pin.name}
				className={classes.radioButton}
				color="primary"
			/>
		}
		{getDisplayName(port.data.pin, displayScriptName)}
	</PositionedDiv>;
}

function OutputLabel({ port, node, displayScriptName, extraPadding, classes }: { port: ExtendedElkPort } & IProps & ClassesType) {
	return <PositionedDiv
		x={0}
		y={port.y - portHeightAdjustment}						// At the height of the port
		width={node.width - (extraPadding ?? 0)}							// By extending the width to the whole node
		className={classes.outPinLabel}							// the CSS can right-justify and have it align to the right
	>
		{getDisplayName(port.data.pin, displayScriptName)}
	</PositionedDiv>;
}

