import * as _ from "lodash";
import * as vmTypes from "vm";

import { ScriptingObject, System } from "public/runtime";
import { isNode } from "../platform";

// cSpell:ignore fixstacks

// Wrap source code in a function so that it can be passed to an eval or similar call

// eslint-disable-next-line @typescript-eslint/ban-types
function wrapSourceAsFunction(source: string | Function, scriptGlobals: string[]) {
	if (typeof source === "string") {
		const joinedParamNames = _.join(scriptGlobals, ",");
		source = `function(${joinedParamNames}){"use strict";${source}` + "\n}";
	} else {
		// This is the case of a pre-bundled function.  Our bundlers already add
		// "use strict"; so we don't need to do that here

		source = source.toString();
	}

	const code = `(${source})`;
	return code;
}

// Take pre-wrapped code and eval it.  We use "sourceURL" to get javascript mapping (for
// debug or exception).  We use eval.call vs eval so that the code won't pull in other 
// scoped variables via closure.  We don't use new Function as there's no accurate way
// to make line-numbers align.  We don't use vm.runInContext as that causes the code to
// run in the background page in node-webkit, which makes cross-tool debugging more 
// difficult.
// http://2ality.com/2014/01/eval.html

// eslint-disable-next-line @typescript-eslint/ban-types
function contextifyCode<T extends Function>(path: string, code: string): T {
	// We always need a sourceURL.  That's what V8 uses for stack frames, but fixstacks.ts
	// will associate a map file if there is one

	code += "\n//# sourceURL=" + _.replace(path, /\s/g, "%20");

	// Check if the file had a .map file associated with it.  If so, update the link to a full 
	// path, and then add that to the end.  Only the last one takes effect

	const match = code.match(/\/\/# sourceMappingURL=.*.js.map/);
	if (match) {
		code += `\n//# sourceMappingURL=file:///${_.replace(path, /\\/g, "/")}.map`;
	}

	// Now evaluate the code so it runs

	const result = eval.call(null, code); // eslint-disable-line no-eval
	return result;
}

// This is the same as above, but uses runInThisContext which will inject the source line
// into SyntaxErrors.  But, this only works in node

// eslint-disable-next-line @typescript-eslint/ban-types
function nodeContextifyError<T extends Function>(path: string, code: string): T {
	const vm = require("vm") as typeof vmTypes;
	return vm.runInThisContext(code, {
		filename: path,
		displayErrors: true,
	});
}

export function appendSource(error: Error, path: string) {
	error.stack = `${error.toString()}\n    at ${path}${error.stack.slice(error.toString().length)}`;
	return error;
}

// These are common functions that are very likely to lead to problems - we'll shadow them as "undefined" so 
// they can't be used.  Ideally, we'd shadow window and global, but then they can't use things like Object.*
// which they do make heavy use of.  Plus, global can only be shadowed if run in a non-debuggable context, which
// isn't very helpful.

const shadowedFunctions = [
	"setTimeout", "setImmediate", 	// we can't have them scheduling jobs
];

// Returns a function based on the passed in source code, but associated with the supplied path.  
// This is better than require, as we can alter what global variables the script can see for
// all time, and also because require doesn't work outside of node

// eslint-disable-next-line @typescript-eslint/ban-types
export function contextify<T extends Function>(path: string, source: string | T, scriptGlobals: string[]): T {
	const code = wrapSourceAsFunction(source, [...scriptGlobals, ...shadowedFunctions]);

	try {
		return contextifyCode(path, code);
	} catch (error) {

		// This MUST be a syntax error, as we aren't executing the function that we wrapped the 
		// code in yet.  Node has an excellent way of finding the line number for syntax errors, 
		// but for CCS/cloud, all we can do is shove in the path with no line number

		if (isNode()) {
			return nodeContextifyError(path, code);
		} else {
			throw appendSource(error, path);
		}
	}
}

// Note that "pmux" is the legacy name for "system", but we have to pass it twice so the script sees both names

export type MetaCodeLoader =
	(lodash: typeof _, system: System, pmux: System, scripting: ScriptingObject, require: (path: string) => any) => any;
export const passedInArgs = ["_", "system", "pmux", "scripting", "require"];

export function contextifyMetaCode(path: string, source: string | MetaCodeLoader): MetaCodeLoader {

	return contextify(path, source, passedInArgs);
}
