import * as _ from "lodash";
import { RawResourceLoader, toCanonicalPath, ResourceType } from "../resources/metaContentLoaders/resourceLoader";
import { validateMeta, SCHEMA } from "../JSONschemaValidator";
import { Board } from "public/runtime";
import { getRenamedDeviceId } from "../data";
import { DiscoveryJSON } from "dataInterfaces";
import { Product } from "../product/types";

const defaultBoardPath = "/ti/boards/";

// Returns what board files exist within a loader.  

export function getBoardFiles(loader: RawResourceLoader, discoveryData: DiscoveryJSON, products: Product[]) {
	return (
		_.chain(getBoardResources(loader, products))
			.filter((b) => loader.isFile(b) && _.endsWith(b, ".json"))
			.map((r) => toCanonicalPath(r, ResourceType.DATA))
			.map((boardFile) => {
				try {
					const resource = loader.getJSONResource(boardFile);
					const boardDef = validateMeta(resource, boardFile, SCHEMA.BoardDef);
					boardDef.device = getRenamedDeviceId(boardDef.device, discoveryData);
					boardDef.emulated = _.map(boardDef.emulated, (deviceInfo) => ({
						...deviceInfo,
						device: getRenamedDeviceId(deviceInfo.device, discoveryData),
					}));
					return { boardDef, boardFile };
				} catch (e) {
					// Just ignore any ill formed or non board files.
					return undefined;
				}
			})
			.compact()
			.value()
	);
}

function getBoardResources(loader: RawResourceLoader, products: Product[]) {
	return _.chain(products)
		.map((p) => p.file.boardPath ?? defaultBoardPath) // Use the supplied path, or default
		.uniq()
		.flatMap((p) => _.map(safelyListResources(loader, p), (r) => `${p}${r}`)) // Append the folder to the file name
		.value();
}

function safelyListResources(loader: RawResourceLoader, path: string) {
	try {
		return loader.listResources(path);
	} catch (e) {
		return [];
	}
}

export function getAttachedBoosterpacks(board?: Board) {
	return _.chain(board?.components)
		.map((component) => component.source)
		.filter((source) => source.definition !== board.source)
		.uniq()
		.value();
}
