import React = require("react");
import * as _ from "lodash";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { ILocalFileBrowseProps } from "../local/LocalFileBrowse";
import { CloudFileSelectionDialog } from "./CloudFileSelectionDialog";
import { Button } from "../../imports/material-ui-imports";
import { CloudFileSaveAsDialog } from "./CloudFileSaveAsDialog";

export class CloudFileBrowse
	extends React.Component<ILocalFileBrowseProps & Pick<IGlobalServiceProps, "modalService" | "errorStore">, { open: boolean }> {

	public override state = {
		open: false,
	};

	public override render() {
		const childrenWithProps = getChildrenWithProps(this.props.id, this.handleButtonClick, this.props.children);

		return <React.Fragment>
			{childrenWithProps}
			{_.isUndefined(this.props.saveAs) && <CloudFileSelectionDialog
				folder={this.props.folder}
				errorStore={this.props.errorStore}
				modalService={this.props.modalService}
				id={this.props.id + "Dialog"}
				accept={this.props.accept}
				onChange={this.props.onChange}
				onClose={() => this.setState({ open: false })}
				title={"Open"}
				open={this.state.open}
			/>}
			{!_.isUndefined(this.props.saveAs) && <CloudFileSaveAsDialog
				errorStore={this.props.errorStore}
				modalService={this.props.modalService}
				id={this.props.id + "Dialog"}
				accept={this.props.accept}
				onChange={this.props.onChange}
				onClose={() => this.setState({ open: false })}
				title={"Save As"}
				open={this.state.open}
				initialName={this.props.saveAs}
			/>}
		</React.Fragment>;
	}

	private handleButtonClick = () => {
		this.setState({ open: true });
	}
}

// We want to work like LocalFileBrowse, which creates an <input> and the children
// are used to "click" that input.  

// In order to do that here, we need to pass down an onClick handler to handle us,
// and also an id so that clicks sent to us will respond appropriately (file-menu)
// does just that for shortcuts

// Note that React.Children.map !== _.map.  I don't know the difference, but it's 
// different and react breaks.
export function getChildrenWithProps(id: string, onClick: () => void, children?: React.ReactNode) {
	if (_.isUndefined(children)) {

		// If no children are defined, create a hidden child so something exists that
		// can be clicked

		// Note that buttons must have children (or you get a warning), hence the empty
		// string
		children = <Button style={{ display: "none" }} >""</Button >;
	}
	return React.Children.map(children, (child) => {
		// have to check if child is valid element
		if (_.isObject(child) && React.isValidElement(child)) {
			return React.cloneElement(child, { onClick, id });
		}
		return child;
	});
}
