import * as React from "react";
import { ClassesType } from "../styling/clockTreeStyles";
import { GenericNode, IGenericNodeProps } from "./GenericNode";

// A normal node (square), but smaller with an X in the middle

export const PinFunctionNode = React.memo((props: IGenericNodeProps & ClassesType) => {
	const { classes } = props;
	return (
		<GenericNode {...props} >
			<svg className={classes.svgNodeContainer}>
				<line x1="0" y1="100%" x2="100%" y2="0" className={classes.line} />
				<line x1="100%" y1="100%" x2="0" y2="0" className={classes.line} />
			</svg>
		</GenericNode>
	);
});
