import * as React from "react";
import * as _ from "lodash";
import { ConfigStoreActions } from "../../services/configStore";
import { ClockTreeNode } from "../../services/instanceContainers/clockTreeNode";
import { CModuleInstance, IConfigProps } from "../../services/objectManagers/ui/moduleInstance";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { Typography } from "../../imports/material-ui-imports";
import { shouldShowLongDescription } from "../../services/utils";
import { DisplayLongDescButton, LongDescription } from "../LongDescription";
import { ResourceType } from "../../services/resources/metaContentLoaders/resourceLoader";

// This component represents the configurables for the currently selected node in the clock tree

interface IClockTreeProps {
	actions: ConfigStoreActions;
	treeNode: ClockTreeNode;
}

type IProps = IClockTreeProps
	& Omit<IConfigProps, "instMgr" | "productLookupName">
	& IGlobalServiceProps

const divStyle = { width: "100%", height: "100%", display: "flex", flexDirection: "column", overflowY: "hidden" } as const;
const headerContainerStyle = { padding: 8 } as const;
const contentContainerStyle = { flex: 1, height: "100%", overflowY: "auto" } as const;

export class ClockTreeConfigurables extends React.Component<IProps> {

	public override render() {
		const { actions, treeNode, ...rest } = this.props;
		const selection = treeNode.getSelection().instanceId;
		const instMgr = treeNode.getIpInstanceMgr(selection);
		const moduleMgr = instMgr.getModuleMgr();
		const showLongDescription = shouldShowLongDescription(moduleMgr, false);

		return (
			<div style={divStyle}>
				<div style={headerContainerStyle}>
					<Typography variant="button" display="inline" gutterBottom>
						{instMgr.getDisplayName(this.props.displayScriptName)}
					</Typography>
					<DisplayLongDescButton
						onClick={this.toggleLongDescription}
						name={moduleMgr.getDisplayName(false)}
						hidden={!moduleMgr.getLongDescription()}
					/>
				</div>
				<div style={contentContainerStyle}>
					{showLongDescription &&
						<LongDescription
							id="module_documentation"
							closeDescription={this.toggleLongDescription}
							longDescription={moduleMgr.getLongDescription()}
							canonicalName={moduleMgr.getName()}
							resourceType={ResourceType.CODE}
							disableClose={false}
							resourceLoader={this.props.resourceLoader}
							formatter={this.props.formatter}
							actions={this.props.actions}
						/>
					}
					<CModuleInstance
						instMgr={instMgr}
						{...rest}
						actions={this.props.actions}
						productLookupName={moduleMgr.getName()}
					/>
				</div>
			</div>
		);
	}

	private toggleLongDescription = () => {
		const selection = this.props.treeNode.getSelection().instanceId;
		const instMgr = this.props.treeNode.getIpInstanceMgr(selection);
		const moduleMgr = instMgr.getModuleMgr();
		const showLongDescription = shouldShowLongDescription(moduleMgr, false);
		this.props.actions.setShowUserLongDescPref(moduleMgr, !showLongDescription);
	}
}
