import * as React from "react";
import {
	// Note that we are using the MUI tooltip, and not our own wrapper.  We do 
	// this because our wrapper adds a <span> over top of the child in order to
	// work with disabled and internal components, and also so that the 
	// onChange of Tabs gets a callback.  Ideally, we need to fix our wrapper 
	// so it can be used	
	Tooltip,
} from "../../../imports/material-ui-imports";
import { generateToolTipProps } from "../../Tooltip";

// Renders a <div> at a specific position
// Used as a building block for other components

interface IProps {
	x: number;
	y: number;
	width?: number,
	height?: number,
	onSelect?: () => void;
	tooltip?: string;
	className: string;
}

export function PositionedDiv({ x, y, width, height, onSelect, tooltip, className, children }: React.PropsWithChildren<IProps>) {

	return (
		<Tooltip {...generateToolTipProps(tooltip)}>
			<div
				style={{
					transform: `translate(${x}px, ${y}px)`,
					width: width,
					height: height,
				}}
				onClick={onSelect}
				className={className}
			>
				{children}
			</div>
		</Tooltip>
	);
}
