import React = require("react");
import { IGlobalServiceProps } from "./IGlobalServicesProps";

interface IState {
	error: Error;
}

export class ErrorBoundary extends React.Component<IGlobalServiceProps, IState> {
	constructor(props: IGlobalServiceProps) {
		super(props);
		this.state = { error: null };
	}

	public override componentDidMount() {
		this.props.errorStore.onException().addListener(this.handleException);
	}

	public override componentWillUnmount() {
		this.props.errorStore.onException().removeListener(this.handleException);
	}

	public override componentDidCatch(error: Error) {
		this.props.errorStore.registerException(error);
	}

	public override render() {
		return (
			!this.state.error &&
			<span>{this.props.children}</span>
		);
	}

	private handleException = (error: Error) => {
		const { modalService, errorStore } = this.props;
		this.setState({ error },
			() => {
				if (error) {
					modalService.showOhSnapErrorModal(error, () => errorStore.clearException());
				}
			});
	}
}
