import * as _ from "lodash";
import React = require("react");

import { InterfaceInstanceMgr } from "../interfaceInstance";
import { DropDown } from "../../../components/DropDown";

interface IUseCaseSelectionProps {
	instMgr: InterfaceInstanceMgr;
	onChange: (useCaseName: string) => void;
}

export class UseCaseSelection extends React.PureComponent<IUseCaseSelectionProps, {}> {

	public override render() {
		const iface = this.props.instMgr.managedObject.$interface;
		const useCases = iface.useCases;
		const sortedUseCases = _.sortBy(useCases, (uc) => uc.description);
		const selectedUseCase = this.props.instMgr.getUseCaseMgr().getValue();
		const options = _.map(sortedUseCases, (useCase) => {
			return {
				name: useCase.name,
				displayName: useCase.description,
			};
		});

		return (
			<DropDown
				id="reqUseCase"
				onChange={this.props.onChange}
				selectedOptionName={selectedUseCase}
				enabledOptions={options}
				disabled={false}
				displayScriptName={false}
			/>
		);
	}
}
