import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/clockTreeStyles";
import { Multiplier } from "clockTree";
import { IMultiplyOrDivideNodeProps, MultiplyOrDivideNode } from "./MultiplyOrDivideNode";

// A multiplier node is a rectangle with the multiplication amount in the middle.  If the multiplication is configurable, then that 
// amount becomes a drop down

type IProps = Omit<IMultiplyOrDivideNodeProps, "formatPrefix" | "values" | "mgr" | "currentValue">;
export function MultiplierNode(props: IProps & ClassesType) {
	const ipInstance = props.node.data.ipInstance as Multiplier;
	const mgr = props.treeNode.getIpInstanceMgr(ipInstance.name).memberMgrs.multiplyValue;
	const value = mgr?.getValue() ?? _.first(ipInstance.multiplyValues);
	return <MultiplyOrDivideNode
		{...props}
		formatPrefix={"X"}
		values={ipInstance.multiplyValues}
		currentValue={value}
		mgr={mgr}
	/>;
}
