import { ReferenceFile } from "dataInterfaces";
import { BaseFileList } from "../../FileList";
import React = require("react");
import { ReferencedFilesViewMgr } from "../../../services/ui/outputView";
import { IGlobalServiceProps } from "../../IGlobalServicesProps";
import { ITemplateActions } from "../../actions/ITemplateActions";
interface IProps {
	actions: ITemplateActions;
	mgr: ReferencedFilesViewMgr;
}

export function ReferencedFileView(props: IProps & IGlobalServiceProps) {
	return <BaseFileList<ReferenceFile>
		{...props}
		id="referenced"
		files={props.mgr.getReferences()}
		hasErrors={false} // No need to decorate in this view, as the files are always physically present
		showSaveIcons={false} // No need to save files that are in the SDK and not generated
	/>;
}
