import * as _ from "lodash";
import React = require("react");
import { Button, Grid, Typography, PropTypes } from "../imports/material-ui-imports";
import { PlusCircleOutline, DeleteSweep } from "../imports/mdi-material-ui-imports";
import { commonStyles } from "./styles/common";
import { ModuleMgr } from "../services/instanceContainers/module";
import { ConfigStoreActions } from "../services/configStore";
import { InterfaceMgr } from "../services/instanceContainers/interface";
import { Popup } from "./Popup";
import { CannotBeRemovedPopup } from "./CannotBeRemovedPopup";
import { IFormatter } from "../services/formatting/formattingTypes";
import { IMyListItem } from "../services/IMyListItem";
import { FileModuleMgr } from "../services/instanceContainers/fileModuleMgr";
import { DisplayLongDescButton } from "./LongDescription";
import { ModuleInstanceAdderMgr } from "../services/objectManagers/moduleInstanceAdderMgr";
import { Tooltip } from "./Tooltip";

interface IProps<T extends InterfaceMgr | ModuleMgr> {
	selectedTreeNode: T;
	actions: ConfigStoreActions;
	displayScriptName: boolean;
	formatter: IFormatter;
	showLongDescription: boolean;
	hideLongDescriptionButton?: boolean;
	title: string;
}

const addItemLayoutStyle: React.CSSProperties = {
	alignSelf: "center",
};

interface ButtonProps {
	text: string;
	disabled: boolean;
	title: string;
	onClick: () => void;
	id: string;
}

interface IBaseProps extends IProps<InterfaceMgr | ModuleMgr> {
	addButton: ButtonProps;
	removeButton?: ButtonProps;
	getPopupContent: () => JSX.Element;
	displayScriptName: boolean;
}

export class StaticHeader extends React.Component<IProps<ModuleMgr>> {
	public override render() {

		const moduleMgr = this.props.selectedTreeNode as ModuleMgr;
		const addDisabled = moduleMgr.staticAddDisabled();
		const removeDisabled = moduleMgr.removeModuleDisabled();

		const addButton = {
			text: "Add",
			title: "Add",
			disabled: addDisabled,
			id: "addStaticBtn",
			onClick: () => this.props.actions.addStatic(moduleMgr),
		};

		const removeButton = {
			text: "Remove All",
			title: "Remove All",
			id: "removeModuleBtn",
			disabled: removeDisabled,
			onClick: () => this.props.actions.removeModule(moduleMgr),
		};

		return (
			<BaseHeader
				{...this.props}
				addButton={addButton}
				removeButton={removeButton}
				getPopupContent={this.getPopupContent}
			/>
		);
	}

	private getPopupContent = () => {
		const moduleMgr = this.props.selectedTreeNode as ModuleMgr;
		const ownershipInfo = moduleMgr.static && moduleMgr.static.getOwnershipInfo();
		const removeDisabled = moduleMgr.removeModuleDisabled();

		return ownershipInfo && removeDisabled &&
			<CannotBeRemovedPopup
				formatter={this.props.formatter}
				reason={ownershipInfo}
			/>;
	}
}

export class InstanceHeader extends React.Component<IProps<ModuleMgr>> {
	public override render() {

		const moduleMgr = this.props.selectedTreeNode;
		const removeDisabled = moduleMgr.removeModuleDisabled();
		const isSummary = moduleMgr.getUIAdd() === "summary";
		const isStaticAndInstance = moduleMgr.getUIAdd() === "staticAndInstance";

		const addButton = {
			text: "Add",
			title: "Add",
			disabled: moduleMgr.instanceAddDisabled(),
			id: "viewRequirementAddBtn",
			onClick: () => this.props.actions.addInstance(moduleMgr),
		};

		const removeButton = {
			text: "Remove All",
			title: "Remove All",
			disabled: removeDisabled,
			id: "viewRequirementRemoveBtn",
			onClick: () => this.props.actions.removeModule(moduleMgr),
		};

		return (
			<BaseHeader
				{...this.props}
				addButton={!isSummary && addButton}
				removeButton={!isSummary && !isStaticAndInstance && removeButton}
				getPopupContent={this.getPopupContent}
			/>
		);
	}

	private getPopupContent = () => {

		const moduleMgr = this.props.selectedTreeNode;
		const formatter = this.props.formatter;

		const removeDisabled = moduleMgr.removeModuleDisabled();

		if (removeDisabled) {
			if (!_.isEmpty(moduleMgr.instances)) {
				return (<span>Some instances are currently owned/shared by others.</span>);
			}

			if (moduleMgr.static) {
				const ownershipInfo = moduleMgr.static.getOwnershipInfo();
				return (
					<CannotBeRemovedPopup
						formatter={formatter}
						reason={ownershipInfo}
					/>
				);
			}
		}

		return null;
	}
}

interface IModuleInstanceAdderHeaderProps extends IProps<ModuleMgr> {
	adderMgr: ModuleInstanceAdderMgr;
	cannotRemoveReason: string;
}

export class ModuleInstanceAdderHeader extends React.Component<IModuleInstanceAdderHeaderProps> {
	public override render() {

		const adderMgr = this.props.adderMgr;

		const addButton = {
			text: "Add",
			title: "Add",
			disabled: adderMgr.instanceAddDisabled(),
			id: `${adderMgr.getName()}AddBtn`,
			onClick: () => this.props.actions.adderAddInstance(this.props.adderMgr),
		};

		const removeButton = {
			text: "Remove All",
			title: "Remove All",
			disabled: !adderMgr.canRemoveAll(),
			id: `${adderMgr.getName()}RemoveBtn`,
			onClick: () => this.props.actions.adderRemoveAll(this.props.adderMgr),
		};

		return (
			<BaseHeader
				{...this.props}
				addButton={addButton}
				removeButton={removeButton}
				getPopupContent={() =>
					adderMgr.getNumberOfUsed() > 0 &&
					!adderMgr.canRemoveAll() &&
					<span>{this.props.cannotRemoveReason}</span>
				}
			/>
		);
	}
}

// normal interfaces
export class InterfacesHeader extends React.Component<IProps<InterfaceMgr>> {
	public override render() {
		const selectedTreeNode = this.props.selectedTreeNode;
		const addButton = {
			text: "Add",
			title: "Add",
			disabled: selectedTreeNode.instanceAddDisabled(),
			id: "viewRequirementAddBtn",
			onClick: () => this.props.actions.addInstance(this.props.selectedTreeNode),
		};

		const listItems: IMyListItem[] = selectedTreeNode.getInstances();
		const removeDisabled = _.every(listItems, (item) => !item.isRemovable());
		const removeButton = {
			text: "Remove All",
			title: "Remove All",
			disabled: removeDisabled,
			id: "viewRequirementRemoveBtn",
			onClick: () => this.props.actions.removeAllInstances(this.props.selectedTreeNode),
		};

		const popupContent = (listItems.length > 0 && removeDisabled) ?
			<span>Some instances are currently owned/shared by others.</span> : null;

		return (
			<BaseHeader
				{...this.props}
				addButton={addButton}
				removeButton={removeButton}
				getPopupContent={() => popupContent}
			/>
		);
	}
}

interface IFileRequirementHeaderProps extends IProps<FileModuleMgr> {
	moduleMgr: FileModuleMgr;
}

export class FileRequirementHeader extends React.Component<IFileRequirementHeaderProps> {

	public override render() {

		const { moduleMgr } = this.props;

		const addButton = {
			text: "Add",
			title: "Add",
			disabled: moduleMgr.staticAddDisabled(),
			id: "addStaticBtn",
			onClick: () => this.props.actions.addStatic(moduleMgr),
		};

		const removeButton = {
			text: "Remove All",
			title: "Remove All",
			id: "removeModuleBtn",
			disabled: moduleMgr.removeModuleDisabled(),
			onClick: () => this.props.actions.removeModule(moduleMgr),
		};

		return (
			<BaseHeader
				{...this.props}
				addButton={addButton}
				removeButton={removeButton}
				getPopupContent={() => null}
				selectedTreeNode={moduleMgr}
			/>
		);
	}
}

class BaseHeader extends React.Component<IBaseProps> {
	public override render() {

		const { addButton, removeButton, ...nonButton } = this.props;

		return (
			<Grid container justify="space-between" alignItems="flex-end">
				<Grid item key="info" style={addItemLayoutStyle}>
					<Heading {...nonButton} />
				</Grid>
				<Grid item key="buttons">
					{addButton && <Tooltip
						disabled={!addButton.disabled} title={"Instance limit has been reached."} placement={"top-start"}>
						<HeaderButton
							id="viewRequirementAddBtn"
							color="primary"
							key="add"
							{...addButton}>
							<PlusCircleOutline style={{ ...commonStyles.smallButtonIcon }} />
						</HeaderButton>
					</Tooltip>}
					{removeButton && <Popup
						align={"top"}
						getContent={this.props.getPopupContent}
						hoverTarget={
							<HeaderButton
								id="viewRequirementRemoveBtn"
								key="remove"
								disabled={removeButton.disabled}
								color="primary"
								{...removeButton}>
								<DeleteSweep style={{ ...commonStyles.smallButtonIcon }} />
							</HeaderButton>
						}
					/>}
				</Grid>
			</Grid>
		);
	}
}

interface HeadingProps {
	selectedTreeNode: ModuleMgr | InterfaceMgr;
	title: string;
	actions: ConfigStoreActions;
	displayScriptName: boolean;
	showLongDescription: boolean;
	hideLongDescriptionButton?: boolean;
}

class Heading extends React.Component<HeadingProps, {}> {
	public override render() {

		const { selectedTreeNode, showLongDescription } = this.props;
		const hideLongDescriptionButton
			= _.isUndefined(this.props.hideLongDescriptionButton) ? false : this.props.hideLongDescriptionButton;

		const moduleMgr = selectedTreeNode instanceof ModuleMgr && selectedTreeNode;

		return (
			<span>
				<Typography id="headingTitle" variant="subtitle2" style={{ display: "inline-block", fontWeight: 600 }}>
					<span>{this.props.title}</span>
				</Typography>
				{moduleMgr && !hideLongDescriptionButton &&
					<DisplayLongDescButton
						onClick={() =>
							this.props.actions.setShowUserLongDescPref(moduleMgr, !showLongDescription)}
						name={moduleMgr.getDisplayName(false)}
						hidden={!moduleMgr.getLongDescription() || showLongDescription}
					/>
				}
			</span>
		);
	}
}

interface IHeaderButtonProps {
	id: string;
	text: string;
	disabled: boolean;
	color: PropTypes.Color;
	onClick: () => void;
}

class HeaderButton extends React.PureComponent<IHeaderButtonProps, {}> {
	public override render() {
		return (
			<Button
				id={this.props.id}
				onClick={this.props.onClick}
				disabled={this.props.disabled}
				variant="contained"
				size="small"
				color={this.props.color}
				style={commonStyles.button}
			>
				{this.props.children}
				{this.props.text}
			</Button>
		);
	}
}
