import { ITreeNodeStatus } from "../../components/TreeNode";
import { TreeNodeStatusType } from "../treeNodeStatusType";

// common Tree Entry Status implementation
export class TreeNodeStatus implements ITreeNodeStatus {
	private status: IStatusProps;

	constructor(
		private readonly type: TreeNodeStatusType,
		private readonly id: string,
	) {
	}

	public getID() {
		return this.id;
	}

	public getType() {
		return this.type;
	}

	public hasError() {
		return this.status.error;
	}

	public hasWarning() {
		return this.status.warning;
	}

	public isSuccess() {
		return this.status.success;
	}

	public getText() {
		return this.status.text;
	}

	public setStatus(statusProp: IStatusProps) {
		this.status = statusProp;
	}
}

interface IStatusProps {
	error: boolean;
	warning: boolean;
	success: boolean;
	text?: string;
}
