import * as _ from "lodash";
import { AdaptedDeviceInfo } from "dataInterfaces";
import { AObjectMgr } from "./object";
import { ModuleInstance, HardwareComponentSignal, HardwareComponent } from "public/runtime";
import { createChildIdentifier, createMemberValueAssignmentStatement, getBPVariableName } from "../scripting/serialize";
import { ModuleToHardwareMap } from "../moduleToHardwareMap";
import { DropDownOption } from "../../components/ComponentUtils";
import { getDisplayName } from "../utils";
import { SerializationOptions, MigrationType } from "../scripting/toScript";
import { FormattersMap } from "../formatting/formattersMap";
import { IHardwareOptions } from "./options";
import { HardwareConfigurable, Configurable } from "public/defs";
import { SCHEMA } from "../JSONschemaValidator";
import { assignmentToString } from "../niceExceptions";
import { shallowReadOnlyProxyHandler } from "./proxyHandlers/shallowReadOnlyProxyHandler";
import { Validations } from "./validations";
import { ConfigurableMgr } from "./configurables/configurableMgr";
import { validateDisabledOptions } from "./configurables/baseEnumerationConfigurableMgr";
import { validateConfigurable } from "./configurables/configurable";

export interface HardwareOption extends DropDownOption {
	component?: HardwareComponent;	// stores the underlying HardwareComponent associated with this option
	isHeading?: boolean; // indicates if this entry is there only for grouping
}

export class HardwareMemberMgr extends ConfigurableMgr<
	HardwareComponent, ModuleInstance, Configurable<HardwareComponent> & HardwareConfigurable>
	implements IHardwareOptions {

	private uiOptions: HardwareOption[]; // calculated lazily

	public constructor(
		parentObjectMgr: AObjectMgr<ModuleInstance>,
		hardwareConfig: HardwareConfigurable,
		private readonly moduleToHardwareMap: ModuleToHardwareMap,
		private readonly deviceData: AdaptedDeviceInfo,
		formattersMap: FormattersMap,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			{
				displayName: "Use Hardware",
				description: "Select the hardware to use, or 'None' to use available header pins",
				default: null,
				...hardwareConfig,
				readOnly: false,
			},
		);

		const context = `Configurable "$hardware" of "${this.getParentRuntimeObj().$module.$name}"`;
		validateConfigurable(hardwareConfig, context, SCHEMA.HardwareConfigurable);

		// No choices === don't show option
		// Since this uses a member function, we need to set it here vs in the def passed to super

		this.uiState.hidden = _.isEmpty(this.getValidComponents());
	}

	public override getUIHash(_validations: Validations): string {

		// return undefined for the same reason as ObjectMemberManager

		return undefined;
	}

	public override generateScriptStatements(parentIdentifier: string, options: SerializationOptions) {
		const rValue = this.getScriptRValue();
		return [
			createMemberValueAssignmentStatement(
				this.def,
				parentIdentifier,
				options.deviceDataMigration ? toSafeRValue(rValue, this.value) : rValue,
				{ shouldQuoteStrings: false }),
		];
	}

	public getCLIOptions() {

		// The UI options never have a separate "disabledOptions" set because it is currently
		// grouped as a tree, and moving disabled entries to the bottom looks weird.  But we 
		// want that separation for the CLI options.  So get just the enabled options, filter
		// out the headings, and split into a disabled/enabled set

		// Note: it's likely easier to calculate this without re-formatting the UI options,
		// but since this exists only for testing, it seems like it would be better to base
		// it on what the UI shows

		const [enabledOptions, disabledOptions] = _.chain(this.getUIOptions().enabledOptions)
			.filter((o) => !o.isHeading)
			.partition((o) => !o.isDisabled)
			.value();

		// Now re-format each set to match what we are supposed to return

		return {
			enabledOptions: _.map(enabledOptions, (o) => o.component),
			disabledOptions: _.map(disabledOptions, (o) => ({ component: o.component, reason: o.description })),
		};
	}

	public getUIOptions() {

		// Generate a tree of selectable options and save it for re-use later

		if (_.isUndefined(this.uiOptions)) {
			this.uiOptions = [
				{
					name: "None",
					displayName: "None",
					component: null,
					description: "Solve for free pins on the header not associated with any hardware",
				},
				...this.createOptions(),
			];
		}

		// If we don't have any disabled options, we can return the above tree directly

		const disabledOptions = this.getDisabledComponents();
		if (_.isEmpty(disabledOptions)) {
			return { enabledOptions: this.uiOptions, disabledOptions: [] };
		}

		// Otherwise, mark the disabled options disabled and update the tool tip to be
		// the reason why

		const enabledOptions = _.map(this.uiOptions, (o) => {
			const disabled = _.find(disabledOptions, (d) => d.component === o.component);
			if (disabled) {
				return {
					...o,
					description: disabled.reason,
					isDisabled: true,
				};
			}
			return o;
		});

		return { enabledOptions, disabledOptions: [] as HardwareOption[] };
	}

	protected override createManagedUIState() {

		// Do not allow meta-content to change

		return new Proxy(this.uiState, shallowReadOnlyProxyHandler);
	}

	// If we are migrating, never serialize $hardware.  That will cause all side effects of $hardware to self 
	// serialize when migrating because the base class version of shouldSerialize will check "if I was set by 
	// configurable x, and x isn't being serialized, then serialize me"

	// Also, we can't just call super.shouldSerialize() because TOOL_ASSIGN won't capture the cause (and if
	// this is a shared module, there will be multiple causes).  Thus if all the parents are later removed,
	// then we won't see ourself as a side effect and thus serialize ourself.
	// See https://jira.itg.ti.com/browse/PMUX-1895

	protected override shouldSerialize(options: SerializationOptions): boolean {
		const setNotByParent = null !== this.value && !this.uiState.readOnly;
		return options.deviceDataMigration !== MigrationType.BOARD_TO_DEVICE &&
			(super.shouldSerialize(options) || setNotByParent);
	}

	protected override validateValue(value: HardwareComponent, forceWrite: boolean) {
		super.validateValue(value, forceWrite);

		if (null !== value) {

			if (!_.includes(this.getValidComponents(), value)) {
				const validOptions = ["null", ..._.map(this.getValidComponents(), (c) => this.getScriptRValue(c))];
				throw new Error(`Invalid hardware component assigned, valid options are\n${validOptions.join("\n")}`);
			}
		}

		if (!forceWrite && value !== this.getValue() && this.uiState.readOnly) {
			const reason = _.isString(this.uiState.readOnly) ? this.uiState.readOnly : "configurable is read only";
			throw new Error(`Cannot write $hardware: ${reason}`);
		}
	}

	private getValidComponents() {
		return this.moduleToHardwareMap.getComponents(this.getParentRuntimeObj().$module);
	}

	private getDisabledComponents() {
		if (!this.def.getDisabledOptions) {
			return [];
		}

		// Call into meta-data to get what's disabled

		const validComponents = this.getValidComponents();
		const disabledComponents = this.def.getDisabledOptions(this.getParentRuntimeObj(), validComponents);

		// Validate returned result

		validateDisabledOptions(disabledComponents, "$hardware", (o) => {
			if (!_.includes(validComponents, o.component)) {
				throw new Error(`$hardware: attempted to disable unknown option '${assignmentToString(o.component)}'`);
			}
		});

		return disabledComponents;
	}

	// returns list of compatible component options, flattening the subcomponents into the list in order

	private createOptions(
		validComponents = this.getValidComponents(),
		components = this.deviceData.board ? this.deviceData.board.components : {},
		parentName = "",
		level = 0,
	) {
		const flatOptions: HardwareOption[] = [];

		_.each(components, (component) => {

			// Ignore this component if:
			// 1. this is a subcomponent, and it is aliased to a top-level component
			//    - if the subComponent is already exposed as a top-level component, then we don't want it to
			//      show up multiple times under each sub-component that happens to use it as the author as clearly
			//      indicated that users should know what the subcomponent is.
			// 2. this is a top component, and it's alias has already been added
			//    - top level components may be aliases of each other for cross-device compatibility
			//      (ie different keys point to the same component) and we don't want to list that same component twice
			// Note: 2 subcomponents that are aliases of itself are still added to the list right now

			if (!(parentName !== "" && this.isTopComponent(component)) &&
				!(parentName === "" && _.some(flatOptions, (option) => option.component === component))) {

				// Booster pack components will have the booster pack display name appended for identification

				const displayName =
					(this.isTopComponent(component) && component.source.definition !== this.deviceData.board.source) ?
						`${getDisplayName(component, false)} (${getDisplayName(component.source, false)})` :
						getDisplayName(component, false);

				const option: HardwareOption = {
					name: parentName + component.name,
					displayName,
					component,
					level,
					description: component.description,
				};

				const isValidComponent = _.includes(validComponents, component);
				const subOptions =
					this.createOptions(validComponents, component.subComponents, component.name, level + 1);

				// heading entry (disabled) if it is not a valid option, but has sub-options

				option.isHeading = option.isDisabled = !isValidComponent && !_.isEmpty(subOptions);

				// include this option if it is a valid component, or it is a heading

				if (isValidComponent || option.isHeading) {
					flatOptions.push(option);
					flatOptions.push(...subOptions);
				}
			}
		});

		return flatOptions;
	}

	// checks if the given component is a top component (ie; no parents/is not a subcomponent)

	private isTopComponent(component: HardwareComponent) {
		return _.some(this.deviceData.board.components, (topComponent) => topComponent === component);
	}

	private getScriptRValue(component = this.value): string {
		if (!component) {
			return null;
		} else if (this.deviceData.board.components[component.name] !== component) {

			// Not a top level component - create an rvalue for the parent, and then attach 
			// .subComponents.ourKey

			const parent = _.first(component.$parents);
			return createChildIdentifier(
				`${this.getScriptRValue(parent)}.subComponents`,
				_.findKey(parent.subComponents, (value) => value === component));
		} else if (component.source.definition === this.deviceData.board.source) {

			// component is directly on the board

			return createChildIdentifier(
				"system.deviceData.board.components", component.name);
		} else {

			// component is from the boosterpack, not the board

			const boosterpackName = getBPVariableName(component.source);
			const componentName = _.replace(component.name, `${component.source.name}/`, "");
			return createChildIdentifier(`${boosterpackName}.components`, componentName);
		}
	}
}

export function fetchPinConnections(signalTypes: string[], component: HardwareComponent) {
	if (!component || _.isEqual(signalTypes, ["external-to-hardware"])) {
		return null;
	}

	const signals = _.isEmpty(component.signals) ? gatherSubComponentSignals(component) : _.values(component.signals);

	return _.chain(signals)
		.filter((signal) => _.some(signal.type, (type) => _.includes(signalTypes, type)))
		.map((signal) => signal.devicePin)
		.value();
}

function gatherSubComponentSignals(component: HardwareComponent): HardwareComponentSignal[] {
	return ([
		..._.values(component.signals),
		..._.flatMap(component.subComponents, gatherSubComponentSignals),
	]);
}

function toSafeRValue(rvalue: string, component: HardwareComponent) {
	// We want to convert something like:
	// system.deviceData.board.components.name.subComponent.name2
	// to
	// _.get(system.deviceData.board.components, ["name", "subComponent", "name2"], "displayName")
	// so that if any component no longer exists, an invalid string assignment of the original 
	// display name is assigned instead

	// Convert any array accesses to dots, then split at ".components."

	const [obj, path] = _.chain(rvalue)
		.replace(/\["/g, ".")
		.replace(/"\]/g, ".")
		.trimEnd(".")
		.split(".components.")
		.value();
	return `_.get(${obj}.components, ${JSON.stringify(_.split(path, "."))}, "${getDisplayName(component, false)}")`;
}
