import { AMemberMgr } from "./member";
import { ModuleInstanceMgr } from "./moduleInstance";
import { ModuleInstance } from "public/runtime";
import { FormattersMap } from "../formatting/formattersMap";
import { ModuleInstanceAdderMgr } from "./moduleInstanceAdderMgr";
import { Statement } from "../scripting/serialize";
import * as _ from "lodash";
import { ObjectMemberManager } from "./objectMember";
import { assignmentToString } from "../niceExceptions";
import { templateSettings } from "../resources/templateCompiler";

export class InstanceAdderLengthLegacyMemberMgr extends AMemberMgr<number, ModuleInstance> {
	private nameMapTemplate: _.TemplateExecutor;
	constructor(
		parentObjectMgr: ModuleInstanceMgr,
		formattersMap: FormattersMap,
		name: string,
		initValue: number,
		private adderMgr: ModuleInstanceAdderMgr,
		private nameMap: string[] | string, // either an explicit mapping array or a template string
	) {
		super(
			parentObjectMgr,
			formattersMap,
			{
				name,
			},
			initValue,
		);
		if (_.isString(nameMap)) {
			this.nameMapTemplate = _.template(nameMap, { ...templateSettings, variable: undefined });
		}
	}

	public override get() {
		return this.adderMgr.getNumberOfUsed();
	}

	public override set(val: number) {
		if (!_.isInteger(val)) {
			throw new Error(
				`The value ${assignmentToString(val)} assigned to ${this.def.name}(used as lengthConfigName) must be an integer.`,
			);
		}
		if (_.isArray(this.nameMap) && val > this.nameMap.length) {
			throw new Error(
				`There are not enough(${this.nameMap.length}) elements in instanceNameMapping to satisfy ${val} children.`,
			);
		}
		this.clearAllAliasInstances();
		this.adderMgr.create(val);
		this.createAllAliasInstances();
	}

	public setValueFromArgs(val: number) {
		this.set(val);
	}

	public setValueFromRequiredArgs() {
		throw new Error("Instance adder's legacy compatibility length member does not support required args.");
	}

	public removeArgs() {
		throw new Error("Instance adder's legacy compatibility length member should not have args removed.");
	}

	public removeReqArgs() {
		this.removeArgs();
	}

	protected override shouldSerialize() {
		return false;
	}

	protected generateScriptStatements(): Statement[] {
		return [];
	}

	private getListOfAliasInstanceNames(count: number) {
		if (_.isArray(this.nameMap)) {
			return _.slice(this.nameMap, 0, count);
		} else {
			return _.map(_.range(count), (i) => this.nameMapTemplate({ index: i }));
		}
	}

	private clearAllAliasInstances() {
		_.each(this.getListOfAliasInstanceNames(this.adderMgr.getNumberOfUsed()),
			(instName) => {
				if (this.parentObjectMgr.memberMgrs[instName]) {
					this.parentObjectMgr.removeMember(this.parentObjectMgr.memberMgrs[instName]);
				}
			});
	}

	private createAllAliasInstances() {
		_.each(this.getListOfAliasInstanceNames(this.adderMgr.getNumberOfUsed()),
			(instName, index) => {
				if (
					this.parentObjectMgr.memberMgrs[instName] &&
					!(this.parentObjectMgr.memberMgrs[instName] instanceof InstanceAdderAliasInstanceMemberManager)
				) {
					throw new Error(
						`${assignmentToString(instName)} cannot be used as instanceNameMapping because a member of the same name exists.`,
					);
				}
				new InstanceAdderAliasInstanceMemberManager(
					this.adderMgr.instances[index],
					this.formattersMap,
					this.parentObjectMgr as ModuleInstanceMgr,
					instName,
				);
			});
	}
}

export class InstanceAdderAliasInstanceMemberManager
	extends ObjectMemberManager<ModuleInstanceMgr, ModuleInstance, ModuleInstanceMgr> {
	constructor(
		valueObjectMgr: ModuleInstanceMgr,
		formattersMap: FormattersMap,
		parentObjectMgr: ModuleInstanceMgr,
		aliasInstanceName: string,
	) {
		super(
			valueObjectMgr,
			formattersMap,
			{ name: aliasInstanceName },
			parentObjectMgr,
		);
	}

	public override remove() {
	}

	public override generateScriptStatements(): Statement[] {
		return [];
	}

	protected override shouldSerialize() {
		return false;
	}
}
