import * as _ from "lodash";
import React = require("react");
import DeviceData = require("dataInterfaces");
import { HeaderPin } from "public/defs";
import {
	BoardViewLabelEntry, BoardViewEmptyEntry, Placement, BoardViewDevicePinEntry,
} from "./BoardViewEntry";
import { PinInfo } from "../services/pinInfo";
import { ATheme } from "./styles/themes";

const listContainerCommonStyle: React.CSSProperties = {
	listStyleType: "none",
	padding: 0,
	margin: 0,
	borderRadius: "4px",
};

const listContainerStyle: React.CSSProperties = {
	...listContainerCommonStyle,
	display: "inline-block",
};

const listContainerHorizontalStyle: React.CSSProperties = {
	...listContainerCommonStyle,
	display: "inline-flex",
	width: "100%",
};

export interface IBoardViewCollectionProps {
	theme: ATheme;						// theme
	start: number;						// the first pin number
	end: number;						// the last pin number (can be greater or less than start)
	increment: number;					// controls the increment of pin numbers per entry
	type: "pin" | "label" | "empty";	// draw pins, labels, or an empty row/column
	shouldShowModeTable: boolean;		// determine whether to show mode table
	placement?: Placement;				// controls alignment of a label 
	displayNumbers?: boolean;			// determines if number should be displayed at the start/end of a pin column/row
	side1?: boolean;					// determines if left border (column) or top border (row) is needed
	side2?: boolean;					// determines if right border (column) or bottom border (row) is needed
	headerPins?: HeaderPin[];			// header pin information (can be used to look up the pin based on current pin number)
	devicePins?: DeviceData.NameToDevicePinMap;	// look up the device pin based on the header pin
	horizontal?: boolean;				// true if this is a row, false if column
	pinInfo: PinInfo;					// service to look up pin information
	focusedSubItemName?: string;		// the name of the selected item
	boardNumberOffset?: number; 		// offsets the header pin numbers
}

// draws a row or column of pins
export class BoardViewCollection extends React.Component<IBoardViewCollectionProps, {}> {
	public override render() {
		// array of pin entries to draw; 
		// can contain BoardViewLabelEntry, BoardViewEmptyEntry, or BoardViewDevicePinEntry components
		const entriesArr: JSX.Element[] = [];
		const offsetLabel = this.props.boardNumberOffset || 0;
		// head entry (if needed)
		if (this.props.displayNumbers) {
			// add a label entry for displaying numbers, or empty entry for non-pin row/columns (for alignment purposes)
			entriesArr.push(
				<BoardViewLabelEntry
					key={"header"}
					label={(this.props.type === "pin") ? (this.props.start + offsetLabel).toString() : null}
					placement={this.props.horizontal ? "left" : "top"}
					horizontal={this.props.horizontal}
				/>,
			);
		}

		// main entries (start, end, and increment will determine how many entries we will draw)
		for (let curPinNum = this.props.start;
			(this.props.start > this.props.end) ? curPinNum >= this.props.end : curPinNum <= this.props.end;
			(this.props.start > this.props.end) ? curPinNum -= this.props.increment : curPinNum += this.props.increment) {

			const curheaderPin = this.lookupHeaderPin(curPinNum);
			const key = curPinNum.toString();

			if (this.props.type === "empty") {
				entriesArr.push(<BoardViewEmptyEntry key={key} horizontal={this.props.horizontal} />);
			} else if (this.props.type === "label") {
				entriesArr.push(
					<BoardViewLabelEntry
						key={key}
						label={curheaderPin ? curheaderPin.name : curPinNum.toString()}
						placement={this.props.placement}
						horizontal={this.props.horizontal}
					/>,
				);
			} else {
				entriesArr.push(
					<BoardViewDevicePinEntry
						theme={this.props.theme}
						key={key}
						devicePin={this.lookupDevicePin(curheaderPin)}
						shouldShowModeTable={this.props.shouldShowModeTable}
						headerPin={curheaderPin}
						top={this.props.horizontal ? this.props.side1 : curPinNum === this.props.start}
						bottom={this.props.horizontal ? this.props.side2 : curPinNum === this.props.end}
						left={this.props.horizontal ? curPinNum === this.props.start : this.props.side1}
						right={this.props.horizontal ? curPinNum === this.props.end : this.props.side2}
						horizontal={this.props.horizontal}
						pinInfo={this.props.pinInfo}
						boardNumberOffset={this.props.boardNumberOffset}
					/>,
				);
			}
		}

		// footer entries (if needed)
		if (this.props.displayNumbers) {
			// add a label entry for displaying numbers, or empty entry for non-pin row/columns
			entriesArr.push(
				<BoardViewLabelEntry
					key={"footer"}
					label={(this.props.type === "pin") ? (this.props.end + offsetLabel).toString() : null}
					placement={this.props.horizontal ? "right" : "bottom"}
					horizontal={this.props.horizontal}
				/>,
			);
		}

		// add extra spacing at the end of the row
		if (this.props.horizontal) {
			entriesArr.push(<BoardViewEmptyEntry key="extraSpace" horizontal />);
		}

		return (
			<ul style={this.props.horizontal ? listContainerHorizontalStyle : listContainerStyle} >
				{
					_.map(entriesArr, (content) => {
						return (content);
					})
				}
			</ul>
		);
	}

	// return the HeaderPin associated with the given pin number
	private lookupHeaderPin(pinNum: number) {
		return _.find(this.props.headerPins, (pin) => pin.number === pinNum);
	}

	// return the DevicePin associated with the given header pin
	private lookupDevicePin(headerPin: HeaderPin) {
		return _.find(this.props.devicePins, (pin) => {
			return pin.name === headerPin.ball;
		});
	}
}
