import fsMod = require("fs");
import pathMod = require("path");
import child_processMod = require("child_process");
import { isNode, getProcess } from "./platform";

type CallbackType = (supported: boolean) => void;

let update: {
	supported: () => boolean,
	available: (callback: CallbackType) => void,
	install: () => void,
};

if (isNode()) {
	const fs = require("fs") as typeof fsMod;
	const path = require("path") as typeof pathMod;
	const childProcess = require("child_process") as typeof child_processMod;
	// privates
	const updateExecName = "autoupdate-windows.exe";
	let updateExecPath: string = null;
	let foundUpdateExec: boolean = null;

	const checkForUpdateExec = () => {
		if (foundUpdateExec === null) {
			const nwPath = path.dirname(getProcess().execPath);
			updateExecPath = path.resolve(nwPath, "../", updateExecName);
			foundUpdateExec = fs.existsSync(updateExecPath);
		}
	};

	// public
	update = {
		supported: () => {
			checkForUpdateExec();
			return foundUpdateExec;
		},
		available: (callback) => {
			const args = ["--check_for_updates", "true", "--mode", "unattended"];

			try {
				const proc = childProcess.spawn(updateExecPath, args, {});
				proc.on("exit", (code: number) => {
					// the update installer indicates weather an update is available by checking the process return codes
					if (code === 0) { // update available
						callback(true);
					} else { // update not available
						callback(false);
					}
				});
			} catch (e) {
				// if some error occurs, just swallow it and indicate no updates available
				console.error("Failed to check for updates! -> " + e);
				callback(false);
			}

		},
		install: () => {
			try {
				childProcess.spawn(updateExecPath, [], {
					detached: true,
				});
				const gui = require("nw.gui");
				gui.App.quit();
			} catch (e) {
				// if some error occurs, just swallow it and indicate no updates available
				console.error("Failed to start update installation! -> " + e);
			}
		},
	};
} else {
	update = {
		supported: () => {
			return false;
		},
		available: (callback) => {
			callback(false);
		},
		install: () => { },
	};
}

export function supported() {
	return update.supported();
}

export function available(callback: CallbackType) {
	return update.available(callback);
}

export function install() {
	update.install();
}
