import * as React from "react";
import * as _ from "lodash";
import { ConfigStoreActions } from "../../services/configStore";
import { ClockTreeZoomableGraph } from "./graph/ClockTreeZoomableGraph";
import { ClockTreeLowerPane } from "./ClockTreeLowerPane";
import { ClockTreeNode } from "../../services/instanceContainers/clockTreeNode";
import { IGlobalServiceProps } from "../IGlobalServicesProps";
import { Validations } from "../../services/objectManagers/validations";
import { commonStyles } from "../styles/common";
import { ResizableBorder } from "../ResizableBorder";
import { Dock } from "../actions/IOutputActions";

// This component represents the middle pane view for a clock tree, which is a graph based on the tree node selection
// in the left pane, with the specific module associated with the selected ipInstance underneath

interface IClockTreeProps {
	actions: ConfigStoreActions;
	validations: Validations;
	treeNode: ClockTreeNode;
	heightPercent: number;
	col3Width: number;
	outputDocking: Dock;
}

type IProps = IClockTreeProps
	& Omit<React.ComponentProps<typeof ClockTreeLowerPane>, "selectedTreeNode">
	& IGlobalServiceProps

export class ClockTreeView extends React.Component<IProps> {
	public override render() {
		const { actions, treeNode } = this.props;

		return <div style={commonStyles.columnFlexLayout}>
			<div style={{ overflow: "hidden", flex: 1 }}>
				<ClockTreeZoomableGraph
					onSelect={this.onSelect}
					actions={actions}
					treeNode={treeNode}
					validations={this.props.validations}
					errorStore={this.props.errorStore}
					displayScriptName={this.props.displayScriptName}
					formatter={this.props.formatter}
					resourceLoader={this.props.resourceLoader}
					modalService={this.props.modalService}
					notificationService={this.props.notificationService}
					theme={this.props.theme}
				/>
			</div>
			<ResizableBorder
				theme={this.props.theme}
				borderAfterChild={false}
				position={this.props.heightPercent}
				onPositionChanged={this.updateHeight}
				percentage={true}
				displayed={true}
				horizontal={false}
				showBorder={true}
			>
				<ClockTreeLowerPane
					{...this.props}
				/>
			</ResizableBorder>
		</div>;
	}

	private onSelect = (selection: string) => {
		this.props.actions.setSelectedMyListItem(
			this.props.treeNode, this.props.treeNode.getIpInstanceMgr(selection));
	}

	private updateHeight = (height: number) => {
		this.props.actions.setClockTreeHeight(height);
	}
}
