import * as _ from "lodash";
import React = require("react");
import { AsyncComponent } from "./AsyncComponent";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { AccountCircle, LogOut } from "../imports/mdi-material-ui-imports";
import { defaultTheme } from "./styles/themes";
import { getUserInfo } from "../services/accountManagement";
import { loginServer } from "../services/loginServer";
import { LogoutModal } from "./modals/LogoutModal";
import { commonStyles } from "./styles/common";
import { Tooltip } from "./Tooltip";

interface IState {
	userName: string;
	userLoggedIn: boolean;
}

interface IPropsBase {
	savingPromise: Promise<void>;
}

type IProps = IPropsBase & IGlobalServiceProps;

export class UserStatus extends AsyncComponent<IProps, IState> {

	public override state = {
		userName: "",
		userLoggedIn: true,
	};

	public override componentDidMount() {
		loginServer.onLoginChanged().addListener(this.listener);
		document.addEventListener("keydown", loginServer.userEvent, false);
		document.addEventListener("mousedown", loginServer.userEvent, false);
		super.componentDidMount();
	}

	public override componentWillUnmount() {
		document.removeEventListener("keydown", loginServer.userEvent);
		document.removeEventListener("mousedown", loginServer.userEvent);
		loginServer.onLoginChanged().removeListener(this.listener);
	}

	public override render() {
		if (this.state.userLoggedIn) {
			return <div>
				<AccountCircle
					style={{
						...commonStyles.smallIcon,
						verticalAlign: "middle",
						paddingRight: defaultTheme.theme.spacing(1),
					}} />
				{this.state.userName}
				<span style={{
					paddingLeft: defaultTheme.theme.spacing(2),
					paddingRight: defaultTheme.theme.spacing(2),
				}}>
					<Tooltip title={"Click to sign-out"}>
						<LogOut
							id="logout"
							style={{
								...commonStyles.smallIcon,
								position: "fixed",
								verticalAlign: "middle",
							}}
							onClick={() => loginServer.handleLogOut()} >
						</LogOut>
					</Tooltip>
				</span >
			</div >;
		} else {
			// we are directly rendering LogoutModal to avoid React warning
			return <LogoutModal
				savingPromise={this.props.savingPromise}
				theme={this.props.theme}
				confirmAction={
					() => {
						loginServer.handleLogIn();
					}
				}
				registerSubModalMountPoint={null}
			/>;
		}
	}

	protected propsChanged() {
		return false;
	}

	protected clearAsyncData() {
	}

	protected async fetchAsyncData() {
		try {
			const userName = await getUserInfo();
			const userLoggedIn = userName ? true : false;
			return { userName, userLoggedIn };
		} finally {
		}
	}

	private listener = (status: boolean) => {
		this.setState({ userLoggedIn: status });
	}
}
