// Contains cross platform file system APIs

import * as NodeFSForType from "fs";
import * as _ from "lodash";
import * as path from "path";
import { isNode, isEclipse, getProcess } from "./platform";
import { parseJSON } from "./utils";

export interface FS {
	readFile(filePath: string): string;
	fileExists(filePath: string): boolean;
	writeFile(filePath: string, contents: string, options?: { mode?: number }): void;
	mkdir(filePath: string, options?: { recursive?: boolean }): void;
	cwd(): string;
	isFile(filePath: string): boolean;
	readdir(filePath: string): string[];
}

class NodeFS implements FS {

	private fs = require("fs") as (typeof NodeFSForType);

	public readFile(filePath: string): string {
		return this.fs.readFileSync(filePath).toString();
	}

	public fileExists(filePath: string): boolean {
		return this.fs.existsSync(filePath);
	}

	public writeFile(filePath: string, contents: string, options: { mode?: number } = {}): void {
		this.fs.writeFileSync(filePath, contents, options);
	}

	public mkdir(filePath: string, options: { recursive?: boolean } = {}): string {
		return this.fs.mkdirSync(filePath, options);
	}

	public readdir(filePath: string): string[] {
		return this.fs.readdirSync(filePath);
	}

	public cwd() {
		const process = getProcess();
		return typeof nw === "undefined" ? process.cwd() : nw.App.startPath;
	}

	public isFile(filePath: string) {
		return this.fs.lstatSync(filePath).isFile();
	}
}

class EclipseFS implements FS {
	public readFile(filePath: string): string {
		return eclipseGetFileContents(filePath);
	}

	public fileExists(filePath: string): boolean {
		return eclipseFileExists(filePath);
	}

	public writeFile(filePath: string, contents: string, options: { mode?: number } = {}): void {
		if (!_.isEmpty(options)) {
			throw new Error("Eclipse writeFile does not support options");
		}
		eclipsePutFileContents(filePath, contents);
	}

	public mkdir(filePath: string, options: { recursive?: boolean } = {}): void {
		if (options.recursive) {
			// recursively walk output dir path and create dirs as required
			const parts = filePath.split(path.sep);

			// handle root
			let currPath = parts.shift();
			if (_.isEmpty(currPath)) {
				currPath = "/";
			}

			do {
				currPath = path.join(currPath, parts.shift());
				if (!eclipseFileExists(currPath)) {
					eclipseMkdir(currPath);
				}

			} while (parts.length > 0);
		} else {
			eclipseMkdir(filePath);
		}
	}

	public cwd() {
		return eclipseEnv.CWD;
	}

	public isFile(filePath: string) {
		return parseJSON<IEclipseFileInfo>(eclipseGetFileStats(filePath)).isFile;
	}

	public readdir(filePath: string): string[] {
		return _.map(parseJSON<IEclipseFileInfo[]>(eclipseGetDirContents(filePath)), (i) => i.name);
	}
}

class UnSupportedFS implements FS {

	public readFile(_filePath: string): string {
		throw new Error("Method not implemented.");
	}

	public fileExists(_filePath: string): boolean {
		throw new Error("Method not implemented.");
	}

	public writeFile(_filePath: string, _contents: string): void {
		throw new Error("Method not implemented.");
	}

	public mkdir(_filePath: string): void {
		throw new Error("Method not implemented.");
	}

	public cwd(): string {
		throw new Error("Method not implemented.");
	}

	public isFile(_filePath: string): boolean {
		throw new Error("Method not implemented.");
	}

	public readdir(_filePath: string): string[] {
		throw new Error("Method not implemented.");
	}
}

export let fs: FS;

export function getFsForTesting(type: string) {
	switch (type) {
		case "eclipse":
			return new EclipseFS();
		case "node":
			return new NodeFS();
		case "unsupported":
		default:
			return new UnSupportedFS();
	}
}

if (isNode()) {
	fs = new NodeFS();
} else if (isEclipse()) {
	fs = new EclipseFS();
} else {
	fs = new UnSupportedFS();
}
