import "../services/fixStacks";
import "typeface-roboto";
import * as _ from "lodash";
import React = require("react");
import { HashRouter, Switch, Route, Redirect } from "react-router-dom";
import { LoadStartPage } from "./LoadStartPage";
import { LoadConfigPage } from "./LoadConfigPage";
import ReactDOM = require("react-dom");
import { ErrorBoundary } from "./ErrorBoundary";
import {
	configPage,
	startPage,
	constructRoute,
	eclipseLandingPage,
	constructConfigPageRouteFromQuery,
	QueryParams,
	getQueryParams,
	extractArgsFromRoute,
	extractStringFromRoute,
} from "../services/routing";
import { LaunchFromEclipse } from "./LaunchFromEclipse";
import { ModalService } from "../services/ui/modals";
import { NotificationService } from "../services/ui/notification";
import { isNode, isUnderTest, isNodeWebkit } from "../services/platform";
import { ThemeProvider, CssBaseline } from "../imports/material-ui-imports";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { ErrorStore } from "../services/errorStore";
import { defaultTheme, darkTheme, ThemeType } from "./styles/themes";
import { parseArgs } from "../services/args/parseArgs";
import { enableTestHooks } from "../services/testability";
import { ProgressBar } from "./ProgressBar";
import { IAvailableProducts, createAvailableProducts } from "../services/product/available";
import { parseArgsStringToArgv } from "../services/args/stringToArgv";

interface IProps {
	nwArgs: string[];
	queryParams: QueryParams;
	test: boolean;
}

interface IState {
	products: IAvailableProducts;
	loadProductsComplete: boolean;
}
class Index extends React.Component<IProps, IState> {
	private readonly globalServices: IGlobalServiceProps;

	constructor(props: IProps) {
		super(props);
		const theme = this.getTheme();
		this.globalServices = {
			modalService: new ModalService(theme),
			notificationService: new NotificationService(theme),
			errorStore: new ErrorStore(),
			theme,
		};

		this.state = {
			products: null,
			loadProductsComplete: false,
		};
	}

	public override async componentDidMount() {

		if (this.props.test) {
			enableTestHooks(this.globalServices.modalService);
		}

		if (this.props.queryParams.products) {
			// only try to look up products if we have to 
			try {
				const availableProducts = await createAvailableProducts();
				this.setState({ products: availableProducts, loadProductsComplete: true });
			} catch (e) {
				// just log for now, normal error handling should take the user to the start page.
				console.error("Failed to load available products");
				this.setState({ loadProductsComplete: true });
			}

		} else {
			this.setState({ loadProductsComplete: true });
		}

	}

	public override render() {
		if (!this.state.loadProductsComplete) {
			return <ProgressBar id="configProgress" title="Loading..." />;
		} else {

			// If there are query parameters, and we haven't yet navigated to a hash page, directly redirect via location.replace
			// We can't use <Redirect> to do that as it will place the hash page after the query params

			if (!window.location.hash && !_.every(this.props.queryParams, _.isEmpty)) {
				const redirectTo = _.replace(window.location.href, window.location.search, "") + "#" +
					constructConfigPageRouteFromQuery(this.props.queryParams, this.state.products);
				window.location.replace(redirectTo);
			}

			return <ErrorBoundary {...this.globalServices}>
				<ThemeProvider theme={this.globalServices.theme.theme}>
					<CssBaseline />
					<HashRouter>
						<Switch>
							<Route
								path={configPage}
								render={(props) => <LoadConfigPage {...props} {...this.globalServices} />} />
							<Route
								path={startPage}
								render={(props) => <LoadStartPage {...props} {...this.globalServices} />}
							/>
							<Route
								path={eclipseLandingPage}
								render={(props) => <LaunchFromEclipse {...props} {...this.globalServices} />} />
							{
								(!_.isEmpty(this.props.nwArgs) && !this.onlyContainsThemeArg(this.props.nwArgs)) &&
								<Redirect to={constructRoute(configPage, this.props.nwArgs)} />
							}
							<Redirect to={startPage} />
						</Switch>
					</HashRouter>
				</ThemeProvider>
			</ErrorBoundary>;
		}
	}

	private getTheme() {
		let args = null;
		if (typeof eclipseGetCLIArgsString !== "undefined") {
			args = parseArgsStringToArgv(eclipseGetCLIArgsString());
		} else if (!_.isEmpty(this.props.nwArgs)) {
			args = this.props.nwArgs;
		} else {
			args = extractArgsFromRoute(window.location);
		}
		const parsedArgs = parseArgs(args, true);
		if (!isUnderTest() && parsedArgs.parsedArgs.theme && parsedArgs.parsedArgs.theme.value === ThemeType.DARK) {
			return darkTheme;
		}
		return defaultTheme;
	}

	private onlyContainsThemeArg(nwArgs: string[]) {
		const parsedArgs = parseArgs(nwArgs, true);
		return _.size(parsedArgs.parsedArgs) === 1 && parsedArgs.parsedArgs.theme;
	}
}

function getNWArgs() {
	if (isNode() && !isUnderTest()) {
		return _.without(nw.App.argv, "");
	} else {
		return [];
	}
}

const test
	= isNodeWebkit() ? !!_.includes(nw.App.argv, "--test") : extractStringFromRoute(window.location, "test");

ReactDOM.render(
	<Index nwArgs={getNWArgs()} queryParams={getQueryParams()} test={Boolean(test)} />,
	document.getElementById("reactRoot"));
