import * as _ from "lodash";
// Handles GPIO requirements in a way that is different than core pinmux and specific to sysconfig,
import * as data from "dataInterfaces";
import { APinMgr, PinSolverOptions } from "./pin";
import { GPIOPin } from "public/runtime";
import { SelectionFilterGroup } from "./selectionFilterGroup";
import { GPIO } from "../solver/requirements";
import { Runtime } from "../resources/runtime";
import { FormatOptions } from "../formatting/formattingTypes";
import { FormattedMsgPart } from "../formatting/link";
import { ModuleInstanceMgr } from "./moduleInstance";
import { Const } from "../utils";

/**
 * Extends and adapts the basic pin mgr specific to GPIO.
 */
export class GPIOPinMgr extends APinMgr<GPIOPin> {

	// Solver reqs need unique id's
	private static solverReqIdSuffix = 1;
	private readonly gpioSolverReq: GPIO;

	constructor(
		runtime: Runtime,
		formatter: (options: FormatOptions, member?: string) => FormattedMsgPart,
		reqName: string,
		solverOptions: PinSolverOptions,
		componentConnections: data.DevicePin[],
		parentModuleMgr: ModuleInstanceMgr,
	) {
		const gpioInterface = runtime.getDeviceData().interfaces.GPIO;
		super(
			runtime,
			formatter,
			reqName,
			new SelectionFilterGroup(),
			_.values(gpioInterface.interfacePins),
			componentConnections,
			solverOptions,
			parentModuleMgr,
			"",
			false,
			parentModuleMgr,
		);
		this.addFixedMember(this.runtime.getFormattersMap(), "$interface", gpioInterface);
		this.gpioSolverReq = new GPIO("MyGPIO" + GPIOPinMgr.solverReqIdSuffix++, "GPIO");
	}

	public override getSolverRequirements() {
		this.gpioSolverReq.pinRequirements = [this.getSolverRequirement()];
		return [this.gpioSolverReq];
	}

	public override setLockStatus(status: boolean) {
		if (!status || !_.isEmpty(this.getSolution().assignedToName)) {
			this.setSelectedDevicePin(status ? this.getSolution().assignedToName : Const.ANY);
		}
	}
}
