import * as semver from "semver";
import * as _ from "lodash";
import { parseArgsStringToArgv } from "./args/stringToArgv";
import { IAvailableProducts } from "./product/available";
import { AvailableProductInfo } from "./product/types";

export type RouteTarget = "/start" | "/config" | "/launchFromEclipse" | "/test";

export const startPage: RouteTarget = "/start";
export const configPage: RouteTarget = "/config";
export const eclipseLandingPage: RouteTarget = "/launchFromEclipse";
export enum Mode {
	Compatibility = "compatibility",
	Default = "default"
}

export function constructRoute(page: RouteTarget, argv: string[], mode?: Mode) {
	// Escape any arguments containing a space with quotes, then encode them to escape everything else
	if (_.isEmpty(argv)) {
		return page;
	}
	const modeArg = mode ? `&mode=${mode}` : "";
	const args = _.map(argv, (arg) => _.includes(arg, " ") ? `"${arg}"` : arg).join(" ");
	return `${page}/?args=${encodeURIComponent(args)}` + modeArg;
}

interface Location {
	search: string;
}

export function extractArgsFromRoute(location: Location) {
	const argsString = new URLSearchParams(location.search).get("args");
	return argsString ? parseArgsStringToArgv(argsString) : [];
}

export function extractStringFromRoute(location: Location, property: "module" | "device" | "part" | "package" | "test" | "mode") {
	return new URLSearchParams(location.search).get(property);
}

export function extractModeFromRoute(location: Location): Mode {
	return extractStringFromRoute(location, "mode") === Mode.Compatibility ?
		Mode.Compatibility : Mode.Default;
}

function extractProductsShortNameFromRoute(location: Location) {
	return new URLSearchParams(location.search).getAll("product");
}

export type QueryParams = ReturnType<typeof getQueryParams>;

export function getQueryParams() {

	const location = window.location;
	const params = {
		products: extractProductsShortNameFromRoute(location),
		module: extractStringFromRoute(location, "module"),
		device: extractStringFromRoute(location, "device"),
		part: extractStringFromRoute(location, "part"),
		package: extractStringFromRoute(location, "package"),
	};

	return params;
}

// Construct analog config page route
export function constructConfigPageRouteFromQuery(params: QueryParams, availabeProducts: IAvailableProducts) {
	const productArgs = _.chain(params.products)
		.map((product) => getLatestVersion(availabeProducts.getProductInfo(), product))
		.flatMap(({ path }) => ["--product", path])
		.value();

	const deviceArgs = ["--device", params.device ?? "Other"]; // Use "Other" device if not specified to maintain legacy ASCStudio links
	const partArgs = params.part ? ["--part", params.part] : [];
	const packageArgs = params.package ? ["--package", params.package] : [];

	const route = constructRoute(
		configPage,
		[
			...productArgs,
			...deviceArgs,
			...partArgs,
			...packageArgs,
		],
	);

	if (params.module) {
		return `${route}&module=${encodeURIComponent(params.module)}`;
	}

	return route;

}

export function getLatestVersion(infos: AvailableProductInfo[], productName: string) {
	return (
		_.chain(infos)
			.filter((p) => p.name === productName)
			.sort((a, b) => {
				return semver.gt(a.version, b.version) ? 1 : -1;
			})
			.last()
			.value()
	);
}
