import React = require("react");
import { Button } from "../../imports/material-ui-imports";
import { IButtonProps } from "./IButtonProps";
export class GeneralButton extends React.Component<IButtonProps> {
	public override render() {
		return (
			<Button
				component="span"
				color="primary"
				variant="contained"
				disabled={this.props.disabled}
				onClick={this.props.onClick}
				id={this.props.id}
				style={this.props.style}
				size="small"
			>
				{this.props.children}
			</Button>
		);
	}
}
