import React = require("react");
import * as _ from "lodash";
import { DevicePinSelection } from "./pinAssign";
import { CConfigurable } from "./configurables/configurable";
import { IFormatter } from "../../formatting/formattingTypes";
import { CheckBox } from "../../../components/CheckBox";
import { IGlobalServiceProps } from "../../../components/IGlobalServicesProps";
import { CValidation } from "./validation";
import { ResourceLoader } from "../../resources/metaContentLoaders/resourceLoader";
import { GPIOPinMemberMgr, ExtendedPinMemberMgr, PinMemberMgr } from "../pinObjectMembers";
import { ConfigStoreActions } from "../../configStore";
import { MemberRow } from "./memberRows";
import { getDisplayName } from "../../utils";
import { ConflictControl } from "../../../components/ConflictControl";
import { Validations } from "../validations";
import { PinDisplayType } from "../../userPreferences";

export class PinSelectRow extends React.Component<
	{
		memberMgr: PinMemberMgr | GPIOPinMemberMgr | ExtendedPinMemberMgr,
		actions: ConfigStoreActions,
		formatter: IFormatter,
		validations: Validations;
		displayScriptName: boolean,
		devicePinDisplayType: PinDisplayType[],
		headerPinDisplayType: PinDisplayType[],
		resourceLoader: ResourceLoader,
		productLookupName: string,
		highlightedMember: string,
		showUsed: boolean,
		columns?: number,
		configurablesOrder: string[];
		borderSides?: boolean;
		borderBottom?: boolean;
	} & IGlobalServiceProps> {
	public override render() {
		const memberMgr = this.props.memberMgr;
		return (
			<React.Fragment>
				<MemberRow
					style={{ verticalAlign: "baseline" }}
					{...this.props}
					highlight={this.props.highlightedMember === memberMgr.def.name}
					labelLeft={this.props.showUsed &&
						<CheckBox
							id={"chk" + memberMgr.def.name}
							onChange={(value) => this.props.actions.setUsed(memberMgr.valueObjectMgr, value)}
							value={memberMgr.valueObjectMgr.getUsed()}
							disabled={false}
						/>
					}
					conflictControl={
						<ConflictControl
							req={memberMgr.valueObjectMgr}
							formatter={this.props.formatter}
							actions={this.props.actions}
						/>
					}
				>
					<DevicePinSelection
						pinRequirement={memberMgr.valueObjectMgr}
						formatter={this.props.formatter}
						validations={this.props.validations}
						onChange={(value) =>
							this.props.actions.setSelectedDevicePin(memberMgr.valueObjectMgr, value, getDisplayName(memberMgr.def, false))}
						actions={this.props.actions}
					/>
					{this.renderConfigurables()}
				</MemberRow>
			</React.Fragment>
		);
	}

	private renderConfigurables() {
		const configurables = this.props.memberMgr.valueObjectMgr.metaContentConfigurableMgrs;
		const order = this.props.configurablesOrder;
		return _.chain(order)
			.map((key) => configurables[key])
			.reject((configurable) => !configurable || configurable.uiState.hidden)
			.map((configurable) => {
				return (
					<React.Fragment key={configurable.def.name}>
						<CConfigurable {...this.props} mgr={configurable} actions={this.props.actions} />
						<CValidation
							validations={this.props.validations}
							validatableObj={configurable}
							formatter={this.props.formatter}
							actions={this.props.actions}
							memberName={configurable.def.name} />
					</React.Fragment>
				);
			})
			.value();
	}
}
