// eslint-disable-next-line prefer-const
export let decorateAny = (decorateText: string) => decorate(Const.ANY, decorateText);

export function decorate(baseText: string, decorateText: string) {
	if (decorateText && decorateText !== "") {
		return baseText + "(" + decorateText + ")";
	} else {
		return baseText;
	}
}

function duplicateDetected(item: { name: string }) {
	throw new Error("Duplicate detected: " + item.name);
}

/* Turn an array into a map where the key is the 'name' property from array values */
export function toNameMap<T extends { name: string }>(arr: Record<string, T> | T[], onDuplicate: (item: T) => void = duplicateDetected) {
	return _.reduce(arr as T[], (map, item) => {
		if (map[item.name]) {
			onDuplicate(item);
		}
		map[item.name] = item;
		return map;
	}, {} as Record<string, T>);
}

export function naturalSort<T>(collection: T[], iteratee: (item: T) => string | number) {

	const sortImpl = naturalSortImpl();
	return collection.sort((a, b) => sortImpl(iteratee(a), iteratee(b)));
}

