// From https://www.npmjs.com/package/true-case-path
// Copied from repo and translated to Typescript
// Reasons: 
// - no @types for it
// - it is very short
// - replaced process with getProcess
export function trueCasePathSync(fsPath: string) {
	if (isNode()) {
		// Normalize the path so as to resolve . and .. components.
		// !! As of Node v4.1.1, a path starting with ../ is NOT resolved relative
		// !! to the current dir, and glob.sync() below then fails.
		// !! When in doubt, resolve with fs.realPathSync() *beforehand*.
		let fsPathNormalized = path.normalize(fsPath);

		// OSX: HFS+ stores filenames in NFD (decomposed normal form) Unicode format,
		// so we must ensure that the input path is in that format first.
		if (getProcess().platform === "darwin") {
			fsPathNormalized = fsPathNormalized.normalize("NFD");
		}

		// !! Windows: Curiously, the drive component mustn't be part of a glob,
		// !! otherwise glob.sync() will invariably match nothing.
		// !! Thus, we remove the drive component and instead pass it in as the 'cwd'
		// !! (working dir.) property below.
		const pathRoot = path.parse(fsPathNormalized).root;
		const noDrivePath = fsPathNormalized.slice(Math.max(pathRoot.length - 1, 0));

		// Perform case-insensitive globbing (on Windows, relative to the drive /
		// network share) and return the 1st match, if any.
		// Fortunately, glob() with no case case-corrects the input even if it is
		// a *literal* path.
		return glob.sync(noDrivePath, { nocase: true, cwd: pathRoot })[0] || fsPath;
	}
	return fsPath;
}

const validCIdentifier = /^[_a-zA-Z][_a-zA-Z0-9]*$/;

export function isValidCIdentifier(identifier: string) {
	return validCIdentifier.test(identifier);
}

export function toKB(byteSize: number) {
	return `${(byteSize / 1024).toFixed(1)} KB`;
}

export function resolveRelativePathToProduct(productJsonPath: string, relativePath: string) {
	// get the path to the product json (includes the name of the product.json)
	const productFullPath = productJsonPath.replace(/\\/g, "/");
	// remove the product.json part to just the path
	let productPath = productFullPath.replace(/[^/]*$/, "");
	if (isCloud()) {
		// We see the product as being at the dfuse mount point, but we want links to 
		// be updated to go to the tirex url route for content
		productPath = _.replace(productPath, backendContentPath, tirexContentRoute);
	}
	// product path + documentation relative path + documentation filename
	return path.join(productPath, relativePath);
}

export function shouldShowLongDescription(item: HardwareComponentMgr): boolean;
export function shouldShowLongDescription(item: ModuleMgr, isPreview: boolean): boolean;
export function shouldShowLongDescription(item: ModuleMgr | HardwareComponentMgr, isPreview?: boolean) {

	if (item instanceof HardwareComponentMgr) {
		return item.getLongDescription() && (item.getShowUserLongDescPref() || item.isDetached());
	}

	return item.getLongDescription() && (isPreview || item.getShowUserLongDescPref());
}

export function flattenNode(node: ITreeNode): ITreeNode[] {
	if (_.isEmpty(node.getChildren())) {
		return [node];
	} else {
		return (_.flatMap(node.getChildren(), (n) => flattenNode(n)));
	}
}

export const enum ResourceConflictText {
	RES_CONFLICT = "Resource conflict",
	UNPINNED = "Not pinned out",
	ON_HARDWARE = "Connected to hardware",
}

export function productInRange(
	product: { name: string, version: string },
	range: { productName: string, productRange: string },
) {
	if (product.name !== range.productName) {
		return false;
	}
	const coercedPVer = isTIProductVersion(product.version) ? tiVersionToSemver(product.version) : product.version;
	// if the range is a valid semver range, we treat it as a range
	if (isTIProductVersion(range.productRange)) {
		return semver.eq(coercedPVer, tiVersionToSemver(range.productRange));
	} else if (semver.validRange(range.productRange)) {
		return semver.satisfies(coercedPVer, range.productRange);
	} else {
		// if not a valid semver range, we assume it is pointing to a specific non-semver formatted version
		// (i.e. version_1 is not a valid range)
		return product.version === range.productRange;
	}
}

export function isTIProductVersion(version: string) {
	// Format is: M.mm.pp.b_q
	// or M_mm_pp_b_q
	// where:
	// M is a single digit Major version number
	// mm is a 2 digit Minor version number
	// pp is a 2 digit patch number
	// b is an unrestricted set of digits used as incrementing build counter
	// q is an optional qualifier for product to indicate state, intended use etc. of the product. ('eng' only)
	return /^[0-9]\.[0-9][0-9]\.[0-9][0-9](\.[0-9]+(_eng)?)?$/.test(version) ||
		/^[0-9]_[0-9][0-9]_[0-9][0-9](_[0-9]+(_eng)?)?$/.test(version)
		; // eslint-disable-line indent
}

export function tiVersionToSemver(version: string) {
	// we can safely remove anything other than M.mm.pp because build is ignorable 
	const parts = _.includes(version, ".") ? version.split(".") : version.split("_");
	return _.chain(parts)
		.slice(0, 3)
		.map((p) => p.length === 2 && p.charAt(0) === "0" ? p.charAt(1) : p)
		.join(".")
		.value();
}

export function delay(ms: number) {
	return new Promise<void>((resolve) => {
		setTimeout(resolve, ms);
	});
}

export function uniquifyDocoptRepeatedArgs(parsedObj: any) {
	return _.mapValues(parsedObj, (val) => _.isArray(val) ? _.uniq(val) : val) as any;
}

export const reservedMarkerText = "Reserved";

// Format for core pinmux and reserve peripherals
export function formatRootInterfaceCLI(instMgr: InterfaceInstanceMgr | GPIOInterfaceInstanceMgr, member?: string) {
	const instName = instMgr.managedObject.$name;
	const instText = instMgr.isReservation() ? `${instName}(${reservedMarkerText})` : instName;

	const textParts = [
		instMgr.getContextDisplayName(),
		instText,
		member,
	];

	return _.chain(textParts)
		.compact()
		.join(memberSeparator)
		.value();
}

// This is a replacement for _.memoize that differs in two ways:
// 1) the cache is keyed on EVERY argument, not just the first
// 2) only one value is cached at a time

export function memoizeOne<T extends (...args: any[]) => any>(expensiveFunction: T) {
	let cacheKey: Parameters<T> = null;
	let cacheValue: ReturnType<T> = null;
	const memoized = (...args: Parameters<T>) => {
		// Shallow compare - if they deeply compare only, then we re-cache.  Keeps cache check fast
		if (_.size(cacheKey) !== _.size(args) ||
			!_.every(args, (arg, index) => arg === cacheKey[index]) ||
			null === cacheKey) {
			cacheValue = expensiveFunction(...args);
			cacheKey = args;
		}
		return cacheValue;
	};

	// Just like _.memoize, add a "cache" member to the function.  For now, we just need clear

	memoized.cache = { clear };
	return memoized;

	function clear() {
		cacheKey = null;
		cacheValue = null;
	}
}

// This takes a function that returns a non-trivial result and ensures an identical result is returned if the result
// is equivalent according to _.isEqual.  This allows for the results of some calculations to be used as a react prop,
// even though it's an object or array.

export function memoizeResult<T extends (...args: any[]) => any>(func: T) {
	let cache: ReturnType<T> = null;
	return (...args: Parameters<T>) => {
		const result = func(...args);
		if (_.isEqual(cache, result)) {
			return cache;
		}
		cache = result;
		return cache;
	};
}

// Intentionally empty function.  Calling it requires an await, which will force the caller to 
// yield to the event loop, and thus allow rendering animations to proceed

export async function yieldToRendering() {
	return new Promise<void>((resolve) => {
		setTimeout(resolve);
	});
}

export function getShortValidationString(vString: string | DetailedText) {
	if (_.isString(vString)) {
		return vString;
	} else {
		return vString.shortText;
	}
}

export function getLongValidationString(vString: string | DetailedText) {
	if (_.isString(vString)) {
		return [];
	} else {
		return vString.longTexts;
	}
}

export function suppressionHasMatch(matchers: Set<string>, key: string) {
	return _.some([...matchers], (matcher) => (new RegExp(matcher)).test(key));
}

export function getValidationKey(vString: string | DetailedText) {
	let msgKey = "";
	if (_.isString(vString)) {
		msgKey = vString;
	} else if (!_.isEmpty(vString.longTexts)) {
		msgKey = _.join([vString.shortText, ...vString.longTexts], ",");
	} else {
		msgKey = vString.shortText;
	}
	const matcherString = _.chain(msgKey)
		.replace(/@@@.+?@@@/g, "@@@temp@@@")
		.escapeRegExp()
		.replace(/@@@temp@@@/g, "@@@.+?@@@")
		.value();
	return { matcher: matcherString, key: msgKey };
}

export function adaptPinmuxTemplates(templates: CodeGenTemplateFile[]) {
	return _.map(templates, (t) => ({ ...t, excludable: true, excluded: false }));
}

// If you don't attach a catch handler to a promise, and the promise rejects, then node will give 
// you an unhandledPromiseRejection error.  Right now that's just nasty text on the console, bug
// later will be an exception.  
//
// The reason node does this is the following:
//
// try {
//     const parallelOperation = doRequest(); // we acquire the promise here
//     await anotherTask(); // if this throws - we're left with a mess
//     await anotherTask2(); // if this throws - we're left with a mess
//     const result = await parallelOperation;
// catch(e) { // cleanup
//
// In the above code, if there's special cleanup that needs to happen, it never does.  However, 
// most of the time there isn't - if you're just pre-fetching some data, and stuff fails earlier,
// the user doesn't really care that the data couldn't be fetched.
//
// That's the purpose of this function.  You can use it to indicate you are doing something in
// parallel, and it doesn't need any cleanup, and this function will add a catch handler that does
// nothing, but keeps node happy
export function inParallelNoCleanup<T>(promise: Promise<T>) {
	promise.catch(() => { });
	return promise;
}

export function getDuplicates<T>(arr: T[], by: (i: T) => string) {
	return _.chain(arr)
		.groupBy(by)
		.pickBy((entry) => _.size(entry) !== 1)
		.keys()
		.value();
}

export function sortedFindBy<T, K extends keyof T>(arr: T[], value: T[K], key: K) {
	const index = _.sortedIndexBy(arr, { [key]: value } as any as T, (entry) => entry[key]);
	if (-1 !== index) {
		return arr[index];
	}
	return undefined;
}

export function getNodePath() {

	// Cloud is a special case - they can never actually use it for a button, 
	// but a template would end up using the CCS version, so we can hard-code that

	if (isCloud()) {

		return "/mnt/ccs/ccs/tools/node";
	}

	// Otherwise, the standalone version is located in the nodejs folder at the 
	// same level as "dist".  And sometimes CCS picks up the standalone version
	// so we can't just check "isEclipse" or something

	const executable = isWin() ? "node.exe" : "node";
	const standalonePath = path.join(rootDir(), "..", "nodejs", executable);
	if (fs.fileExists(standalonePath)) {
		return path.normalize(standalonePath);
	}

	// If it doesn't exist, we must be inside of CCS, so return the CCS version
	// Need to find C:\ti\CCS10.3.0.00006\ccs\tools\node
	// given C:\ti\CCS10.3.0.00006\ccs\utils\sysconfig_1.8.0\dist

	return path.normalize(path.join(rootDir(), "..", "..", "..", "tools", "node", executable));
}

// Same as _.keys, but typed to return an array of key types vs just string

export function keys<T extends {}>(obj: T) {
	return _.keys(obj) as (keyof T)[];
}

// Given a type, and a map of the keys of that type to booleans, this returns the keys for which the value is "true".
// This allows us to select just some keys, and ensure we've been explicit about every key.  That way, if keys are 
// added or removed later, TS will generate a type error.  For instance
//
// interface Foo { a: string, b?: string }
// filterKeys<Foo>({a: true, b: false}) // returns ["a"]
// filterKeys<Foo>({a: true, b: true}) // returns ["a", "b"]
// filterKeys<Foo>({a: true}) // ts error - missing b
// filterKeys<Foo>({a: true, b: false, c: true}) // ts error - c is extra

export function filterKeys<T extends {}>(keyMap: Record<keyof Required<T>, boolean>) {
	return _.filter(keys(keyMap), (key) => keyMap[key]);
}
