import React = require("react");
import { ConfigStoreActions } from "../services/configStore";
import { ButtonType, createButton } from "./ComponentUtils";
import { InterfaceMgr } from "../services/instanceContainers/interface";
import { ModuleMgr } from "../services/instanceContainers/module";

interface IProps {
	treeNode: ModuleMgr | InterfaceMgr;
	actions: ConfigStoreActions;
	type?: ButtonType;
}

export class AddAdaptedTreeNodeButton extends React.Component<IProps> {
	public override render() {

		const { treeNode, actions, type } = this.props;

		return (
			createButton(
				treeNode.getButtonInfo(),
				() => actions.addAdaptedTreeNode(treeNode),
				type,
			)
		);
	}
}
