import React = require("react");
import * as _ from "lodash";
import * as path from "path";
import { IStorageFile, storage } from "../../services/storage";
import { ErrorStore } from "../../services/errorStore";
import { ModalService } from "../../services/ui/modals";
import { AsyncComponent } from "../AsyncComponent";
import { ProgressBar } from "../ProgressBar";
import { generateDownloadLink } from "../../services/project";
import { isCloud } from "../../services/platform";
import { FileNode } from "./FileNode";
import { ICommonProps } from "./common";

interface IState {
	roots?: IStorageFile[];
}

interface IFileTreeProps extends ICommonProps {
	errorStore: ErrorStore;
	modalService: ModalService;
	hideUpload?: boolean;
	onFileSelect: (filePath: string) => void;
	onFolderSelect?: (folderPath: string) => void;
}

// File tree used for cloud file browsing, this usually exists within a modal so it looks larger than FileExplorer
export class CloudFileTree extends AsyncComponent<IFileTreeProps, IState> {

	public override state: IState = {};

	public override render(): JSX.Element {
		if (!this.state.roots) {
			return <ProgressBar title="Reading workspace..." />;
		}

		const rootNodes = _.map(this.state.roots, (root) =>
			<FileNode
				style={"cloudBrowser"}
				selectedPath={this.props.selectedPath}
				onFileSelect={(file) => this.props.onFileSelect(file.path)}
				onFolderSelect={(folder) => this.props.onFolderSelect ? this.props.onFolderSelect(folder.path) : undefined}
				level={1}
				getSize={(file) => file.size || 0}
				disabled={false}
				pickDir={this.props.pickDir}
				key={root.name}
				fileTree={root}
				fnameFilter={this.props.fnameFilter}
				onFileUpload={isCloud() && !this.props.hideUpload ? this.handleOnFileUpload : undefined}
				onFileDownload={isCloud() ? this.handleOnFileDownload : undefined}
				onFileDelete={
					(file: IStorageFile) => {
						const fileName = file.path;
						this.props.modalService.showConfirmModal(
							"Delete File",
							`Are you sure you wish to delete ${storage.formatPathForUser(fileName)}`,
							async () => {
								// Actually delete the file on the cloud
								try {
									await storage.deleteFile(fileName);
								} catch (e) {
									this.props.modalService.showErrorModal(
										"File deletion failed",
										e.message,
									);
									return;
								}

								// Now remove the file from our set of files to refresh

								let parent = root;
								_.chain(fileName)
									.split(path.sep)
									.compact()
									.drop(2) // /pinmux/default or /syscfg/default
									.each((name) => {
										const child = _.find(parent.children, (c) => c.name === name);
										if (child) {
											if (!child.isDirectory) {
												parent.children = _.pull(parent.children, child);
											} else {
												parent = child;
											}
										} else {
											throw new Error("No child found");
										}
									})
									.value();
								this.setState({ roots: this.state.roots });
							},
							() => { },
							"Yes",
							"No",
						);
					}
				}
			/>,
		);
		return <React.Fragment>{rootNodes}</React.Fragment>;
	}

	protected propsChanged() {
		return false;
	}

	protected clearAsyncData() {
		this.setState({ roots: null });
	}

	protected async fetchAsyncData() {
		const roots = storage.getRootPaths();
		const children = await Promise.all(
			_.map(roots, async (r) => storage.readDirectory(r.path, r.path)),
		);
		return {
			roots: _.map(roots, (r, index) => (
				{
					name: r.displayName,
					path: r.path,
					relativePath: r.path,
					isDirectory: true,
					children: children[index],
				}
			)),
		};
	}

	private handleOnFileDownload = async (file: IStorageFile) => {
		const fileName = file.path;
		const { data } = await storage.openFile(fileName);
		generateDownloadLink(path.basename(fileName), data, "text/plain");
	}

	private handleOnFileUpload = async (folder: IStorageFile, event: React.ChangeEvent<HTMLInputElement>) => {
		const folderName = folder.path;
		const selectedFile = event.target.files[0];
		const reader = new FileReader();
		reader.onloadend = async () => {
			try {
				await storage.saveFile(folderName + selectedFile.name, reader.result);
				this.props.onFileSelect(folderName + selectedFile.name);
			} catch (e) {
				this.props.modalService.showErrorModal(
					"File import failed",
					e.message,
				);
			}
		};
		reader.readAsText(selectedFile);
	}
}
