import * as _ from "lodash";
// Handles loading saved files to re-initialize application state.
import { getSysConfig } from "../sysConfigFactory";
import { loadLegacy, PinMuxFileData, getResolvedArgsFromLegacy } from "../legacy/loadJSONPinmuxFile";
import { ScriptingObject, System } from "public/runtime";
import { contextify } from "../resources/contextify";
import { runAsUserScript } from "./scriptingGuard";
import { SuggestSolutionMgr } from "../objectManagers/assignMembers";
import { parseJSON } from "../utils";
import { setSerializeProjectPath } from "../projectPath";
import { ErrorStore } from "../errorStore";
import { SysConfig } from "../sysConfig";
import { ResolvedArgs } from "../args/argTypes";

// Type function of wrapping cfg scripts
type ScriptPmuxFunction = (system: System, scripting: ScriptingObject, argv: string[]) => any;

export class LegacyBoardFile extends Error {
	public readonly link = "http://processors.wiki.ti.com/index.php/TI_PinMux_Tool#Archived_Versions";
	constructor(public readonly pinmuxFile: string) {
		super("Legacy board configuration files are no longer supported");
	}
}

export class ScriptRunError extends Error {
	constructor(public originalError: Error, public script: string) {
		super(originalError.message);
	}
}

function toLegacyJSONPinmuxFile(source: string, fileName: string) {
	let pinmuxFile;
	try {
		pinmuxFile = parseJSON<PinMuxFileData>(source);
	} catch (e) {
		return null;
	}
	if (pinmuxFile.boardId && pinmuxFile.boardId !== "undefined") {
		throw new LegacyBoardFile(fileName);
	}
	return pinmuxFile;
}

async function loadAsJSONPinmuxFile(
	errorStore: ErrorStore,
	pinmuxFile: PinMuxFileData,
	solveAndValidate: boolean,
	resolvedArgs: ResolvedArgs,
) {
	const configParams = await getResolvedArgsFromLegacy(pinmuxFile, resolvedArgs);
	const sysConfig = await getSysConfig(errorStore, configParams, true);
	runAsUserScript(() => loadLegacy(sysConfig, pinmuxFile));
	if (solveAndValidate) {
		sysConfig.validateAndSolve(SuggestSolutionMgr.optionSet);
	}
	return sysConfig;
}

export async function runScripts(
	resolvedArgs: ResolvedArgs,
	errorStore: ErrorStore,
	solveAndValidate = true,
) {
	// Were we passed a legacy Pinmux Tool file?

	if (1 === _.size(resolvedArgs.script)) {
		const { script } = resolvedArgs.script[0];
		const pinmuxFile = toLegacyJSONPinmuxFile(script?.contents, script?.path);
		if (pinmuxFile) {
			return loadAsJSONPinmuxFile(
				errorStore,
				pinmuxFile,
				solveAndValidate,
				resolvedArgs,
			);
		}
	}

	// Create the sysconfig object

	const sysConfig = await getSysConfig(errorStore, resolvedArgs, true);
	SuggestSolutionMgr.optionSet = false;

	// Now run each of the user's scripts and any dependent scripts

	_.each(sysConfig.getRuntimes(), (runtime) => {
		const scriptArgs = _.find(resolvedArgs.script, (script) => script.context === runtime.getName());
		if (scriptArgs && scriptArgs.script) {
			const userScript = scriptArgs.script;

			setSerializeProjectPath(userScript.path);

			// Create the sysconfig object, then run the user's script and any dependent scripts

			const cliArgs = [userScript.path, ...scriptArgs.argsForScript];
			const system = runtime.createSystemObj();
			const scripting = runtime.getScripting();
			_.each([userScript, ...scriptArgs.dependentScripts], (script) => {
				const scriptFunc = contextify<ScriptPmuxFunction>(script.path, script.contents, ["system", "scripting", "argv"]);
				runAsUserScript(() => {
					try {
						scriptFunc(system, scripting, cliArgs);
					} catch (e) {
						throw new ScriptRunError(e, script.path);
					}

				}, { read: true, write: true });
			});
		}
	});

	// Notify all modules that the scripts have finished

	callOnUserScriptsComplete(sysConfig);

	// Solve/validate

	if (solveAndValidate) {
		sysConfig.validateAndSolve(SuggestSolutionMgr.optionSet);
	}

	cleanStaleModules(sysConfig);

	// User's script is done - we can definitely freeze the board content now

	sysConfig.freezeBoardContent();

	return sysConfig;
}

// This removes any modules that aren't user created or held in the system by something else.  For
// instance, lets say a module is statically pulled in, and has pin assignments.  We would need to
// serialize those assignments.  However, if a new version of the SDK no longer pulled that module
// in, then it's just hanging around suddenly.  We'd want to clean that up.  Especially if the 
// module is no longer a top module.  Likewise, if migrating to a different target, the 
// dependencies of any module could change quite a bit, and again we would need to clean these
// cases up

export function cleanStaleModules(sysConfig: SysConfig) {
	while (!_.chain(sysConfig.getModuleMgrs())
		.flatMap((m) => m.allInstancesIncludingStatic())
		.filter((m) => !m.isUserCreatedOrTouched() && m.isRemovable())
		.each((m) => m.remove())
		.isEmpty()
		.value()) { }
}

export function callOnUserScriptsComplete(sysConfig: SysConfig) {
	_.chain(sysConfig.getModuleMgrs())
		.flatMap((m) => m.allInstancesIncludingStatic())
		.each((m) => m.onUserScriptsComplete())
		.value();
}
