import * as React from "react";
import * as _ from "lodash";
import { ExtendedElkLine } from "../layout/customTypes";
import { ClassesType } from "../styling/clockTreeStyles";

// A straight line to indicate a connection on the graph.  The line is small, so the hover area is wider

function getElkPath(edge: ExtendedElkLine) {
	const start = `M ${edge.start.x},${edge.start.y}`;
	const end = `L ${edge.end.x},${edge.end.y}`;
	return start + " " + end;
}

interface IProps {
	edge: ExtendedElkLine;
	onMouseEnter: (line: ExtendedElkLine) => void;
	onMouseLeave: () => void;
	onClick: (line: ExtendedElkLine) => void;
	highlight: boolean;
	selected: boolean;
}

export class LineComponent extends React.PureComponent<IProps & ClassesType> {
	public override render() {
		const { edge, onMouseLeave, highlight, selected, classes } = this.props;
		const edgePath = getElkPath(edge);

		return <>
			<path
				className={getClassName(selected, highlight, classes)}
				d={edgePath}
			/>
			<path
				className={classes.hoverSelectLine}
				d={edgePath}
				onMouseEnter={this.onMouseEnter}
				onMouseLeave={onMouseLeave}
				onClick={this.onClick}
			/>
		</>;
	}

	private onMouseEnter = (e: React.MouseEvent<SVGPathElement, MouseEvent>) => {

		// Do not fire a line-hover event when dragging.  The hover event can fire if the dragged elements don't keep 
		// up with the mouse, and that causes a large amount of unnecessary re-rendering which then immediately 
		// reverts once the dragged elements catch up to the mouse.  This makes the drag feel very unresponsive

		if (0 === e.buttons) { // buttons will be non-zero if any are clicked
			this.props.onMouseEnter(this.props.edge);
		}
	}

	private onClick = () => {
		this.props.onClick(this.props.edge);
	}
}

function getClassName(selected: boolean, highlight: boolean, classes: ClassesType["classes"]) {
	if (selected) {
		return classes.selectedLine;
	}
	if (highlight) {
		return classes.highlightedLine;
	}
	return classes.line;
}
