import React = require("react");
import srvDeviceData = require("../services/data");
import { StartPage } from "./StartPage";
import { DiscoveryJSON } from "dataInterfaces";
import { RouteComponentProps } from "react-router-dom";
import { AsyncComponent } from "./AsyncComponent";
import { ProgressBar } from "./ProgressBar";
import { IGlobalServiceProps } from "./IGlobalServicesProps";
import { clearTitle } from "../services/ui/documentTitle";
import { extractArgsFromRoute } from "../services/routing";
import { parseArgs } from "../services/args/parseArgs";
import { ParsedArgs } from "../services/args/argTypes";
import { createAvailableProducts } from "../services/product/available";
import { AvailableProductsAndTargets } from "../services/product/types";
import { createLoader } from "../services/resources/otherLoaders/scriptAndProductLoader";
import { fs } from "../services/fileSystem";
import { resolveScriptArg } from "../services/args/resolveScriptArg";

interface IState {
	deviceData: DiscoveryJSON;
	availableProducts: AvailableProductsAndTargets[];
	routeArgs: Pick<ParsedArgs, "board" | "device" | "part" | "package" | "product">;
}

type IProps = RouteComponentProps<{}> & IGlobalServiceProps;

export class LoadStartPage extends AsyncComponent<IProps, IState> {

	constructor(props: IProps) {
		super(props);
		this.state = { deviceData: null, availableProducts: null, routeArgs: null };
	}

	public override componentDidMount() {
		clearTitle();
		super.componentDidMount();
	}

	public override render() {
		if (this.state.deviceData && this.state.availableProducts) {
			return <StartPage
				{...this.props}
				deviceData={this.state.deviceData}
				availableProducts={this.state.availableProducts}
				initialArgs={this.state.routeArgs} />;
		}

		return <ProgressBar id="startProgress" title="Loading Device Information..." />;
	}

	protected propsChanged() {
		return false;
	}

	protected clearAsyncData() {
		this.setState({ deviceData: null });
	}

	protected async fetchAsyncData() {
		const [deviceData, availableProducts, routeArgs] =
			await Promise.all([srvDeviceData.getDeviceDescriptions(), this.getProducts(), this.getScriptArgs()]);
		return { deviceData, availableProducts, routeArgs };
	}

	private async getProducts() {
		const knownProducts = await createAvailableProducts();
		return knownProducts.getProductAndTargetInfo();
	}

	private async getScriptArgs() {
		const loader = createLoader(fs);
		const { parsedArgs } = parseArgs(extractArgsFromRoute(this.props.location), true);
		try {
			return await resolveScriptArg(parsedArgs, loader);
		} catch (e) {
			// Return the args from the route alone, without using embedded args from the script
			return parsedArgs;
		}
	}
}
