import * as _ from "lodash";
import { MultiValueEnumerationConfigurable } from "public/defs";
import { ModuleInstance } from "public/runtime";
import { FormattersMap } from "../../formatting/formattersMap";
import { AObjectMgr } from "../object";
import { IOptions } from "../options";
import { verifyOptionTypes, unknownOptionError, validateDisabledOptions } from "./baseEnumerationConfigurableMgr";
import { BaseMultiValueEnumerationConfigurableMgr } from "./baseMultiValueEnumerationConfigurableMgr";

export class MultiValueEnumerationConfigurableMgr<
	T extends number | string = string>
	extends BaseMultiValueEnumerationConfigurableMgr<T, ModuleInstance>
	implements IOptions<T> {
	public override readonly def: MultiValueEnumerationConfigurable<T>;
	public minSelections: number;
	constructor(
		parentObjectMgr: AObjectMgr<ModuleInstance>,
		formattersMap: FormattersMap,
		def: MultiValueEnumerationConfigurable<T>,
	) {
		super(parentObjectMgr, formattersMap, def);
		verifyOptionTypes(this.getCurrentOptions());

		this.minSelections = _.isUndefined(this.def.minSelections) ? 1 : this.def.minSelections;

		// validate default
		try {
			this.validateValue(this.def.default);
		} catch (e) {
			throw new Error(`Can't set default: ${e.message}`);
		}
		// freeze the init value
		this.onSet(this.value);
	}

	public getOptions() {
		const inst = this.getParentRuntimeObj();
		const disabledOptions = this.def.getDisabledOptions ?
			this.def.getDisabledOptions(inst) : [];
		const optionsByName = this.getOptionsByName();
		validateDisabledOptions(disabledOptions, this.def.name, (o) => {
			if (!optionsByName[o.name]) {
				throw new Error(`${this.def.name}: attempted to disable unknown option '${o.name}'`);
			}
		});

		// Return both the disabled and enabled options

		const enabledOptions = _.differenceWith(this.def.options, disabledOptions, (a, b) => a.name === b.name);
		return { disabledOptions, enabledOptions };
	}

	protected getCurrentOptions() {
		return this.def.options;
	}

	protected getOptionsByName() {
		const currentOptions = this.def.options;
		return _.keyBy(currentOptions, (o) => o.name);
	}

	protected transform(newVal: T[]) {
		// Always save in sorted order
		// so [1,2] and [2,1] can be treated as being equal.
		// This can occur if the user is un-checking/checking items in the GUI
		return _.chain(newVal)
			.map((v) => this.legacyNamesMap?.get(v) ?? v)
			.sortBy()
			.sortedUniq()
			.value();
	}

	protected getSelectedOptions() {
		return (_.isEmpty(this.value) ? "" : "Selected: \n") +
			_.chain(this.getCurrentOptions())
				.filter((option) => _.includes(this.get(), option.name))
				.map((o) => o.displayName ?? o.name.toString())
				.join("\n")
				.value() || "";
	}

	protected override validateValue(newVal: T[]) {
		const options = this.getCurrentOptions();
		if (!_.isArray(newVal)) {
			this.typeMismatch("array", typeof newVal);
		}

		if (newVal.length < this.minSelections) {
			throw new Error(`[] must contain at least ${this.minSelections} value(s)`);
		}

		if (_.uniq(_.map(newVal, (v) => typeof v)).length > 1) {
			throw new Error("All elements of the [] must be of the same type");
		}

		if (!_.isEmpty(newVal) && (typeof newVal[0] !== typeof options[0].name)) {
			throw new Error(`[] elements must be of type ${typeof options[0].name}`);
		}

		const validOptions = _.map(options, (o) => o.name);
		_.each(newVal, (val) => {
			if (!_.includes(validOptions, val) && !this.legacyNamesMap?.has(val)) {
				unknownOptionError(val, validOptions);
			}
		});
	}
}
