import * as _ from "lodash";
import { Module } from "public/defs";
import { AdaptedDeviceInfo } from "dataInterfaces";

export const powerDomainsModuleName = "/ti/corePinmux/powerDomains";

export function getPowerDomainsModule(deviceData: AdaptedDeviceInfo): Module {

	let config = _.map(deviceData.powerDomains, (domain, name) => {
		const hasChoices = _.size(domain.powerValue) > 1;

		const c = {
			name,
			default: _.isEmpty(domain.powerValue) ? "" : _.first(domain.powerValue),
			readOnly: !hasChoices,
		};

		return hasChoices ? { ...c, options: _.map(domain.powerValue, (value) => ({ name: value })) } : c;
	});

	config = _.chain(config)
		.filter((c) => !!c.name)	// Workaround for PMUX-1320
		.sortBy((c) => c.name)	// Sort configurables
		.value();

	return {
		displayName: "Power Domains",
		description: "Add to configure the power domains",
		moduleStatic: { config },
	};
}
