import * as React from "react";
import * as _ from "lodash";
import { ConfigStoreActions } from "../../../services/configStore";
import { ProgressBar } from "../../ProgressBar";
import { ClockTreeGraph } from "./ClockTreeGraph";
import { ExtendedElkNode } from "../layout/customTypes";
import { getLayout } from "../layout/layout";
import { WithZoom } from "../../higherOrderComponents/WithZoom";
import { AsyncComponent } from "../../AsyncComponent";
import { ErrorStore } from "../../../services/errorStore";
import { ClockTreeNode } from "../../../services/instanceContainers/clockTreeNode";
import { Validations } from "../../../services/objectManagers/validations";
import { ClockIpInstanceMgr } from "../../../services/objectManagers/clockIpInstanceMgr";
import { FloatingSearch } from "./floatingControls/FloatingSearch";
import { FloatingMetaButtons } from "./floatingControls/FloatingMetaButtons";
import { FloatingNavigation } from "./floatingControls/FloatingNavigation";
import { IFormatter } from "../../../services/formatting/formattingTypes";
import { ResourceLoader } from "../../../services/resources/metaContentLoaders/resourceLoader";
import { IGlobalServiceProps } from "../../IGlobalServicesProps";
import { FloatingHelp } from "./floatingControls/FloatingHelp";

// This component calculates the layout of for a selected clock tree node, and then renders the associated graph in a 
// zoom-able container

interface IProps extends IGlobalServiceProps {
	onSelect: (selection: string) => void;
	actions: ConfigStoreActions;
	treeNode: ClockTreeNode;
	validations: Validations;
	width?: number;
	height?: number;
	errorStore: ErrorStore;
	displayScriptName: boolean;
	formatter: IFormatter,
	resourceLoader: ResourceLoader,
}

interface IState {
	layout: ExtendedElkNode;
	ipInstances: ClockIpInstanceMgr[];
	searchText: string;
}

export class ClockTreeZoomableGraph extends AsyncComponent<IProps, IState> {
	public override state: IState = {
		layout: null,
		ipInstances: [],
		searchText: "",
	}

	public override render() {
		const { layout, ipInstances, searchText } = this.state;
		if (!layout) {
			return <ProgressBar title="rendering" />;
		}

		const { treeNode, validations, displayScriptName, actions } = this.props;
		return (
			<WithZoom
				childWidth={layout.width}
				childHeight={layout.height}
				floatingContentLeft={
					<FloatingMetaButtons
						moduleMgr={treeNode.getStaticConfiguration()}
						validations={validations}
						displayScriptName={displayScriptName}
						actions={actions}
						errorStore={this.props.errorStore}
						formatter={this.props.formatter}
						resourceLoader={this.props.resourceLoader}
						modalService={this.props.modalService}
						notificationService={this.props.notificationService}
						theme={this.props.theme}
					/>
				}
				floatingContentRight={(props) =>
					<>
						<FloatingSearch
							searchText={searchText}
							onSearchTextChanged={this.onSearchTextChanged}
							key={treeNode.getSelection().instanceId} // Ensures a selection change resets the search
						/>
						<div> {/* div ensures that FloatingHelp will be underneath */}
							<FloatingNavigation
								zoomIn={props.zoomIn}
								zoomOut={props.zoomOut}
								reset={props.reset}
							/>
						</div>
						<FloatingHelp />
					</>
				}
			>
				<ClockTreeGraph
					layout={layout}
					onSelect={this.onSelect}
					treeNode={treeNode}
					validations={validations}
					actions={actions}
					displayScriptName={displayScriptName}
					ipInstances={ipInstances}
					searchText={searchText}
				/>
			</WithZoom>
		);
	}

	protected propsChanged(nextProps: Readonly<IProps>) {
		return this.props.treeNode !== nextProps.treeNode;
	}

	protected clearAsyncData() {
		this.setState({ layout: null });
	}

	protected async fetchAsyncData() {
		const { treeNode } = this.props;
		const ipInstances = treeNode.getInstances();
		const layout = await getLayout(
			treeNode.getClockTree(), _.map(ipInstances, (i) => i.getID()), treeNode.getGraphSettings());
		return { layout, ipInstances };
	}

	private onSearchTextChanged = (filterText: string) => {
		this.setState({ searchText: filterText });
	}

	private onSelect = (selection: string) => {
		this.setState({ searchText: "" });
		this.props.onSelect(selection);
	}
}
