import * as _ from "lodash";
import { loadProductMetaData } from "../resources/metaContentLoaders/loaderFactory";
import { ScriptAndProductLoader } from "../resources/otherLoaders/scriptAndProductLoader";
import { Product, ProductFile } from "./types";
import { loadMinProductFile, toProductFile } from "./parseProductFile";
import { verifyMinToolVersion } from "./versionCheck";
import { getToolVersion } from "../toolVersion";
import { http } from "../http";

export const scriptDirProductName = "_generated";

const scriptDirProduct: ProductFile = {
	path: null,
	name: scriptDirProductName,
	version: "0.0.0",
	includePaths: ["."],
	devices: [".*"],
	isBuiltIn: false,
};

export function loadScriptDirProductPathProduct(scriptDirProductPath: string) {
	scriptDirProduct.path = scriptDirProductPath;
	return loadProductResources(scriptDirProduct);
}

export function loadProducts(
	paths: string[],
	loader: ScriptAndProductLoader,
	isBuiltIn: boolean = false,
): Promise<Product[]> {

	return readProductFiles(paths, loader, isBuiltIn).then((file) => loadProductsResources(file, isBuiltIn));
}

export function loadProductsResources(file: ProductFile[], isBuiltIn: boolean) {
	return isBuiltIn ? Promise.all(
		_.chain(file)
			.each((f) => {
				if (f.dependencies) {
					throw new Error("Built-in products should not have dependencies");
				}
			})
			.map(loadProductResources)
			.value()
	) : Promise.all(
		_.map(file, loadProductResources)
	);
}

function loadProductResources(file: ProductFile) {
	return (
		loadProductMetaData(file.path, file.includePaths)
			.then((resources) => {
				return {
					file,
					resources,
				};
			})
	);
}

async function readProductFiles(
	paths: string[],
	loader: ScriptAndProductLoader,
	isBuiltIn: boolean = false,
) {

	const fetchFile = isBuiltIn
		? (filePath: string) => http.get(filePath)
		: (filePath: string) => loader.readProductFile(filePath);

	const unvalidated = await Promise.all(
		_.map(paths, (filePath) => {
			return fetchFile(filePath)
				.then((fileContent) => loadMinProductFile(filePath, fileContent));
		})
	);
	verifyMinToolVersion(unvalidated, getToolVersion());

	return _.compact(_.map(unvalidated, (uv) => toProductFile(uv, isBuiltIn)));
}
