import * as _ from "lodash";
import { TabName } from "../tabNames";
import { ITreeNode } from "../../components/TreeNode";
import { Member } from "public/defs";
import { getDisplayName } from "../utils";
import { IMyListItem } from "../IMyListItem";
import { CurrentSelection } from "./formattingTypes";
import { ILinkActions } from "../../components/actions/ILinkActions";
import { SelectionInConfigStore } from "../objectManagers/ui/selection";

export interface FormattedLink {
	baseText: string;
	linkAction: (actions: ILinkActions) => void;
}

export function isFormattedLink(msgPart: FormattedMsgPart): msgPart is FormattedLink {
	return !!(msgPart as any as FormattedLink)?.linkAction;
}

export interface FormattedLinkAndDestination extends FormattedLink {
	destination: SelectionInConfigStore;
}

export function toFormattedLink(
	contextId: number,
	contextName: string,
	tabName: TabName,
	treeNode: ITreeNode | string,
	listItem: IMyListItem,
	member?: Member,
	selection?: CurrentSelection,
): FormattedLinkAndDestination {

	// We want the display to first name the context and then the list item.  But, only if we have 
	// multiple contexts (non-null name) and the selection doesn't include that context

	let baseText = contextName && selection?.contextIndex !== contextId ? `${contextName}: ` : "";

	// After that, we want to name the list item

	baseText += _.isString(listItem) ? listItem : listItem.getNameMgr().getDisplayValue();

	// But, if the current selection is a member of the list item, then refer to the member instead
	// ie if "MySPI" is selected, I'd rather say "'use hardware' prevents that choice" than to say
	// "MySPI prevents that choice"

	if (selection && selection.listItem === listItem && member) {
		baseText = _.isString(member) ? member : getDisplayName(member, false);
	}

	// We want to stay on the current tab if we can - so if this object is the current selection, then
	// use the current tab as the tab name and tree node

	if (selection && selection.listItem === listItem) {
		tabName = selection.tab.getTitle();
		treeNode = selection.treeNode;
	}

	const destination = {
		runtimeIndex: contextId,
		tabName,
		treeNodePath: _.isString(treeNode) ? [treeNode] : treeNode.getNodePath(),
		instanceId: listItem.getID(),
		memberPath: member ? [member.name] : [],
	};

	return (
		{
			baseText,
			destination,
			linkAction: (actions: ILinkActions) => actions.navigateTo(destination),
		}
	);
}

export type FormattedMsgPart = string | FormattedLink;

// A formatted msg represents a message that is properly formatted by a formatter
// it is saved a an array of plain text string or links.
// links are different because they have both a destination that can be navigated to 
// when linked in the UI.
export class FormattedMsg {
	constructor(private msgParts: FormattedMsgPart[] = [""]) {
	}

	// for testing
	public toParts() {
		return this.msgParts;
	}

	// get the entire message as plain text
	public toString() {
		return _.chain(this.msgParts)
			.map((part) => {
				return isFormattedLink(part) ? part.baseText : part;
			})
			.join("")
			.value();
	}
}
