import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/clockTreeStyles";
import { Divider } from "clockTree";
import { IMultiplyOrDivideNodeProps, MultiplyOrDivideNode } from "./MultiplyOrDivideNode";

// A divider node is a rectangle with the division amount in the middle.  If the division is configurable, then that 
// amount becomes a drop down

type IProps = Omit<IMultiplyOrDivideNodeProps, "formatPrefix" | "values" | "mgr" | "currentValue">;
export function DividerNode(props: IProps & ClassesType) {
	const ipInstance = props.node.data.ipInstance as Divider;
	const mgr = props.treeNode.getIpInstanceMgr(ipInstance.name).memberMgrs.divideValue;
	const value = mgr?.getValue() ?? _.first(ipInstance.divideValues);
	return <MultiplyOrDivideNode
		{...props}
		formatPrefix={"/"}
		values={ipInstance.divideValues}
		mgr={mgr}
		currentValue={value}
	/>;
}
