import * as _ from "lodash";
import { DisabledOption, DynamicEnumerationConfigurable, EnumerationOption } from "public/defs";
import { ModuleInstance } from "public/runtime";
import { FormattersMap } from "../../formatting/formattersMap";
import { validateMeta, SCHEMA } from "../../JSONschemaValidator";
import { AObjectMgr } from "../object";
import {
	BaseEnumerationConfigurableMgr,
	isNumberEnumerationConfigurable,
	toDropDownOptions,
	validateDisabledOptions,
} from "./baseEnumerationConfigurableMgr";

export function getOptionsForDynamicEnum<T extends number | string = string>(
	inst: ModuleInstance,
	options: ((inst: ModuleInstance) => EnumerationOption<T>[]),
	name: string,
	disabledOptions: DisabledOption<T>[],
	selectedOptions?: T[]) {
	const currentOptions = options(inst);

	validateMeta(currentOptions, name, SCHEMA.DynamicEnumOptions);
	// change the selectedOptions to correct format
	const reformattedOptions = _.map(selectedOptions, (o) => ({ name: o }));
	const invalidOptions = _.differenceWith(reformattedOptions, currentOptions, (a, b) => a.name === b.name);
	// Return both the invalid and enabled options
	const enabledOptions =
		_.union<EnumerationOption<T>>(
			invalidOptions,
			_.differenceWith(
				currentOptions,
				disabledOptions, (a, b) => a.name === b.name,
			),
		);

	return { enabledOptions, disabledOptions };
}

export class DynamicEnumerationConfigurableMgr<
	T extends number | string = string>
	extends BaseEnumerationConfigurableMgr<T, T, ModuleInstance, DynamicEnumerationConfigurable<T>> {
	constructor(
		parentObjectMgr: AObjectMgr<ModuleInstance>,
		formattersMap: FormattersMap,
		def: DynamicEnumerationConfigurable<T>,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			def,
		);
	}

	public override getUIOptions() {
		const { enabledOptions, disabledOptions } = this.getOptions();
		const displayFormat = isNumberEnumerationConfigurable(this.def) ? this.def.displayFormat : null;
		return {
			disabledOptions: toDropDownOptions(disabledOptions, displayFormat),
			enabledOptions: toDropDownOptions(enabledOptions, displayFormat),
		};
	}

	public getOptions() {
		const inst = this.getParentRuntimeObj();
		const disabledOpts = this.def.getDisabledOptions ?
			this.def.getDisabledOptions(inst) : [];
		const optionsByName = this.getOptionsByName();
		validateDisabledOptions(disabledOpts, this.def.name, (o) => {
			if (!optionsByName[o.name]) {
				throw new Error(`${this.def.name}: attempted to disable unknown option '${o.name}'`);
			}
		});
		return getOptionsForDynamicEnum(
			inst as ModuleInstance,
			this.def.options,
			this.def.name,
			disabledOpts);
	}

	public override getUIHash(): string {
		return undefined;
	}

	public getSelectedOption() {
		return this.value.toString();
	}

	protected getOptionsByName() {
		const inst = this.getParentRuntimeObj();
		const currentOptions = this.def.options(inst);
		return _.keyBy(currentOptions, (o) => o.name);
	}

	protected override createLegacyNamesMap(): void {
		// no point in having a static map if options are dynamic and thus legacyNames would be dynamic
	}
}
