import * as _ from "lodash";
import { DiscoveryJSON } from "dataInterfaces";

interface DeviceSelection {
	device: string;
	part: string;			// Part name, not id
	package: string;		// Package name, not id
}

export class DiscoveryData {
	constructor(private readonly discoveryJSON: DiscoveryJSON) { }

	public getDevices() {
		return this.discoveryJSON.devices;
	}

	public getDevice(selection: Pick<DeviceSelection, "device">) {
		return _.find(this.discoveryJSON.devices, (d) => d.name === selection.device);
	}

	public getParts(selection: Pick<DeviceSelection, "device">) {
		return this.getDevice(selection).part;
	}

	public getPart(selection: Pick<DeviceSelection, "device" | "part">) {
		return _.find(this.getParts(selection), (p) => p.name === selection.part);
	}

	public getPackages(selection: Pick<DeviceSelection, "device" | "part">) {
		return this.getPart(selection).packageDescriptions;
	}

	public getPackage(selection: DeviceSelection) {
		return _.find(this.getPackages(selection), (p) => p.name === selection.package);
	}

	public getTargetDBDevices(selection: Pick<DeviceSelection, "device" | "part">) {
		return this.getPart(selection).targetDBDevices;
	}
}
