import * as React from "react";
import { Typography, Link } from "../imports/material-ui-imports";
import { getMessageAndStack } from "../services/niceExceptions";
import { isError } from "../services/utils";
import { ATheme } from "./styles/themes";
import * as _ from "lodash";

interface IProps {
	description?: string;
	exception: any;
	inEditor?: boolean;
	theme: ATheme;
}

interface IState {
	showDetails: boolean;
}

export class ExceptionText extends React.Component<IProps, IState> {
	public override state: IState = {
		showDetails: false,
	};

	public override render() {
		const messageAndStack = isError(this.props.exception) ?
			getMessageAndStack(this.props.exception) :
			JSON.stringify(this.props.exception);
		const contents = this.props.description ?
			`${this.props.description}\n${messageAndStack}` :
			messageAndStack;
		const title = contents.substr(0, _.indexOf(contents, "\n"));
		const details = contents.substr(_.indexOf(contents, "\n") + 1);
		//  whiteSpace: "pre" preserves whitespace of content and only wrap on line break 
		return <>
			<Typography
				variant="body2"
				id="ExceptionText">
				{title}
				<br />
				{this.props.exception &&
					<Link
						display="inline"
						id={"switchDetails"}
						component="button"
						underline="hover"
						variant="subtitle2"
						style={{ verticalAlign: "baseline" }}
						onClick={() => this.setState({ showDetails: !this.state.showDetails })}>
						{this.state.showDetails ? "Hide Details..." : "Show Details..."}
					</Link>
				}
			</Typography>
			{this.state.showDetails &&
				<Typography
					variant="body2"
					style={{ whiteSpace: this.props.inEditor ? "pre-wrap" : "pre" }}
					id="details">
					{details}
				</Typography>
			}
		</>;
	}
}
