import * as _ from "lodash";
import * as React from "react";
import { IConfigurablesActions } from "./configurableActions";
import { CConfigurable } from "./configurables/configurable";
import { IMemberRowProps, MemberRow } from "./memberRows";
import { ConfigLeafNode } from "../viewNodes";
import { ILinkActions } from "../../../components/actions/ILinkActions";

interface IProps extends Omit<IMemberRowProps, "highlight" | "memberMgr"> {
	node: ConfigLeafNode;
	actions: IConfigurablesActions & ILinkActions;
	highlightedMember: string;
}

// Render a ConfigLeafNode, which should contain a bunch of related configurables

export function CConfigLeafNode(props: IProps) {
	const { node, highlightedMember, ...rest } = props;
	const {
		actions,
		formatter,
		resourceLoader,
		validations,
		modalService,
		notificationService,
		errorStore,
		displayScriptName,
		theme,
	} = props;
	return <>
		{_.map(node.getConfigurables(), (c) => {
			return (
				<MemberRow
					{...rest} // safe as IProps are based on IMemberRows
					key={c.def.name}
					memberMgr={c}
					highlight={c.def.name === highlightedMember}
				>
					<CConfigurable // explicitly pass props vs ...rest so we don't pass extra
						mgr={c}
						actions={actions}
						displayScriptName={displayScriptName}
						formatter={formatter}
						resourceLoader={resourceLoader}
						validations={validations}
						modalService={modalService}
						notificationService={notificationService}
						errorStore={errorStore}
						theme={theme}
					/>
				</MemberRow>
			);
		})}
	</>;
}
