import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/clockTreeStyles";
import { ExtendedElkNode } from "../layout/customTypes";
import { Alignment, MainLabel } from "./NodeLabels";
import { ClockTreeNode } from "../../../services/instanceContainers/clockTreeNode";
import { FrequencyLabelNode } from "./FrequencyLabelNode";
import { PositionedNode } from "./PositionedNode";

// A label just below the connection line and nothing else

interface IProps {
	treeNode: ClockTreeNode;
	node: ExtendedElkNode;
	onSelect: (selection: string) => void;
	displayScriptName: boolean;
}

const LabeledConnectionNode = React.memo(
	({ node, onSelect, displayScriptName, classes }: React.PropsWithChildren<IProps & ClassesType>) => {
		return (
			<PositionedNode
				node={node}
				onSelect={onSelect}
				className={classes.positionedDiv}
			>
				<MainLabel
					node={node}
					displayScriptName={displayScriptName}
					alignment={getAlignment(node)}
					classes={classes}
				/>
			</PositionedNode>
		);
	});

export function NamedConnectionNode(props: React.PropsWithChildren<IProps & ClassesType>) {
	if (_.includes(props.treeNode.getGraphSettings().frequencyLabels, props.node.data.ipInstance.name)) {
		return <FrequencyLabelNode {...props} />;
	}
	return <LabeledConnectionNode {...props} />;
}

function getAlignment(node: ExtendedElkNode) {
	const { ipInstance } = node.data;
	if (_.isEmpty(ipInstance.inPins)) {
		return Alignment.LEFT;
	}
	if (_.isEmpty(ipInstance.outPins)) {
		return Alignment.RIGHT;
	}
	return Alignment.CENTER;
}
