import React = require("react");
import { Button } from "../../imports/material-ui-imports";
import { IButtonProps } from "./IButtonProps";
import { defaultTheme } from "../styles/themes";
export class NavButton extends React.Component<IButtonProps> {
	public override render() {
		return (<Button
			component="span"
			color="inherit"
			id={this.props.id}
			disabled={this.props.disabled}
			onClick={this.props.onClick}
			style={{
				...this.props.style,
				marginLeft: defaultTheme.theme.spacing(1),
				marginRight: defaultTheme.theme.spacing(1),
			}}>
			{this.props.children}
		</Button>);
	}
}
