import * as React from "react";
import * as _ from "lodash";
import { ClassesType } from "../styling/clockTreeStyles";
import { PositionedNode } from "../nodes/PositionedNode";
import { NodeLabels } from "../nodes/NodeLabels";
import { ClockTreeInnerGraph, IClockTreeInnerGraphProps } from "../graph/ClockTreeInnerGraph";

// This component renders a graph for a given inner group within a larger ELK layout and outlines it with a box to 
// visually separate it from the containing graph. 

export function Group(props: IClockTreeInnerGraphProps & ClassesType) {
	const { layout, displayScriptName, classes } = props;
	return <>

		{
			// First, render two PositionedNodes.  The first is the group label and bounding box.  The second is the
			// fill.  The fill is done separately so that it can have a partial opacity and thus groups inside of 
			// groups will be drawn darker over time
		}
		<PositionedNode
			key="labelsAndOutline"
			node={layout}
			onSelect={noSelect}
			suppressTooltip={true}
			className={classes.genericGroupNodeOutline}
		>
			<NodeLabels key="labels" node={layout} displayScriptName={displayScriptName} classes={classes} />
		</PositionedNode>
		<PositionedNode
			key="semiTransparentFill"
			node={layout}
			onSelect={noSelect}
			suppressTooltip={true}
			className={classes.genericGroupNodeFill}
		/>

		{
			// Now graph the elements inside the group.  Note that ELK will provide all x,y coordinates to nodes, edges
			// and subsequent groups as offset from the group's position.  As such, the graph component will render 
			// everything correctly, as long as we position it where this child group is positioned.  As such, we wrap
			// it in a PositionedNode at the this group's coordinates 
		}
		<PositionedNode
			key="innerGraph"
			node={layout}
			onSelect={noSelect}
			suppressTooltip={true}
			className={classes.positionedDiv}
		>
			<ClockTreeInnerGraph {...props} />
		</PositionedNode>
	</>;
}

function noSelect() { }
