import * as _ from "lodash";
import { enableTest } from "./platform";
import { ModalService } from "./ui/modals";
import { clearSysConfigCache } from "./sysConfigFactory";
import { constructRoute, RouteTarget } from "./routing";

const OriginalPromise = Promise;

// Save the original Promise on the windows object so we can refer to it
// See webpack.common.js for the reason why
// @ts-ignore
window.ti_testing_originalPromise = Promise;

function injectTestability() {
	(window as any).getAngularTestability = () => {
		return Testability.instance();
	};

	(window as any).getAllAngularTestabilities = () => {
		return [Testability.instance()];
	};

	class PromiseReplacement<T> extends OriginalPromise<T> {
		constructor(
			executor: (resolve: (value?: T | PromiseLike<T>) => void, reject: (reason?: any) => void) => void) {
			super((realResolve, realReject) => {

				const lock = Testability.instance().operationPending();
				try {

					const resolve = (value?: T | PromiseLike<T>) => {
						lock.dismiss();
						realResolve(value);
					};

					const reject = (reason?: any) => {
						lock.dismiss();
						realReject(reason);
					};

					// Call the original executor, but with our wrappers instead

					executor(resolve, reject);

				} catch (e) {
					lock.dismiss();
					throw e;
				}
			});
		}
	}
	Promise = PromiseReplacement;

	const originalDebounce = _.debounce;
	function debounceReplacement<T extends (...args: any[]) => any>(
		func: T,
		wait?: number,
		options?: _.DebounceSettings,
	) {
		let lock: Dismissable = null;

		// Wrap the passed in function with something that will unlock protractor

		const unlockThenCallFunc = (...args: any[]) => {
			lock.dismiss();
			lock = null;
			return func(...args);
		};

		// Debounce our wrapped function

		const debouncedFunc = originalDebounce(unlockThenCallFunc, wait, options);

		// Return something that will lock, if not already locked, then call the debounce
		// version

		const replacementFunc = (...args: any[]) => {
			if (!lock) {
				lock = Testability.instance().operationPending();
			}
			return debouncedFunc(...args);
		};
		(replacementFunc as any).flush = () => debouncedFunc.flush();
		(replacementFunc as any).cancel = () => {
			if (lock) {
				lock.dismiss();
				debouncedFunc.cancel();
			}
		};
		return replacementFunc;
	}
	// @ts-ignore
	_.debounce = debounceReplacement;
}

class Dismissable {
	private dismissed = false;
	constructor(private readonly onDismissed: () => void) { }
	public dismiss() {
		if (!this.dismissed) {
			this.dismissed = true;
			this.onDismissed();
		}
	}
}

