class Testability {

	private static _instance = new Testability();

	public static instance() {
		return Testability._instance;
	}

	private pendingCount: number = 0;
	private protractorCallback: (didWork: boolean) => void = null;
	private internalCallback: () => void = null;

	// We need to skip counting and basically use the native promise when the promise comes from 
	// protractor, as obviously protractor wants to check the system for idle excluding itself.
	// This can be identified by the current call stack.

	public operationPending() {
		if (calledByProtractorInjectedCode()) {
			return new Dismissable(() => {
				this.runCBsIfReady();
			});
		} else {
			this.pendingCount++;
			return new Dismissable(() => {
				this.pendingCount--;
				this.runCBsIfReady();
			});
		}
	}

	// Protractor will look for and call this function register an event to
	// fire every time the application has no more work to do
	public whenStable(callback: (didWork: boolean) => void) {
		this.protractorCallback = callback;
		this.runCBsIfReady();
	}

	// Called by us to register to do something synchronous just before 
	// protractor is notified
	public runOnceBeforeStable(callback: () => void) {
		this.internalCallback = callback;
		this.runCBsIfReady();
	}

	private runCBsIfReady() {
		if (this.isStable()) {
			if (this.internalCallback) {
				this.internalCallback();
				this.internalCallback = null;
			}
			if (this.protractorCallback) {
				this.protractorCallback(false);
			}
		}
	}

	private isStable() {
		return this.pendingCount === 0;
	}
}

function calledByProtractorInjectedCode() {
	return areAnyOnCurrentCallstack("callFunction", "executeAsyncScript");
}

function areAnyOnCurrentCallstack(...strings: string[]) {
	const stackTraceLimit = Error.stackTraceLimit;
	Error.stackTraceLimit = 100;
	const tempError = new Error();
	Error.stackTraceLimit = stackTraceLimit;

	return _.some(strings, (s) => tempError.stack.includes(s));
}

export function enableTestHooks(modalService: ModalService) {
	enableTest();
	injectTestability();
	(window as any).sysconfigTestBaseGet = (target: RouteTarget, args: string[]) => {
		Testability.instance().runOnceBeforeStable(() => {
			modalService.reset();
			clearSysConfigCache();
			const url = constructRoute(target, args);
			window.location.href = `#${url}`;
			if ((window as any).gc) {
				(window as any).gc();
			}
		});
	};
}

