import * as _ from "lodash";

import { AnyConfigurable, ConfigurableGroup, StandardConfigurable } from "public/defs";

export function flattenConfigs(config: (StandardConfigurable | ConfigurableGroup)[]): StandardConfigurable[];
export function flattenConfigs(config: (AnyConfigurable | ConfigurableGroup)[]): AnyConfigurable[];
export function flattenConfigs(config: (AnyConfigurable | ConfigurableGroup)[]): AnyConfigurable[] {
	return (
		_.flatMap(
			config,
			(c) => {
				if (isConfigurableGroup(c)) {
					return flattenConfigs(c.config);
				} else {
					return [c];
				}
			})
	);
}

export function isConfigurableGroup(c: AnyConfigurable | ConfigurableGroup): c is ConfigurableGroup {
	return !!(c as any as ConfigurableGroup).config;
}
